object Workspace {
  import Main._

  class UnionFind(val n: Int) {
  private val par = Array.ofDim[Int](n)
  REP(n) (i => par(i) = i)
  val rank: Array[Int] = Array.fill[Int](n)(1) // 集合の要素数
  private val visits = Array.ofDim[Int](n) // 訪れた場所をfind毎に用意するのがもったいないのでつかいまわす

  def find(x: Int): Int = {
    var ptr = 0
    def step(x: Int): Int = {
      if (par(x) == x) x
      else {
        visits(ptr) = x
        ptr += 1
        step(par(x))
      }
    }

    val res = step(x)
    REP(ptr){ i => par(visits(i)) = res }
    res
  }

  private def merge(node: Int, rt: Int): Int = {
    par(node) = rt
    rank(rt) += rank(node)
    rt
  }

  def unite(x: Int, y: Int): Boolean = {
    val x1 = find(x)
    val y1 = find(y)
    if (x1 == y1) false
    else {
      if (rank(x1) < rank(y1))
        merge(x1, y1)
      else
        merge(y1, x1)

      true
    }
  }

  /**
    * xを解決する必要がないときは直にrankをみる
    */
  def cntNodes(x: Int): Int = rank(find(x))
}
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val n = ni()
    val A, B = na(n)
    val Sa = A.zipWithIndex.sorted
    val Sb = B.sorted
    val rev = Sa.map(_._2)
    val P = Array.ofDim[Int](n)
    REP(n) { i =>
      P(rev(i)) = i
    }

    def test: Boolean = {
      REP(n) { i =>
        if (Sa(i)._1 > Sb(i)) return false
      }

      val uf = new UnionFind(n)
      REP(n - 1) { i =>
        if (!uf.unite(i, P(i))) return true
      }

      REP(n - 1) { i =>
        if (Sa(i + 1)._1 <= Sb(i)) return true
      }

      false
    }

    if (test) out.println("Yes")
    else out.println("No")
  }
}

