object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val N = in.next().toInt

  val _A = Array.fill[(Int, Int)](N+1)((0, 0)) // (value, index)
  val _B = Array.fill[(Int, Int)](N+1)((0, 0)) // (value, index)
  for (i <- 1 to N)
    _A(i) = (in.next().toInt, i)
  for (i <- 1 to N)
    _B(i) = (in.next().toInt, i)

  val A = _A.sorted
  val B = _B.sorted

  //
  var flag = 2
  breakable {
    for (i <- 1 to N) {
      if (A(i)._1 > B(i)._1) {
        flag = 0
        break
      }

      if (i < N) {
        if (A(i)._1 <= B(i)._1)
          flag = 1
      }
    }
  }

  var ans = ""
  if (flag == 0)
    ans = "No"
  else if (flag == 1)
    ans = "Yes"
  else {
    val uf = new UnionFind(N+1)

    for (i <- 1 to N) {
      uf.connect(A(i)._2, B(i)._2)
    }

    if (uf.size(1) < N)
      ans = "Yes"
    else
      ans = "No"
  }

  println(ans)
}


// O(α(n)) << O(log(n))
// v は頂点数

class UnionFind(v: Int){
  // 根であれば *そのグループの要素数(負)* が、子であれば親の番号が入る。
  val uni = Array.fill(v)(-1)

  // 頂点 v の所属するグループを調べる
  def root(v: Int): Int =
    uni(v) < 0 match{
      case true  =>  // v が親の場合
        return v
      case false =>  // v が子の場合
        uni(v) = root(uni(v))  // 親のrootを調べる
        return uni(v)
    }

  // 頂点 a と頂点 b をつなぐ。もともと同じグループのとき、False を返す
  def connect(a: Int, b: Int): Boolean = {
    // まずはそれぞれ根の番号に置き換える
    var ra = root(a)
    var rb = root(b)
    if(ra == rb)
      return false  // a と b がそもそも同じグループに属しているなら即終了

    // ra を大きなグループにしたいので、逆であれば入れ替える
    if(uni(ra) > uni(rb)) {  // rbの方が要素数が多ければ
      var tmp = ra
      ra = rb
      rb = tmp
    }

    // ra と rb を結合し、rb の親を ra とする
    uni(ra) += uni(rb)
    uni(rb) = ra
    return true
  }

  // 頂点 a, b が同じグループであるかを調べる
  def isConnect(a: Int, b: Int): Boolean =
    root(a) == root(b)

  // 頂点 a を含むグループの頂点数を調べる
  def size(a: Int): Int = -uni(root(a))
}




