    def nm_c(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  }

  def REP(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def REP_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }
  def TO(from: Int, to: Int)(f: Int => Unit): Unit = {
    REP(to - from + 1, from)(f)
  }
  def map[@specialized A: ClassTag](n: Int, offset: Int = 0)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    REP(n)(i => res(i) = f(i + offset))
    res
  }

  def sumL(as: Array[Int]): Long = {
    var s = 0L
    REP(as.length)(i => s += as(i))
    s
  }
  def cumSum(as: Array[Int]): Array[Long] = {
    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

object Workspace {
  import Main._

  class UnionFind(val n: Int) {
    private val par = Array.ofDim[Int](n)
    REP(n)(i => par(i) = i)
    val rank: Array[Int] = Array.fill[Int](n)(1) // 集合の要素数
    private val visits = Array.ofDim[Int](n) // 訪れた場所をfind毎に用意するのがもったいないのでつかいまわす

    def find(x: Int): Int = {
      var ptr = 0

      def step(x: Int): Int = {
        if (par(x) == x) x
        else {
          visits(ptr) = x
          ptr += 1
          step(par(x))
        }
      }

      val res = step(x)
      REP(ptr) { i => par(visits(i)) = res }
      res
    }

    private def merge(node: Int, rt: Int): Int = {
      par(node) = rt
      rank(rt) += rank(node)
      rt
    }

    def unite(x: Int, y: Int): Boolean = {
      val x1 = find(x)
      val y1 = find(y)
      if (x1 == y1) false
      else {
        if (rank(x1) < rank(y1))
          merge(x1, y1)
        else
          merge(y1, x1)

        true
      }
    }

    /**
      * xを解決する必要がないときは直にrankをみる
      */
    def cntNodes(x: Int): Int = rank(find(x))

    def countDisjointSets(): Int = {
      var cnt = 0
      REP(n) { i =>
        // 同じかどうかだけを見るので、find使ってどの集合に属するかを解決する必要がない
        if (par(i) == i) cnt += 1
      }
      cnt
    }
  }
}

