    rep(i, n){
        cin >> b[i];
        ib.emplace_back(i);
    }
    sort(ib.begin(), ib.end(), [&](int i, int j){ return b[i] < b[j]; });

    rep(i, n){
        if(a[ia[i]] > b[ib[i]]){
            return false;
        }
    }

    int cnt = 0;
    rep(i, n){
        cnt += a[i] > b[i];
    }

    if(cnt < n - 1){
        return true;
