void __solve()
{
    int n; cin>>n;
    vector<int> a(n),b(n); cin>>a>>b;
    vector<int> idx(n);
    {
        iota(all(idx),0);
        sort(all(idx),[&](int x,int y){return b[x]<b[y];});
        vector<int> newa(n);
        for(i32 i=0; i<n; ++i)
        {
            newa[i]=a[idx[i]];
        }
        swap(a,newa);
        sort(all(b));
        sort(all(idx),[&](int x,int y){return a[x]>a[y];});
    }

    bool flag=false;
    rheap<pii> aque;
    for(i32 i=0; i<n; ++i)
    {
        aque.emplace(a[i],i);
    }
    heap<int> ique;
    heap<pii> que;

    for(i32 i=0; i<n; ++i)
    {
        while(!aque.empty() and aque.top().first<=b[i])
        {
            ique.emplace(aque.top().second);
            aque.pop();
        }
        if(b[i]<a[i])
        {
            while(!ique.empty() and ique.top()<=i) ique.pop();
            if(ique.empty())
            {
                cout << "No" << "\n";
                return;
            }
            int k=ique.top(); ique.pop();
            swap(a[i],a[k]);
            aque.emplace(a[k],k);
        }
        else
        {
            flag=true;
        }
    }

    if(flag)
    {
        cout << "Yes" << "\n";
    }
    else
    {
        cout << "No" << "\n";
    }
}

