int n,a[N],b[N],pa[N],pb[N],pos[N],vis[N];
bool Solve(){
	for(int i=1;i<=n;++i){
		pa[i]=pb[i]=i;
	}
	sort(pa+1,pa+n+1,[&](int i,int j){return a[i]<a[j];});
	sort(pb+1,pb+n+1,[&](int i,int j){return b[i]<b[j];});
	for(int i=1;i<=n;++i){
