	}
	for(int i=1;i<=n;++i){
		pos[pa[i]]=pb[i];
	}
	int cnt=0,u=n;
	while(!vis[u]){
		vis[u]=1;
		u=pos[u];
		++cnt;
	}
	return cnt<n;
}
