int main()
{
  int N;
  cin >> N;
  vector<int> A(N), B(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  for (auto i = 0; i < N; i++)
  {
    cin >> B[i];
  }
  vector<Info> I(N);
  for (auto i = 0; i < N; i++)
  {
    I[i] = Info(B[i], A[i]);
  }
  sort(I.begin(), I.end());
  for (auto i = 0; i < N; i++)
  {
    A[i] = get<1>(I[i]);
  }
  vector<int> old_A{A}, old_B{B};
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());
  for (auto i = 0; i < N; i++)
  {
    if (A[i] > B[i])
    {
      No();
    }
  }
  for (auto i = 0; i < N; i++)
  {
    if (old_A[i] == A[i])
    {
      Yes();
    }
  }
  assert(false);
  vector<bool> C(N, true);
  for (auto i = 1; i < N; i++)
  {
    C[i] = (A[i] <= B[i - 1]);
  }
  for (auto k = 0; k < N; k++)
  {
    int x{old_A[k]};
    int y{old_B[k]};
    if (x > y)
    {
      continue;
    }
    auto it_a{upper_bound(A.begin(), A.end(), x)};
    --it_a;
    assert(*it_a == x);
    auto it_b{lower_bound(B.begin(), B.end(), y)};
    assert(*it_b == y);
    int num_a(it_a - A.begin());
    int num_b(it_b - B.begin());
    if (num_b <= num_a)
    {
      Yes();
    }
    else
    {
      bool ok{true};
      for (auto i = num_a + 1; i <= num_b; i++)
      {
        if (!C[i])
        {
          ok = false;
          break;
        }
      }
      if (ok)
      {
        Yes();
      }
    }
  }
  for (auto i = 0; i < N; i++)
  {
    if (old_A[i] == A[i])
    {
      Yes();
    }
  }
  assert(false);
  vector<int> V(N, -1);
  for (auto i = 0; i < N; i++)
  {
    auto it{lower_bound(A.begin(), A.end(), old_A[i])};
    int num(it - A.begin());
    V[num] = i;
  }
  for (auto i = 0; i < N; i++)
  {
    if (V[i] == -1)
    {
      Yes();
    }
  }
  vector<bool> used(N, false);
  int now{0};
  int cnt{0};
  while (cnt < N)
  {
    if (used[now])
    {
      Yes();
    }
    used[now] = true;
    cnt++;
    now = V[now];
  }
  No();
}

