#include <bits/stdc++.h>

const int N = 200010;
using pii = std::pair <int, int>;

int a[N], b[N], c[N], bb[N];
int ccnt[N];
pii p[N];
bool vis[N];

int main(){
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; ++ i){
        scanf("%d", &a[i]);
        c[i] = a[i];
    }
    for (int i = 0; i < n; ++ i){
        scanf("%d", &b[i]);
        c[i + n] = b[i];
    }
    std::sort(c, c + 2 * n);
    int cnt = std::unique(c, c + 2 * n) - c;
    for (int i = 0; i < n; ++ i){
        a[i] = std::lower_bound(c, c + cnt, a[i]) - c;
        b[i] = std::lower_bound(c, c + cnt, b[i]) - c;
        ++ ccnt[a[i]];
        bb[i] = b[i];
    }
    for (int i = 1; i < N; ++ i){
        ccnt[i] += ccnt[i - 1];
    }
    std::sort(bb, bb + n);
    bool flag = false;
    for (int i = 0; i < n; ++ i){
        if (ccnt[bb[i]] <= i){
            puts("No");
            return 0;
        }
        if (ccnt[bb[i]] > i + 1){
            flag = true;
        }
    }
    if (flag){
        puts("Yes");
        return 0;
    }
    for (int i = 0; i < n; ++ i){
        p[i] = {a[i], b[i]};
    }
    std::sort(p, p + n);
    for (int i = 0; i < n; ++ i){
        c[i] = p[i].second;
    }
    std::sort(c, c + n);
    for (int i = 0; i < n; ++ i){
        p[i].second = std::lower_bound(c, c + n, p[i].second) - c;
    }
    int x = 0;
    cnt = 0;
    while (!vis[x]){
        vis[x] = true;
        x = p[x].second;
        ++ cnt;
    }
    puts(cnt == n ? "No" : "Yes");
    return 0;
}

