  vector<int> V(N, -1);
  for (auto i = 0; i < N; i++)
  {
    auto it{lower_bound(A.begin(), A.end(), old_A[i])};
    int num(it - A.begin());
    V[num] = i;
  }
  for (auto i = 0; i < N; i++)
  {
    if (V[i] == -1)
    {
      Yes();
    }
  }
