{
	int N;
	scanf("%d", &N);
	std::vector<std::pair<int, int>> AB(N);
	for (auto& e: AB) scanf("%d", &e.first);
	for (auto& e: AB) scanf("%d", &e.second);
	std::vector<std::pair<int, int>> B(N);
	std::sort(AB.begin(), AB.end());
	for (int i{}; i < N; i++)
		B[i] = {AB[i].second, i};
	std::sort(B.begin(), B.end());

	// そもそもN-1回で可能か
	for (int i{}; i < N; i++)
		if (AB[i].first > B[i].first)
			return false;

	for (int i{}; i < N - 1; i++)
		if (AB[i].first <= B[i + 1].first)
			return true;

	std::vector<bool> visited(N);
	for (int i{}; !visited[i]; i = B[i].second)
		visited[i] = true;
	for (const auto& e: visited)
		if (!e)
			return true;
	for (int i{}; i < N; i++)
		if (AB[B[i].second].second >= AB[i].first)
			return true;
	return false;
}

