void sort_tuple(vector<ll> &as, vector<ll> &bs) {
    int n = as.size();
    vector<P> ps(n);
    rep(i, n) ps[i].first = bs[i];
    rep(i, n) ps[i].second = as[i];

    sort(ps.begin(), ps.end());

    rep(i, n) as[i] = ps[i].second;
    rep(i, n) bs[i] = ps[i].first;
}

int main() {
    int n;
    cin >> n;
    vector<ll> as(n), bs(n);
    rep(i, n) cin >> as[i];
    rep(i, n)cin >> bs[i];

    if (!check(as, bs)) {
        cout << "No" << endl;
        ret();
    }

    sort_tuple(as, bs);

    map<ll, int> index;
    rep(i, n) {
        assert(index.find(as[i]) == index.end());
        index[as[i]] = i;
    }
    assert(index.size() == n);

    multiset<ll> wait;
    for (ll l : as) wait.insert(l);

    int count = 0;

    rep(i, n) {
        ll o = as[i];

        if (as[i] <= bs[i]) {
            wait.erase(wait.find(o));
            continue;
        }


        ll sp = *wait.begin();
        ll spi = index[sp];

        swap(as[i], as[spi]);
        swap(index[o], index[sp]);

        assert(as[i] <= bs[i]);

        wait.erase(wait.find(sp));
        count++;

    }

    cout << (n - 2 >= count ? "Yes" : "No") << endl;

}

