  for (int i = 1; i < n; ++i) {
    if (p[i] <= q[i - 1]) return true;
  }
  return false;
}

bool iscycle() {
  vector<PP> p;
  vector<PP> q;
  for (int i = 0; i < n; ++i) {
    p.push_back(PP(a[i], i));
    q.push_back(PP(b[i], i));
  }
  sort(p.begin(), p.end());
  sort(q.begin(), q.end());

  vector<int> mp(n);
  for (int i = 0; i < n; ++i) {
    mp[p[i].second] = q[i].second;
  }

  int c = 0;
  int cnt = 0;
  do {
    c = mp[c];
    ++cnt;
  } while(c != 0);

  return cnt == n;
}

