const int maxn = 110000;

int id[maxn];
int a[maxn], b[maxn];
int ta[maxn], to[maxn], from[maxn];

struct Level {
	int id, val, lvl;
	Level(int id = 0, int val = 0, int lvl = 0) : id(id), val(val), lvl(lvl) {}
} l[maxn];

inline bool operator < (const Level& lhs, const Level& rhs) {
	if(lhs.lvl != rhs.lvl) return lhs.lvl < rhs.lvl;
	return lhs.id < rhs.id;
}

inline bool operator > (const Level& lhs, const Level& rhs) {
	return lhs.id < rhs.id;
}

priority_queue<Level, vector<Level>, greater<Level>> q;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	int n; cin >> n;
	for(int i = 0; i < n; ++ i) cin >> ta[i];
	for(int i = 0; i < n; ++ i) cin >> b[i];
	for(int i = 0; i < n; ++ i) id[i] = i;
	sort(id, id + n, [&](const int& i, const int& j) {
		return b[i] < b[j];
	});
	sort(b, b + n);
	for(int i = 0; i < n; ++ i) a[i] = ta[id[i]];
	for(int i = 0; i < n; ++ i) id[i] = i;
	sort(id, id + n, [&](const int& i, const int& j) {
		return a[i] < a[j];
	});
	int x = 0;
	int ff = 1;
	for(int i = 0; i < n; ++ i) {
		if(b[x] < a[id[i]]) {
			++ x; -- i;
			if(x == n) {
				ff = 0;
				break;
			}
			continue;
		}
		l[i] = Level(id[i], a[id[i]], x);
	}
	sort(l, l + n);
	for(int i = 0; i < n; ++ i) {
		to[l[i].id] = i;
		from[i] = l[i].id;
	}
	bool flag = false;
	if(ff) {
		int cnt = n - 2, st = 0;
		for(int i = 0; i < n; ++ i) {
			if(a[i] <= b[i]) {
				sort(a + i + 1, a + n);
				int f = 1;
				for(int j = i + 1; j < n; ++ j) {
					if(a[j] > b[j]) f = 0;
				}
				if(f) flag = true;
				break;
			}
			// find the last value which is not larger than b[i]
			for(; st < n && l[st].lvl <= i; ++ st) {
				q.push(l[st]);
			}
			if(q.empty()) {
				break;
			}
			auto cur = q.top(); q.pop();
			swap(a[i], a[cur.id]);
			l[to[i]].id = cur.id;
			assert(l[to[i]].lvl > i);
			if(cnt == 0) {
				break;
			}
			-- cnt;
		}
	}
	cout << (flag ? "Yes\n" : "No\n");
	return 0;
}

