bool solve1(int n, vector<int> a, const vector<int> & b, int cnt) {
// dump(a);
// dump(b);
// dump(cnt);
    assert (is_sorted(ALL(b)));
    vector<int> sorted_a = a;
    sort(ALL(sorted_a));
    REP (i, n) {
        if (sorted_a[i] > b[i]) {
            return false;
        }
    }
    if (n == 0) return true;

    vector<int> order(n);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) {
        return a[i] < a[j];
    });
    vector<bool> fixed(n);
    REP (i, n) {
        if ((i == 0 or b[i - 1] < sorted_a[i]) and (i == n - 1 or b[i] < sorted_a[i + 1])) {
            fixed[i] = true;
        }
    }
    REP (i, n) if (fixed[i]) {
        if (a[i] != sorted_a[i] and a[order[i]] == sorted_a[i]) {
            -- cnt;
            swap(a[i], a[order[i]]);
        }
    }
    if (cnt < 0) return false;
    vector<int> na;
    vector<int> nb;
    REP (i, n) {
        if (fixed[i] and a[i] == sorted_a[i]) continue;
        na.push_back(a[i]);
        nb.push_back(b[i]);
    }
// dump(sorted_a);
// dump(fixed);
    if (na.size() < a.size()) {
        return solve1(na.size(), na, nb, cnt);
    }

    return true;
}

bool solve(int n, const vector<int> & a, const vector<int> & b) {
    vector<int> order(n);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) {
        return make_pair(b[i], a[i]) < make_pair(b[j], a[j]);
    });
    vector<int> na(n);
    vector<int> nb(n);
    REP (i, n) {
        na[i] = a[order[i]];
        nb[i] = b[order[i]];
    }
    return solve1(n, na, nb, n - 2);
}

