    int n; cin >> n;
    vector<int> a(n), b(n);
    cin >> a >> b;

    vector<int> orda(n), ordb(n);
    iota(orda.begin(), orda.end(), 0);
    iota(ordb.begin(), ordb.end(), 0);
    sort(orda.begin(), orda.end(), [&](int i,int j){
            return a[i] < a[j];
            });
    sort(ordb.begin(), ordb.end(), [&](int i,int j){
            return b[i] < b[j];
            });

    // ソートして無理ならNo
    for (int i = 0; i < n; ++i) {
        if (b[ordb[i]] < a[orda[i]]) {
            printf("No\n");
            return 0;
        }
    }

    // 置換が分かれていたらYes
    vector<int> transition(n);
    for (int i = 0; i < n; ++i) {
        transition[ordb[i]] = orda[i];
    }
    int now = 0, cnt = 1;
    do {
        now = transition[now];
        ++cnt;
    } while (now != 0);

    if (cnt < n) {
        printf("Yes\n");
        return 0;
    }

    // 入れ替え可能ならYes
    for (int i = 0; i < n-1; ++i) {
        if (b[ordb[i]] >= a[orda[i+1]]) {
            printf("Yes\n");
            return 0;
        }
    }
    printf("No\n");

    return 0;
}

