using namespace std;
class UnionFind {
  public:
    vector<int> parent;
    UnionFind(int n) {
        parent = vector<int>(n, -1);
    }
    int root(int a) {
        if (parent[a] < 0) return a;
        return parent[a] = root(parent[a]);
    }
    int size(int a) {
        return -parent[root(a)];
    }
    bool is_connected(int a, int b) {
        return root(a) == root(b);
    }
    bool connect(int a, int b) {
        a = root(a);
        b = root(b);
        if (a == b) {
            return false;
        }
        if (size(a)<size(b)) swap(a, b);
        parent[a] += parent[b];
        parent[b] = a;
        return true;
    }
};
int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (auto & a : A) cin >> a;
    for (auto & b : B) cin >> b;
    vector<int> AS = A, BS = B;
    sort(AS.begin(), AS.end());
    sort(BS.begin(), BS.end());
    map<int, int> AB, BI;
    UnionFind UF(N);
    for (int i = 0; i < N; ++i) {
        if (BS[i] < AS[i]) {
            puts("No");
            return 0;
        }
        AB[AS[i]] = BS[i];
        BI[B[i]] = i;
    }
    for (int i = 0; i < N; ++i) {
        UF.connect(i, BI[AB[A[i]]]);
    }
    for (int i = 1; i < N; ++i) {
        if (BS[i-1] >= AS[i]) {
            puts("Yes");
            return 0;
        }
        if (UF.root(i) != UF.root(i-1)) {
            puts("Yes");
            return 0;
        }
    }
    puts("No");
    return 0;
}

