        edge[V2[i].second] = V1[i].second;
    }
    if (!OK1) return !printf("No\n");
    if (OK2) return !printf("Yes\n");
    int cnt = 0;
    for (int i = 0; i < N; i++) {
        if (visit[i]) continue;
        cnt++;
        int cur = i;
        while (!visit[cur]) {
              visit[cur] = 1;
              //printf("i = %d cur = %d\n", i, cur);
              //printf("nxt = %d\n", edge[cur]);
              cur = edge[cur];
        }
    }
    if (cnt > 1) puts("Yes");
    else puts("No");
    return 0;
}

