bool solve() {
  bool ch = 0, allok = 1;
  ap = a;
  sort(ap.begin(), ap.end());
  sort(b.begin(), b.end());
  for(int i = 0; i < n; ++i) {
    if(ap[i] > b[i]) return 0;
    if(ap[i] != a[i]) allok = 0;
    if(i != 0 && ap[i] <= b[i - 1]) ch = 1;
  }
  return ch || allok;
}

