using namespace std;

using ll = long long;

struct Record
{
  ll v;
  ll i;
  bool operator<(const Record &rhs) const
  {
    return v < rhs.v;
  }
};

int main()
{
  int n;
  vector<Record> a;
  vector<int> b; // bはソートしたものにする

  cin >> n;
  int v;
  for (ll i = 0; i < n; ++i)
  {
    cin >> v;
    a.push_back({v, i});
  }
  for (ll i = 0; i < n; ++i)
  {
    cin >> v;
    b.push_back(v);
  }
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());

  // N-2 の制限を考えずに自由に並び替えたばあい
  for (int i = 0; i < n; ++i)
  {
    if (a[i].v > b[i])
    {
      // No が確定
      cout << "No" << endl;
      return 0;
    }
  }

  // サイクル数が1じゃないかどうか調べる
  const long long size = 1e5 + 10;
  bitset<size> visited(0);
  int cycles = 0;
  for (int i = 0; i < n; ++i)
  {
    //cout << "a v:" << a[i].v << " i:" << a[i].i << endl;
    if (visited.test(i))
    {
      continue;
    }

    int crnt = i;
    while (!visited.test(crnt))
    {
      visited.set(crnt);
      crnt = a[crnt].i;
    }
    cycles++;
  }

  //cout << "cycles : " << cycles << endl;
  if (cycles >= 2)
  {
    cout << "Yes" << endl;
    return 0;
  }
  for (int i = 0; i < n - 1; ++i)
  {
    if (a[i + 1].v <= b[i])
    {
      cout << "Yes" << endl;
      return 0;
    }
  }

  cout << "No" << endl;
  return 0;
}

