        if (ai>bi) {
            c++;
            bool flag2=false;
            auto itr = lower_bound(b.begin(),b.end(),ai);
            for (int j=itr-b.begin();j<n;j++) {
                if (p1[j].second<=bi) {
                    swap(p1[i].second,p1[j].second);
                    flag2=true;
                    break;
                }
            }
            if (!flag2) {
                for (int j=itr-b.begin();j<n;j++) {
                    if (a[j]<=p1[i].first) {
                        swap(p1[i].second,p1[j].second);
                        flag2=true;
                        break;
                    }
                }
            }
            if (!flag2) flag=false;
        }
    }

    if (flag && c<=n-2) cout << "Yes" << endl;
    else cout << "No" << endl;

}

