        cin >> p[i].second;
        p[i].second *= -1;
    }
    for(int i = 0; i < n; i++){
        cin >> p[i].first;
    }
    priority_queue<pair<int, int>> success, fail;
    for(auto&& i : p){
        if(i.first == -i.second) continue;
        if(i.first > -i.second){
            success.push(i);
        }else{
            fail.push(make_pair(-i.second, i.first));
        }
    }
    int cnt = 0;
    while(!success.empty() && cnt < n - 2 && !fail.empty()){
        auto s = success.top();
        success.pop();
        if(s.first < fail.top().first){
            cout << "No\n";
            return 0;
        }
        if(-s.second >= fail.top().first){
            continue;
        }
        auto a = fail.top();
        fail.pop();
        swap(a.first, s.second);
        a.first = -a.first;
        s.second = -s.second;
        success.push(s);
        if(a.first < a.second){
            success.push(make_pair(a.second, -a.first));
        }else if(a.second > a.first){
            fail.push(a);
        }
        cnt++;
    }
    if(fail.empty()){
        cout << "Yes\n";
    }else{
        cout << "No\n";
    }
