struct UnionFind {
    vector<int> A;
    UnionFind(int n) : A(n, -1) {}
    int find(int x) {
        if (A[x] < 0) return x;
        return A[x] = find(A[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (A[x] > A[y]) swap(x, y);
        A[x] += A[y];
        A[y] = x;
    }
    int ngroups() {
        int ans = 0;
        for (auto a : A) if (a < 0) ans++;
        return ans;
    }
};
void yes() { cout << "Yes\n"; exit(0); }
void no() { cout << "No\n"; exit(0); }
int main() {
    int N; cin >> N;
    vector<int> A(N); for (auto &a : A) cin >> a;
    vector<int> B(N); for (auto &b : B) cin >> b;
    vector<int> I(N); iota(begin(I), end(I), 0);
    vector<int> J(N); iota(begin(J), end(J), 0);
    sort(begin(I), end(I), [&](int i0, int i1) { return A[i0] < A[i1]; });
    sort(begin(J), end(J), [&](int j0, int j1) { return B[j0] < B[j1]; });
    for (int i = 0; i < N; i++) {
        if (A[I[i]] > B[J[i]]) {
            no();
        }
    }
    for (int i = 0; i < N; i++) {
        if (A[i] <= B[i]) {
            yes();
        }
    }
    UnionFind uf(N);
    for (int i = 0; i < N; i++) {
        uf.unite(i, I[i]);
    }
    if (uf.ngroups() == 1) {
        no();
    } else {
        yes();
    }
    return 0;
}

