  for (size_t i = 0; i < n; i++) {
    scanf("%d", &A[i]);
  }

  for (size_t i = 0; i < n; i++) {
    scanf("%d", &B[i]);
  }
  qsort(/*配列*/A, /*要素数*/n, /*要素のバイト数*/sizeof (A[0]), /*比較方法*/compare);
  qsort(/*配列*/B, /*要素数*/n, /*要素のバイト数*/sizeof (B[0]), /*比較方法*/compare);

  for (size_t i = 0; i < n; i++) {
    if (A[i] > B[i]) {
      count++;
    }
  }
  if (A[n-1] > B[n-1]) {
    count = -1;
  }
  if (count >= 0 && count <= n-2) {
    printf("Yes\n" );
  }else printf("No\n" );

  return 0;
}

