#include <bits/stdc++.h>

using namespace std;

constexpr int N = 100000;

int a[N + 1];
int b[N + 1];
int sa[N + 1];
int sb[N + 1];
int pa[N + 1];
int pb[N + 1];
bool seen[N + 1];

bool comp_sa(int x, int y) {
	return sa[x] < sa[y];
}

bool comp_b(int x, int y) {
	return b[x] < b[y];
}

int main() {
	int n, i;

	scanf("%d", &n);

	for (i = 1; i <= n; i++) {
		scanf("%d", a + i);
		pa[i] = i;
	}

	for (i = 1; i <= n; i++) {
		scanf("%d", b + i);
		pb[i] = i;
	}

	// Applying permutation to sort b.
	sort(pb + 1, pb + 1 + n, comp_b);

	for (i = 1; i <= n; i++) {
		sb[i] = b[pb[i]];
		sa[i] = a[pb[i]];
	}

	// Getting needed permutation.
	sort(pa + 1, pa + 1 + n, comp_sa);

	for (i = 1; i <= n; i++) {
		if (sa[pa[i]] > sb[i]) {
			break;
		}
	}

	if (i <= n) { // Not even sorting.
		printf("No\n");
		return 0;
	}

	for (i = 2; i <= n; i++) {
		if (sa[pa[i - 1]] <= sb[i] and sa[pa[i]] <= sb[i - 1]) {
			break;
		}
	}

	if (i <= n) { // Has multiple solution permutations.
		printf("Yes\n");
		return 0;
	}

	i = 1;

	while (!seen[i]) {
		seen[i] = true;
		i = pa[i];
	}

	for (i = 1; i <= n; i++) {
		if (!seen[i]) {
			break;
		}
	}

	if (i <= n) {
		printf("Yes\n");
	}
	else { // Permutation is one big cycle of order n.
		printf("No\n");
	}

	return 0;
}


