	sort(A, A + N);
	sort(B, B + N);
	for (int i = 0; i < N; i++) {
		if (A[i].first > B[i].first) return false;
	}
	for (int i = 0; i+1 < N; i++) {
		if (A[i+1].first <= B[i].first) return true;
