int a[MAXN], b[MAXN];

pii t[4 * MAXN];

#define left v<<1,tl,tm
#define right v<<1|1,tm+1,tr

void upd(int v) {
    t[v] = min(t[v << 1], t[v << 1 | 1]);
};

void build(int v, int tl, int tr) {
    if (tl == tr) {
        t[v] = {a[tl], tl};
    } else {
        int tm = (tl + tr) >> 1;
        build(left);
        build(right);
        upd(v);
    }
}


pii get(int v, int tl, int tr, int l, int r) {
    if (l > tr || r < tl)
        return {inf_int, inf_int};
    if (l <= tl && tr <= r) {
        return t[v];
    } else {
        int tm = (tl + tr) >> 1;
        return min(get(left, l, r), get(right, l, r));
    }
}

void update(int v, int tl, int tr, int pos, int val) {
    if (tl == tr) {
        t[v] = {val, pos};
    } else {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
            update(left, pos, val);
        else
            update(right, pos, val);
        upd(v);
    }
}


