class Bit {
  ll n;
  vector<ll> v;
public:
  Bit(ll sz) : n((sz+1)*2), v((sz+1)*2, 0) {}
  // v[pos] += val
  void add(ll pos, ll val) {
    ++pos;
    while (pos < n) {
      v[pos] += val;
      pos += pos & -pos;
    }
  }
  // [l, r)
  ll find(ll l, ll r) {
    return find(r) - find(l);
  }
  // [0, pos)
  ll find(ll pos) {
    ll res = 0;
    while (pos >= 1) {
      res += v[pos];
      if (pos == 0) break;
      pos -= pos & -pos;
    }
    return res;
  }
};

// 転倒数を数える
ll inversion(const vector<ll>& a) {
  const ll n = a.size();
  map<ll, vector<ll>> m;
  rep(i, n) m[-a[i]].pb(i);
  Bit bit(n);
  ll res = 0;
  each(p, m) {
    each(i, p.second) {
      res += bit.find(i);
    }
    each(i, p.second) {
      bit.add(i, 1);
    }
  }
  return res;
}

