                isOk = true;
                break;
            }
            else if(i < temp){
                int cnt = leftOkAcc[temp + 1] - leftOkAcc[i + 1];
                if(cnt == temp - i){
                    isOk = true;
                    break;
                }
            }
            else{ // i > temp
                int cnt = rightOkAcc[i] - rightOkAcc[temp];
                if(cnt == i - temp){
                    isOk = true;
                    break;
                }
            }
        }
    }

    if(isOk){
        cout << "Yes" << endl;
    }
    else{
        cout << "No" << endl;
    }

    return 0;
}

