		if (arr[i].first > brr[i].first)
		{
			cout << "No" << endl;
			return 0;
		}
	}
	dp[0] = -1;
	for (int i = 1; i < N; i++)
	{
		if (arr[i].first <= brr[i - 1].first) dp[i] = dp[i - 1] < 0 ? i : dp[i - 1];
