template<typename T>
struct SegmentTree{
private:
    int n;
    T E;
    vector<T> node;
    inline void updatef(T& x,T& y){
        x = y;
        //x += y;
        //x = max(x,y);
        //x = min(x,y);
    }
    inline T queryf(T& x,T& y){
        return min(x,y);
    }

public:
    SegmentTree(int sz,T E_):E(E_){
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
    }

    SegmentTree(vector<T>& A,T E_):E(E_){
        int sz=A.size();
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
        rep(i,sz)node[i+n-1]=A[i];
        for(int i=n-2;i>=0;--i){
            node[i]=queryf(node[2*i+1], node[2*i+2]);
        }
    }
    void update(int k,T x){
        k+=n-1;
        updatef(node[k],x);
        while(k>0){
            k=(k-1)/2;
            node[k]=queryf(node[2*k+1], node[2*k+2]);
        }
    }
       //[a,b)での和を返す
    T get(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return E;
        if(a<=l&&r<=b)return node[k];
        T xl=get(a,b,2*k+1,l,(l+r)/2);
        T xr=get(a,b,2*k+2,(l+r)/2,r);
        return queryf(xl, xr);
    }

};
int main(){
    int n;
    cin>>n;
    vector<int> a(n),b(n);
    rep(i,n)cin>>a[i];
    rep(i,n)cin>>b[i];
    vector<int> as = a, bs = b;
    sort(as.begin(),as.end());
    sort(bs.begin(),bs.end());
    rep(i,n){
        if(as[i]>bs[i]){
            cout<<"No"<<endl;
            return 0;
        }
    }
    rep(i,n){
        a[i] = lower_bound(as.begin(), as.end(),a[i])-as.begin();
        b[i] = lower_bound(bs.begin(), bs.end(),b[i])-bs.begin();
    }
    vector<int> ord(n);
    rep(i,n)ord[i]=i;
    sort(ord.begin(),ord.end(),[&](int x,int y){
        return b[x]<b[y];
    });
    vector<int> c(n);
    rep(i,n)c[i]=a[ord[i]];
    SegmentTree<int> sg(c,inf);
    int cnt = 0;
    rep(i,n){
        if(bs[i]>=as[c[i]])continue;
        ++cnt;
        int ok = i, ng = n;
        while(ng-ok>1){
            int mid = (ok+ng)/2;
            int idx = sg.get(mid,n);
            if(bs[i]>=as[idx])ok=mid;
            else ng = mid;
        }
        swap(c[i],c[ok]);
        sg.update(ok,c[ok]);
    }
    if(cnt<n-1)cout<<"Yes"<<endl;
    else cout<<"No"<<endl;
    return 0;
}

