template<class T>
class SegmentTree {

public:
    /**
     * @param N size
     * @param e identity element
     * @param operation operation for query
     * @param updater operation for update
     */
    SegmentTree(size_t N, T e, function<T(T, T)> operation, function<T(T, T)> updater)
            : e(e), operation(std::move(operation)), updater(move(updater)) {
        n = 1;
        while (n < N) {
            n *= 2;
        }
        data = vector<T>(2 * n - 1, e);
    }

    /**
     * iの値をxに更新
     * @param i index ( 0-indexed )
     * @param x  value
     */
    void update(int i, T x) {
        i += n - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    /**
     * [a, b)の区間でクエリを実行
     */
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    /**
     * 添字でアクセス
     * @param i index ( 0-indexed )
     */
    T operator[](int i) {
        return data[i + n - 1];
    }

private:
    int n;
    vector<T> data;
    T e;
    function<T(T, T)> operation;
    function<T(T, T)> updater;

    T query(int a, int b, int k, int l, int r) {
        // 交差しない
        if (r <= a || b <= l) return e;
        // 区間 [a, b) に l, r が含まれる
        if (a <= l && r <= b) return data[k];
        // 左の子
        T c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        // 右の子
        T c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return operation(c1, c2);
    }
};

void Main() {
    int N, M;
    cin >> N >> M;
    vector<pair<int, pair<int, ll>>> items;
    SegmentTree<ll> segmentTree(N, INF, [](ll a, ll b) { return min(a, b); }, [](ll a, ll b){ return min(a, b); });
    rep(i, M) {
        int l, r;
        ll c;
        cin >> l >> r >> c;
        items.push_back({r, {l, c}});
    }
    sort(items.begin(), items.end());

    vector<ll> dp(N, INF);
    dp[0] = 0;
    segmentTree.update(0, 0);
    rep(i, M) {
        int r = items[i].first;
        int l = items[i].second.first;
        ll c = items[i].second.second;
        l--;
        r--;
        ll x = segmentTree.query(l, r + 1);
        ll tmp = x + c;
        dp[r] = min(dp[r], tmp);
        segmentTree.update(r, tmp);
    }
    if (dp[N - 1] != INF) {
        cout << dp[N - 1] << '\n';
    } else {
        cout << -1 << '\n';
    }
}

