int n;

bool solve(void){
    vector<int> a(n);
    vector<int> ia;
    rep(i, n){
        cin >> a[i];
        ia.emplace_back(i);
    }
    sort(ia.begin(), ia.end(), [&](int i, int j){ return a[i] < a[j]; });

    vector<int> b(n);
    vector<int> ib;
    rep(i, n){
        cin >> b[i];
        ib.emplace_back(i);
    }
    sort(ib.begin(), ib.end(), [&](int i, int j){ return b[i] < b[j]; });

    rep(i, n){
        if(a[ia[i]] > b[ib[i]]){
            return false;
        }
    }

    CoordinateCompression<int> ca(a), cb(b);

    if(ca.size() < n || cb.size() < n){
        return true;
    }

    vector<int> rev(n);
    rep(i, n){
        rev[cb.get(b[i])] = i;
    }

    UnionFind uf(n);
    rep(i, n){
        uf.unite(i, rev[ca.get(a[i])]);
    }

    return uf.size() != 1;
}

