  REP(i,N)
    {
      Q[i] = make_pair(P[i].first,i);
    }

  sort(ALL(Q));

  vector<int> ito(N);

  REP(i,N)
    {
      if( P[i].second < Q[i].first )
	{
	  puts("No");
	  return 0;
	}

      ito[Q[i].second] = i;
    }

  vector<int> used(N,false);
  vector<vector<int> > G(N);
  int mx = 0;
  REP(i,N)
    {
