    return b[i] < b[j];    
  });
  sort(oa.begin(), oa.end(), [&](int i, int j) {
    return a[i] < a[j];    
  });

  vector<int> pa(n), pb(n);
  for (int i = 0; i < n; ++i) {
    pa[oa[i]] = i;
    pb[ob[i]] = i;
  }


  for (int i = 0; i < n; ++i) {
    if (a[oa[i]] > b[ob[i]]) {
      cout << "No\n";
      return 0;
    }
  }

  if (n == 2) {
    for (int i = 0; i < n; ++i) {
      if (a[i] > b[i]) {
        cout << "No\n";
        return 0;
      }
    }
  }

  vector<int> allow(n, -1);
  for (int i = n - 1; i >= 1; --i) {
    if (a[oa[i]] > b[ob[i - 1]]) {
      allow[i] = 0;
    } else {
      allow[i] = 1;
      if (i + 1 < n)
        allow[i] += allow[i + 1];
    }
  }

  for (int i = 0; i < n; ++i) {
    if (a[i] > b[i]) continue;

    int p1 = pa[i];
    int p2 = pb[i];
