    for (int i = 0; i < N; i++) {
        cin >> A.at(i);
    }

    for (int i = 0; i < N; i++) {
        cin >> B.at(i);
    }

    std::vector<int> sortA=A;
    std::vector<int> sortB=B;
    std::sort(sortA.begin(), sortA.end());
    std::sort(sortB.begin(), sortB.end());
    for (int i = 0; i < N; i++) {
        if (sortA.at(i) > sortB.at(i)) {
            cout << "No" << endl;
            return 0;
        }
    }

    std::vector<int> ind_A(N);
    std::vector<int> copy_A = A;
    for (auto i = 0; i < N; i++) {
        auto iter = std::find(copy_A.begin(), copy_A.end(), sortA.at(i));
        auto index = std::distance(copy_A.begin(), iter);
        ind_A.at(i) = index;
        copy_A.at(index) = -1;
    }

    auto next_i = 0;
    for (auto i = 0; i < N; i++) {
        auto tmp_i = ind_A.at(next_i);
        ind_A.at(next_i) = -1;
        next_i = tmp_i;

        if (next_i == -1) {
            cout << "Yes" << endl;
            return 0;
        }
    }

