        rep(i, N) {
            ba.push_back({ b[i],a[i] });
        }
    }
    sort(ba.begin(), ba.end());
    auto f = [](pii a, pii b) {return max(a, b); };
    SegmentTree<pii> st(f, { -1,-1 });
    {
        vector<pair<int, int>> a;
        rep(i, N) {
            a.push_back({ ba[i].second,i });
        }
        st.build(a);
    }

    bool ignore = false;
    rep(i, N - 2) {
        int r = N - 1 - i;
        auto maxv = st.query(r, r + 1);
        auto minv = st.query(0, r);
        if (minv.first > maxv.first) {
            int pl = minv.second;
            int pr = maxv.second;
            swap(ba[pl].second, ba[pr].second);

            pii vl = { maxv.first,pl };
            pii vr = { minv.first,pr };
            st.set_val(pl, vl);
            st.set_val(pr, vr);
        }
        else {
            ignore = true;
        }
    }
