template <typename T>
struct BIT {
    vector<T> a;
    function<T(T,T)> bin_op;
    const T init;
    explicit BIT(int n, function<T(T,T)> bin_op, T init=T()):bin_op(bin_op), init(init) {
        a.assign(n + 1, init);
    }

    T prefix(int x) {
        auto res = init;
        while (x) {
            res = bin_op(a[x], res);
            x -= x & -x;
        }
        return res;
    }
    void modify(int x, T v) {
        while (x < (int)a.size()) {
            a[x] = bin_op(a[x], v);
            x += x & -x;
        }
    }
    void clear(){
        fill(a.begin(), a.end(), init);
    }
};

