vi get_mu(int n) {
    assert(n > 0);
    vi mu(n + 1);
    vi min_p(n + 1);
    vi prime;
    mu[1] = 1;
    rng (i, 2, n + 1) {
        if (!min_p[i]) {
            prime.pb(i);
            min_p[i] = i;
            mu[i] = -1;
        }
        FOR (p, prime) {
            if (p > min_p[i]) {
                break;
            }
            int t = p * i;
            if (t > n) break;
            min_p[t] = p;
            mu[t] = p == min_p[i] ? 0 : -mu[i];
        }
    }
    return mu;
}

template<typename num>
num fp(num x, ll n, int mod) { //fast power: hat off to quailty
    if (n < 0) {
        x = inverse(x, mod);
        n = -n;
    }
    num ans = 1;
    while (n) {
        if (n & 1) ans *= x;
        n /= 2;
        x *= x;
    }
    return ans;
}

