	for(int i = 0; i < N; i++)
		scanf("%d", &A[i]);
	for(int i = 0; i < N; i++)
		scanf("%d", &B[i]);

	vector < pair <int, int> > v;
	for(int i = 0; i < N; i++)
		v.push_back(make_pair(B[i], A[i]));
	sort(v.begin(), v.end());

	for(int i = 0; i < N; i++){
		A[i] = v[i].second;
		B[i] = v[i].first;
	}

	set < pair <int, int> > w;
	for(int i = 0; i < N; i++)
		w.insert(make_pair(A[i], i));

	set <int> s;

	int cnt = 0;
	for(int i = 0; i < N; i++){
		while(!w.empty() && w.begin()->first <= B[i]){
			s.insert(w.begin()->second);
			w.erase(w.begin());
		}

		if(A[i] <= B[i]){
			s.erase(i);
			continue;
		}

		if(s.empty()){
			printf("No\n");
			return 0;
		}

		w.erase(make_pair(A[i], i));
		w.insert(make_pair(A[i], *prev(s.end())));

		swap(A[i], A[*prev(s.end())]);

		s.erase(prev(s.end()));

		cnt++;
	}

	if(cnt <= N - 2)printf("Yes\n");
	else printf("No\n");

	return 0;
}

