int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];
    vector<int> As = A, Bs = B;
    sort(As.begin(), As.end());
    sort(Bs.begin(), Bs.end());
    for (int i = 0; i < N; i++) {
        if (As[i] > Bs[i]) {
            cout << "No" << endl;
            return 0;
        }
    }
    for (int i = 0; i < N - 1; i++) {
        if (As[i] == As[i+1] || As[i+1] <= Bs[i]) {
            cout << "Yes" << endl;
            return 0;
        }
    }
    unordered_map<int, int> mp;
    for (int i = 0; i < N; i++) mp[As[i]] = i;
    for (int i = 0; i < N; i++) A[i] = mp[A[i]];
    vector<bool> visited(N);
    int cnt = 0;
    for (int i = 0; i < N; i++) {
        if (visited[i] || A[i] == i) continue;
        int size = 0;
        int j = i;
        while (!visited[j]) {
            visited[j] = true;
            j = A[j];
            size++;
        }
        if (size) cnt += size - 1;
    }
    cout << (cnt <= N - 2 ? "Yes" : "No") << endl;
}

