int main()
{
  int n;
  scanf("%d", &n);
  int a[100000];
  int b[100000];
  using pair = std::pair<int, int>;
  std::vector<pair> c;
  std::vector<pair> bad;
  for (int i = 0; i < n; ++i)
  {
    scanf("%d", a + i);
    c.emplace_back(a[i], -1);
  }
  for (int i = 0; i < n; ++i)
  {
    scanf("%d", b + i);
    c.emplace_back(b[i], 1);
    if (b[i] < a[i]) bad.emplace_back(a[i], b[i]);
  }
  std::sort(c.begin(), c.end(), std::greater<pair>());
  if (c[0].second < 0)
  {
    puts("No");
    return 0;
  }
  long long count = 0;
  for (const auto& p : c)
  {
    count += p.second;
    if (count < 0)
    {
      puts("No");
      return 0;
    }
  }

  for (const auto& ba : bad)
  {
    int count = 0;
    bool good = true;
    for (const auto& p : c)
    {
      if ((p.first == ba.first && p.second < 0) || (p.first == ba.second && p.second > 0)) continue;
      count += p.second;
      if (count < 0)
      {
        good = false;
        break;
      }
    }
    if (good)
    {
      puts("Yes");
      return 0;
    }
  }
  puts("No");
  return 0;
}

