int main(int argc, char *argv[]) {
  i64 N, i;
  cin >> N;
  vi A0(N), B0(N), A(N), B(N);
  REP(0, N, i)
    cin >> A0[i];
  REP(0, N, i)
    cin >> B0[i];

  // B is increasing
  vector<pi> Bp(N);
  REP(0, N, i)
    Bp[i] = make_pair(B0[i], i);
  sort(all(Bp));

  REP(0, N, i) {
    B[i] = Bp[i].first;
    A[i] = A0[Bp[i].second];
  }

  i64 ans = 0;
  set<pi> As;
  REP(0, N, i) {
    As.insert(make_pair(A[i], i));
  }
  //
  REP(0, N, i) {
    //cout << As.size() << endl;
    if(A[i] > B[i]) {
      // find max j which satisfies A[j] <= B[i]
      // find min j A[j+1] > B[i]
      auto lb = As.lower_bound(make_pair(B[i], N));
      if(lb == As.begin()) {
	cout << "No" << endl;
	return 0;
      }
      lb--;
      i64 j = lb->second;
      As.erase(As.find(make_pair(A[i], i)));
      As.erase(As.find(make_pair(A[j], j)));
      As.insert(make_pair(A[i], j));
      swap(A[i], A[j]);
      //cout << "swap " << i << " " << j << endl;
      ans++;

    }
    else {
      As.erase(As.find(make_pair(A[i], i)));
    }    
  }

  cout << ((ans <= (N - 2)) ? "Yes" : "No") << endl;
  return 0;
}

