int tin[N<<4],tout[N<<4],temp;

long long dis[N<<4];



void build(int k,int l,int r){

	if(l==r){

		tin[k]=tout[k]=l;

		return ;

	}

	int mid=(l+r)>>1;

	build(k<<1,l,mid);

	build(k<<1|1,mid+1,r);

	tin[k]=++temp;tout[k]=++temp;

	add(tout[k<<1],tout[k],0);

	add(tout[k<<1|1],tout[k],0);

	add(tin[k],tin[k<<1],0);

	add(tin[k],tin[k<<1|1],0);

}



void update1(int k,int l,int r,int L,int R,int u,int w){

	if(L<=l&&r<=R){

		add(u,tin[k],w);

		return ;

	}

	int mid=(l+r)>>1;

	if(mid>=L){

		update1(k<<1,l,mid,L,R,u,w);

	}

	if(mid<R){

		update1(k<<1|1,mid+1,r,L,R,u,w);

	}

}



void update2(int k,int l,int r,int L,int R,int u,int w){

		if(L<=l&&r<=R){

		add(tout[k],u,w);

		return ;

	}

	int mid=(l+r)>>1;

	if(mid>=L){

		update2(k<<1,l,mid,L,R,u,w);

	}

	if(mid<R){

		update2(k<<1|1,mid+1,r,L,R,u,w);

	}

}



struct node{

	int u;

	long long d;

	bool operator<(const node&h)const{return d>h.d;};

};



void dij(){

	memset(dis,0x3f,sizeof(dis));

	inf=dis[1];

	priority_queue<node> q;

	dis[s]=0;

	q.push((node){s,0});

	while(!q.empty()){

		node now=q.top();

		int u=now.u;

		long long d=now.d;

		q.pop();

		if(d!=dis[u])continue;

		for(int i=head[u];i;i=e[i].nxt){

			int v=e[i].v,w=e[i].w;

			if(dis[v]>dis[u]+w){

				dis[v]=dis[u]+w;

				q.push((node){v,dis[v]});

			}

		}

	}

}



