        cin >> B[i].first;
        B[i].second = A[i].first;
    }

    sort(B.begin(), B.end());
    sort(A.begin(), A.end());

    bool ans = true;
    for(int i=0;i<N;++i){
        if(A[i].first > B[i].first){
            ans = false;
            break;
        }
    }

    vector< int > p(N);
    if(ans){
        for(int i=0;i<N;++i){
            p[A[i].second] = B[i].second;
        }
        int count = 0, root = 0, node = 0;
        while(1){
            node = p[node];
            ++count;
            if(root == node) break;
        }
        if(count == N) {
            ans = false;
            for(int i=0;i<N-1;++i){
                if(A[i+1].first <= B[i].first){
                    ans = true;
                    break;
                }
            }
        }
    }

    if(ans) cout << "Yes" << endl;
    else cout << "No" << endl;
}

