using namespace std;

struct UnionFind {
    vector<ll> par;

    UnionFind(ll N) : par(N) {
        Rep (i, N) par[i] = i;
    }

    ll root (ll x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite (ll x, ll y) {
        ll rx = root(x);
        ll ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same (ll x, ll y) {
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    vector<pair<ll, ll>> a(N);
    Rep (i, N) {
        cin >> A[i];
        a[i] = make_pair(A[i], i);
    }
    Rep (i, N) cin >> B[i];

    sort(a.begin(), a.end());
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    Rep (i, N) {
        if (A[i] > B[i]) {
            cout << "No\n";
            return 0;
        }
    }    

    UnionFind tree(N);
    Rep (i, N) {
        tree.unite(i, a[i].second);
    }

    set<ll> s;
    Rep (i, N) {
        s.insert(tree.root(i));
    }

    if (s.size() > 1) {
        cout << "Yes\n";
        return 0;
    }

    Rep (i, N-1) {
        if (B[i] >= A[i+1]) {
            cout << "Yes\n";
            return 0;
        }
    }

    cout << "No\n";
    return 0;
}

