int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int32 n;
    cin >> n;
    vector<int32> a(n);
    vector<int32> b(n);
    vector<pii> ab(n);
    REP(i,n)cin >> a[i];
    REP(i,n)cin >> b[i];
    REP(i,n)ab[i] = pii(a[i], b[i]);
    sort(ALL(ab));
    priority_queue<int32> bpq;
    REP(i,n){
        a[i] = ab[i].first;
        b[i] = ab[i].second;
        bpq.push(b[i]);
    }
    multiset<int32> bset;
    int32 cnt = 0;
    int32 erasedCnt = 0;
    int32 undecided = 0;
    FORR(i,n-1,0){
        while(!bpq.empty() && a[i] <= bpq.top()){
            bset.insert(bpq.top());
            bpq.pop();
        }
        if(bset.size() + erasedCnt - (n - 1 - i) <= 0){
            cout << "No\n";
            return 0;
        }
        auto biiter = bset.lower_bound(b[i]);
        if(*biiter == b[i]){
            bset.erase(biiter);
            erasedCnt++;
        }else{
            cnt++;
            undecided++;
        }
        if(undecided > 0 && undecided == (signed)bset.size()){
            erasedCnt += bset.size();
            bset.clear();
            undecided = 0;
        }
    }
    Yes(cnt - 1 <= n-2);
    return 0;
}

