int main(){

    int N;
    cin >> N;
    vector<int> a(N), b(N);
    rep(i, N)cin >> a[i];
    rep(i, N)cin >> b[i];

    vector<int> sa = a, sb = b;
    sort(all(sa));
    sort(all(sb));

    vector<int> c1(N, 0), c2(N, 0), c3(N, 0);
    rep(i, N){
        if(sa[i] <= sb[i])c1[i]++;
        if(i > 0){
            if(sa[i] <= sb[i - 1])c2[i]++;
        }
        if(i < N - 1){
            if(sa[i] <= sb[i + 1])c3[i]++;
        }
    }

    auto func = [](int x, int y){ return x + y; };
    SegmentTree<int> seg1(c1, func, 0), seg2(c2, func, 0), seg3(c3, func, 0);

    rep(i, N){
        if(a[i] > b[i])continue;
        int pa = lower_bound(all(sa), a[i]) - sa.begin();
        int pb = lower_bound(all(sb), b[i]) - sb.begin();
        if(pa == pb){
            if(seg1.fold(0, pa) + seg1.fold(pa + 1, N) == N - 1){
                cout << "Yes\n";
                return 0;
            }
        }
        if(pa < pb){
            if(seg1.fold(0, pa) + seg2.fold(pa + 1, pb) + seg1.fold(pb, N) == N - 1){
                cout << "Yes\n";
                return 0;
            }
        }
        if(pa > pb){
            if(seg1.fold(0, pb) + seg3.fold(pb, pa) + seg1.fold(pa + 1, N) == N - 1){
                cout << "Yes\n";
                return 0;
            }
        }
    }

    cout << "No\n";
    return 0;

}

