    if(ta[i] > tb[i]) can = false;
  }
  if(!can) {
    cout << "No" << endl;
    return 0;
  }
  sort(c.begin(),c.end());
  bool ans = false;
  vector<int> na(2*n,0), nb(2*n,0);
  SegTree<int> st(2*n,[](int a, int b){return min(a,b);},INF);
  rep(i,2*n) {
    d.push_back(c[i].first);
    if(c[i].second < n) {
      if(i == 0) na[0] = 1;
      else {
        na[i] = na[i-1] + 1;
        nb[i] = nb[i-1];
      }
    } else {
      if(i == 0) nb[0] = 1;
      else {
        nb[i] = nb[i-1] + 1;
        na[i] = na[i-1];
      }
    }
    st.update(i,n[a]-n[b]);
  }
  rep(i,2*n) {
    if(c[i].second >= n && a[c[i].second % n] <= b[c[i].second % n]) {
      int l = upper_bound(d.begin(),d.end(),a[c[i].second % n]) - d.begin();
      if(a[c[i].second % n] == b[c[i].second % n]) ans = true;
      else if(st.query(l-1,i) >= 1) ans = true;
    }
  }
