struct cv{
    int x,y;
}a[maxn];
int b[maxn];
int cnt;
set<int>s[maxn];
int dp[maxn],du[maxn];
bool cmp(cv p,cv q){
    if(p.x!=q.x) return p.x<q.x;
    return p.y<q.y;
}
int main(){
    int n;
    scanf("%d",&n);
    for(int i=0;i<n;i++) scanf("%d",&a[i].x);
    for(int i=0;i<n;i++) scanf("%d",&a[i].y),b[i]=a[i].y;
