    for(int i=0;i<n;i++){
        if(a[i].x>b[i]){
            printf("No\n");
            return 0;
        }
        if(i!=0){
            if(b[i]==b[i-1]) flag=1;
        }
        if(i!=0&&a[i].x!=a[i-1].x){
            cnt++;
            s[cnt].insert(a[i].y);
        }
        else{
            s[cnt].insert(a[i].y);
            if(i!=0) flag=1;
        }
    }
    cnt=0;
