        printf("Yes\n");
        return 0;
    }
    for(int i=0;i<n;i++){
        dp[lower_bound(b,b+n,a[i].y)-b]=i;
    }
    cnt=0;
    for(int i=0;i<n;i++){
        if(du[i]) continue;
        cnt++;
        du[i]=1;
        int x=dp[i];
        while(du[x]==0){
            du[x]=1;
            x=dp[x];
        }
    }
