void solve()
{
    int n;
    cin >> n;
    akari<int> as(n), bs(n);
    akari<pair<int, int>> ps(n);
    for (int i = 0; i < n; i++)
    {
        cin >> ps[i].second;
    }
    for (int i = 0; i < n; i++)
    {
        cin >> ps[i].first;
    }
    sort(ps.begin(), ps.end());
    for (int i = 0; i < n; i++)
    {
        as[i] = ps[i].second;
        bs[i] = ps[i].first;
    }
    for (int i = 0; i < n; i++)
    {
        ps[i].first = as[i];
        ps[i].second = i;
    }
    sort(ps.begin(), ps.end());
    akari<long> v(n), inv(n);
    for (int i = 0; i < n; i++)
    {
        v[i] = ps[i].second;
        inv[v[i]] = i;
    }
    SegmentTree<long> segtree(v);

    int cnt = n - 2;

    // for (int i = 0; i < n; i++)
    // {
    //     print(as[i], bs[i]);
    // }
    // for (int i = 0; i < n; i++)
    // {
    //     cout << v[i] << ' ';
    // }
    // cout << endl;

    for (int i = 0; i < n; i++)
    {
        if (bs[i] >= as[i])
        {
            continue;
        }
        if (cnt == 0)
        {
            cout << "No" << endl;
            return;
        }
        //self
        segtree.update(inv[i], n + 100);
        int k = distance(bs.begin(), lower_bound(bs.begin(), bs.end(), as[i]));
        if (k >= n)
        {
            cout << "No" << endl;
            return;
        }
        int idx = segtree.getmin(i, k + 1);
        //print("i =", i, inv[i], "k =", k, "idx =", idx);
        if (idx < i || as[idx] > bs[i])
        {
            cout << "No" << endl;
            return;
        }
        as[idx] = 0;
        cnt--;
        segtree.update(k, n + 100);
    }
    cout << "Yes" << endl;
}

