  set<pair<int, Pi>> A;
  set<Pi> B;
  FOR(i, N) { cin >> Al[i]; }
  FOR(i, N) {
    cin >> Bl[i];
    B.insert(Pi(Bl[i], i));
  }
  FOR(i, N) { A.insert(pair<int, Pi>(-Al[i], Pi(-Bl[i], i))); }
  int ct = 0;
  vector<int> A2(Al), B2(Bl);
  sort(ALL(A2));
  sort(ALL(B2));
