  }
  bool same(int x, int y) {
    if(find(x) == find(y))return true;
    else return false;
  }
  bool unite(int x, int y){
    int xp = find(x);
    int yp = find(y);
    if(xp == yp)return false;
    if(rank_[xp] > rank_[yp]){
      par[yp] = xp;
      siz[xp] += siz[yp];
    }
    else if(rank_[xp] < rank_[yp]){
      par[xp] = yp;
      siz[yp] += siz[xp];
    }
    else {
      par[yp] = xp;
      siz[xp] += siz[yp];
      rank_[xp]++;
    }
    return true;
  }
  int size(int i){
    return siz[find(i)];
  }
} UnionFind;


