void dfs(vector<vector<Edge>> &Graph, int v, stack<int> &stk, vector<bool> &seen, vector<bool> &finish, bool &c){
  if(c) return;
  seen.at(v) = true;
  stk.push(v);
  for(Edge ed : Graph.at(v)){
    int nv = ed.to;
    if(seen.at(nv) && !finish.at(nv)){
      c = true;
      return;
    }
    if(finish.at(nv)) continue;
    dfs(Graph,nv,stk,seen,finish,c);
  }
  if(c) return;
  finish.at(v) = true;
  stk.pop();
}

long circuit(vector<vector<Edge>> &Graph, int s){
  stack<int> stk;
  vector<bool> seen(Graph.size(), false);
  vector<bool> finish(Graph.size(), false);
  bool c = false;
  dfs(Graph,s,stk,seen,finish,c);
  if(c) return stk.size();
  else return 0;
}


