  void solve() {
    deque<int> p(n);
    vector<int> curp(n), initp(n);
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
      cin >> b[i];
      p[i] = i;
      curp[i] = i;
      initp[i] = i;
    }
    sort(p.begin(), p.end(), [&](int x, int y) -> bool { return b[x] < b[y]; });
    for (int i = 0; i < n; ++i) {
      A[i] = a[p[i]];
      B[i] = b[p[i]];
    }
    DBG(A, B)
    sort(p.begin(), p.end(), [&](int x, int y) -> bool { return A[x] < A[y]; });
    set<int> S;
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      while (!p.empty() && A[curp[p.front()]] <= B[i]) {
        S.insert(curp[p.front()]);
        p.pop_front();
      }
      if (S.upper_bound(i) == S.end()) {
        if (A[i] > B[i]) {
          cout << "No" << endl;
          return;
        } else {
          continue;
        }
      }
      auto it = S.end();
      it--;
      int pos = *it;
      swap(A[i], A[pos]);
      int initi = initp[i];
      int initpos = initp[pos];
      swap(curp[initi], curp[initpos]);
      swap(initp[i], initp[pos]);
      S.erase(pos);
      if (A[pos] <= B[i]) S.insert(pos);
      DBG(A)
      cnt++;
      if (cnt == n - 2) break;
    }
    bool ok = true;
    for (int i = 0; i < n; ++i) {
      if (A[i] > B[i]) ok = false;
    }
    if (ok) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }
};

