bool firstCheck(vector<ll> A, vector<ll> B) {
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    for (int i = 0; i < A.size(); i++) {
        if (A[i] > B[i]) return false;
    }
    return true;

}

bool solve(long long N, std::vector<long long> A, std::vector<long long> B) {
    if (!firstCheck(A, B)) {
        return false;
    }

    // Without
    for (int i = 0; i < N; i++) {
        if (A[i] <= B[i]) {
            return true;
        }
    }

    cout << "Guard" << endl;

}

