        if(mt2.size() == 0)
        {
            o = n;
            break;
        }
        auto itr = mt2.upper_bound(mp(ele.ff, 1000000001));
        if(itr == mt2.begin())
        {
            o = n;
            break;
        }
        itr--;
        auto ele2 = *itr;
        mt.erase(mt.find(mp(itr->ss, itr->ff)));
        mt2.erase(itr);
        mt.insert(mp(ele2.ss,ele.ss));
        mt2.insert(mp(ele.ss, ele2.ss));

    }
    if(o <= n-2)
        cout<<"Yes";
    else
        cout<<"No";
    return 0;
}

