    int ng = -1;             //「index = 0」が条件を満たすこともあるので、初期値は -1
    int ok = (int)C.size();  // 「index = A.size()-1」が条件を満たさないこともあるので、初期値は A.size()

    // ok と ng のどちらが大きいかわからないことを考慮
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;  // オーバーフロー注意

        if (isOK(mid, a, C))
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

