    sort(A2.begin(), A2.end());  // 昇順
    sort(B2.begin(), B2.end());  // 昇順
    for (int i = 0; i < N; i++)
        if (A2[i] > B2[i]) {
            cout << "No" << endl;
            return 0;
        }

    vvi C = vvi(N, vi(2));
    for (int i = 0; i < N; i++) {
        C[i][0] = A[i];
        C[i][1] = B[i];
    }

    sort(C.begin(), C.end(), [](vi l, vi r) { return l[1] < r[1]; });

