    }
    for (int i = 0; i < N; i++) {
        if (C[i][0] <= C[i][1]) continue;
        // C[i][0]の入れ替え先は、ぎりぎり条件を満たすところ以下で、
        // C[i][1]の条件を満たすやつがある最大のところ
        count++;
        int idx = binary_search(C[i][0], C);
        for (int j = idx; j < N; j++) {
            if (C[j][0] <= C[i][1]) {
                int tmp = C[i][0];
                C[i][0] = C[j][0];
                C[j][0] = tmp;
