                break;
            }
        }
        if (C[i][0] > C[i][1]) {
            cout << "No" << endl;
            return 0;
        }
    }

    if (count > N - 2) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;
    return 0;
}

