const int MAX_N=100000;
int par[MAX_N];  //親 **親を探すときはfind
int rank1[MAX_N]; //木の深さ
void init(int n)
{
    for (int i = 0; i < n; i++)
    {
        par[i] = i;
        rank1[i] = 0;
    }
}
//木の根を求める
int find(int x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}
//併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if(x==y) return;
    if(rank1[x]<rank1[y]){
        par[x]=y;
    }
    else{
        par[y]=x;
        if(rank1[x]==rank1[y]) rank1[x]++;
