	std::vector<int> topologicalSort() const {
		const int N = vertex.size();
		std::vector<int>ref(N);		//各ノードに向いている入力辺の数
		for (int i = 0; i < N; ++i) {
			for (auto& edge : vertex[i].edges) {
				ref[edge.next]++;
			}
		}
		//
		unordered_set<int> S;		//入力辺を持たないすべてのノードの集合
		std::vector<int>L;			//トポロジカルソートした結果を蓄積する空リスト
		L.reserve(N);
		for (int i = 0; i < N; ++i) {
			if (ref[i] == 0)S.insert(i);
		}
		while (!S.empty()) {
			auto itr = S.begin();
			int n = *itr;
			S.erase(itr);
			L.push_back(n);
			for (auto& edge : vertex[n].edges) {
				ref[edge.next]--;
				if (ref[edge.next] == 0) {
					S.insert(edge.next);
				}
			}
		}
		for (int i = 0; i < N; ++i) {
			if (ref[i] != 0) {
				throw "DAGではない";
			}
		}
		return L;
	}
