typedef long long ll;
const ll modn=998244353;
const ll INF = 0x3f3f3f3f;
ll tr[1001000];
ll lazy[1001000];
int a[100100];
int b[100100];
int aa[100100];
int bb[100100];
int n;
void build(int o,int l,int r){
    if(l==r){
        tr[o]= -(l+1);
        return;
    }
    int mid = (l+r)/2;
    build(o*2+1,l,mid);
    build(o*2+2,mid+1,r);
    tr[o]=min(tr[o*2+1],tr[o*2+2]);
}
void push_down(int o){
    lazy[o*2+1]+=lazy[o];
    lazy[o*2+2]+=lazy[o];
    tr[o*2+1]+=lazy[o];
    tr[o*2+2]+=lazy[o];
    lazy[o]=0;
}
void push_up(int o){
    tr[o]=min(tr[o*2+1],tr[o*2+2]);
}

int query(int o,int L,int R,int l,int r){
    //cout<<l<<r<<endl;
    if(l<=L && r>=R){
        return tr[o];
    }
    push_down(o);
    int mid = (L+R)/2;
    int ans= INF;
    if(l<=mid)ans=min(ans,query(o*2+1,L,mid,l,r));
    if(r>mid) ans=min(ans,query(o*2+2,mid+1,R,l,r));
    push_up(o);
    return ans;
}

void ins(int o,int L,int R,int l,int r,int val){
    //cout<<L<<R<<" "<<l<<r<<endl;
    if(l<=L && r>=R){
        lazy[o]+=val;
        tr[o]+=val;
        return;
    }
    push_down(o);
    int mid = (L+R)/2;
    if(l<=mid)ins(o*2+1,L,mid,l,r,val);
    if(r>mid)ins(o*2+2,mid+1,R,l,r,val);
    push_up(o);
}


int main(){

    scanf("%d",&n);
    for(int i=0;i<n;i++){
        scanf("%d",&a[i]);
        aa[i]=a[i];
    }
    for(int i=0;i<n;i++){
        scanf("%d",&b[i]);
        bb[i]=b[i];
    }

    aa[n]=bb[n]=INF;
    sort(aa,aa+n);sort(bb,bb+n);
    build(0,0,n-1);
    for(int i=0;i<n;i++){

        int t = lower_bound(bb,bb+n+1,a[i])-bb;
        //cout<<t<<endl;
        if(t>=0 && t<n)
            ins(0,0,n-1,t,n-1,1);
    }
    int flag = 0;
    for(int i=0;i<n;i++){

        if(a[i]>b[i])continue;

        int t = lower_bound(bb,bb+n+1,a[i])-bb;
        int t2 = upper_bound(bb,bb+n+1,b[i])-bb-1;

        if(t>=0 && t<n)
            ins(0,0,n-1,t,n-1,-1);
        int ans=INF;
        if(t2)ans = min(ans,query(0,0,n-1,0,t2-1));
        if(t2<n-1) ans = min(ans,query(0,0,n-1,t2+1,n-1)+1);
        if(t>=0 && t<n)
            ins(0,0,n-1,t,n-1,1);
        if(ans>=0){
            flag = 1;
        }
    }
    if(flag == 1)
        printf("Yes\n");
    else
        printf("No\n");
    return 0;
}

