    sort(begin(sorted_a), end(sorted_a));
    for (int i = 0; i < n; ++i) {
        if (sorted_a[i] > b[i]) {
            cerr << "sorted_a[i] > b[i]" << endl;
            return false;
        }
    }
    for (int i = 0; i < n - 1; ++i) {
        if (sorted_a[i + 1] <= b[i]) {
            cerr << "sorted_a[i + 1] <= b[i]" << endl;
            return true;
        }

    }
