void selectsort(int A[],int n)
{
  int i,j,min,temp;
  for(i=0;i<n-2;++i){
    min=i;
    for(j=i+1;j<n;++j){
      if(A[j]<A[min]){
        min=j;
      }
    }
    temp = A[i];
    A[i] = A[min];
    A[min] = temp;
  }
}

