class UnionFind {
public:
    UnionFind() :data(0) {}
    UnionFind(int size) : data(size, -1) { }
    void resize(int size) { *this = { size }; }
    bool unionset(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) std::swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findset(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
private:
    std::vector<int> data;
};


int n;
void solve() {
    cin >> n;

    vector<pair<ll, ll>> ab(n);
    rep(i, n) cin >> ab[i].first;
    rep(i, n) cin >> ab[i].second;

    vector<int> a2(n), b2(n);
    vector<ll> a3(n), b3(n);

    all(sort, ab);
    rep(i, n) {
        a3[i] = ab[i].first;
        ab[i].first = a2[i] = i;
        swap(ab[i].first, ab[i].second);
    }
    all(sort, ab);
    rep(i, n) {
        b3[i] = ab[i].first;
        ab[i].first = b2[i] = i;
        swap(ab[i].first, ab[i].second);
    }


    rep(i, n)
        if (a3[i] > b3[i]) {
            cout << "No" << endn;
            return;
