        ba[i].first = b;
    }
    sort(all(ba));

    map<int, vi> mp;
    rep(i, n) {
        mp[ba[i].second].push_back(i);
    }

    segment seg(n);
    vector<ll> aaa(n);
    rep(i, n) {
        aaa[i] = ba[i].second;
    }
    seg.init(aaa);

    /*rep(i, n) {
        cout << ba[i].first << ' ' << ba[i].second << endl;
    }*/

    int cou = 0;
    rep(i, n) {
        if(ba[i].second > ba[i].first) {
            cou++;
            auto itr = lower_bound(all(ba), P(ba[i].second, 0));
            if(itr == ba.end()) {
                cou = n;
                break;
            }
            int num = itr-ba.begin();
            int smm = seg.query_(num, n, 0, 0, seg.n);
            //cout << i << endl;
            if(smm <= ba[i].first) {
                int yy = *(mp[smm].end()-1);
                seg.update(yy, ba[i].second);
                ba[yy].second = ba[i].second;
                mp[ba[i].second].push_back(yy);
                mp[smm].pop_back();
            } else {
                smm = seg.query(i+1, n);
                if(smm > ba[i].first) {
