    for(int i = 0; i < N; i++) {
        cin >> A[i].first;
        A[i].second = i;
    }
    sort(A, A + N);
    for(int i = 0; i < N; i++) {
        cin >> B[i].first;
        B[i].second = i;
    }
    sort(B, B + N);
    int iA[N], iB[N];
    for(int i = 0; i < N; i++) {
        iA[A[i].second] = i;
        iB[B[i].second] = i;
    }
    bool isok = true;
    for(int i = 0; i < N; i++) {
        isok &= A[i].first <= B[i].first;
    }
    if(!isok) {
        cout << "No" << endl;
        return 0;
    }
    SegmentTree<RandQ> seg(N - 1);
    for(int i = 0; i < N - 1; i++) {
        seg.set_val(i, A[i + 1].first <= B[i].first);
    }
    isok = false;
    for(int i = 0; i < N; i++) {
        if(iA[i] == iB[i]) {
            isok = true;
            break;
        }
        if(iA[i] < iB[i]) {
            isok = true;
            isok |= seg.query(iA[i], iB[i]);
        } else {
            isok |= A[iA[i]].first <= B[iB[i]].first;
        }
    }
    cout << (isok ? "Yes" : "No") << endl;
    return 0;
}

