    for (int i = 0; i < N; i++) {
        A.push(Av[i]);
        B.insert(Bv[i]);
    }
    ll a;
    while (!A.empty()) {
        a = A.top();
        A.pop();
        auto itr = B.lower_bound(a);
        if (itr == B.end()) {
            cout << "No" << endl;
            return 0;
        }
        B.erase(itr);
    }
    cout << "Yes" << endl;

    return 0;
}

