using P = pair<int, int>;

struct UnionFind {
    vector<int> d; // 根なら (-サイズ), そうでないなら親の番号
    UnionFind(int N) : d(N, -1){} // 全て根として初期化

    int root(int x) { // データ x が属する木の根を再帰で得る
        if (d[x] < 0) return x;
        return d[x] = root(d[x]);
    }

    bool unite(int x, int y) { // x と y の木を併合. 併合した場合 true
        x = root(x); y = root(y); // x <- x の根, y <- y の根
        if (x == y) return false; 
        // merge technique（データ構造をマージするテク. 小を大にくっつける）
        if (d[x] > d[y]) swap(x, y);    // x の木のサイズ > y の木のサイズにする. d[x], d[y] < 0 に注意.
        d[x] += d[y];   // x の木のサイズ += y の木のサイズ
        d[y] = x;   // y の親は x
        return true;
    }

    bool same(int x, int y) { // 2つのデータ x, y が属する木が同じなら true
        return root(x) == root(y);
    }

    int size(int x) { // 素集合のサイズ
        return -d[root(x)]; // d[root(x)] < 0 に注意.
    }
};

void Main(){
    ll n; cin >> n;
    vector<P> d(n);
    rep(i, n) cin >> d[i].se;
    rep(i, n) cin >> d[i].fi;
    sort(all(d));

    vi a(n), b(n);
    vector<P> ap(n);
    rep(i, n) {
        a[i] = d[i].se;
        b[i] = d[i].fi;
        ap[i] = {a[i], i};
    }
    sort(all(ap));

    UnionFind UF(n);
    rep(i, n){
        if(ap[i].fi > b[i]){
            cout << "No" << endl;
            return;
        }else{
            UF.unite(i, ap[i].se);
        }
    }
    rep(i, n){
        if(UF.size(i) != n){
            cout << "Yes" << endl;
            return;
        }
    }
    rep(i, n-1){
        if(ap[i+1].fi <= b[i]){
            cout << "Yes" << endl;
            return;
        }
    }    
    cout << "No" << endl;
    return;
}

