const string YES = "Yes";
const string NO = "No";
// 1-indexed BIT (i : [1, len])
template<typename T>
struct BIT
{
    int len;
    vector<T> val;
    BIT(int num) : len(num), val(num + 1) {}
    BIT() : BIT(0) {}
    void reset() { fill(val.begin(), val.end(), 0); }
    void add(int pos, T v) { while (pos > 0 and pos <= len) val[pos] += v, pos += pos & -pos; }
    T sum(int pos) const // (0, pos]
    {
        T res = 0;
        while (pos > 0) res += val[pos], pos -= pos & -pos;
        return res;
    }
};
template<typename T> ostream &operator<<(ostream &os, const BIT<T> &b){ T prv = 0; os << "["; REP(i, b.len) { T nxt = b.sum(i + 1); os << nxt - prv << ","; prv = nxt; } os << "]"; return os; }


void no()
{
    cout << NO << endl;
    exit(0);
}
void yes()
{
    cout << YES << endl;
    exit(0);
}
struct SizeAwareUnionFind
{
    vector<int> par, cou;
    SizeAwareUnionFind(int N) : par(N), cou(N) { REP(i, N) par[i] = i, cou[i] = 1; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (cou[x] < cou[y]) swap(x, y); 
        par[y] = x, cou[x] += cou[y];
    }
    int count(int x) { return cou[find(x)]; }
    bool same(int x, int y) { return find(x) == find(y); }
};

int main()
{
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    cin >> A >> B;
    vector<int> AS = A, BS = B;
    sort(ALL(AS));
    sort(ALL(BS));
    REP(i, N) if (BS[i] < AS[i]) no();

    BIT<int> bit(N + 10);
    REP(i, N - 1) if (AS[i + 1] <= BS[i]) bit.add(i + 1, 1);

    REP(i, N)
    {
        int a = A[i], b = B[i];
        if (a > b) continue;
        int j = upper_bound(ALL(AS), a) - AS.begin() - 1;
        int k = lower_bound(ALL(BS), b) - BS.begin();
        if (j >= k or bit.sum(k) - bit.sum(j) == k - j)
        {
            yes();
        }
    }
    map<lint, int> AC;
    for (auto a : A) AC[a]++;
    for (auto b : B) AC[-1 - b]++;
    for (auto p : AC) if (p.second > 1) yes();

    vector<pint> AP(N), BP(N);
    REP(i, N) AP[i] = make_pair(A[i], i);
    REP(i, N) BP[i] = make_pair(B[i], i);
    sort(ALL(AP));
    sort(ALL(BP));
    SizeAwareUnionFind uf(N);
    REP(i, N) uf.unite(AP[i].second, BP[i].second);
    if (uf.count(0) == N) no();
    else yes();
}

