    vector<pair<ll, ll>> ba(n, {0, 0});

    REP(i, n) cin >> ba[i].second;
    REP(i, n) {
        cin >> ba[i].first;
        ba[i].second *= -1;
    }
    sort(ALL_OF(ba));
    REP(i, n) {
        ba[i].second *= -1;
    }

    vector<ll> a(n), b(n);
    REP(i, n) tie(b[i], a[i]) = ba[i];

    vector<pair<ll, ll>> p(n);
    REP(i, n) {
        p[i] = make_pair(a[i], -i);
    }

    segtree sgt(p);

    ll kaisu = 0;
    REP(i, n) {
        auto u = sgt.fetch(i, i+1);
        if (u.first > b[i]) {
            auto v = sgt.fetch(i+1, n);
            if (v.first > b[i]) {
                kaisu += INF;
                break;
            }
            ll j = -v.second;
            // swap w/o soegies
            sgt.apply(i, i+1, make_pair(v.first, -i));
            sgt.apply(j, j+1, make_pair(u.first, -j));
            kaisu++;
        }
    }
    cout << Yes(kaisu <= n - 2) << endl;
}

