void solve()
{
    int n;
    cin >> n;
    akari<pair<int, int>> as(n), bs(n);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i].first;
        as[i].second = i;
    }
    for (int i = 0; i < n; i++)
    {
        cin >> bs[i].first;
        bs[i].second = i;
    }
    sort(as.begin(), as.end());
    sort(bs.begin(), bs.end());
    UnionFind uf(n);
    for (int i = 0; i < n; i++)
    {
        if (as[i].first > bs[i].first)
        {
            cout << "No" << endl;
            return;
        }
        uf.merge(as[i].second, bs[i].second);
    }
    for (int i = 0; i < n - 1; i++)
    {
        if (as[i].first <= bs[i + 1].first && as[i + 1].first <= bs[i].first)
        {
            cout << "Yes" << endl;
            return;
        }
    }
    cout << (uf.size(0) != n ? "Yes" : "No") << endl;
}

