	sort(AB.begin(), AB.end());

	vector<pair<int, int>> bs(N);
	for(int i=0; i<N; i++) bs[i]={AB[i].second, -i};
	SegmentTree<pair<int, int>> st(bs, {0, 0});

	int cnt = 0;
	for(int i=N-1; i>0; i--){
		int a = AB[i].first;
		int b = AB[i].second;
		if(a<=b) continue;
		debug(a, b);
		cnt++;
		auto p = st.query(0, i);
		int x = p.first;
		int n = -p.second;
		if(x<a) {
			cout << "No" << endl;
			return 0;
		}
		p = st.query(0, 1);
		x = p.first;
		n = -p.second;
		if(x>=a){
			st.update(0, {b, 0});
			AB[n].second = b;
