int cnt[N+9],p[N+9],vis[N+9],ans;

void Get_ans(){
  sort(x+1,x+n+1);
  sort(y+1,y+n+1);
  for (int i=1;i<=n;++i)
	if (x[i]>y[i]) return;
  for (int i=1;i<=n;++i){
	++cnt[a[i]=upper_bound(y+1,y+n+1,a[i])-y-1];
