int main()
{
  int N;
  cin >> N;
  vector<int> A(N), B(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  for (auto i = 0; i < N; i++)
  {
    cin >> B[i];
  }
  vector<Info> I(N);
  for (auto i = 0; i < N; i++)
  {
    I[i] = Info(B[i], A[i]);
  }
  sort(I.begin(), I.end());
  for (auto i = 0; i < N; i++)
  {
    A[i] = get<1>(I[i]);
  }
  vector<Info> J(N);
  for (auto i = 0; i < N; i++)
  {
    J[i] = Info(A[i], i);
  }
  sort(J.begin(), J.end());
  vector<int> P(N);
  for (auto i = 0; i < N; i++)
  {
    P[i] = get<1>(J[i]);
  }
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());
  for (auto i = 0; i < N; i++)
  {
    if (A[i] > B[i])
    {
      No();
    }
  }
  int cnt{N};
  vector<bool> used(N, false);
  int now{0};
  while (cnt > 0)
  {
    if (used[now])
    {
      Yes();
    }
    used[now] = true;
    now = P[now];
    --cnt;
  }
  for (auto i = 0; i < N - 1; i++)
  {
    if (A[i + 1] <= B[i])
    {
      Yes();
    }
  }
  No();
}

