struct LLPair {
	ll a = 0;
	ll b = 0;
};

int main() {
	ll N;
	scanf("%lld", &N);
	vector<ll> a(N);
	for (ll i = 0; i < N; i++) {
		scanf("%lld", &a[i]);
	}
	vector<ll> b(N);
	for (ll i = 0; i < N; i++) {
		scanf("%lld", &b[i]);
	}

	ll need = 0;
	vector<LLPair> p(N);
	for (ll i = 0; i < N; i++) {
		p[i].a = a[i];
		p[i].b = b[i];

		if (a[i] > b[i]) {
			need++;
		}
	}

	//����
	std::sort(a.begin(), a.end());
	std::sort(b.begin(), b.end());

	for (ll i = 0; i < N; i++) {
		if (a[i] > b[i]) {
			printf("No\n");
			return 0;
		}
	}

	//�~��
	std::sort(p.begin(), p.end(), [](const LLPair &a, const LLPair &b) {
		return a.a > b.a;
	});

	ll swap = 0;

	for (ll i = 0; i < N; i++) {
		if (p[i].a > p[i].b) {
			auto itLow = lower_bound(a.begin(), a.end(), p[i].b);
			auto itUp = upper_bound(a.begin(), a.end(), p[i].b);

			ll indexLow = itLow - a.begin();
			ll indexUp = itUp - a.begin();

			indexLow = N - 1 - indexLow;
			indexUp = N - 1 - indexUp + 1;

			ll hold1 = -1;
			ll min = INF;
			ll hold2 = -1;
			ll max = -1;
			for (ll j = indexUp; j <= indexLow; j++) {
				if (p[j].b >= p[i].a) {
					if (min > p[j].b) {
						min = p[j].b;
						hold1 = j;
					}
				}
				else {
					if (max < p[j].b) {
						max = p[j].b;
						hold2 = j;
					}
				}
			}

			if (hold1 >= 0) {
				ll temp = p[i].a;
				p[i].a = p[hold1].a;
				p[hold1].a = temp;
			}
			else {
				ll temp = p[i].a;
				p[i].a = p[hold2].a;
				p[hold2].a = temp;
			}

			swap++;
		}
	}


	if (swap <= N - 2) {
		printf("Yes\n");
	}
	else {
		printf("No\n");
	}
}

