template<class Monoid>
struct SegmentTree{
private:

    int sz; 
    vector<Monoid> node;
    using Func = function<Monoid(Monoid, Monoid)>;
    const Func operate; 
    const Monoid unit;

public:

    SegmentTree(){}
    SegmentTree(const Func f, const Monoid m) : operate(f), unit(m) {}
    SegmentTree(const vector<Monoid>& vec, const Func f, const Monoid m)
        : operate(f), unit(m) { bulid(vec); }
    ~SegmentTree(){}

    inline void init(){
        fill(node.begin(), node.end(), unit);
    }

    inline void bulid(const vector<Monoid> &vec){
        for(sz = 1; sz < (int)vec.size(); sz <<= 1);
        node.assign(sz << 1, unit);
        for(int i = 0; i < (int)vec.size(); i++)
            node[i + sz] = vec[i];
        for(int i = sz - 1; i > 0; i--)
            node[i] = operate(node[i << 1], node[i << 1 | 1]);
    }

    inline void set(int i, Monoid v){
        for(node[i += sz] = v; i >>= 1;)
            node[i] = operate(node[i << 1], node[i << 1 | 1]);
    }

    inline void add(int i, Monoid v){
        set(i, node[i + sz] + v);
    }

    inline Monoid fold(int l, int r){
        Monoid vl = unit, vr = unit;
        for((l += sz), (r += sz); l < r; l >>= 1, r >>= 1){
            if(l & 1)vl = operate(vl, node[l++]);
            if(r & 1)vr = operate(node[--r], vr);
        }
        return operate(vl, vr);
    }

    inline Monoid operator [] (int i){
        return node[i + sz];
    }

};

