#define P pair<ll, ll>


ll n, cnt, now;
priority_queue<P> q;
int main() {
	cin >> n;
	vector<P> s(n);
	vector<ll> x(n), y(n);
	REP(i, n) cin >> x[i];
	REP(i, n) cin >> y[i];
	REP(i, n) s[i] = P(y[i], x[i]);
	now = n - 1;
	sort(ALL(s));
	sort(ALL(x));
	sort(ALL(y));
	REP(i, n) {
		if (x[i] > y[i]) {
			cout << "No" << endl;
			return 0;
		}
	}
	REP(i, n) {
		ll b = s[i].first, a = s[i].second;
		if (a > b)q.push(P(a, -1 * i));
	}
	//cout << q.size() << endl;
	while (now > 0 and !q.empty() and cnt <= n - 2) {
		P p = q.top();
		ll ppos = p.second * -1;
		cout << p.first << " " << p.second << endl;
		q.pop();
		if (ppos >= now or p.first == s[now].second)continue;
		cnt++;
		if (s[ppos].first < s[now].second)q.push(P(s[now].second, ppos * -1));
		swap(s[ppos].second, s[now].second);
		now--;
	}
	cout << (q.empty() and cnt <= n - 2 ? "Yes" : "No") << endl;

}

