const int MAX_N=1e6+1;
int A[MAX_N],B[MAX_N];
int N;

bool solve() {
  VI AA(A,A+N),BB(B,B+N);
  sort(A,A+N),sort(B,B+N);
  REP(i,N)if(A[i]>B[i]) return false;
  REP(i,N-1)if(A[i]==A[i+1]) return true;
  MAPII pos;
  REP(i,N)pos[A[i]]=i;
  VI P(N,-1);
  REP(i,N)P[i]=pos[AA[i]];
  VI viz(N,0);
  function<void(int)> dfs=[&](int u)->void {
    if(viz[u]) return;
    viz[u]=1;
    dfs(P[u]);
  };
  int cnt=0;
  REP(i,N)if(!viz[i]) ++cnt,dfs(i);
//  dump(cnt);
  if(cnt>1) return true;
  REP(i,N-1) if(A[i+1]<=B[i]) return true;
  return false;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N;
  REP(i,N) cin>>A[i];
  REP(i,N) cin>>B[i];
  cout<<(solve()?"Yes":"No")<<endl;

  return 0;
}

