	}

	pair<int, int> table[N_MAX];
	for (int i = 0; i < N; i++){
		table[i] = make_pair(tmpB[i], tmpA[i]);
	}

	sort(table, table + N);

	int A[N_MAX], B[N_MAX];
	pair<int, int> sortA[N_MAX];
	for (int i = 0; i < N; i++){
		A[i] = table[i].second;
		B[i] = table[i].first;
		sortA[i] = make_pair(A[i], i);
	}

	sort(sortA, sortA + N);

	for (int i = 0; i < N; i++){
		if (sortA[i].first > B[i]){
			printf("No");
			return;
		}
	}

	for (int i = 0; i < N - 1; i++){
		if (sortA[i + 1].first <= B[i]){
			printf("Yes");
			return;
		}
	}


	int rev[N_MAX];
	for (int i = 0; i < N; i++){
		rev[sortA[i].second] = i;
	}

	int visit[N_MAX];
	fill(visit, visit + N, 0);
	int cur = 0;
	for (int i = 0; i < N; i++){
		if (0 == visit[rev[cur]]){
			visit[rev[cur]] = 1;
			cur = sortA[rev[cur]].second;
		}
		else{
			printf("Yes");
			return;
		}
	}

	printf("No");
	return;
}

