#define rep(i,m,n) for(ll i = (m); i <= (n); i++)
#define zep(i,m,n) for(ll i = (m); i < (n); i++)
#define rrep(i,m,n) for(ll i = (m); i >= (n); i--)
#define print(x) cout << (x) << endl;
#define printa(x,m,n) for(ll i = (m); i <= n; i++){cout << (x[i]) << " ";} cout<<endl;

int main(){
	cin.tie(0); ios::sync_with_stdio(false);

	ll n;
	cin >> n;
	ll a[n], b[n];
	P pa[n], pb[n];
	zep(i, 0, n){cin >> a[i]; pa[i] = P(a[i], i);}
	zep(i, 0, n){cin >> b[i]; pb[i] = P(b[i], i);}

	bool ans = true;
	ll cnt = 0;
	zep(i, 0, n){
		if(a[i] > b[i]){
			cnt++;
		}
	}
	if(cnt > n-2){
		ans = false;
	}

	sort(pa, pa+n);
	sort(pb, pb+n);
	zep(i, 0, n){
		if(pa[i].first > pb[i].first){
			ans = false;
		}
	}

	if(ans){
		ans = false;

		ll rpa[n], rpb[n];
		zep(i, 0, n){
			rpa[pa[i].second] = i;
			rpb[pb[i].second] = i;
		}
		rrep(i, n-2, 0){
			if(pa[i].first == pa[i+1].first){
				rpa[pa[i].second] = rpa[pa[i+1].second];
			}
		}
		zep(i, 1, n){
			if(pb[i].first == pb[i-1].first){
				rpb[pb[i].second] = rpb[pb[i-1].second];
			}
		}

		ll cum[n];
		memset(cum, 0, sizeof(cum));
		zep(i, 1, n){
			cum[i] += cum[i-1];
			if(pa[i].first <= pb[i-1].first){
				cum[i] += 1;
			}
		}

		zep(i, 0, n){
			//cout << rpa[i] << " " << rpb[i] << endl;
			if(rpa[i] <= rpb[i] && cum[rpb[i]]-cum[rpa[i]] == rpb[i]-rpa[i]){
				ans = true;
			}
		}
	}
	print((ans)? "Yes" : "No")
	return 0;
}

