// セグ木
template<typename T,typename F>
struct ST{

  int size;
  vector<T> seg;
  const F func;
  const T UNIT;

  ST(int N,F func , T UNIT): func(func) , UNIT(UNIT) {
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
  }

  ST(const vector<T> &v,F func , T UNIT) : func(func) , UNIT(UNIT){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size , UNIT);
    // set
    for(int i = 0; i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k, T x){
    seg[k + size] = x;
  }

  void build(){
    for(int k = size-1; k > 0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func( seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void add(int k , T x){
    k += size; seg[k] += x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  // 半開区間[a,b)へのクエリ
  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

void solve(){
  ini(N);
  vl a(N) , b(N); in(a , b);
  vl c(N); rep(i , N) c[i] = a[i];
  vp d(N); rep(i , N) d[i] = P(b[i] , i);
  sort( all(c) ); sort(all(d));

  trc(a , b , c);
  // 自明
  rep(i , N){if( c[i] > d[i].fi) die("No");}

  // 巡回置換かを判定 おなじもの2ko?
  rep(i , N-1){
    if(c[i] == c[i + 1]) die("Yes");
    if(d[i].fi == d[i+1].fi) die("Yes");
  }

  // 巡回している すなわち　N-2回のswapで未解決
  rep(i , N - 2){
    trc(a);
    trc(b);
    auto it = lower_bound(all(c) , a[0]);
    int ci = it - c.begin(); // ci番目の大きさ
    // どこに置く？　-> d[ci].se番目
    if(d[ci].se == 0) die("Yes"); 
    swap(a[0] , a[d[ci].se]);
  }

  // 最後　1個swap
  auto f = [](ll a,ll b){return min(a , b);};
  vl sg(N); rep(i , N) sg[i] = d[i].fi - c[i];
  ST<ll,decltype(f)> seg(sg , f , infLL);

  rep(i , N - 1){
    trc(i);
    // swap c[i]とc[i+1]
    seg.add(i+1 , c[i + 1] - c[i]);
    seg.add(i , c[i] - c[i + 1]);
    rep(i,N) trc(seg[i]);
    // 判定
    if(seg.query(0,N) >= 0) die("Yes");
    // 復元
    seg.add(i , c[i + 1] - c[i]);
    seg.add(i+1 , c[i] - c[i + 1]);
  }

  out("No");

}

