struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

bool solve(vector<ll> A, vector<ll> B) {
  int N = A.size();
  sort(B.begin(), B.end());
  vector<int> id(N);
  iota(id.begin(), id.end(), 0);
  sort(id.begin(), id.end(), [&](int a, int b) {
    if (A[a] != A[b]) return A[a] < A[b];
    return a < b;
  });
  for (int i = 0; i < N; i++) {
    if (A[id[i]] > B[i]) return false;
  }
  UnionFind uf(N);
  for (int i = 0; i < N; i++) uf.unite(i, id[i]);
  set<int> S;
  for (int i = 0; i < N; i++) S.insert(uf.root(i));
  if (S.size() > 1) return true;
  for (int i = 0; i + 1 < N; i++) {
    int a = id[i], b = id[i + 1];
    if (A[b] <= B[i] && A[a] <= B[i + 1]) {
      return true;
    }
  }
  return false;
}

