      puts("Yes");
      return 0;
    }
    else if (x < y) {
      if (check(0, x-1, 0) && check(x+1, y, 2) && check(y+1, n-1, 0)) {
        puts("Yes");
        return 0;
      }
    }
    else {
      if (check(0, y-1, 0) && check(y, x-1, 1) && check(x+1, n-1, 0)) {
        puts("Yes");
        return 0;
      }
    }
  }
  puts("No");
  return 0;
}

