vector<int> divisor(int n){
  vector<int> ret;
  for(int i = 1;i*i <= n;i++){
    if(n%i == 0){
      ret.push_back(i);
      if(i*i != n)ret.push_back(n/i);
    }
  }
  sort(ret.begin(), ret.end());
  return ret;
}

int mod = 998244353;

int pow(int x, int y){
  if(y == 1)return x;
  int ret;
  if(y % 2 == 0){
    ret = pow(x, y/2);
    return ret*ret % mod;
  }else{
    ret = pow(x, y/2);
    return ret*ret % mod * x % mod;
  }
}
