struct Record
{
  int v;
  int i;
  bool operator<(const Record &rhs) const
  {
    return v < rhs.v;
  }
};

int main()
{
  int n;
  vector<Record> a;
  vector<int> b; // bはソートしたものにする

  cin >> n;
  int v;
  for (int i = 0; i < n; ++i)
  {
    cin >> v;
    a.push_back({v, i});
  }
  for (int i = 0; i < n; ++i)
  {
    cin >> v;
    b.push_back(v);
  }
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());

  // N-2 の制限を考えずに自由に並び替えたばあい
  for (int i = 0; i < n; ++i)
  {
    if (a[i].v > b[i])
    {
      // No が確定
      cout << "No" << endl;
      return 0;
    }
  }

  // スワップ数を数える
  // 到達した場所を数えるフラグ. 0で初期化.
  const long long size = 1e5 + 10;
  bitset<size> visited(0);
  long long swapcount = 0;
  for (int i = 0; i < n; ++i)
  {
    //cout << "a v:" << a[i].v << " i:" << a[i].i << endl;
    if (visited.test(i))
    {
      continue;
    }
    int crnt = i;
    while (!visited.test(crnt))
    {
      auto rec = a[crnt];
      visited.set(crnt);

      auto next = a[crnt].i;
      if (crnt != next && !visited.test(next))
      {
        swapcount++;
      }
      crnt = next;
    }
  }
  //cout << "swap count : " << swapcount << endl;

  // スワップ回数が規定よりも少なかったら
  if (swapcount <= n - 2)
  {
    cout << "Yes" << endl;
    return 0;
  }

  // スワップ回数が最大値のN-1の場合
  // swap
  for (int i = 0; i < n - 1; ++i)
  {
    if (a[i + 1].v <= b[i])
    {
      cout << "Yes" << endl;
      return 0;
    }
  }

  cout << "No" << endl;
  return 0;
}

