    }
    vector<int> order(n);
    iota(all(order), 0);
    sort(all(order), [&](int f, int s) {
        return b[f] < b[s];
    });
    sort(all(b));
    vector<int> tmp(n);
    for (int i = 0; i < n; ++i) {
        tmp[i] = a[order[i]];
    }
    a = tmp;
    vector<int> sorted = a;
    sort(all(sorted));
    for (int i = 0; i < n; ++i) {
        if (sorted[i] > b[i]) {
            cout << "No\n";
            return 0;
        }
    }
    iota(all(order), 0);
    sort(all(order), [&](int f, int s) {
        return a[f] < a[s];
    });
    for (int i = n - 1; i >= 0; --i) {
        int pos = lower_bound(all(b), a[order[i]]) - b.begin();
        qs[pos].push_back(i);
    }
    for (int i = 0; i < n; ++i) {
        update(0, 0, n, i, order[i]);
        pos[order[i]] = i;
    }
    for (int l = 0; l < n; ++l) {
        for (int r : qs[l]) {
            if (get(0, 0, n, l, r + 1) <= r) {
                cout << "Yes\n";
                return 0;
            }
        }
    }
    cout << "No\n";
}

