	for (int i=0; i<n; i++) scanf("%d", &a[i]);
	for (int i=0; i<n; i++) scanf("%d", &b[i]);
	return 1;
}

int one_cycle(int *a, int n) {
	int j = a[0], c = 1;
	while (j) j = a[j], c++;
	return c<n;
}

void init() {
}

int solve() {
	for (int i=0; i<n; i++) c[i] = i;
	sort(c, c+n, [](auto &x, auto &y) {
		return a[x]<a[y];
	});
	int one = one_cycle(c, n);
	sort(a, a+n);
	sort(b, b+n);
	for (int i=0; i<n; i++)
		if (a[i]>b[i]) return 0;
	if (!one) return 1;
	for (int i=0; i<n-1; i++)
		if (a[i]<=b[i+1]) return 1;
	return 0;
}

