const string YES = "Yes";
const string NO = "No";

typedef struct UnionFind{
    vector<lli> par; //par[i]:iの親番号 par[3] = 2 : 3の親が2
    vector<lli> size;//size[i]:iの大きさ 自分のみのときは1,根っこにsizeを持たせる*/

    UnionFind(int N){/*最初はすべてが根であると初期化*/
        REP(i,0,N){
            par.push_back(i);
            size.push_back(1);
        }
    }

    lli root(lli x){/*データxが属する木の根を再起で得る root(x) = {xの木の根}}*/
        if(par[x] == x)return x;
        return par[x] = root(par[x]);
    }

    void unite(lli x,lli y){/*xとyの併合*/
        lli rx = root(x);
        lli ry = root(y);
        if(rx == ry)return;
        par[rx] = ry; /*xとyの根が同じじゃない: xの根をrxをyの根ryに変更する */
        lli resize = size[rx] + size[ry];
        size[rx] = resize;
        size[ry] = resize;
    }

    bool same(lli x,lli y){
        lli rx = root(x);
        lli ry = root(y);
        return rx == ry;
    }

    lli getSize(lli x){
        lli rx = root(x);
        return size[rx];
    }
};

map<lli,queue<lli>> d;

void func(long long N, std::vector<long long> A, std::vector<long long> B){

    vector<pair<lli,lli>> v;
    REP(i,0,N)v.push_back({B[i],A[i]});

    SORT(v);
    SORT(A);

    bool ok = true;
    lli cnt = 0;
    REP(i,0,N){
        if(A[i] > v[i].first)ok = false;
    }

    if(!ok){
        cout<<NO<<endl;
        return;
    }

    REP(i,0,N){
        d[A[i]].push(i);
    }
    UnionFind uf(N);

    REP(i,0,N){
        lli nex = d[v[i].second].front();
        d[v[i].second].pop();
        uf.unite(i,nex);
    }
    set<lli> roots;
    REP(i,0,N){
        roots.insert(uf.root(i));
    }
    if(roots.size()==1){
        cout<<NO<<endl;
    }
    else{
        cout<<YES<<endl;
    }
}

int main(){
    // cout << fixed << setprecision(5);

