    REP(i, N) if (BS[i] < AS[i]) no();

    BIT<int> bit(N + 1);
    REP(i, N - 1) if (AS[i + 1] <= BS[i]) bit.add(i + 1, 1);

    REP(i, N)
    {
        int a = A[i], b = B[i];
        if (a > b) continue;
        int j = upper_bound(ALL(AS), a) - AS.begin() - 1;
        int k = lower_bound(ALL(BS), b) - BS.begin();
        if (j >= k or bit.sum(k + 1) - bit.sum(j + 1) == k - j)
        {
            yes();
        }
    }
    no();
}

