bool check(vector<int> a, vector<int> b) {
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for (int i = 0; i < int(a.size()); ++i)
    if (a[i] > b[i])
      return false;
  return true;
}

int main() {
  int n;
  scanf("%d", &n);
  vector<int> a(n), b(n);
  for (int i = 0; i < n; ++i)
    scanf("%d", &a[i]);
  for (int i = 0; i < n; ++i)
    scanf("%d", &b[i]);
  if (!check(a, b))
    return 0 * puts("No");
  vector<int> c(a), d(b);
  sort(c.begin(), c.end());
  sort(d.begin(), d.end());
  c.erase(unique(c.begin(), c.end()), c.end());
  d.erase(unique(d.begin(), d.end()), d.end());
