	}
	int m=l+r>>1;
	build(lson);build(rson);
}
void change(int p,ll v,int l,int r,int rt){
    if(l==r){
        tr[rt]=min(tr[rt],v);
        return ;
    }
    int m=l+r>>1;
    if(p<=m) change(p,v,lson);
    if(p>m) change(p,v,rson);
    tr[rt]=min(tr[rt<<1],tr[rt<<1|1]);
}
ll query(int L,int R,int l,int r,int rt){
    if(L<=l && r<=R) return tr[rt];
    ll ret=inf;
    int m=l+r>>1;
    if(L<=m) ret=min(ret,query(L,R,lson));
    if(R>m) ret=min(ret,query(L,R,rson));
    return ret;
}
ll dfs(int l,int r,ll v){
	if(l==r) return l;
	int m=l+r>>1;
	ll Q=query(l,m,1,n,1);
	if(Q>v) dfs(m+1,r,v);
	else dfs(l,m,v);
}
