template <typename T>
class SegmentTree
{
private:
  using Fn = function<T(T, T)>;
  int N;
  vector<T> dat;
  T unit;
  Fn func;

public:
  SegmentTree() {}
  SegmentTree(int n_, Fn func_, T unit_) : func(func_), unit(unit_)
  {
    N = 1;
    while (N < n_)
      N *= 2;
    dat.assign(2 * N - 1, unit);
  }

  void init(int n_, Fn func_, T unit_)
  {
    func = func_, unit = unit_;
    N = 1;
    while (N < n_)
      N *= 2;
    dat.assign(2 * N - 1, unit);
  }

  void update(int k, T a)
  {
    k += N - 1;
    dat[k] = a;
    while (k > 0)
    {
      k = (k - 1) / 2;
      dat[k] = func(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  T query(int a, int b, int k = 0, int l = 0, int r = -1)
  {
    if (r < 0)
      r = N;
    if (r <= a || b <= l)
      return unit;
    if (a <= l && r <= b)
      return dat[k];
    else
    {
      T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return func(vl, vr);
    }
  }
};

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << setprecision(30) << setiosflags(ios::fixed);

  int n;
  cin >> n;
  pii p[100010];
  rep(i, n) cin >> p[i].first;
  rep(i, n) cin >> p[i].second;
  sort(p, p + n);
  int a[100010], b[100010];
  rep(i, n) a[i] = p[i].first, b[i] = p[i].second;
  int b_s[100010];
  rep(i, n) b_s[i] = b[i];
  sort(b_s, b_s + n);
  map<int, int> pos;
  rep(i, n) pos[b_s[i]] = i;
  auto f = [](bool b1, bool b2) { return b1 & b2; };
  SegmentTree<bool> sg(n, f, true), sg_l(n, f, true), sg_r(n, f, true);
  rep(i, n)
  {
    sg.update(i, (a[i] <= b_s[i]));
    if (i != n - 1)
      sg_l.update(i, (a[i] <= b_s[i + 1]));
    if (i != 0)
      sg_r.update(i, (a[i] <= b_s[i - 1]));
  }

  rep(i, n)
  {
    int j = pos[b[i]];
    bool can = true;
    if (j < i)
    {
      can &= sg.query(0, j);
      can &= sg_l.query(j, i);
      can &= (a[i] <= b[i]);
      can &= sg.query(i + 1, n);
    }
    else if (j > i)
    {
      can &= sg.query(0, i);
      can &= (a[i] <= b[i]);
      can &= sg_r.query(i + 1, j + 1);
      can &= sg.query(j + 1, n);
    }
    else
    {
      can &= sg.query(0, n);
    }
    if (can)
    {
      Yes(true);
      return 0;
    }
  }
  Yes(false);
  return 0;
}

