  sort(ALL(cop_a));
  sort(ALL(cop_b));
  REP(i, n) {
    if (cop_a[i] > cop_b[i]) {
      cout << "No\n";
      return 0;
    }
  }
  map<int, int> group;
  map<int, set<int> > elem;
  int l = 0;
  FOR(i, 1, n) {
    if (cop_a[i] > cop_b[l]) {
      int sz = group.size();
      FOR(j, l, i) {
        group[cop_a[j]] = sz;
        elem[sz].emplace(cop_b[j]);
      }
      l = i;
    }
  }
  int sz = group.size();
  FOR(j, l, n) {
    group[cop_a[j]] = sz;
    elem[sz].emplace(cop_b[j]);
  }
  REP(i, n) {
