    build(o*2+1,l,mid);
    build(o*2+2,mid+1,r);
    tr[o]=min(tr[o*2+1],tr[o*2+2]);
}
void push_down(int o){
    lazy[o*2+1]+=lazy[o];
    lazy[o*2+2]+=lazy[o];
    tr[o*2+1]+=lazy[o];
    tr[o*2+2]+=lazy[o];
    lazy[o]=0;
}
void push_up(int o){
    tr[o]=min(tr[o*2+1],tr[o*2+2]);
}

int query(int o,int L,int R,int l,int r){
    //cout<<l<<r<<endl;
    if(l<=L && r>=R){
        return tr[o];
    }
    push_down(o);
    int mid = (L+R)/2;
    int ans= INF;
    if(l<=mid)ans=min(ans,query(o*2+1,L,mid,l,r));
    if(r>mid) ans=min(ans,query(o*2+2,mid+1,R,l,r));
    push_up(o);
    return ans;
}

void ins(int o,int L,int R,int l,int r,int val){
    //cout<<L<<R<<" "<<l<<r<<endl;
    if(l<=L && r>=R){
        lazy[o]+=val;
        tr[o]+=val;
        return;
    }
    push_down(o);
    int mid = (L+R)/2;
    if(l<=mid)ins(o*2+1,L,mid,l,r,val);
    if(r>mid)ins(o*2+2,mid+1,R,l,r,val);
    push_up(o);
}


