    sort (ALL (sorted_a));
    sort (ALL (sorted_b));
    rep (i, n)
    {
      if (not (sorted_a [i] <= sorted_b [i]))
      {
        goto finish;
      }
    }
  }
  {
    vector <pair <ll, ll>> v1;
    rep (i, n) v1.emplace_back (b [i], a [i]);
