struct VectorItem
{
  uint64_t a, i;
  VectorItem(uint64_t a=-1, uint64_t i=-1) : a(a), i(i) {}

  bool operator<(const VectorItem &item) const {
    return (a == item.a) ? i < item.i : a < item.a;
  }
};

uint64_t count_cycles(uint64_t N, const vector<VectorItem> &A)
{
  uint64_t count = 0;
  vector<bool> checked(N, false);

  for (uint64_t n = 0; n < N; ++n) {
    if (checked[n]) { continue; }

    uint64_t start = n, index = A[n].i;
    while (index != start) {
      checked[index] = true;

      index = A[index].i;
      if (checked[index]) { break; }
    }

    ++count;
  }

  return count;
}

int main()
{
  uint64_t N;
  cin >> N;

  vector<VectorItem> A(N);
  vector<uint64_t> B(N);
  for (uint64_t n = 0; n < N; ++n) { cin >> A[n].a; A[n].i = n; }
  for (uint64_t n = 0; n < N; ++n) { cin >> B[n]; }
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());

  bool flag = true;
  for (uint64_t n = 0; n < N; ++n) {
    flag &= A[n].a <= B[n];
  }

  if (count_cycles(N, A) == 1) {
    bool flag2 = false;
    for (uint64_t n = 0; n < N - 1; ++n) {
      flag2 |= B[n] >= A[A[n + 1].i].a;
    }
    flag &= flag2;
  }

  cout << (flag ? "Yes" : "No") << endl;

  return 0;
}

