struct UnionFind
{
	const int n;
	vector<int> rank;
	vector<int> par;
	UnionFind(int _n): n(_n)
	{
		rank.assign(n, 0);
		par.assign(n, -1);
	}

	int find(int i)
	{
		if (par[i] == -1) return i;
		else return par[i] = find(par[i]);
	}

	void unite(int i, int j)
	{
		i = find(i);
		j = find(j);
		if (i == j) return;

		if (rank[i] == rank[j])
		{
			par[i] = j;
			++rank[j];
		}
		else
		{
			if (rank[i] > rank[j]) swap(i, j);
			par[i] = j;
		}
	}
	bool is_same(int i, int j)
	{return find(i) == find(j);}
};



