		if (cnt[uni.root(b[i].second)] == 0)cnt[uni.root(b[i].second)] = 1;
		if (cnt[uni.root(a[i].second)] == 0)cnt[uni.root(a[i].second)] = 1;
		if (!uni.same(a[i].second, b[i].second))cnt[uni.root(b[i].second)]+=cnt[uni.root(a[i].second)];
		if(!uni.same(a[i].second,b[i].second))uni.unite(a[i].second, b[i].second);
		//cout << uni.root(a[i].second) <<" "<<uni.root(b[i].second)<< endl;
	}
