int nextInt() { int x; scanf("%d", &x); return x;}
ll nextLong() { ll x; scanf("%lld", &x); return x;}

const int MAX_N = 112345;
int A[MAX_N];
int B[MAX_N];
int tA[MAX_N];
int tB[MAX_N];
pair<int,int> P[MAX_N];

bool solve() {
  int N = nextInt();
  REP(i, N) A[i] = nextInt();
  REP(i, N) B[i] = nextInt();
  {
    REP(i, N) tA[i] = A[i];
    REP(i, N) tB[i] = B[i];
    sort(tA, tA + N);
    sort(tB, tB + N);
    REP(i, N) if (tA[i] > tB[i]) return false;

    for (int i = 1; i < N; i++) {
      swap(tA[i-1], tA[i]);
      if (tA[i] <= tB[i] && tA[i-1] <= tB[i-1]) return true;
      swap(tA[i-1], tA[i]);
    }
  }

  REP(i, N) P[i] = make_pair(A[i], B[i]);
  sort(P, P+N, [](const pair<int,int>&a, const pair<int,int>& b){
    return a.second < b.second;
  });
  REP(i, N) P[i] = make_pair(P[i].first, i);
  sort(P, P+N);

  int cycle_len = 0;
  int i = 0;
  do {
    i = P[i].second;
    cycle_len++;
  } while (i != 0);
  if (cycle_len == N) return false;
  return true;
}

