namespace Cesare {

	/*
		根据 b 排序，使 a 也有序的最少交换次数。 
		n - 2 次交换是否能使序列有序。

		3 1 6 4 3 2
		2 2 3 3 4 8

		1 2 3 3 4 6 
	*/

	ll n, A[N];

	struct Node {
		ll a, b;
	} K[N];

	inline bool cmp (Node a, Node b) {
		return a.b == b.b? a.a < b.a: a.b < b.b;
	}

	#define int long long

	vector <int> v;

	int getMinSwaps(vector<int> v)
	{
	    vector<int> v1(v);   //将A内元素复制到B。
	    sort(v1.begin(), v1.end());
	    map<int,int> m;
	    int len = v.size();
	    for (int i = 0; i < len; i++)
	    {
	        m[v1[i]] = i;    //  建立每个元素与其应放位置的映射关系
	    }
	    int loops = 0;      //  循环节个数
	    vector<bool> flag(len, false); //初始化
	    //找出循环节的个数
	    for (int i = 0; i < len; i++)
	    {
	        if (!flag[i])
	        {
	            int j = i;
	            while (!flag[j])     //对环处理
	            {
	                flag[j] = true;
	                j = m[v[j]];    //原序列中j位置的元素在有序序列中的位置
	            }
	            loops++;
	        }
	    }
	    return len - loops;
	}

	signed main() {
		n = read();
		For ( i, 1, n ) A[i] = K[i].a = read();
		For ( i, 1, n ) K[i].b = read();
		For ( i, 1, n ) v.push_back(A[i]);
		sort(A + 1, A + n + 1);
		sort(K + 1, K + n + 1, cmp);

		For ( i, 1, n ) if (A[i] > K[i].b) return puts("No"), 0;
		ll num = getMinSwaps(v);
		if (num <= n - 2) puts("Yes");
		else puts("No");
		return 0;
	} // 至少有一个位置的交换一次就换对两个地方。 

}

