int minSwapsToSort(int arr[], int n)
{
    pair<int, int> arrPos[n];
    for (int i = 0; i < n; i++)
    {
        arrPos[i].first = arr[i];
        arrPos[i].second = i;
    }
    sort(arrPos, arrPos + n);
    vector<bool> vis(n, false);
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        if (vis[i] || arrPos[i].second <= i)
            continue;
        int cycle_size = 0;
        int j = i;
        while (!vis[j])
        {
            vis[j] = 1;
            j = arrPos[j].second;
            cycle_size++;
        }
        ans += (cycle_size - 1);
    }

    return ans;
}
int minSwapToMakeArraySame(int a[], int b[], int n)
{
    map<int, int> mp;
    for (int i = 0; i < n; i++)
        mp[b[i]] = i;

    for (int i = 0; i < n; i++)
        b[i] = mp[a[i]];

    return minSwapsToSort(b, n);
}

