class Solution {
public:
	void no(){
		cout << "No\n";
		return;
	}
	void yes(){
		cout << "Yes\n";
		return;
	}
	void solve() {
		int n;
		cin >> n;
		vector<int> a(n, 0), b(n, 0);
		for(int i=0; i<n; i++)cin >> a[i];
		for(int i=0; i<n; i++)cin >> b[i];
		vector<int> sa{a}, sb{b};
		sort(sa.begin(), sa.end());
		sort(sb.begin(), sb.end());
		for(int i=0; i < n; i++)if(sa[i] > sb[i])return no();
		vector<int> prevok(n+1, 0);
		for(int i=1; i < n; i++)if(sa[i] <= sb[i-1])prevok[i] = 1;
		for(int i=0; i < n; i++)prevok[i+1] += prevok[i];
		unordered_map<int, int> ai, bi;
		for(int i=0; i < n; i++)ai[sa[i]] = i;
		for(int i=n-1; i >= 0; i--)bi[sb[i]] = i;
		for(int i=0; i < n; i++){
			if(a[i] <= b[i]){
				if(prevok[bi[b[i]]+1]-prevok[ai[a[i]]] == bi[b[i]+1] - ai[a[i]]){
					cout << "Yes\n";
					return;
				}
			}
		}
		cout << "No\n";
		return;
	};
};

