struct SegTree {

	vector<int> data;
	int size;

	void init(vector<int>& init_data) {
		size = 1;
		while(size < (int)init_data.size()) {
			size = size * 2;
		}
		data.resize(size * 2);
		for(int i = 0; i < (int)init_data.size(); i++) {
			data[size + i] = init_data[i];
		}
		for(int i = (int)init_data.size(); i < size; i++) {
			data[size + i] = -1;
		}
		for(int i = size - 1; i > 0; i--) {
			data[i] = max(data[i * 2 + 0], data[i * 2 + 1]);
		}
	}

	void update(int pos, int val) {
		pos = pos + size;
		data[pos] = val;
		pos = pos / 2;
		while(pos > 0) {
			data[pos] = max(data[pos * 2 + 0], data[pos * 2 + 1]);
			pos = pos / 2;
		}
	}

	int maxi(int l, int r, int a, int b, int k) {

		if(r <= a || b <= l) {
			return -1;
		}
		if(a <= l && r <= b) {
			return data[k];
		}

		int mid = (a + b) / 2;
		int lv = maxi(l, r, a, mid, k * 2 + 0);
		int rv = maxi(l, r, mid, b, k * 2 + 1);
		return max(lv, rv);
	}

	int maxi(int l, int r) {
		return maxi(l, r, 0, size, 1);
	}
};

int main()
{
	int n;
	vector<int> as, bs;

	scanf("%d", &n);
	as.resize(n);
	bs.resize(n);
	for(int i = 0; i < n; i++) {
		scanf("%d", &as[i]);
	}
	for(int i = 0; i < n; i++) {
		scanf("%d", &bs[i]);
	}

	vector<pair<int, int>> cells;

	for(int i = 0; i < n; i++) {
		cells.push_back({bs[i], as[i]});
	}
	sort(cells.begin(), cells.end());

	vector<pair<int, int>> as_list;
	for(int i = 0; i < n; i++) {
		as_list.push_back({cells[i].second, i});
	}
	sort(as_list.begin(), as_list.end());

	vector<int> a_ord(n);
	for(int i = 0; i < n; i++) {
		a_ord[as_list[i].second] = i;
	}

	vector<int> pos_list_data(n);
	for(int i = 0; i < n; i++) {
		pos_list_data[a_ord[i]] = i;
	}

	SegTree pos_list;
	pos_list.init(pos_list_data);
	int step = 0;

	for(int pos = 0; pos < n; pos++) {

		int b = cells[pos].first, a = cells[pos].second;

		if(b >= a) {
			continue;
		}

		pair<int,int> l = {b, inf};
		int o = upper_bound(as_list.begin(), as_list.end(), l) - as_list.begin();
		int target = pos_list.maxi(0, o);

		if(o == 0 || target <= pos) {
			step = inf;
			break;
		} else {
			swap(cells[pos].second, cells[target].second);
			swap(a_ord[pos], a_ord[target]);
			pos_list.update(a_ord[pos], pos);
			pos_list.update(a_ord[target], target);
			step += 1;
		}
	}

	printf("%s\n", step <= n - 2 ? "Yes" : "No");

	return 0;
}

