class union_find{
public:
	int n;
	vector<int> parent;
	union_find(int n_){
		n = n_;
		parent.assign(n, 0);
		rep(i, n){
			parent[i] = i;
		}
	}

	int get_parent(int x){
		if(parent[x] == x)return x;
		return parent[x] = get_parent(parent[x]);
	}

	bool is_same(int a, int b){
		int ap = get_parent(a);
		int bp = get_parent(b);
		return ap == bp;
	}

	void merge(int a, int b){
		int ap = get_parent(a);
		int bp = get_parent(b);
		if(ap==bp)return;
		parent[bp] = ap;
	}

	int solve(){
		vector<int> cnt(n, 0);
		foreach(i, parent){ 
			++cnt[i];
		}
		int res = 0;
		foreach(i, cnt){
			if(!i)continue;
			res += i - 1;
		}
		return res;
	}
};


int main(){
	int n;
	cin >> n;
	vector<pii> line(n);
	foreach(i, line)cin>>i.second;
	foreach(i, line)cin>>i.first;
	sort(all(line));
	vector<int> need(n, 0);
	union_find uf(n);
	line.emplace_back(INF, 0);
	rep(j, n){
		pii i = line[j];
		if(i.first >= i.second)continue;
		int p = lower_bound(all(line), pii(i.second, 0)) - line.begin();
		if(p==n){
			cout << "No" << endl;
			return 0;
		}
		++need[p];
		uf.merge(p, j);
	}
	rep(i, n){
		rep(j, need[i]){
			if(i+j>=n){
				cout << "No" << endl;
				return 0;
			}
			uf.merge(i, i+j);
		}
	}

	int ans = uf.solve();
	if(ans<=n-2){
		cout << "Yes" << endl;
	}else{
		cout << "No" << endl;
	}
	return 0;
}

