    for(int i=0; i<N; i++){
        AS[i] = {A[i], i};
        BS[i] = {B[i], i};
    }
    sort(AS.begin(), AS.end());
    sort(BS.begin(), BS.end());
    vector<int> AR(N), BR(N);
    for(int i=0; i<N; i++){
        AR[AS[i].second] = i;
        BR[BS[i].second] = i;
    }

