    BIT<int> bitl(N), bitc(N), bitr(N);
    for(int i=0; i<N; i++){
        if(i > 0 && AS[i].first > BS[i-1].first) bitl.plus(i, 1);
        if(AS[i].first > BS[i].first) bitc.plus(i, 1);
        if(i < N-1 && AS[i].first > BS[i+1].first) bitr.plus(i, 1);
    }

    for(int i=0; i<N; i++){
        if(A[i] > B[i]) continue;
        int ap = AR[i], bp = BR[i];
        int ng = 0;
        if(ap < bp){
