#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}

bool solve(int N, vi& a, vi& b) {
    vi _a(ALL(a)), _b(ALL(b));
    sort(ALL(_a));
    sort(ALL(_b));
    map<int,set<int>> mp;
    rep(i,N){
        if (_a[i] > _b[i]) return false;
        mp[ _a[i] ].insert( _b[i] );
    }

    int ngc = 0;
    rep(i,N) {
        if (a[i] > b[i]) ngc++;
    }
    if (ngc < N) return true;

    vii c(N); rep(i,N) c[i]=ii(b[i],a[i]);
    sort(ALL(c));
    int d = 0;
    rep(i,N-1){
        if (c[i].first >= c[i].second) d++;
    }
    return (d > 0);
}

int main() {
    int N; scanf("%d%*c", &N);
    vi a(N), b(N);
    loadvec(a,N); loadvec(b,N);
    cout << (solve(N,a,b) ? "Yes":"No") << endl;
    return 0;
}

