const int N=1e5+5;
int n,f[N],fff[N],ggg[N],g[N],t[2][N<<2],pre[N],bk[N];
struct node
{
    int x,id;
    bool operator<(const node&o)const
    {
        return x<o.x;
    }
}a[N],b[N];
void build(int l,int r,int k)
{
    if(l==r)
    {
        t[0][k]=pre[l];
        t[1][k]=bk[l];
        return;
    }
    int m=l+r>>1;
    build(l,m,k<<1);
    build(m+1,r,k<<1|1);
    t[0][k]=t[0][k<<1]&t[0][k<<1|1];
    t[1][k]=t[1][k<<1]&t[1][k<<1|1];
}
int query(int l,int r,int k,int x,int y,int p)
{
    if(l>y||r<x) return 1;
    if(l>=x&&r<=y) return t[p][k];
    int m=l+r>>1;
    return query(l,m,k<<1,x,y,p)&query(m+1,r,k<<1|1,x,y,p);
}
int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++) scanf("%d",&a[i].x),a[i].id=i;
    for(int i=1;i<=n;i++) scanf("%d",&b[i].x),b[i].id=i;
    sort(a+1,a+1+n);
    sort(b+1,b+1+n);
    bool flag=true;
    for(int i=1;i<=n;i++)
        if(a[i].x>b[i].x) flag=false;
    for(int i=2;i<=n;i++)
        if(a[i-1].x<=b[i].x) pre[i]=1;
    for(int i=1;i<n;i++)
        if(a[i+1].x<=b[i].x) bk[i]=1;
    build(1,n,1);
    for(int i=1;i<=n;i++)
    {
        f[a[i].id]=i;fff[a[i].id]=a[i].x;
        g[b[i].id]=i;ggg[b[i].id]=b[i].x;
    }
    bool ff=false;
    for(int i=1;i<=n;i++)
    {
        if(fff[i]>ggg[i]) continue;
        int x=f[i],y=g[i];
        if(x==y) {ff=true;break;}
        if(b[x].x==ggg[i]) {ff=true;break;}
        if(x<y)
        {
            if(query(1,n,1,x,y-1,1)) ff=true;
        }
        else
        {
            if(query(1,n,1,y+1,x,0)) ff=true;
        }
    }
    if(!ff) flag=false;
    printf(flag?"Yes\n":"No\n");
}

