          cout << "No" << endl;
          return;
        }
      }
      for(int i=1; i<n-1; i++) {
        if (sa[i+1] <= sb[i]) {
          cout << "Yes" << endl;
          return;
        }
        if (sa[i] == sa[i+1] || sb[i] == sb[i+1]) {
          cout << "Yes" << endl;
          return;
        }
      }

      map<int, int> ma, mb;
      rep(i, n) {
        ma[a[i]] = i;
        mb[b[i]] = i;
      }

      for(int i=0; i<n-2; i++) {
        auto apos = ma[sa[i]];
        auto bpos = mb[sb[i]];
        if (apos == bpos) {
          cout << "Yes" << endl;
          return;
        }
        swap(a[apos], a[bpos]);
        ma[a[apos]] = apos;
        ma[a[bpos]] = bpos;
      }

      rep(i, n) {
        if (a[i] > b[i]) {
          cout << "No" << endl;
          return;
        }
      }

      cout << "Yes" << endl;
    }
};

