typedef pair<int, int> P;
typedef long long ll;
class UnionFindTree
{
    vector<int> parent;
    vector<int> depth;
    vector<int> cnt;

public:
    UnionFindTree(int n) : parent(n), depth(n), cnt(n)
    {
        for (int i = 0; i < n; i++)
        {
            parent[i] = i;
            depth[i] = 0;
            cnt[i] = 1;
        }
    }

    //木の根を求める
    int find(int x)
    {
        if (parent[x] == x)
        {
            return x;
        }
        else
        {
            return parent[x] = find(parent[x]);
        }
    }

    //xとyの属する集合を併合
    void unite(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (depth[x] < depth[y])
        {
            parent[x] = y;
            cnt[y] += cnt[x];
        }
        else
        {
            parent[y] = x;
            cnt[x] += cnt[y];
            if (depth[x] == depth[y])
                depth[x]++;
        }
    }

    bool same(int x, int y)
    {
        return find(x) == find(y);
    }

    int size(int x)
    {
        return cnt[find(x)];
    }
};
int main(){
    int n;
    cin >> n;
    vector<P> c(n);
    vector<P> d(n);
    int mx = 0;
    UnionFindTree utree(n+10);
    rep(i,n){
        int x;
        cin >> x;
        c[i] = P(x,i);
    }
    rep(i,n){
        int x;
        cin >> x;
        d[i] = P(x,i);
    }
    sort(c.begin(),c.end());
    sort(d.begin(),d.end());
    rep(i,n){
        if(c[i].first>d[i].first){
            cout << "No" << endl;
            return 0;
        }
        utree.unite(c[i].second,d[i].second);
        mx = max(mx,utree.size(c[i].second));
    }
    if(mx==n){
        cout << "No" << endl;
    }
    else{
        cout << "Yes" << endl;
    }
    return 0;
}

