template <typename T>
inline auto sort_with_index (const vector <T> & a)
{
  vector <pair <T, size_t>> res;
  size_t i = 0;
  for (auto && elem : a)
  {
    res.emplace_back (elem, i ++);
  }
  sort (ALL (res));
  return res;
}

auto main () -> int
{
  cin.tie (nullptr);
  ios::sync_with_stdio (false);

  size_t n;
  cin >> n;

  vector <ll> a (n), b (n);
  rep (i, n) cin >> a [i];
  rep (i, n) cin >> b [i];

  auto sorted_a = a;
  auto sorted_b = b;
  sort (ALL (sorted_a));
  sort (ALL (sorted_b));

  auto murimi = false;

  rep (i, n)
  {
    if (not (sorted_a [i] <= sorted_b [i]))
    {
      murimi = true;
      goto finish;
    }
  }

  {
    {
      vector <pair <ll, ll>> v;
      rep (i, n)
      {
        v.emplace_back (b [i], a [i]);
      }
      sort (ALL (v));
      rep (i, n)
      {
        tie (b [i], a [i]) = v [i];
      }
    }
    size_t cnt = 0;
    rep (i, n)
    {
      if (not (a [i] <= b [i]))
      {
        rep (j, n)
        {
          if (i == j) continue;
          if (a [j] <= b [i] && a [i] <= b [j])
          {
            swap (a [i], a [j]);
            ++ cnt;
            goto next_loop;
          }
        }
        rep (j, n)
        {
          if (i == j) continue;
          if (a [j] <= b [i])
          {
            swap (a [i], a [j]);
            ++ cnt;
            goto next_loop;
          }
        }
      }
next_loop:
      ;
    }
    if (cnt >= n - 1)
    {
      murimi = true;
    }
  }

finish:
  cout << (murimi ? "No" : "Yes") << endl;
}

