struct BIT{
	int b[maxn];
	void clear(){
		memset(b,0,sizeof(b));
	}
	inline int lowbit(int x){
		return x&(-x);
	}
	void upd(int x,int d){
		for(;x<maxn;x+=lowbit(x))
			b[x]+=d;
	}
	int query(int x){
		int ret=0;
		for(;x;x-=lowbit(x))
			ret+=b[x];
		return ret;
	}
}bit;
