// This means that either the permutation already has 2 disjoint cycles, or
// some pair of (a[i],a[j]) can be swapped and still result in a sorted configuration.



int n;
vector<int> a,b;

vector<pair<int,int>> v;

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);
    cin>>n;
