    }
    for (int i=0; i<n; i++) {
	cin>>b[i];
    }
    for (int i=0; i<n; i++) {
	v[i].first=a[i];
	v[i].second=b[i];
    }
    sort(a.begin(),a.end());
    sort(b.begin(),b.end());

    // Impossible even if we had infinite swaps
    for (int i=0; i<n; i++) {
	if (a[i]>b[i]) out("No");
    }

    // Permutations take at most n-1 swaps to sort.

    // We know that [..(a[i],b[i]),(a[i+1],b[i+1])..] and
    // [..(a[i+1],b[i]),(a[i],b[i+1])..] are both valid, which means
    // that we can sort up to 2 disjoint cycles which will take at most n-2 swaps.

    for (int i=0; i<n-1; i++) {
	if (a[i+1]<=b[i]) out("Yes");
    }



    // If perm has more than 1 disjoint cycle, it's possible
    sort(v.begin(), v.end(), [&](pair<int,int> p1, pair<int,int> p2) {
	    return p1.second<p2.second;
	});

    vector<int> perm(n, 0);
    for (int i=0; i<n; i++) {
	perm[i] = lower_bound(a.begin(), a.end(), v[i].first) - a.begin();
    }
    vector<int> viz(n, 0);
    for (int i=0, x=0; i<n; i++) {
	viz[x]=1;
	x=perm[x];
    }

    cout<<(std::count(viz.begin(),viz.end(),1)==n ? "No\n" : "Yes\n");


    return 0;
}

