  sort(A.begin(), A.end());
  sort(B.begin(), B.end());

  bool able = true;
  for(int i = 0; i < N; i++){
    if(A[i].first > B[i]){
      able = false;
      break;
    }
  }

  UnionFindTree permutation(N);
  for(int i = 0; i < N; i++){
    permutation.unite(A[i].second, i);
  }

  int cnt = 0;
  for(int i = 0; i < N; i++){
    if(permutation.find(i) == i) cnt++;
  }

  if(able && cnt == 1){
    able = false;
    for(int i = 0; i < N - 1; i++){
      if(B[i] >= A[i + 1].first){
        able = true;
        break;
      }
    }
  }

  cout << (able ? "Yes" : "No") << endl;

  return 0;
}

