const int SIZE = 1e6+10;
int A[SIZE],B[SIZE],aa[SIZE],bb[SIZE];
struct Union_Find{
    int d[SIZE],num[SIZE];
    void init(int n){
        REP(i,n)d[i]=i,num[i]=1;
    }
    int find(int x){return (x!=d[x])?(d[x]=find(d[x])):x;}
    bool is_root(int x){return d[x]==x;}
    bool uu(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y)return 0;
        if(num[x]>num[y])swap(x,y);
        num[y]+=num[x];
        d[x]=y;
        return 1;
    }
}U;
int main(){
    int N; R(N);
    REP(i,N){R(A[i]);aa[i]=A[i];}
    REP(i,N){R(B[i]);bb[i]=B[i];}
    sort(aa,aa+N);
    sort(bb,bb+N);
    REP(i,N){
        if(aa[i]>bb[i]){
            W("No");
            return 0;
        }
    }
    REPP(i,1,N){
        if(aa[i]<=bb[i-1]){
            W("Yes");
            return 0;
        }
    }
    U.init(N);
    REP(i,N){
        int pos=lower_bound(aa,aa+N,A[i])-aa;
        U.uu(i,pos);
    }
    int cc=0;
    REP(i,N){
        if(U.is_root(i))cc++;
    }
    W(cc>1?"Yes":"No");
    return 0;
}

