    bool can() {
        sort(RALL(B));
        sort(RALL(A));
        for (int i = 0; i < N; ++i) {
            if(B[i] < A[i]) return false;
        } // end i
        return true;
    }

    int sp() {
        int count = 0;
        for (int i = 0; i < N; ++i) {
            int a, b;
            tie(b, a) = ba[i];
            if(b < a) count++;
        } // end i
        return count;
