int N;

bool check(vector<int> A, vector<int> B) {
    sort(ALL(A));
    sort(ALL(B));
    for (int i : range(N)) {
        if (A[i] > B[i]) return false;
    }
    return true;
}
bool check1(vector<int> A, vector<int> B) {
    sort(ALL(A));
    sort(ALL(B));
    for (int i : range(N - 1)) {
        if (A[i + 1] <= B[i]) return true;
    }
    return false;
}


bool check2(vector<int> A, vector<int> B) {
    vector<int> id(N);
    iota(ALL(id), 0);
    sort(ALL(id), [&](int l, int r) {
        return pair<int, int>(A[l], B[l]) < pair<int, int>(A[r], B[r]);
    });
    vector<int> AA(N);
    vector<pair<int, int>> BB(N);
    for (int i : range(N)) {
        AA[i] = A[id[i]];
        BB[i] = {B[id[i]], i};
    }
    sort(ALL(BB));
    int cnt = 0;
    int x   = 0;
    do {
        x = BB[x].second;
        cnt++;
    } while (x > 0);
    return cnt != N;
}

