        cout << "No" << endl;
        return 0;
    }
    if (check1(A, B)) {
        cout << "Yes" << endl;
        return 0;
    }
    if (check2(A, B)) {
        cout << "Yes" << endl;
        return 0;
    }
    cout << "No" << endl;
    return 0;
}

