	int ct = 0;
	for (auto& x : AB)
	{
		B[i] = x.first;
		A[i++] = x.second;
		if (x.first >= x.second)
		{
			++ct;
		}
	}
	if (ct == 0)
	{
		cout << "No" << endl;
		return;
	}
	multimap<int, int> Ai;
	for (int i = 0; i < N; ++i)
	{
		Ai.insert({ A[i], i });
	}
	vector<int> C(N);
	vector<int> oldIdx(N);
	i = 0;
	for (auto& x : Ai)
	{
		oldIdx[i] = x.second;
		C[i++] = x.first;
	}
	vector<int> flag(N);
	for (int i = 0; i < N; ++i)
	{
		if (C[i] > B[i])
		{
			cout << "No" << endl;
			return;
		}
		if(i< N-1)
			flag[i + 1] = flag[i] + (C[i + 1] > B[i] ? 0 : 1);
	}
	for (int i = 0; i < N; ++i)
	{
		int j = oldIdx[i];
		if (A[j] > B[j])
			continue;
		if (j <= i)
		{
			cout << "Yes" << endl;
			return;
		}
		int x = flag[j] - flag[i];
		if (x == j - i)
		{
			cout << "Yes" << endl;
			return;
		}
	}
	cout << "No" << endl;
}
