#include <bits/stdc++.h>
using namespace std;

bool hasCycle = false;

void search(int curr, vector<vector<int>> &v, vector<bool> &visited) {
    if (hasCycle) return;
    visited[curr] = true;
    for (auto &to: v[curr]) {
        if (visited[to]) {
            hasCycle = true;
            return;
        }
        search(to, v, visited);
    }
}

int main() {
    int n; cin >> n;
    vector<int> a(n), b(n), c(n), d(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i]; c[i] = a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i]; d[i] = b[i];
    }
    sort(c.begin(), c.end());
    sort(d.begin(), d.end());
    for (int i = 0; i < n; i++) {
        if (c[i] > d[i]) {
            cout << "No" << endl;
            return 0;
        }
    }
    for (int i = 0; i < n; i++) {
        int di = upper_bound(d.begin(), d.end(), c[i]) - d.begin();
        if (di-i != 1) {
            cout << "Yes" << endl;
            return 0;
        }
    }
    map<int, int> cm, dm;
    for (int i = 0; i < n; i++) {
        cm[c[i]] = i; dm[d[i]] = i;
    }
    vector<vector<int>> v(n);
    vector<bool> visited(n, false);
    for (int i = 0; i < n; i++) {
        v[cm[c[i]]].emplace_back(dm[b[i]]);
    }
    for (int i = 0; i < n; i++) {
        if (!visited[i]) search(i, v, visited);
    }
    if (hasCycle) cout << "Yes" << endl;
    else cout << "No" << endl;
    return 0;
}

