			ll it=lower_bound(ALL(a),mp(a[i].s,a[i].f))-a.begin();

			if(it>=i || cnt>n-2)
			{
				cout<<"No";

				return;
			}

			cnt++;

			swap(a[it].s,a[i].s);

			ll j=i+1;

			while(a[j-1].f==a[j].f && a[j-1].s>a[j].s && j<n)
			{
				swap(a[j-1],a[j]);
				j++;
			}

			i--;
		}
	}

	cout<<"Yes";
}

