      i64 j = (i64)(lower_bound(all(B), A[y]) - begin(B));
      MIN = min(MIN, j + CC[B[j]] - 1);
      CC[B[j]]--;
    }
    right = i;
    if(cnt <= MIN) {
      cout << "Yes" << endl;
      return 0;
    }
  }
  cout << "No" << endl;
