int N;
itn A[101010], B[101010];
vector<P> V;

void solve() {
    V.resize(N);
    FOR(N) {
        V[i] = P{A[i], B[i]};
    }
    sort(all(V));
    sort(A, A + N);
    sort(B, B + N);
    bool flag = true;
    FOR(i, 0, N) {
        if (A[i] > B[i])
            flag = false;
    }
    if (!flag) {
        No();
        return;
    }
    bool flag2 = false;
    FOR(i, 0, N - 1) {
        if (A[i + 1] <= B[i])
            flag2 = true;
    }
    if (flag2) {
        Yes();
        return;
    }
    SegmentTree<int> seg(N + 1, [](int a, int b) { return a + b; }, 0);
    seg.build();

    map<int, int> M;
    FOR(N) {
        M[V[i].second] = i;
    }

    int SUM = 0;
    FOR(N) {
        SUM += seg.query(0, M[V[i].second]);
        seg.update(M[V[i].second], 1);
    }

    Yes(SUM % 2 == (N - 1) % 2);
    return;
}

