    rep(i, n) cin >> as[i];
    rep(i, n)cin >> bs[i];

    if (!check(as, bs)) {
        cout << "No" << endl;
        ret();
    }

    sort_tuple(as, bs);

    map<ll, int> index;
    rep(i, n) {
        assert(index.find(as[i]) == index.end());
        index[as[i]] = i;
    }

    multiset<ll> wait;
    for (ll l : as) wait.insert(l);

    rep(i, n) {
        if (as[i] <= bs[i]) {
            cout << "Yes" << endl;
            ret();
        }

        ll o = as[i];

        ll sp = *wait.begin();
        ll spi = index[sp];

        swap(as[i], as[spi]);
        swap(index[o], index[sp]);

        assert(as[i] <= bs[i]);

        wait.erase(wait.find(sp));

    }

    cout << "No" << endl;

}

