const string YES = "Yes";
const string NO = "No";
// 1-indexed BIT (i : [1, len])
template<typename T>
struct BIT
{
    int len;
    vector<T> val;
    BIT(int num) : len(num), val(num + 1) {}
    BIT() : BIT(0) {}
    void reset() { fill(val.begin(), val.end(), 0); }
    void add(int pos, T v) { while (pos > 0 and pos <= len) val[pos] += v, pos += pos & -pos; }
    T sum(int pos) const // (0, pos]
    {
        T res = 0;
        while (pos > 0) res += val[pos], pos -= pos & -pos;
        return res;
    }
};
template<typename T> ostream &operator<<(ostream &os, const BIT<T> &b){ T prv = 0; os << "["; REP(i, b.len) { T nxt = b.sum(i + 1); os << nxt - prv << ","; prv = nxt; } os << "]"; return os; }


void no()
{
    cout << NO << endl;
    exit(0);
}
void yes()
{
    cout << YES << endl;
    exit(0);
}
int main()
{
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    cin >> A >> B;
    vector<int> AS = A, BS = B;
    sort(ALL(AS));
    sort(ALL(BS));
    REP(i, N) if (BS[i] < AS[i]) no();

    BIT<int> bit(N + 1);
    REP(i, N - 1) if (A[i + 1] <= B[i]) bit.add(i + 1, 1);

    map<int, int> Ainv, Binv;
    REP(i, N) Ainv[A[i]] = i;
    REP(i, N) if (Binv.count(B[i]) == 0) Binv[B[i]] = i;

    REP(i, N)
    {
        int a = A[i], b = B[i];
        int j = Ainv[a], k = Binv[b];
        if (j >= k or bit.sum(k) - bit.sum(j) == k - j) yes();
    }
    no();
}

