	vi b=readvi(n);
	vi c=a;
	c.insert(c.ed,all(b));
	mkuni(c);

	int s=c.size();
	vi sum(s);
	rep(i,n){
		a[i]=lower_bound(all(c),a[i])-c.bg;
		b[i]=lower_bound(all(c),b[i])-c.bg;
		sum[a[i]]++;
		sum[b[i]]--;
	}

	rep(i,s-1){
		sum[i+1]+=sum[i];
		if(sum[i]<0){
			no();
		}
	}

	unionfind uf(s);

	vi deg(s);
	rep(i,n){
		deg[b[i]]++;
		uf.unite(a[i],b[i]);
	}

	rep(i,s-1)if(sum[i]>0){
		uf.unite(i,i+1);
		deg[i]+=sum[i];
	}

	if(uf.c>=2)yes();

	if(*max_element(all(deg))>=2)yes();

	no();
}

