  sort(b2, b2+n);
  map<ll, set<ll>> mp;
  for (ll i = 0; i < n; i++) mp[a2[i]].insert(i);
  for (ll i = 0; i < n; i++) {
    auto tmp = mp[a[i]].begin();
    rev[i] = *tmp;
    mp[a[i]].erase(tmp);
  }
  SegmentTree<bool> sgt_aleft, sgt_aright; // b基準でaを左にずらす, aを右にずらす
  sgt_aleft.init(n, bsum, true, true);
  sgt_aright.init(n, bsum, true, true);
  for (ll i = 0; i < n; i++) if (a2[i] > b2[i]) {
    printf("No\n");
    return 0;
  }
  for (ll i = 1; i < n; i++) if (a2[i-1] > b2[i]) sgt_aleft.valueChange(i, false);
  for (ll i = 0; i < n-1; i++) if (a2[i+1] > b2[i]) sgt_aright.valueChange(i, false);
  ll counter = 1, now = rev[0];
  while (now != 0) counter++, now = rev[now];
  if (counter != n) {
    printf("Yes\n");
    return 0;
  }
  //for (ll i = 0; i < n; i++) printf("%c ", sgt_aleft.rangeQuery(i, i+1) ? 'o' : 'x'); printf("\n");
  //for (ll i = 0; i < n; i++) printf("%c ", sgt_aright.rangeQuery(i, i+1) ? 'o' : 'x'); printf("\n");
  for (ll i = 0; i < n; i++) if (a[i] <= b[i]) {
    ll x = rev[i];
    if (i < x) {
      if (!sgt_aleft.rangeQuery(i+1, x+1)) continue;
    }
    if (i > x) {
      if (!sgt_aright.rangeQuery(x, i)) continue;
    }
    printf("Yes\n");
    return 0;
  }
  printf("No\n");
}

