class Solve {
public:
    Int N;
    vector<Int> A, B;

    bool firstCheck() {
        vector<Int> X = A;
        vector<Int> Y = B;
        sort(all(X));
        sort(all(Y));
        for (int i = 0; i < N; ++i) {
            if (X[i] > Y[i]) {
                return false;
            }
        }
        return true;
    }

    void solve() {
        cin >> N;
        A.resize(N);
        B.resize(N);
        for (auto &a : A) cin >> a;
        for (auto &b : B) cin >> b;
        if (!firstCheck()) {
