            return;
        }

        int cnt = 0;
        for (int i = 0; i < N; ++i) {
            if (A[i] > B[i]) {
                cnt++;
            }
        }
        if (cnt <= N - 2) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }


    }
};


