  x = f(x);
  y = f(y);

  if(x == y) return;

  if(r[x] > r[y]) {
    p[y] = x;
  }
  else {
    if(r[x] == r[y]) r[x]++;
    p[x] = y;
  }
  comp--;
  return;
}

