vector<int> A, B;

class SegmentTree{

private: vector<int> st; int n;

inline int left (int p) { return p << 1; }
inline int right(int p) { return (p << 1) + 1; }

public:

void update(int p, int L, int R, int index){

    if(index < L || index > R) return;

	if(L == R && L == index) st[p] = index; //index

	else{

        int mid = (L+R)>> 1;

        int l = left(p);
        int r = right(p);

        update(l, L, mid, index);
        update(r, mid + 1, R, index);

        int p1 = st[l];
        int p2 = st[r];

        if(p1 == -1) st[p] = p2;
        else if(p2 == -1) st[p] = p1;
        else
            st[p] = (A[p1] <= A[p2]) ? p1 : p2;
    }

}

int rmq(int p, int L, int R, int i, int j){

	if(L > j || R < i) return -1; // non-existent
	if(L >= i && R <= j) return st[p];

	int mid = (L+R)>> 1;

	int l = left(p);
	int r = right(p);

	int p1 = rmq(l, L, mid, i, j);
	int p2 = rmq(r, mid + 1, R, i, j);

    if(p1 == -1) return p2;
	if(p2 == -1) return p1;

	return (A[p1] <= A[p2]) ? p1 : p2;
}

SegmentTree(int n){
	n = (int) A.size();
	st.assign(4*n, -1);
}

int rmq(int i, int j){ return rmq(1, 0, n - 1, i, j); }

};

