bool solve(long long N, std::vector<long long> A, std::vector<long long> B) {
  std::vector<pair<int,int>> ai(N);
  std::vector<pair<int,int>> bi(N);
  REP(i,N) ai[i] = make_pair(A[i], i);
  REP(i,N) bi[i] = make_pair(B[i], i);
  sort(ALL(ai));
  sort(ALL(bi));
  REP(i,N) {
    if (ai[i].first > bi[i].first) return false;
  }
  REP(i,N-1) {
    if (ai[i+1].first <= bi[i].first) return true;
  }
  vector<int> perm(N);
  REP(i,N) perm[ai[i].second] = bi[i].second;
  int v = 0;
  REP(i,N-1) {
    v = perm[v];
    if (v == 0) return true;
  }
  return false;
}

