template<class T> struct  SegTree{
    typedef  function<T(T, T)> F;
    int n = 1;
    vector<T> node;
    T et;
    F f, g;

    SegTree(int n_, T et_, F f_, F g_):
    et(et_), f(f_), g(g_){
        while(n < n_) n *= 2;
        node.resize(n*2-1, et);
    }

    void update(int i, T x){
        i += n-1;
        node[i] = g(node[i], x);
        while(i){
            i = (i-1) / 2;
            node[i] = f(node[i*2+1], node[i*2+2]);
        }
    }

    T query(int a, int b){
        T vl = et, vr = et;
        for(a+=n-1, b+=n-1; a<b; a=(a-1)/2, b=(b-1)/2){
            if(!(a&1)) vl = f(vl, node[a++]);
            if(!(b&1)) vr = f(node[--b], vr);
        }
        return f(vl, vr);
    }
};

int main(){
    int n;
    scanf("%d", &n);
    int A[n], B[n];
    rep(i, n) scanf("%d", &A[i]);
    rep(i, n) scanf("%d", &B[i]);
    pii p[n];
    rep(i, n) p[i] = make_pair(B[i], A[i]);
    sort(p, p+n);

    auto f = [](pii a, pii b){if(a.fi==b.fi){return b;} return min(a, b);};
    auto g = [](pii a, pii b){return b;};
    SegTree<pii> st(n, pii(INT_MAX, -1), f, g);
    rep(i, n) st.update(i, make_pair(p[i].se, i));
    int cnt = 0;
    rep(i, n-1)if(p[i].fi < p[i].se){
        ++cnt;
        auto q = st.query(i+1, n);
        if(q.fi > p[i].fi){
            printf("No\n");
            return 0;
        }
        p[q.se].se = p[i].se;
        p[i].se = q.fi;
        st.update(q.se, make_pair(p[q.se].se, q.se));
    }
    rep(i, n)if(p[i].fi < p[i].se){
        printf("No\n");
        return 0;
    }
    printf("%s\n", cnt <= n-2 ? "Yes" : "No");
}

