signed main(){
	vector<P> vec;
	int n,a[100010],b[100010];
	cin >> n;
	for(int i = 0;i < n;i++) cin >> a[i];
	for(int i = 0;i < n;i++) cin >> b[i];
	for(int i = 0;i < n;i++){
		vec.emplace_back(a[i],b[i]);
	}
	sort(all(vec),[](const P p1,const P p2){
		return p1.second < p2.second;
	});
	for(int i = 0;i < n;i++){
		a[i] = vec[i].first;
		b[i] = vec[i].second;
	}
	RMQ<PP> rmq(n + 5,P(INF,-1));
	for(int i = 0;i < n;i++) rmq.update(i,P(a[i],i));
	vector<P> veca;
	for(int i = 0;i < n;i++){
		veca.emplace_back(a[i],i);
	}
	sort(all(veca));
	for(int i = 0;i < n;i++){
		if(veca[i].first > b[i]){
			No();
			return 0;
		}
	}
	int nowIndex[100010];
	for(int i = 0;i < n;i++){
		nowIndex[i] = i;
	}
	int ans = 0;
	for(int i = n - 1;i >= 0;i--){
		int ind = lower_bound(b,b + n,veca[i].first) - b;
		if(ind <= nowIndex[veca[i].second]) continue;
		PP mi = rmq.get(ind,n);
		rmq.update(nowIndex[veca[i].second],mi.first);
		rmq.update(mi.second,veca[i]);
		swap(nowIndex[veca[i].second],nowIndex[mi.first.second]);
		ans++;
	}
	if(ans <= n - 2) Yes();
	else No();
}

