constexpr ll inf = 1e9;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<ll> a(n), b(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> b[i];
  }
  auto atmp = a, btmp = b;
  sort(atmp.begin(), atmp.end());
  sort(btmp.begin(), btmp.end());
  for (int i = 0; i < n; i++) {
    if (atmp[i] > btmp[i]) {
      //cerr << "!" << endl;
      cout << "No" << endl;
      return 0;
    }
  }
  vector<int> idx(n);
  iota(idx.begin(), idx.end(), 0);
  sort(idx.begin(), idx.end(),
       [&](const int &lhs, const int &rhs) { return b[lhs] < b[rhs]; });
  set<P> st;
  for (int i = 1; i < n; i++) {
    int index = idx[i];
    st.insert(P(a[index], index));
  }
  int cnt = 0;
  for (int i = 0; i < n; i++) {
    int index = idx[i];
    st.erase(P(a[index], index));
    if (a[index] <= b[index]) continue;
    cnt++;
    auto itr = st.upper_bound(P(b[index], inf));
    assert(itr != st.begin());
    itr--;
    int tar = (*itr).second;
    swap(a[index], a[tar]);
    st.erase(itr);
    st.insert(P(a[tar], tar));
  }
  cout << (cnt <= n - 2 ? "Yes" : "No") << endl;
}

