const ll MOD = 1000000007;
const ll INF = (ll)1e15;

ll N;
ll A[100005];
ll B[100005];
ll C[100005];
ll D[100005];
ll U[100005];

bool solve()
{
    if (N == 2)
    {
        REP(i, N)
        {
            if (A[i] > B[i])
                return false;
        }
        return true;
    }
    sort(C, C + N);
    sort(D, D + N);
    REP(i, N)
    {
        if (C[i] > D[i])
            return false;
    }

    memset(U, 0, sizeof(U));
    REP(i, N - 1)
    {
        if (C[i + 1] > D[i])
            U[i + 1]++;
        U[i + 1] += U[i];
    }

    REP(i, N)
    {
        if (A[i] > B[i])
            continue;

        ll r = N - 1, rn = -1;
        while (abs(r - rn) > 1)
        {
            ll mid = (r + rn) / 2;
            if (D[mid] >= B[i])
                r = mid;
            else
                rn = mid;
        }

        ll l = 0, ln = N;
        while (abs(l - ln) > 1)
        {
            ll mid = (l + ln) / 2;
            if (C[mid] <= A[i])
                l = mid;
            else
                ln = mid;
        }
        if (U[r] - U[l] <= 0)
            return true;
    }
    return false;
}

