    for (int i = 1; i <= n; ++i) {
        cc.pb({b[i], a[i]});
    }
    sort(all(cc));

    vector<int> c(a + 1, a + n + 1);
    vector<int> d(b + 1, b + n + 1);

    sort(all(c));
    sort(all(d));
    for (int i = 0; i < sz(d); ++i) {
        if (c[i] > d[i]) {
            cout << "No\n";
            return;
        }
    }

    for (int i = 0; i < n; ++i) {
        a[i + 1] = cc[i].se;
        b[i + 1] = cc[i].fi;
    }

    for (int i = 1; i <= n; ++i) {
