    dout << endl;

    int cnt = 0;
    build(1, 1, n);
    for (int i = 1; i <= n; ++i) {
        if (a[i] <= b[i]) {
            continue;
        }
        dout << i << " : " << a[i] << " - " << b[i] << endl;
        int pos = upper_bound(b + 1, b + n + 1, a[i]) - b;
        pii res1 = get(1, 1, n, i + 1, pos - 1);
        dout <<"ress "<<res1.fi <<" "<<res1.se << endl;
        if (res1.fi <= b[i]) {
            int to = res1.se;
            swap(a[i], a[to]);
            update(1, 1, n, to, a[to]);
            cnt++;

            dout << "res1 : " << a[i] << " " << b[i] << endl;
            continue;
        }
        pii res2 = get(1, 1, n, i + 1, n);
        if (res2.fi > b[i])
            assert(false);
        int to = res2.se;
        swap(a[i], a[to]);
        update(1, 1, n, to, a[to]);
        cnt++;
        dout << "res2 : " << a[i] << " " << b[i] << endl;
    }
    if (cnt <= n - 2) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }


}


