struct Unionfind {
  // tree number
  vector<int> par;
  // tree rank
  vector<int> treerank;
  // constructor
  Unionfind(int n = 1) { stree(n + 1); }
  // make and initialization
  void stree(int n = 1) {
    par.assign(n, -1);
    treerank.assign(n, 0);
  }
  // search root
  int root(int x) {
    if(par[x] < 0) return x;
    return par[x] = root(par[x]);
  }
  // is same?
  bool issame(int x, int y) { return root(x) == root(y); }

  // add
  // already added, return 0
  bool uni(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y) return 0;
    if(treerank[x] > treerank[y]) swap(x, y);
    if(treerank[x] == treerank[y]) ++treerank[y];
    par[y] -= size(x);
    par[x] = y;
    return 1;
  }
  int size(int x) { return -par[root(x)]; }
};

struct data {
  long long a, b, n;
};
bool operator<(const data &l, const data &r) {
  if(l.b != r.b) return l.b < r.b;
  if(l.a != r.a) return l.a < r.a;
  return l.n < r.n;
}

long long n;
vector<long long> a, b;
vector<P> ap;
vector<data> bp;

bool solve();

int main() {
  cin >> n;
  a.resize(n);
  b.resize(n);
  for(int i = 0; i < n; ++i) cin >> a[i];
  for(int i = 0; i < n; ++i) cin >> b[i];
  if(solve())
    cout << "Yes" << endl;
  else
    cout << "No" << endl;
  return 0;
}

bool solve() {
  bool ch = 1;
  Unionfind uf(n);
  for(int i = 0; i < n; ++i) {
    if(a[i] > b[i]) ch = 0;
    ap.push_back({a[i], i});
    bp.push_back({a[i], b[i], i});
  }
  if(ch) return 1;
  sort(ap.begin(), ap.end());
  sort(bp.begin(), bp.end());
  for(int i = 0; i < n; ++i) {
    if(ap[i].fi > bp[i].b) return 0;
    if(i != 0 && ap[i].fi <= bp[i - 1].b) ch = 1;
    uf.uni(ap[i].se, bp[i].n);
  }
  return ch || uf.size(0) != n;
}

