class SegmentTree {
public:
    ll N; //要素数
    vector<bool> dat;

    SegmentTree(int n_) {
        N = 1;
        while (N < n_) N *= 2;
        dat.assign(2 * N - 1, true);
    }

    void update(int k, bool a) { //k番目(0-indexed)をaに変更
        k += N - 1; //一番下
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2; //1つ上がる
            //更新
            dat[k] = dat[k * 2 + 1] && dat[k * 2 + 2]; //
        }
    }

    //[a, b)の値（最小値/和/etc.）を求める
    //kは節点の番号、l, rはその節点が[l,r)に対応づいていることを表す
    //外からはquery(a, b)と呼ぶ

    bool query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = N;
        if (r <= a || b <= l) return true;
        //[a, b)が[l,r)を完全に含む
        if (a <= l && r <= b) return dat[k];
        else {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return vl && vr; //
        }
    }
};

bool comp(pll &p1, pll &p2) {
    return p1.second == p2.second ? (p1.first < p2.first) : (p1.second < p2.second);
}

void Check(bool b) {
    if (b) {
        Yes(true);
        exit(0);
    }
    //cout << b << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20) << setiosflags(ios::fixed);

    ll n;
    cin >> n;
    v.resize(n);
    sva.resize(n);
    svb.resize(n);

    rep(i, n) {
        cin >> v[i].first;
        sva[i] = v[i].first;
    }

    rep(i, n) {
        cin >> v[i].second;
        svb[i] = v[i].second;
    }

    sort(all(v), comp);
    sort(all(sva));
    sort(all(svb));

    SegmentTree sg(n), sg_l(n), sg_r(n);
    //sg_lは[l,r) 間でa[i+1] <= b[i]か
    //sg_rは[l,r) 間でa[i-1] <= b[i]か

    rep(i, n) {
        sg.update(i, sva[i] <= svb[i]);
    }

    sg_l.update(0, true);

    rep(i, n - 1) {
        sg_l.update(i, sva[i + 1] <= svb[i]);
    }

    sg_r.update(n - 1, true);

    REP(i, 1, n) {
        sg_r.update(i, sva[i - 1] <= svb[i]);
    }

    rep(k, n) { //k番目を固定

        //cout << k << " ";
        if (v[k].first == sva[k]) { //固定しても全体がsort済み
            //cout << "そのまま ";
            Check(sg.query(0, n));

        } else if (v[k].first > sva[k]) { //本来の位置より左，固定した要素の右側が右にずれる
            //cout << "→ずれ";
            int no_change_pos; //ずれなくなる最初の位置
            //cout << no_change_pos << " ";
            auto itr = upper_bound(all(sva), v[k].first);
            no_change_pos = (int) distance(sva.begin(), itr);
            Check(sg.query(0, k) && (v[k].first <= svb[k])
                    && sg_r.query(k + 1, no_change_pos) && sg.query(no_change_pos, n));

        } else {
            //cout << "←ずれ";
            int change_pos; //ずれる最初の位置
            auto itr = upper_bound(all(sva), v[k].first);
            itr--;
            change_pos = (int) distance(sva.begin(), itr);
            //cout << change_pos << " ";
            Check(sg.query(0, change_pos) && sg_l.query(change_pos, k)
                    && (v[k].first <= svb[k]) && sg.query(k + 1, n));

        }

    }

    Yes(false);

    return 0;
}

