}

bool judge1(vector<int> A,vector<int> B){
    sort(A.begin(),A.end());
    sort(B.begin(),B.end());
    bool isok=false;
    for(int i=N-1;i>0;i--){
        isok=isok || A[i]<=B[i-1];
    }
    return isok;
}


bool judge2(vector<int> A,vector<int> B){
    vector<pair<int,int>> pv(N);
    for(int i=0;i<N;i++) pv[i]={B[i],A[i]};
    sort(pv.begin(),pv.end());

    set<int> s;
    for(int i=0;i<N;i++) s.insert(A[i]);

    map<int,int> mpA;
    int id=0;
    for(int i=0;i<N;i++) mpA[A[i]]=id++;

    vector<int> posA(N);
    vector<int> inv(N);
    for(int i=0;i<N;i++) posA[i]=mpA[pv[i].second];
    for(int i=0;i<N;i++) inv[posA[i]]=i;

    for(int i=0;i<N-2;i++){
        if(posA[i]==i){
            return true;
        }
        int v=posA[i];
        swap(posA[i],posA[inv[i]]);
        swap(inv[v],inv[i]);
    }
    return is_sorted(posA.begin(),posA.end());
}

