template <typename T>
struct Compress {
    vector<T> xs;

    Compress() = default;

    Compress(const vector<T>& vs) {
        add(vs);
    }

    Compress(const initializer_list<vector<T>>& vs) {
        for (auto& p : vs)
            add(p);
    }

    void add(const vector<T>& vs) {
        copy(begin(vs), end(vs), back_inserter(xs));
    }

    void add(const T& x) {
        xs.emplace_back(x);
    }

    void build() {
        sort(begin(xs), end(xs));
        xs.erase(unique(begin(xs), end(xs)), end(xs));
    }

    vector<int> get(const vector<T>& vs) const {
        vector<int> ret;
        transform(begin(vs), end(vs), back_inserter(ret), [&](const T& x) {
            return lower_bound(begin(xs), end(xs), x) - begin(xs);
        });
        return ret;
    }

    int get(const T& x) const {
        return lower_bound(begin(xs), end(xs), x) - begin(xs);
    }

    const T& operator[](int k) const {
        return xs[k];
    }
};

void solve() {
    V.resize(N);
    FOR(N) {
        V[i] = P{A[i], B[i]};
    }
    sort(all(V));
    sort(A, A + N);
    sort(B, B + N);
    bool flag = true;
    FOR(i, 0, N) {
        if (A[i] > B[i])
            flag = false;
    }
    if (!flag) {
        No();
        return;
    }
    bool flag2 = false;
    FOR(i, 0, N - 1) {
        if (A[i + 1] <= B[i])
            flag2 = true;
    }
    FOR(i, 0, N) {
        if (B[i] == V[i].second)
            flag2 = true;
    }
    if (flag2) {
        Yes();
        return;
    }

    Compress<int> com;
    FOR(N)
    com.add(B[i]);
    com.build();

    vector<int> C(N), D(N);
    FOR(N)
    C[i] = com.get(V[i].second);
    FOR(N)
    D[C[i]] = i;

    FOR(N - 1) {
        if (C[i] == i) {
            Yes();
            return;
        }
        D[C[i]] = i;
        swap(C[i], C[D[i]]);
    }
    No();

    return;
}

