class UF{
#define H pair<int, int>
#define fs first
#define sc second
public:
	int size;
	H pa[500002];
	void init(int n) {
		size = n;
		for (int i = 1; i <= size; i++) pa[i] = H{ i,1 };
	}
	int root(int x) {
		if (pa[x].fs == x) return x;
		return pa[x].fs = root(pa[x].fs);
	}
	void unite(int x, int y) {
		x = root(x); y = root(y);
		if (pa[x].sc < pa[y].sc) swap(x, y);
		pa[x].sc += pa[y].sc;
		pa[y].fs = x;
	}
	H operator[](int x)const {
		return pa[x];
	}
};
