using namespace std;

struct UnionFindTree{
  vector<int> parent;

  UnionFindTree(int n) : parent(n){
    for(int i = 0; i < n; i++) parent[i] = i;
  }

  int find(int x){
    if(parent[x] == x) return x;
    else return parent[x] = find(parent[x]);
  }

  void unite(int x, int y){
    parent[find(x)] = find(y);
  }
};

int main(){
  int N;
  cin >> N;

  vector<pair<int, int>> Ai(N);
  vector<pair<int, int>> BA(N);

  for(int i = 0; i < N; i++){
    int a;
    cin >> a;
    Ai[i] = make_pair(a, i);
  }

  for(int i = 0; i < N; i++){
    int b;
    cin >> b;
    BA[i] = make_pair(b, Ai[i].first);
  }

  sort(Ai.begin(), Ai.end());
  sort(BA.begin(), BA.end());

  bool able = true;
  for(int i = 0; i < N; i++){
    Ai[i] = make_pair(BA[i].second, i);
  }

  sort(Ai.begin(), Ai.end());

  for(int i = 0; i < N; i++){
    if(Ai[i].first > BA[i].first){
      able = false;
      break;
    }
  }

  UnionFindTree permutation(N);
  for(int i = 0; i < N; i++){
    permutation.unite(Ai[i].second, i);
  }

  int cnt = 0;
  for(int i = 0; i < N; i++){
    if(permutation.find(i) == i) cnt++;
  }

  if(able && cnt == 1){
    able = false;
    for(int i = 0; i < N - 1; i++){
      if(BA[i].first >= Ai[i + 1].first){
        able = true;
        break;
      }
    }
  }

  cout << (able ? "Yes" : "No") << endl;

  return 0;
}

