int a[MAXN], b[MAXN];

int parent[MAXN];
int siz[MAXN];

void init(int n) {
    for (int i = 1; i <= n; ++i) {
        parent[i] = i;
        siz[i] = 1;
    }
}

int get_parent(int v) {
    if (parent[v] == v)
        return v;
    return parent[v] = get_parent(parent[v]);
}

void union_set(int a, int b) {
    a = get_parent(a);
    b = get_parent(b);
    if (a != b) {
        parent[b] = a;
        siz[a] += siz[b];
    }
}

int pos[MAXN];
int used[MAXN];

void solve() {
    int n;
    cin >> n;
    init(n);

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; ++i) {
        cin >> b[i];
    }
    vector<int> c(a + 1, a + n + 1);
    vector<int> d(b + 1, b + n + 1);

    sort(all(c));
    sort(all(d));
    for (int i = 0; i < sz(d); ++i) {
        if (c[i] > d[i]) {
            cout << "No\n";
            return;
        }
    }

    vector<pii> cc;
    vector<pii> dd;
    for (int i = 1; i <= n; ++i) {
        cc.pb({a[i], i});
        dd.pb({b[i], i});
    }
    sort(all(cc));
    sort(all(dd));
    for (int i = 0; i < n; ++i) {
        int x = dd[i].se;
        int y = cc[i].se;
        pos[y] = x;
    }
    for (int i = 1; i <= n; ++i) {
        if (used[i])
            continue;
        if (b[i] < a[i]) {
            int v = i;
            while (!used[v]) {
                union_set(v, pos[v]);
                v = pos[v];
                used[v] = 1;
            }
        }
    }

    if (siz[get_parent(1)] == n) {
        cout << "No";
        return;
    }
    cout << "Yes\n";

}


