int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

struct UnionFind{
    std::vector<int> data;
    UnionFind(int size):data(size,-1){}
    bool unite(int x,int y) {
        x=root(x);y=root(y);
        if(x!=y){
            if(data[y]<data[x])std::swap(x,y);
            data[x]+=data[y];data[y]=x;
        }
        return x!=y;
    }
    bool find(int x,int y) {
        return root(x)==root(y);
    }
    int root(int x) {
        return data[x]<0?x:data[x]=root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};


bool solve() {
	int n = ri();
	int a[n], b[n], a_[n], b_[n];
	for (int i = 0; i < n; i++) a[i] = a_[i] = ri();
	for (int i = 0; i < n; i++) b[i] = b_[i] = ri();
	std::sort(a, a + n);
	std::sort(b, b + n);
	for (int i = 0; i < n; i++) if (a[i] > b[i]) return false;
	int ok_next[n];
	ok_next[0] = 0;
	for (int i = 0; i + 1 < n; i++) ok_next[i + 1] = a[i + 1] <= b[i];
	for (int i = 0; i + 1 < n; i++) ok_next[i + 1] += ok_next[i];

	for (int i = 0; i < n; i++) {
		if (a_[i] > b_[i]) continue;
		int lower = std::upper_bound(a, a + n, a_[i]) - a - 1;
		int upper = std::lower_bound(b, b + n, b_[i]) - b;
		if (upper < lower) return true;
		if (ok_next[upper] - ok_next[lower] == upper - lower) return true;
	}
	UnionFind uni(n);
	std::pair<int, int> tmp[n];
	for (int i = 0; i < n; i++) tmp[i] = {a_[i], i};
	std::stable_sort(tmp, tmp + n);
	for (int i = 0; i < n; i++) uni.unite(tmp[i].second, i);
	if (uni.size(0) != n) return true;
	return false;
}

int main() {
	std::cout << (solve() ? "Yes" : "No") << std::endl;
	return 0;
}

