typedef pair<int, int> pii;

int my_lower_bound(vector<int>& sv, int val) {
    int l = 0;
    int r = sv.size();
    int mid;
    while (r - l > 1) {
        mid = (l + r) / 2;
        if (sv[mid] > val) {
            r = mid;
        } else {
            l = mid;
        }
    }
    return l;
}

