using namespace std;

vector<int> root;
vector<int> Rank;

//通常バージョン
int find(int x){
    if (root[x] == x) return x;
    root[x] = find(root[x]);
    return root[x];
}

bool check(int x, int y){
    return find(x) == find(y);
}

void Union(int x, int y){
    x = find(x); y = find(y);
    if (check(x, y)){
        return;
    }
    if (Rank[x] >= Rank[y]) root[y] = x;
    else root[x] = y;
    if (Rank[x] == Rank[y]) Rank[x]++;
}

int main(){
    int n;
    cin >> n;
    vector<int> set_root(n);
    for (int i = 0; i < n; i++) set_root[i] = i;
    root = set_root;
    vector<int> set_Rank(n, 0);
    Rank = set_Rank;
    vector<int> a(n);
    vector<int> b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i]; 
    map<int, int> id;
    for (int i = 0; i < n; i++) id[b[i]] = i;
    vector<int> A = a;
    vector<int> B = b;
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    map<int, int> mp;
    bool flag = true;
    bool ok = false;
    for (int i = 0; i < n; i++){
        mp[a[i]] = id[b[i]];
        if (a[i] > b[i]) flag = false;
        if (i != 0){
            if (a[i] <= b[i - 1]) ok = true;
        }
    }
    if (!flag) {
        cout << "No" << endl;
        return 0;
    }
    if (ok){
        cout << "Yes" << endl;
        return 0;
    }
    int cnt = 0;
    vector<bool> visited(n, false);
    for (int i = 0; i < n; i++){
        if (check(i, mp[A[i]])) {
            if (visited[find(i)]) continue;
            visited[find(i)] = true;
            cnt++;
        }
        else {
            Union(i, mp[A[i]]);
        }
    }
    if (cnt > 1) cout << "Yes" << endl;
    else cout << "No" << endl;
}

