#define INF 1000000

int main() {
  //input
  int N;
  cin >> N;
  vector<int> A(N);
  vector<int> B(N);
  rep(i,N) {
    cin >> A.at(i);
  }
  rep(i,N) {
    cin >> B.at(i);
  }
  //calc
  priority_queue<pair<int,int>> pqB;
  rep(i,N) {
    pqB.push(make_pair(B.at(i),i));
  }
  vector<int> AA(N);
  vector<int> BB(N);
  priority_queue<pair<int,int>> pqAA;
  priority_queue<pair<int,int>> pqBB;
  rep(i,N) {
    pair<int,int> topB = pqB.top();
    pqB.pop();
    int index = topB.second;
    AA.at(i) = A.at(index);
    pqAA.push(make_pair(AA.at(i), i));
    BB.at(i) = B.at(index);
    pqBB.push(make_pair(BB.at(i), i));
  }
  //calc
  int swap_count = 0;
  int size = N;
  while (!pqAA.empty()) {
    pair<int,int> topAA = pqAA.top();
    int topAAIndex = topAA.second;
    if ( topAAIndex >= size ) {
      pqAA.pop();
      continue;
    }
    int topAAvalue = topAA.first;
    int BBvalue = BB.at(topAAIndex);
    if ( topAAvalue > BBvalue ) {
      if (pqBB.empty()) {
        swap_count = INF;
        break;
      }
      pair<int,int> topBB = pqBB.top();
      int topBBValue = topBB.first;
      int topBBIndex = topBB.second;
      if ( topAAvalue > topBBValue ) {
        swap_count = INF;
        break;
      }
      pqBB.pop();
      size--;
      pqAA.pop();
      pqAA.push(make_pair(AA.at(topBBIndex),topAAIndex));
      swap_count++;
    }
    else {
      pqAA.pop();
      pqBB.pop();
    }
  }
  string answer = swap_count <= N - 2 ? "Yes" : "No";
  //output
  cout << answer << endl;
}

