  for (int i = 0; i < n; i++) p.emplace_back(b[i], a[i]);
  sort(p.begin(), p.end());
  map<int, vector<int>> pos;
  for (int i = 0; i < n; i++) {
    pos[p[i].second].push_back(i);
  }
  int cnt = 0;
  for (int i = 0; i < n; i++) {
    if (p[i].first >= p[i].second) continue;
    int x = *prev(upper_bound(aa.begin(), aa.end(), p[i].first));
    int y = pos[x].back();
    pos[x].pop_back();
    pos[p[i].second].push_back(y);
    //cerr << p[i].second << " " << p[y].second << endl;
    swap(p[i].second, p[y].second);
    cnt++;
  }
  //cerr << cnt << endl;
  cout << (cnt < n - 1 ? "Yes\n" : "No\n");
  return 0;
}

