#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

struct SegmentTree {
  using T = int;
  static T op(const T& a, const T& b) { return min(a, b); }
  static constexpr T e() { return 2e9 + 1; }

  const int n;
  V<T> t;
  SegmentTree(int _n) : n(_n), t(2 * n, e()) {}
  T& operator[](int i) { return t[i + n]; }
  void build() { for (int i = n - 1; i; --i) t[i] = op(t[2 * i], t[2 * i + 1]); }
  T acc(int l, int r) const {
    T resl = e(), resr = e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) resl = op(resl, t[l++]);
      if (r & 1) resr = op(t[--r], resr);
    }
    return op(resl, resr);
  }
  void set(int i, const T& a) {
    t[i += n] = a;
    while (i >>= 1) t[i] = op(t[2 * i], t[2 * i + 1]);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<> a(n); for (auto&& e : a) cin >> e;
  V<> b(n); for (auto&& e : b) cin >> e;
  auto va = a, vb = b;
  sort(begin(va), end(va));
  sort(begin(vb), end(vb));
  for (int i = 0; i < n; ++i) {
    if (va[i] > vb[i]) {
      return cout << "No" << '\n', 0;
    }
  }
  SegmentTree st(n - 1);
  for (int i = 0; i < n - 1; ++i) {
    st[i] = vb[i] - va[i + 1];
  }
  st.build();
  for (int i = 0; i < n; ++i) if (a[i] <= b[i]) {
    int ia = lower_bound(begin(va), end(va), a[i]) - begin(va);
    int ib = lower_bound(begin(vb), end(vb), b[i]) - begin(vb);
    if (ia >= ib) {
      return cout << "Yes" << '\n', 0;
    }
    if (st.acc(ia, ib) >= 0) {
      return cout << "Yes" << '\n', 0;
    }
  }
  cout << "No" << '\n';
}

