		if (tmp[i].first > in[i].first) {
			printf("No\n");
			return;
		}
		per[i] = tmp[i].second;
	}
	int mini = 2e9;
	for (int i = n; i >= 1; --i) {
		if (mini <= in[i].first) {
			printf("Yes\n");
			return;
		}
		mini = min(mini, in[per[i]].second);
	}
	int numCycle = 0;
	for (int i = 1; i <= n && numCycle<2; ++i) {
		if (!vis[i]) {
			int node = i;
			while (!vis[node]) {
				vis[node] = true;
				node = per[node];
			}
			++numCycle;
		}
	}
	if (numCycle == 1) {
		printf("No\n");
	}
	else {
		printf("Yes\n");
	}
}
