int now[100010];
int le[100010];
int ri[100010];

bool isOK(int aa, int bb){
    if(aa == bb){
        return now[n] == n;
    }

    if(aa < bb){
        return now[aa] + ri[bb] - ri[aa] + now[n] - now[bb+1] == n-1;
    }else{
        return now[bb] + le[aa] - le[bb] + now[n] - now[aa+1] == n-1;
    }
}

int main(){
    cin >> n;

    for(int i = 0;i < n;i++){
        cin >> a[i];
        sa.push_back(a[i]);
    }

    for(int i = 0;i < n;i++){
        cin >> b[i];
        sb.push_back(b[i]);
    }

    sort(sa.begin(), sa.end());
    sort(sb.begin(), sb.end());

    for(int i = 0;i < n;i++){
        now[i+1] = sa[i] <= sb[i] ? 1 : 0;
        if(i < n-1){
            le[i+1] = sa[i] <= sb[i+1] ? 1 : 0;
            ri[i+1] = sa[i+1] <= sb[i] ? 1 : 0;
            le[i+1] += le[i];
            ri[i+1] += ri[i];
        }
        now[i+1] += now[i];
    }


    for(int i = 0;i < n;i++){
        if(a[i] > b[i]) continue;
        int l1 = lower_bound(sa.begin(), sa.end(), a[i]) - sa.begin();
        int l2 = upper_bound(sa.begin(), sa.end(), a[i]) - sa.begin() - 1;
        int r1 = lower_bound(sb.begin(), sb.end(), b[i]) - sb.begin();
