    rep(i,n)cin >> b[i];

    int aa[n], bb[n];
    rep(i,n){
        aa[i] = a[i];
        bb[i] = b[i];
    }
    sort(aa, aa+n);
    sort(bb, bb+n);
    rep(i,n){
        if(aa[i] > bb[i]){
            cout << "No" << endl;
            return 0;
        }
    }
    rep(i,n-1){
        if(aa[i+1] <= bb[i]){
            cout << "Yes" << endl;
            return 0;
        }
    }

