    rep(i,n){
        a[i] = lower_bound(aa, aa+n, a[i]) - aa;
        b[i] = lower_bound(bb, bb+n, b[i]) - bb;
    }

    vector<P> v;
    rep(i,n)v.push_back(P(b[i], a[i]));
    sort(v.begin(), v.end());
    rep(i,n){
        a[i] = v[i].second;
        b[i] = v[i].first;
    }

    int cnt = 0;
    int now = 0;
    int f[n] = {};
    while(true){
        if(f[now] == 1)break;
        f[now] = 1;
        now = a[now];
        cnt++;
    }

    if(cnt < n)yn;

    return 0;
