#define NODE_MAX 100001
int par[NODE_MAX],rk[NODE_MAX],size[NODE_MAX];
void init(){
  for(int i=0;i<NODE_MAX;i++){
    par[i]=i;
    rk[i]=0;
    size[i]=1;
  }
}
int root(int x){
  if(x==par[x]) return x;
  return par[x]=root(par[x]);
}
void unite(int x,int y){
  x = root(x);
  y = root(y);
  if(x==y) return;

  if(rk[x]<rk[y]){
    par[x] = y;
    size[y] += size[x];
  }else{
    par[y] = x;
    if(rk[x]==rk[y]) rk[x]++;
    size[x] += size[y];
  }
}
bool same(int x,int y){
  return root(x)==root(y);
}
int treesize(int x){
  return size[root(x)];
}
