signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n;
  vector<int> a(n), b(n);
  rep(i, n) cin >> a[i];
  rep(i, n) cin >> b[i];
  vector<int> sa = a;
  vector<int> sb = b;
  sort(all(sa));
  sort(all(sb));
  rep(i, n) {
    if (sa[i] > sb[i]) {
      cout << "No" << endl;
      return 0;
    }
  }
  rep(i, n) {
    p[sb[i]].insert(sa[i]);
  }
  rep(i, n) {
    if (p[b[i]].find(a[i]) != p[b[i]].end()) {
      cout << "Yes" << endl;
      return 0;
    }
  }
  rep(i, n) {
    pos[a[i]].insert(i);
  }
  rep(i, n-1) {
    if (p[b[i]].find(a[i]) != p[b[i]].end()) {
      cout << "Yes" << endl;
      return 0;
    }
    for (auto x : p[b[i]]) {
      if (pos[x].size() == 0) continue;
      int tar = *pos[x].lower_bound(i);
      pos[a[i]].erase(i);
      pos[a[i]].insert(tar);
      swap(a[i], a[tar]);
