int main() {
  ll n;
  cin >> n;
  vector<ll> a(n), b(n);
  vector<P> c(n), d(n);
  REP(i, n) {
    cin >> a[i];
    c[i] = make_pair(a[i], i);
  }
  REP(i, n) {
    cin >> b[i];
    d[i] = make_pair(b[i], i);
  }
  sort(ALL(c));
  sort(ALL(d));

  //何回かけてもだめ
  REP(i, n) {
    if (c[i].first > d[i].first) {
      no();
    }
  }

  //何回かやればできる
  // n-1回かかる条件は？
  ll cnt = 0;
  REP(i, n) {
    if (c[i].second != i) {
      cnt++;
    }
  }

  bool ok = false;
  FOR(i, 1, n) {
    if (d[i - 1].first >= c[i].first) {
      ok = true;
    }
  }

  if (cnt == n && !ok) {
    no();
  }

  yes();
