  int smallestIdx = 0;
  int largestNum = 0;
  int largestIdx = 0;
  for (int i = 0; i < n; i++) {
    if (abi[i].second < smallestNum) {
      smallestNum = abi[i].second;
      smallestIdx = i;
    }
    if (abi[i].second > largestNum) {
      largestNum = abi[i].second;
      largestIdx = i;
    }
  }

  if (largestIdx == 0 && smallestIdx == 1) {
    cout << "No" << endl;
  }
  else {
    cout << "Yes" << endl;
  }

  return 0;
}

