//Union Find Tree
class UnionFindTree {
public:
	vector<int> parent;
    vector<int> rank;

    UnionFindTree(int N) : parent(N), rank(N,0){
		for (int i = 0; i < N; ++i) parent[i] = i;
	}

	int root(int n) {
		return (parent[n] == n ? n : parent[n] = root(parent[n]));
	}

    int same(int n, int m) {
		return root(n) == root(m);
	}

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(rank[n]<rank[m]) {
            parent[n] = m;
        }
        else{
            parent[m] = n;
            if(rank[n] == rank[m]) rank[n]++;
        }
	}
};

int main() {
	int N; cin >> N;
	vector<ll> A(N),B(N);
	for(int i = 0; i < N; ++i) cin >> A[i];
	for(int i = 0; i < N; ++i) cin >> B[i];
	auto C = A,D = B;
	sort(ALL(C));
	sort(ALL(D));
	for(int i = 0; i < N; ++i) corner(C[i]>D[i],"No");
	for(int i = 0; i+1<N; ++i) corner(C[i+1]<=D[i],"Yes");

	vector<pair<ll,int>> Bp(N);
	for(int i = 0; i < N; ++i) Bp[i] = {B[i],i};
	sort(ALL(Bp));
	UnionFindTree uf(N);
	for(int i = 0; i < N; ++i) {
		int l = i,r = Bp[i].second;
		uf.unite(l,r);
	}
	vector<int> cnt(N,0);
	for(int i = 0; i < N; ++i) {
		cnt[uf.root(i)]++;
	}

	for(int i = 0; i < N; ++i) {
		corner(cnt[i]&&cnt[i]!=N,"Yes");
	}
	cout << "No" << endl;

}

