struct UnionFind{
	vector<int>par;
	vector<int>sz;
	UnionFind(int n){
		par=sz=vector<int>(n);
		rep(i,n)par[i]=i,sz[i]=1;
	}
	int find(int x){
		if(par[x]==x)return x;
		return par[x]=find(par[x]);
	}
	void unite(int x,int y){
		x=find(x);y=find(y);
