    rep(i,n)
    {
        m[mp(p[i].ss,-i)]++;
    }

    ll cnt = 0;
    rep(i,n)
    {
        if(p[i].ss<=p[i].ff)
        {
            m.erase(mp(p[i].ss,-i));
            continue;
        }
        else
        {
