                return;
            }

            cnt++;
            ll num = it->ff.ff;
            ll ind = -it->ff.ss;
            m.erase(it);

            p[ind].ss = p[i].ss;
            m[mp(p[ind].ss,-ind)]++;
            m.erase(mp(p[i].ss,-i));
        }
    }

    if(cnt>n-2)
    {
        cout << "No" << endl;
    }
    else
    {
        cout << "Yes" << endl;
    }
}

