#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>

const int MAXN = (int)1e5 + 1;

std::pair<int, int> input[MAXN];
int a[MAXN], b[MAXN];

struct SegTree {
  int min[MAXN * 6];
  int pos[MAXN * 6];

  void Update(int rt) {
    if (min[rt * 2] <= min[rt * 2 + 1]) {
      min[rt] = min[rt * 2];
      pos[rt] = pos[rt * 2];
    } else {
      min[rt] = min[rt * 2 + 1];
      pos[rt] = pos[rt * 2 + 1];
    }
  }

  void Build(int rt, int l, int r) {
    if (l == r) {
      min[rt] = a[l];
      pos[rt] = l;
      return;
    }
    int mid = l + r >> 1;
    Build(rt * 2, l, mid);
    Build(rt * 2 + 1, mid + 1, r);
    Update(rt);
  }

  void Modify(int p, int x, int rt, int l, int r) {
    if (l == r) {
      min[rt] = x;
      return;
    }
    int mid = l + r >> 1;
    if (p <= mid) Modify(p, x, rt * 2, l, mid);
    else Modify(p, x, rt * 2 + 1, mid + 1, r);
    Update(rt);
  }

  std::pair<int, int> Query(int ql, int qr, int rt, int l, int r) {
    if (ql <= l && r <= qr) return std::make_pair(min[rt], pos[rt]);
    int mid = l + r >> 1;
    if (ql > mid) return Query(ql, qr, rt * 2 + 1, mid + 1, r);
    if (qr <= mid) return Query(ql, qr, rt * 2, l, mid);
    auto l_min = Query(ql, qr, rt * 2, l, mid);
    auto r_min = Query(ql, qr, rt * 2 + 1, mid + 1, r);
    return std::min(l_min, r_min);
  }
};
SegTree seg_tree;

void init(int n) {
  std::sort(input + 1, input + n + 1, [](const auto &x, const auto &y) {
    if (x.second == y.second) return x.first < y.first;
    return x.second < y.second;
  });
  for (int i = 1; i <= n; ++i) {
    a[i] = input[i].first;
    b[i] = input[i].second;
    seg_tree.Build(1, 1, n);
  }
}

bool solve(int n) {
  init(n);
  int op_num = 0;

  auto calc_left_limit = [&](int x, int n) -> int {
    if (b[n] < x) return -1;
    return std::lower_bound(b + 1, b + n + 1, x) - b;
  };

  for (int i = 1; i <= n; ++i) {
    if (a[i] <= b[i]) continue;
    int left_limit = calc_left_limit(a[i], n);
    if (left_limit == -1 || left_limit > n) return false;
    std::pair<int, int> min = seg_tree.Query(left_limit, n, 1, 1, n);
    if (min.first > b[i]) return false;
    ++op_num;
    seg_tree.Modify(min.second, a[i], 1, 1, n);
  }

  return op_num <= n - 2;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1, x; i <= n; ++i) {
    scanf("%d", &x);
    input[i].first = x;
  }
  for (int i = 1, x; i <= n; ++i) {
    scanf("%d", &x);
    input[i].second = x;
  }
  if (solve(n)) printf("Yes\n");
  else printf("No\n");
  return 0;
}

