using namespace std;

struct SortItem
{
  uint64_t a, b;
  SortItem(uint64_t a = -1, uint64_t b = -1) : a(a), b(b) {}

  bool operator<(const SortItem &item) const {
    return (b == item.b) ? a < item.a : b < item.b;
  }
};

struct VectorItem
{
  uint64_t v, i;
  VectorItem(uint64_t v = -1, uint64_t i = -1) : v(v), i(i) {}

  bool operator<(const VectorItem &item) const {
    return v < item.v;
  }
};

uint64_t count_cycles(uint64_t N, const vector<VectorItem> &A)
{
  uint64_t count = 0;
  vector<bool> checked(N, false);

  for (uint64_t n = 0; n < N; ++n) {
    if (checked[n]) { continue; }

    uint64_t start = n, index = A[n].i;
    checked[start] = true;
    while (index != start) {
      checked[index] = true;

      index = A[index].i;
      if (checked[index]) { break; }
    }

    ++count;
  }

  return count;
}

int main()
{
  uint64_t N;
  cin >> N;

  vector<uint64_t> A(N), B(N);
  for (uint64_t n = 0; n < N; ++n) { cin >> A[n]; }
  for (uint64_t n = 0; n < N; ++n) { cin >> B[n]; }

  vector<SortItem> vec(N);
  for (uint64_t n = 0; n < N; ++n) { vec[n] = SortItem(A[n], B[n]); }
  sort(vec.begin(), vec.end());

  vector<VectorItem> C(N), D(N);
  for (uint64_t n = 0; n < N; ++n) { C[n].v = vec[n].a; C[n].i = n; }
  for (uint64_t n = 0; n < N; ++n) { D[n].v = vec[n].b; D[n].i = n; }
  sort(C.begin(), C.end());
  sort(D.begin(), D.end());

  bool flag = true;
  for (uint64_t n = 0; n < N; ++n) {
    flag &= C[n].v <= D[n].v;
  }

  if (count_cycles(N, C) == 1) {
    bool flag2 = false;
    for (uint64_t n = 0; n < N - 1; ++n) {
      flag2 |= D[n].v >= C[n + 1].v;
    }
    flag &= flag2;
  }

  cout << (flag ? "Yes" : "No") << endl;

  return 0;
}

