	idxs.reserve(n);
	vector<int> pos(n);
	rep(i, n)idxs[va[i]] = i;
	rep(i, n) {
		int idx = upper_bound(a, a + n, vb[i]) - a - 1;
		pos[i] = idxs[a[idx]];
	}


	UnionFind uf(n);
	uf.init(n);

	rep(i, n) {
		uf.unite(i, pos[i]);
	}
	unordered_set<int> p;
	rep(i, n)p.insert(uf.find(i));

	return p.size() > 1;
}


