// MOD
ll gcd(ll p, ll q) { return (q == 0) ? p : gcd(q, p % q); }
ll pow(ll a, ll n, ll m) {
  if (n == 0)
    return 1;
  if (n & 1)
    return ((a % m) * pow(a, n - 1, m)) % m;
  auto b = pow(a, n / 2, m);
  return (b * b) % m;
}
ll inv(ll a, ll p) { return pow(a, p - 2, p); }
constexpr ll MOD = 998244353LL; // 1e9 + 7;

list<ll> collectCycles(u_map<ll, ll> const &perm, ll const root,
                       u_set<ll> &visited) {
  if (visited.find(root) != visited.end())
    return {};

  visited.insert(root);
  auto &&l = collectCycles(perm, perm.at(root), visited);
  l.push_front(root);
  return l;
}
