		}			
	}

	sort(elem, elem+N, cmp);

	prepare(0, N-1, 0);

	int swaps = 0;
	for(int i = 0; i < N; i++){
		if(elem[i].f <= elem[i].s){
			if(!swapped[i]){
				cout << "Yes" << endl;
				return 0;
			}
			continue;
		}

		swaps++;

		int j = bs_lower(i+1,elem[i].f);
		if(j != -1){
			int l = query(j,N-1,0,0,N-1);
			if(elem[l].f <= elem[i].s){
//				cout << "swap " << i << " " << l << endl;
				int s = elem[l].f;
				elem[l].f = elem[i].f;
				update(0,N-1,0,l);
				elem[i].f = s;
				update(0,N-1,0,i);
				swapped[l] = swapped[i] = true;
				continue ;
			}
		}

		int l = query(i+1,N-1,0,0,N-1);
		if(elem[l].f > elem[i].s){
			cout << "No" << endl;
			return 0;
		}
//		cout << "swap " << i << " " << l << endl;
		int s = elem[l].f;
		elem[l].f = elem[i].f;
		update(0,N-1,0,l);
		elem[i].f = s;
		update(0,N-1,0,i);
		swapped[l] = swapped[i] = true;
	}

	cout << ((swaps <= N-2) ? "Yes" : "No") << endl;
	return 0;
}

