    sort(b.begin(),b.end());
    rep(i,n){
        if(a[i].first>b[i]){
            cout<<"No\n";
            return;
        }
    }
    rep(i,n){
        tree.unite(a[i].second,i);
    }
    rep(i,n)s.insert(tree.find(a[i].second));
    if(s.size()>=2){
        cout<<"Yes\n";
        return;
    }
    else {
        rep(i,n-1){
            if(a[i+1].first<=b[i]){
                cout<<"Yes\n";
                return;
            }
        }
    }
    cout<<"No\n";
}

