using namespace std;

struct Ab {
    int A, B;
    bool operator<(const Ab &another) const {
        return B < another.B;
    };
};

int min(vector<Ab> &ab, int s, int now) {
    int m = 1000000000;
    int mi = s;
    for(int i = s; i < ab.size(); i++) {
        if(m > ab.at(i).A && now != ab.at(i).B) {
            m = ab.at(i).A;
            mi = i;
        }
    }
    return mi;
}

int main() {
    int N;
    cin >> N;
    vector<Ab> ab(N);
    for(int i = 0; i < N; i++) {
        cin >> ab.at(i).A;
    }
    for(int i = 0; i < N; i++) {
        cin >> ab.at(i).B;
    }
    sort(ab.begin(), ab.end());
    int count = 0;
    bool flg = true;
    for(int i = 0; i < N; i++) {
        if(ab.at(i).A > ab.at(i).B) {
            if(i == N - 1) {
                flg = false;
                break;
            }
            if(ab.at(min(ab, i + 1, ab.at(i).B)).A >= ab.at(i).A) {
                flg = false;
                break;
            }
            int box;
            box = ab.at(i).A;
            ab.at(i).A = ab.at(min(ab, i + 1, ab.at(i).B)).A;
            ab.at(min(ab, i + 1, ab.at(i).B)).A = box;
            count++;
        }
    }
    if(count < N - 1 && flg) cout << "Yes" << endl;
    else cout << "No" << endl;
}

