bool impossible( VI A, VI B )
{
	const int N = SZ( A );

	sort( ALL( A ) );
	sort( ALL( B ) );

	REP( i, N )
	{
		if ( B[i] < A[i] )
		{
			return true;
		}
	}
	return false;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N );
	VI A( N ), B( N );
	cin >> A >> B;

	if ( impossible( A, B ) )
	{
		cout << "No" << endl;
		return 0;
	}

	VPII ps_a, ps_b;
	// [ ( value, original index ) ]
	REP( i, N )
	{
		ps_a.EB( A[i], i );
		ps_b.EB( B[i], i );
	}
	sort( ALL( ps_a ) );
	sort( ALL( ps_b ) );

	VI a_moves_to( N ), b_moves_to( N );
	REP( i, N )
	{
		a_moves_to[ ps_a[i].snd ] = i;
		b_moves_to[ ps_b[i].snd ] = i;
	}

	VI violates_by_ur( N ), violates_by_ul( N );
	REP( i, N )
	{
		if ( i + 1 < N && ps_b[i].fst < ps_a[ i + 1 ].fst )
		{
			violates_by_ur[i] = true;
		}
		if ( 0 < i && ps_b[i].fst < ps_a[ i - 1 ].fst )
		{
			violates_by_ul[i] = true;
		}
	}
	VI psum_ur( 1 ), psum_ul( 1 );
	partial_sum( ALL( violates_by_ur ), BI( psum_ur ) );
	partial_sum( ALL( violates_by_ul ), BI( psum_ul ) );

	const auto violates = [&]( const VI &a, const int l, const int r )
	{
		return a[r] - a[l];
	};

	REP( i, N )
	{
		const int idx_a = a_moves_to[i];
		const int idx_b = b_moves_to[i];

		if ( idx_a == idx_b ||
				( idx_a < idx_a && !violates( violates_by_ur, idx_a, idx_b + 1 ) ) ||
				( idx_a > idx_b && !violates( violates_by_ul, idx_b, idx_a + 1 ) ) )
		{
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;

	return 0;
}

