bool solve(){
	int n;
	scanf("%d", &n);
	vector<pii> ps(n);
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].second); }
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].first); }
	sort(ALL(ps));
	vector<int> as(n), bs(n);
	for(int i = 0; i < n; ++i){
		as[i] = ps[i].second;
		bs[i] = ps[i].first;
	}

	if(!check1(as, bs)){ return false; }

	vector<int> ls(n);
	for(int i = 0; i < n; ++i){
		ls[i] = upper_bound(ALL(bs), as[i]) - bs.begin();
		if(ls[i] >= n){ return false; }
	}

	if(set<int>(ALL(ls)).size() != n){ return true; }
	union_find uf(n);
	for(int i = 0; i < n; ++i){ uf.unite(i, ls[i]); }
	if(uf.groups() > 1){ return true; }

	return false;
}

