bool cmp(const pii& lhs, const pii& rhs) {
	if(lhs.first != rhs.first) {
		return lhs.first > rhs.first;
	} else {
		return lhs.second < rhs.second;
	}
}

void solve() {
	int n = fetch<int>();
	vector<pii> ba(n);

	for(int i = 0; i < n; ++i) {
		cin >> ba[i].second;
	}

	for(int i = 0; i < n; ++i) {
		cin >> ba[i].first;
	}

