	vector<int> b(n), fst(n);

	for(int i = 0; i < n; ++i) {
		b[i] = ba[i].first;
	}

	DBG(ba);

	for(int i = 0; i < n; ++i) {
		fst[i] = lower_bound(b.begin(), b.end(), ba[i].second) - b.begin();
		DBG(fst[i]);

		if(fst[i] == n) {
			cout << "No\n";
			return;
		}
	}

	vector<pii> magic(n);

	for(int i = 0; i < n; ++i) {
		magic[i] = make_pair(fst[i], i);
	}

	sort(magic.begin(), magic.end(), cmp);
	int unused = n - 1;
	int ok = 1, found = 0;

	DBG(magic);

	for(auto& pr: magic) {
		if(unused >= pr.first) {
			if(pr.second <= unused) {
				found = 1;
			}
		} else {
			ok = 0;
			break;
		}

		--unused;
	}

	cout << (ok && found ? "Yes\n" : "No\n");
}

