using namespace std;

using ll = long long;

bool judge(vector<ll>& a, vector<ll>& b) {
    int n = b.size();
    vector<int> ids_a(n), ids_b(n);
    iota(ids_a.begin(), ids_a.end(), 0);
    iota(ids_b.begin(), ids_b.end(), 0);
    sort(ids_a.begin(), ids_a.end(), [&](int i1, int i2){return a[i1] < a[i2];});
    sort(ids_b.begin(), ids_b.end(), [&](int i1, int i2){return b[i1] < b[i2];});

    int cnt0 = 0, cnt1 = 0;
    bool ans = false;
    vector<int> used(n, false);
    for (int ii = 0, jj = 0; ii < n; ii++) {
        int i = ids_b[ii];
        used[i] = true;
        while (jj < n) {
            int j = ids_a[jj];
            if (a[j] <= b[i]) {
                jj++;
                if (a[j] <= b[j]) cnt0++;
                else cnt1++;
            }
            else break;
        }
        if (cnt0 + cnt1 == 0) return false;
        if (cnt0 > 0 && a[i] <= b[i]) {
            ans = true;
            cnt0--;
            continue;
        }
        if (cnt1 > 0) cnt1--;
        else cnt0--;
    }
    return ans;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<ll> a(n), b(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }

    if (!judge(a, b)) {
        assert(false);
        cout << "No\n";
        return 0;
    }

    cout << "Yes\n";
    return 0;
}

