bool judge_no(V<ll> alist, V<ll>blist, ll n)
{
    sort(alist);
    sort(blist);
    rep (i, n) if (alist[i] > blist[i]) return true;
    return false;
}

bool judge_yes(V<ll> alist, V<ll>blist, ll n)
{
    sort(alist);
    sort(blist);
    rep (i, n-1) if (alist[i+1] <= blist[i]) return true;
    return false;
}

void make_map(M<ll, ll> &validx, V<ll> alist, ll n)
{
    sort(alist);
    rep (i, n) {
        ll val = alist[i];
        assert(validx.find(val) == validx.end());
        validx[val] = i;
    }
}

bool judge(V<ll> alist, V<ll>blist, ll n)
{
    S M<ll, ll> validx_a;
    make_map(validx_a, alist, n);
    debug_printf("---- validx_a\n");
    debug_print(validx_a);

    S M<ll, ll> validx_b;
    make_map(validx_b, blist, n);
    debug_printf("---- validx_b\n");
    debug_print(validx_b);

    rep (i, n) alist[i] = validx_a[alist[i]];
    rep (i, n) blist[i] = validx_b[blist[i]];

    debug_printf("---- alist\n");
    debug_print(alist);
    debug_printf("---- blist\n");
    debug_print(blist);

    validx_a.clear();
    rep (i, n) {
        assert(validx_a.find(alist[i]) == validx_a.end());
        validx_a[alist[i]] = i;
    }

    ll init = alist[0];
    ll now = alist[0];
    ll cnt = 0;
    while (1) {
        cnt++;
        ll idx = validx_a[now];
        ll now_b = blist[idx];
        ll nidx = validx_a[now_b];
        now = alist[nidx];
        if (now == init) break;
    }

    debug_printf("n=%lld cnt=%lld\n", n, cnt);

    return cnt < n;
}

void _main()
{
    ll n; llin(n);
