        cout << "No" << endl;
        return;
    }

    if (judge_yes(alist, blist, n)) {
        cout << "Yes" << endl;
        return;
    }

    if (judge(alist, blist, n)) {
        cout << "Yes" << endl;
        return;
    }

    cout << "No" << endl;
}

