    REP(i, n) cin >> b[i];

    vector<int> aa(n), bb(n);
    iota(aa.begin(), aa.end(), 0);
    iota(bb.begin(), bb.end(), 0);

   sort(aa.begin(), aa.end(), [&](int i, int j) {
        return a[i] < a[j];
    });

    sort(bb.begin(), bb.end(), [&](int i, int j) {
        return b[i] < b[j];
    });


    REP(i, n) {
        if (a[aa[i]] > b[bb[i]]) {
            cout << "No" << endl;
            return 0;
        }
    }

    vector<int> oa, ob;
    REP(i, n) {
        if (a[i] > b[i]) {
            oa.push_back(i); ob.push_back(i);
        }
    }

    sort(oa.begin(), oa.end(), [&](int i, int j) {
        return a[i] < a[j];
    });

    sort(ob.begin(), ob.end(), [&](int i, int j) {
        return b[i] < b[j];
    });

    int cnt = 0;
    REP(i, n) {
