signed main(void) {
    int n;
    cin >> n;
    vector<pii> v(n);
    rep(i,n)cin >> v[i].first;
    rep(i,n)cin >> v[i].second, v[i].second *= -1;
    sort(all(v));
    reverse(all(v));
    rep(i,n)v[i].second *= -1;
    int cnt = 0;
    priority_queue< pii, vector<pii>, greater<pii> > q;
    //v[i].first < v[k].second となるすべてのkについて
    //pii(v[k].first, k) を push していく
    map<pii,int> ma;
    rep(i,n)ma[pii(v[i].second,i)]++;
    auto itr = ma.end();
    itr--;
    rep(i,n)if(v[i].first > v[i].second){
        //cout << "!" << i << " " << v[i].first << endl;
        while(itr->first.first >= v[i].first){
            int sec = itr->first.first;
            int id = itr->first.second;
            //cout << sec << " " << id << endl;
            q.push(pii(v[id].first,id));
            itr--;
        }
        if(q.empty()){
            cout << "No" << endl;
            return 0;
        }
        pii p = q.top();
        int index = p.second;
        q.pop();
        // v[i].second　と v[index].second を swap する
        //このとき、v[index].firstのペアはv[i].secondになるのでその変更をする
        ma.erase(pii(v[i].second,i));
        ma[pii(v[i].second,index)]++;
        v[index].second = v[i].second;
        cnt++;
    }
    if(cnt <= n-2){
        cout << "Yes" << endl;
    }else{
        cout << "No" << endl;
    }
}

