int main() {
  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (auto &e : a) cin >> e;
  for (auto &e : b) cin >> e;

  vector<int> p(n);
  iota(p.begin(), p.end(), 0);
  sort(p.begin(), p.end(), [&a](int i, int j) { return a[i] < a[j]; });
  int x = -1;
  for (auto i : p) {
    if (a[i] <= b[i]) {
      x = i;
      break;
    }
  }
  if (x == -1) {
    cout << "No" << endl;
    return 0;
  }

  a.erase(a.begin() + x);
  b.erase(b.begin() + x);
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  bool r = true;
  for (int i = 0; i < n - 1; i++) r = r && a[i] <= b[i];
  cout << (r ? "Yes" : "No") << endl;
}

