int main(){
    int n;cin >> n;
    vector<LL> a(n),b(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    auto c = a,d = b;
    sort(ALL(c));
    sort(ALL(d));
    for (int i = 0; i < n; i++) {
        if(c[i]>d[i]){
            puts("No");
            return 0;
        }
    }
    vector<P> v(n);
    set<P> st;
    for (int i = 0; i < n; i++) {
        v[i] = mp(b[i],a[i]);
    }
    sort(ALL(v));
    for (int i = 0; i < n; i++) {
        st.insert(mp(-v[i].sc,-i));
    }
    int cnt=0;
    for (int i = 0; i < n; i++) {
        if(v[i].fs >= v[i].sc){
            auto q = st.find(mp(-v[i].sc,-i));
            if(q!=st.end()) st.erase(q);
            continue;
        }
        else cnt++;
        auto p = *st.lower_bound(mp(-v[i].fs,-INF));
        auto q = st.find(mp(-v[i].sc,-i));
        if(q!=st.end()) st.erase(q);
        st.insert(mp(-v[i].sc,p.sc));
        swap(v[i].sc,v[-p.sc].sc);
        st.erase(p);
    }
    if(cnt<=n-2) puts("Yes");
    else puts("No");
    return 0;
}

