#include<bits/stdc++.h>
using namespace std;
const int SIZE = 1e5+5;
int A[SIZE],B[SIZE];

struct dd{
    int a,b,pos,d;
}arr[SIZE];

bool cmp1(const dd& shk,const dd& czq){
    if(shk.a==czq.a)return shk.b<czq.b;
    return shk.a>czq.a;
}

bool cmp2(const dd& shk,const dd& czq){
    if(shk.b==czq.b)return shk.a>czq.a;
    return shk.b<czq.b;
}

bool cmp3(const dd& shk,const dd& czq){
    return shk.d<czq.d;
}

int main(){
    int n;scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d",&A[i]);
        arr[i].a = A[i];
        arr[i].pos = i;
    }
    for(int i=1;i<=n;i++){
        scanf("%d",&B[i]);
        arr[i].b = B[i];
        arr[i].d = arr[i].b-arr[i].a;
    }

    vector<int>vec1;vec1.clear();
    vector<int>vec2;vec2.clear();
    vector<dd>vec;

    for(int i=1;i<=n;i++){
        if(A[i]<=B[i])vec.push_back(arr[i]);
    }

    int flag = 1;

    //A max
    sort(vec.begin(),vec.end(),cmp1);
    int poi = vec[0].pos;
    for(int i=1;i<=n;i++){
        if(i != poi){
            vec1.push_back(A[i]);
            vec2.push_back(B[i]);
        }
    }
    sort(vec1.begin(),vec1.end());
    sort(vec2.begin(),vec2.end());
    for(int i=0;i<vec1.size();i++){
        if(vec1[i]>vec2[i]){
            flag=0;break;
        }
    }
    if(flag){
        cout<<"YES";return 0;
    }

    //B min
    flag = 1;
    vec1.clear();vec2.clear();
    sort(vec.begin(),vec.end(),cmp2);
    poi = vec[0].pos;
    for(int i=1;i<=n;i++){
        if(i != poi){
            vec1.push_back(A[i]);
            vec2.push_back(B[i]);
        }
    }
    sort(vec1.begin(),vec1.end());
    sort(vec2.begin(),vec2.end());
    for(int i=0;i<vec1.size();i++){
        if(vec1[i]>vec2[i]){
            flag=0;break;
        }
    }
    if(flag){
        cout<<"YES";return 0;
    }

    //B-A min
    flag =1;
    vec1.clear();vec2.clear();
    sort(vec.begin(),vec.end(),cmp3);
    poi = vec[0].pos;
    for(int i=1;i<=n;i++){
        if(i != poi){
            vec1.push_back(A[i]);
            vec2.push_back(B[i]);
        }
    }
    sort(vec1.begin(),vec1.end());
    sort(vec2.begin(),vec2.end());
    for(int i=0;i<vec1.size();i++){
        if(vec1[i]>vec2[i]){
            flag=0;break;
        }
    }
    if(flag){
        cout<<"YES";return 0;
    }

    cout<<"NO";
}

