struct np {
    itn n, p, s;  //number,place,sign;
};

void solve() {
    vector<np> v;
    FOR(i, 0, N) {
        v.pb(np{A[i], i, 1});
        v.pb(np{B[i], i, -1});
    }
    sort(all(v), [](np x, np y) {
        if (x.n == y.n) {
            return x.s > y.s;
        } else {
            return x.n < y.n;
        }
    });
    FOR(i, 0, N * 2) {
        if (v[i].s == 1) {
            sub[v[i].p][1] = v[i].s;
        } else {
            sub[v[i].p][0] = v[i].s;
        }
    }
    SegmentTree<int> seg(N * 2, [](int a, int b) { return min(a, b); }, INF);
    int tmp = 0;
    FOR(i, 0, N * 2) {
        tmp += v[i].s;
        seg.set(i, tmp);
    }
    seg.build();
    if (seg.query(0, N * 2 + 1) < 0) {
        cout << "No" << endl;
        return;
    }

    int flag = false;
    FOR(i, 0, N) {
        int a = sub[i][1];
        int b = sub[i][0];
        if (a > b) {
            flag = true;
        } else {
            if (seg.query(a, b + 1) >= 1) {
                flag = true;
            }
        }
    }
    if (flag) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cin >> N;
    FOR(i, 0, N)
    cin >> A[i];
    FOR(i, 0, N)
    cin >> B[i];
    solve();
    return 0;
}

