using namespace std;
#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
typedef long long ll;

typedef set<pair<int,int> > S;

map<int, S> table;
pair<int,int> ps[100000+50];

int solve(int n) {
  sort(ps, ps + n);
  REP(i, n) {
    auto it = table.find(ps[i].second);
    if(it == table.end()) {
      S s;
      s.insert(make_pair(ps[i].first, i));
      table[ps[i].second] = s;
    } else {
      it->second.insert(make_pair(ps[i].first, i));
    }
  }
  int rest = n-2;
  for(int i = n-1; i >= 0; --i) {
    pair<int,int> p = ps[i];
    if(p.first <= p.second) {
      auto it = table.find(p.second);
      it->second.erase(make_pair(p.first, i));
      if(it->second.empty()) {
        table.erase(it);
      }
      continue;
    }
    if(rest <= 0) return false;
    auto it = table.lower_bound(p.first); // 交換対象のset
    if(it == table.end()) return false;
    auto it2 = it->second.begin(); // 交換対象
    ps[it2->second].second = p.second;
    ps[i].second = it->first;
    auto it3 = table.find(p.second); // 元のset
    it3->second.erase(make_pair(p.first, i));
    it3->second.insert(*it2);
    it->second.erase(it2);
    --rest;
  }
  return true;
}

