	for (int i = 0; i < n; i++) a[i] = a_[i] = ri();
	for (int i = 0; i < n; i++) b[i] = b_[i] = ri();
	std::sort(a, a + n);
	std::sort(b, b + n);
	for (int i = 0; i < n; i++) if (a[i] > b[i]) return false;
	int cnt = 0;
	for (int i = 0; i < n; i++) if (a_[i] > b_[i]) cnt++;
	if (cnt == n - 2) assert(0);
	return cnt <= n - 3;
}

