            ng.pb(make_pair(a[i], -b[i]));
        }
    }
    sort(all(ok));
    reverse(all(ok));
    for(auto k: ok) {
        oka.pb(k.fr);
        okb.pb(k.sc);
    }
    sort(all(ng));
    reverse(all(ng));
    SegmentTree<ll> sg(okb, INF);
