    c.push_back(P(a[i],i));
  }
  rep(i,n) {
    cin >> b[i];
    tb[i] = b[i];
    c.push_back(P(b[i],n+i));
  }
  sort(ta,ta+n);
  sort(tb,tb+n);
  bool can = true;
  rep(i,n) {
    if(ta[i] > tb[i]) can = false;
  }
