    cout << "No" << endl;
    return 0;
  }
  sort(c.begin(),c.end());
  bool ans = false;
  vector<int> na(2*n,0), nb(2*n,0);
  SegTree<int> st(2*n,[](int a, int b){return min(a,b);},INF);
  rep(i,2*n) {
    d.push_back(c[i].first);
    if(c[i].second < n) {
      if(i == 0) na[0] = 1;
      else {
