  cin >> n;
  vector <ll> a (n), b (n);
  vector <pair <ll, size_t>> awi, bwi;
  rep (i, n)
  {
    cin >> a [i];
    awi.emplace_back (a [i], i);
  }
  rep (i, n)
  {
    cin >> b [i];
    bwi.emplace_back (b [i], i);
  }
  auto sorted_a = a;
  auto sorted_b = b;
  sort (ALL (sorted_a));
  sort (ALL (sorted_b));
  auto ans = true;
  rep (i, n)
  {
    if (not (sorted_a [i] <= sorted_b [i]))
    {
      ans = false;
      goto finish;
    }
  }
  {
    size_t cnt = 0;
    rep (i, n)
    {
      if (not (a [i] <= b [i]))
      {
        ++ cnt;
      }
    }
    if (not (cnt <= n - 2))
    {
      ans = false;
      goto finish;
    }
  }
  {
    sort (ALL (awi));
    sort (ALL (bwi));
    UnionFind uf (n);
    rep (i, n)
    {
      auto x = bwi [i].second;
      auto y = awi [i].second;
      if (x == y) continue;
      uf.merge (x, y);
    }
    set <size_t> s;
    rep (i, n)
    {
      s.insert (uf.root (i));
    }
    auto cnt = n - s.size ();
    ans = cnt <= n - 2;
  }
finish:
  cout << (ans ? "Yes" : "No") << endl;
}

