int main () {
    int N;
    cin >> N;
    vector<pair<int, int>> v(N);
    for (int i = 0; i < N; i++) {
        cin >> v[i].first;
    }
    for (int i = 0; i < N; i++) {
        cin >> v[i].second;
    }
    sort(v.begin(), v.end(), [](auto x, auto y) {
        return x.second < y.second;
    });
    vector<pair<int, int>> vv;
    for (int i = 0; i < N; i++) {
        if (!(v[i].first <= v[i].second)) {
            vv.push_back(v[i]);
        }
    }
    for (int i = N-1; i >= 0; i--) {
        if ((v[i].first <= v[i].second)) {
            vv.push_back(v[i]);
        }
    }
    v.erase(v.begin(), v.end());
    map<int, int> mp[400];
    for (int i = 0, s = 0; s < N; i++, s+=300) {
        for (int j = 0; j < 300 && s+j < N; j++) {
            mp[i][vv[s+j].first]++;
        }
    }
    int k = 0;
    for (int i = 0; i < N; i++) {
        if (vv[i].first <= vv[i].second) continue;
        int b = vv[i].second;
        int y = -1;
        for (int j = i+1; j % 300 != 0 && j < N; j++) {
            if (vv[j].first <= b) {
                y = j;
                break;
            }
        }
        if (y == -1) {
            for (int j = (i/300+1); j*300 < N && y == -1; j++) {
                if (!((*mp[j].begin()).first <= b)) {
                    continue;
                }
                for (int k = j*300;; j++) {
                    if (vv[k].first <= b) {
                        y = k;
                        break;
                    }
                }
            }
        }
        if (y == -1) {
            puts("No");
            return 0;
        }
        k++;
        mp[i/300][vv[i].first]--;
        mp[y/300][vv[y].first]--;
        if (mp[i/300][vv[i].first] == 0) {
            mp[i/300].erase(vv[i].first);
        }
        if (mp[y/300][vv[y].first] == 0) {
            mp[y/300].erase(vv[y].first);
        }
        swap(vv[i].first, vv[y].first);
        mp[i/300][vv[i].first]++;
        mp[y/300][vv[y].first]++;
    }
    if (!(k <= (N-2))) {
        puts("No");
        return 0;
    }
    for (int i = 0; i < N; i++) {
        if (!(vv[i].first <= vv[i].second)) {
            puts("No");
            return 0;
        }
    }
    puts("Yes");
}

