typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)

int main(){
    ll n;
    cin >> n;
    vector<ll> a0(n);
    REP(i, n){
        cin >> a0[i];
    }
    vector<pair<ll, ll>> b(n);
    REP(i, n){
        ll bi;
        cin >> bi;
        b[i] = {bi, i};
    }
    sort(b.begin(), b.end());
    vector<pair<ll, ll>> a(n);
    REP(i, n){
        a[i] = {a0[b[i].second], i};
    }
    vector<pair<ll, ll>> sa = a;
    sort(sa.begin(), sa.end());

    REP(i, n){
        if(sa[i].first > b[i].first){
            cout << "No" << endl;
            return 0;
        }
    }

    REP(i, n - 1){
        if(sa[i + 1].first <= b[i].first){
            cout << "Yes" << endl;
            return 0;
        }
    }

    vector<ll> perm(n);
    REP(i, n){
        perm[sa[i].second] = i;
    }
    vector<bool> visited(n, false);
    ll ncycle = 0;
    REP(i, n){
        if(visited[i]){ continue; }
        ncycle++;
        ll cur = i;
        while(!visited[cur]){
            visited[cur] = true;
            cur = perm[cur];
        }
    }

    if(n - ncycle < n - 1){
        cout << "Yes" << endl;
        return 0;
    }

    cout << "No" << endl;
    return 0;
}

