    rep(i,n){
        if(sa[i]>sb[i]){
            Yes(false);
            return 0;
        }
    }

    queue <P> ok;
    rep(i,n){
        if(a[i]==b[i]){
            Yes(true);
            return 0;
        }
        if(a[i]<=b[i]){
            ok.push(mp(a[i],b[i]));
        }
