using namespace std;

int main(){

    int N;
    cin >> N;

    vector<int> A(N);
    vector<int> B(N);

    for(int i = 0; i < N; i++){
        cin >> A[i];
    }

    for(int i = 0; i < N; i++){
        cin >> B[i];
    }

    vector<pair<int, int>> AB(N);

    for(int i = 0; i < N; i++){
        AB[i] = make_pair(A[i], B[i]);
    }

    sort(AB.begin(), AB.end());

    vector<pair<int, int>> BI(N);
    for(int i = 0; i < N; i++){
        BI[i] = make_pair(AB[i].second, i);
    }

    sort(BI.begin(), BI.end());

    vector<int> orderList(N);
    for(int i = 0; i < N; i++){
        orderList[BI[i].second] = i;
    }

    for(int i = 0; i < N; i++){
        if(AB[i].first > BI[i].first){
            cout << "No" << endl;
            return 0;
        }
    }

    vector<int> leftOkAcc(N + 1);
    vector<int> rightOkAcc(N + 1);
    leftOkAcc[0] = 0;
    leftOkAcc[1] = 0;
    for(int i = 2; i <= N; i++){
        int temp = 0;
        if(AB[i - 1].first <= AB[i - 2].second){
            temp = 1;
        }
        leftOkAcc[i] = leftOkAcc[i - 1] + temp;
    }

    rightOkAcc[0] = 0;
    for(int i = 1; i <= N - 1; i++){
        int temp = 0;
        if(AB[i - 1].first <= AB[i].second){
            temp = 1;
        }
        rightOkAcc[i] = rightOkAcc[i - 1] + temp;
    }
    rightOkAcc[N] = rightOkAcc[N - 1];

    bool isOk = false;
    for(int i = 0; i < N; i++){
        int temp = orderList[i];

        int a = AB[i].first;
        int b = AB[temp].second;

        if(a <= b){
            if(i == temp){
                isOk = true;
                break;
            }
            else if(i < temp){
                int cnt = leftOkAcc[temp + 1] - leftOkAcc[i + 1];
                if(cnt == temp - i){
                    isOk = true;
                    break;
                }
            }
            else{ // i > temp
                int cnt = rightOkAcc[i] - rightOkAcc[temp];
                if(cnt == i - temp){
                    isOk = true;
                    break;
                }
            }
        }
    }

    if(isOk){
        cout << "Yes" << endl;
    }
    else{
        cout << "No" << endl;
    }

    return 0;
}

