        return !printf("No\n");
    sort(B, B + n);
    sort(A, A + n);
    for (int i = 0; i < n; i ++)
        if (A[i].first > B[i].first)
            return !printf("No\n");
    for (int i = 0; i < n; i ++)
    {
        R[A[i].second] = B[i].second;
        rev[B[i].second] = A[i].second;
    }
    int __c = 1, iod = rev[0];
    while (iod)
        __c ++, iod = rev[iod];
    cnt = 0;
    for (int i = 0; i < n; i ++)
