	cin >> n;
	vector<pii> a(n), b(n);

	for (int i=0; i<n; ++i)
    {
        int v;
        cin >> v;
        a[i] = make_pair(v, i);
    }
	for (int i=0; i<n; ++i)
    {
        int v;
        cin >> v;
        b[i] = make_pair(v, i);
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());


	// check
	for (int i=0; i <n; ++i)
 	if (a[i].first > b[i].first) ending(false);

	// check spanning 
	UnionFind uf(n);
	for (int i=0; i<n; ++i)
		uf.unite(a[i].second, b[i].second);

	int cnt = 0;
	for (int i=0; i<n; ++i)
	if (uf.par[i] == -1) ++cnt;

	if (cnt > 1)
		ending(true);

	for (int i=0; i<n-1; ++i)
	if (a[i+1].first < b[i].first) ending(true);

    ending(false);
}

