template<typename T> inline vector<T> fetch_vec(int sz) { vector<T> ret(sz); for(auto& elem: ret) cin >> elem; return ret; }

void solve() {
	int n = fetch<int>();
	auto a = fetch_vec<int>(n);
	auto b = fetch_vec<int>(n);

	auto ord_a = a;
	sort(ord_a.begin(), ord_a.end());

	auto ord_b = b;
	sort(ord_b.begin(), ord_b.end());

	for(int i = 0; i < n; ++i) {
		if(ord_a[i] > ord_b[i]) {
			cout << "No\n";
			return;
		}
	}

	for(int i = 1; i < n; ++i) {
		if(ord_b[i - 1] >= ord_a[i]) {
			cout << "Yes\n";
			return;
		}
	}

	vector<int> p(n, NIL), used(n, 0);
	int cycles = 0;

	for(int i = 0; i < n; ++i) {
		p[i] = lower_bound(ord_a.begin(), ord_a.end(), a[i]) - ord_a.begin();
	}

	for(int i = 0; i < n; ++i) {
		if(!used[i]) {
			++cycles;

			for(int j = i; !used[j]; j = p[j]) {
				used[j] = 1;
			}
		}
	}

	DBG(cycles);
	cout << (cycles > 1 ? "Yes\n" : "No\n");
}

