int main() {
	int N; cin >> N;
	vector<long long>A(N), B(N);
	int Amax = 0, Bmax = 0;
	for (int i = 0; i < N; i++) {
		cin >> A.at(i);
		Amax = Amax < A.at(i) ? A.at(i) : Amax;
	}
	for (int i = 0; i < N; i++) {
		cin >> B.at(i);
		Bmax = Bmax < B.at(i) ? B.at(i) : Bmax;
	}
	if (Amax > Bmax) {
		cout << "No" << endl;
		return 0;
	}
	else {
		int ans = 0;
		for (int i = 0; i < N; i++) {
			if (A.at(i) > B.at(i)) ans++;
		}
		if ((N - ans) % ans == 0 && ans <= N - 2) cout << "Yes" << endl;
		else cout << "No" << endl;
		return 0;
	}
}

