main() {
    int64_t n;
    cin >> n;

    vector<pair<int64_t, int64_t>> ba(n);
    for (auto&& aa : ba) {
        cin >> aa.second;
    }
    for (auto&& aa : ba) {
        cin >> aa.first;
    }

    sort(ba.rbegin(), ba.rend());

    vector<int64_t> targets;
    for (auto i : irange(0L, n)) {
        const auto& t = ba[i];
        // a > b
        if (t.second > t.first) {
            targets.push_back(i);
        }
    }

    if (targets.size() >= n - 1) {
        cout << "No" << endl;
        return 0;
    }

    sort(targets.begin(), targets.end(), [&](int64_t lhs, int64_t rhs) {
        return make_pair(ba[lhs].second, ba[lhs].first) >
               make_pair(ba[rhs].second, ba[rhs].first);
    });

    multiset<int64_t> as;
    auto prev_it = ba.begin();
    for (auto idx : targets) {
        auto end = partition_point(ba.begin(), ba.end(),
                                   [&](const pair<int64_t, int64_t>& p) {
                                       return ba[idx].second <= p.first;
                                   });

        if (end == ba.begin()) {
            cout << "No" << endl;
            return 0;
        }

        for (auto it = prev_it; it != end; ++it) {
            as.emplace(it->second);
        }
        prev_it = end;

        auto it = as.upper_bound(ba[idx].first);
        if (it == as.begin()) {
            cout << "No" << endl;
            return 0;
        }
        --it;
        ba[idx].second = *it;
        as.erase(it);
        as.emplace(ba[idx].second);
    }

    cout << "Yes" << endl;
}

