void solve() {
    vector<np> v;
    FOR(i, 0, N) {
        v.pb(np{A[i], i, 1});
        v.pb(np{B[i], i, -1});
    }
    sort(all(v), [](np x, np y) {
        if (x.n == y.n) {
            return x.s > y.s;
        } else {
            return x.n < y.n;
        }
    });
    FOR(i, 0, N * 2) {
        if (v[i].s == 1) {
            sub[v[i].p][1] = i;
        } else {
            sub[v[i].p][0] = i;
        }
    }
    SegmentTree<int> seg(N * 2, [](int a, int b) { return min(a, b); }, INF);
    int tmp = 0;
    FOR(i, 0, N * 2) {
        tmp += v[i].s;
        seg.set(i, tmp);
    }
    seg.build();
    if (seg.query(0, N * 2 + 1) < 0) {
        cout << "No" << endl;
        return;
    }


    int flag = false;
    FOR(i, 0, N) {
        int a = sub[i][1];
        int b = sub[i][0];
        // cout << a << " " << b << endl;
        if (v[a].n <= v[b].n) {
            if (a > b) {
                flag = true;
                //cout << a << " " << b << endl;
            } else {
                //cout << seg.query(a, b + 1) << endl;
                if (seg.query(a, b) >= 1) {
                    flag = true;
                }
            }
        }
    }
    if (flag) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

