	for (int i = 0; i < N; i++){
		A2[i] = make_pair(A[i], i);
	}
	vector<pair<int, int>> B2(N);
	for (int i = 0; i < N; i++){
		B2[i] = make_pair(B[i], i);
	}
	sort(A2.begin(), A2.end());
	sort(B2.begin(), B2.end());
	bool ok = true;
	for (int i = 0; i < N; i++){
		if (B2[i].first < A2[i].first){
			ok = false;
		}
	}
	if (!ok){
		cout << "No" << endl;
	} else {
		ok = false;
		for (int i = 0; i < N - 1; i++){
			if (A2[i].first >= B2[i + 1].first){
				ok = true;
			}
		}
		if (ok){
			cout << "Yes" << endl;
		} else {
			vector<vector<int>> E(N);
			for (int i = 0; i < N; i++){
				E[A2[i].second].push_back(B2[i].second);
				E[B2[i].second].push_back(A2[i].second);
			}
			vector<bool> used(N, false);
			used[0] = true;
			queue<int> Q;
			Q.push(0);
			while (!Q.empty()){
				int v = Q.front();
				Q.pop();
				for (int w : E[v]){
					if (!used[w]){
						used[w] = true;
						Q.push(w);
					}
				}
			}
			for (int i = 0; i < N; i++){
				if (!used[i]){
					ok = true;
				}
			}
			if (ok){
				cout << "Yes" << endl;
			} else {
				assert(false);
				cout << "No" << endl;
			}
		}
	}	
}

