using P = pair<Int, Int>;
Int n;
vector<Int> a, b;
vector<P> v;
priority_queue<P> pq;

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n;
	a.resize(n);
	b.resize(n);
	v.resize(n);
	for(Int i=0; i<n; ++i) cin >> a[i];
	for(Int i=0; i<n; ++i) cin >> b[i];
	for(Int i=0; i<n; ++i) v[i] = P(a[i], b[i]);
	sort(v.rbegin(), v.rend());
	for(Int i=0; i<n; ++i)
		pq.push(P(v[i].second, i));
	Int cnt = 0;
	for(Int i=0; i<n; ++i){
//		cout << i << "\n";
//		for(Int j=0; j<n; ++j)
//			cout << v[j].first << " " << v[j].second << "\n";
		if(v[i].first > v[i].second){
			bool f = false;
			while(!pq.empty() && !f){
				P p = pq.top(); pq.pop();
				Int j = p.second;
				if(v[i].first <= v[j].second && v[j].first <= v[i].second){
					++cnt;
					f = true;
					swap(v[i].first, v[j].first);
				}
			}
			if(!f) cnt = n;
		}
	}
	if(cnt <= n-2) cout << "Yes\n";
	else cout << "No\n";
}

