const int INF = 1LL << 29;
const ll LONGINF = 1LL << 60;
const ll MOD = 1000000007LL;

void modify(pair<int, int> &A, pair<int, int> B) {
    if(A.first < B.first) A = B;
    if(A.first == B.first) {
        if(A.second > B.second) A = B;
    }
}

const pair<int, int> NIL(-1, -1);
const int SIZE = 1 << 17;

// value, -index (要素昇順、インデックス降順？)
struct SegmentTree {
    int val[SIZE];
    set< pair<int, int> > node[2*SIZE];
    SegmentTree() {
        fill(val, val + SIZE, -1);
        fill(node, node + 2*SIZE, set< pair<int, int> >()); 
    }
    void update(int k, int v) {
        int idx = k, pre = val[idx];
        val[idx] = v;

        k += SIZE - 1;
        while(k > 0) {
            // すでにあるものを探して消す
            if(pre != -1) node[k].erase(make_pair(pre, -idx));

            // 挿入する
            node[k].emplace(val[idx], -idx);

            /*
            fprintf(stderr, "# k = %d\n", k);
            for(auto e : node[k]) cerr << e.first << " ";
            cerr << endl;
            */

            if(k == 0) break;
            k = (k - 1) / 2;
        }
    }
    pair<int, int> query(int a, int b, int v, int l=0, int r=SIZE, int k=0) {
        if(b <= l or r <= a) return NIL;
        if(a <= l and r <= b) {
            // v 以下最大の要素
            auto itr = node[k].upper_bound(make_pair(v+1, -INF));
            if(itr == node[k].begin()) return NIL;
            itr = prev(itr);
            return make_pair(itr->first, -(itr->second));
        }
        int mid = (l + r) / 2;
        auto vl = query(a, b, v, l, mid, 2*k+1);
        auto vr = query(a, b, v, mid, r, 2*k+2);

        pair<int, int> res = NIL;
        if(vl != NIL) {
            if(res == NIL) res = vl;
            modify(res, vl);
        }
        if(vr != NIL) {
            if(res == NIL) res = vr;
            modify(res, vr);
        }
        return res;
    }
};

SegmentTree seg;
int main() {
    int N; cin >> N;    
    vector<int> A(N), SA(N);
    vector<int> B(N), SB(N);
    for(int i=0; i<N; i++) cin >> A[i], SA[i] = A[i];
    for(int i=0; i<N; i++) cin >> B[i], SB[i] = B[i];

    sort(SA.begin(), SA.end());
    sort(SB.begin(), SB.end());

    // N - 1 回を許してもできないとき
    if(SA > SB) {
        cout << "No" << endl;
        return 0;
    }

    vector< pair<int, int> > P;
    for(int i=0; i<N; i++) {
        P.emplace_back(B[i], A[i]);
    }

    // B 昇順に並べる
    sort(P.begin(), P.end());

    bool ok = true;
    int swp = 0;
    // B 大きいものから調べる
    for(int i=N-1; i>=0; i--) {
        int b, a; tie(b, a) = P[i];
        if(a <= b) {
            seg.update(i, a);
            continue;
        }

        int l = lower_bound(P.begin(), P.end(), make_pair(a, -1)) - P.begin();
        int r = N;
        if(l == r) ok = false;

        // a 以上の要素から、b 以下最大のものを見つける
        // インデックスを返すようにする
        pair<int, int> e = seg.query(l, r, b);
        if(e == NIL) ok = false;
        int k = e.second;

        // fprintf(stderr, "i = %d: a = %d, b = %d\n", i, a, b);
        // fprintf(stderr, "query: first = %d, second = %d\n", e.first, e.second);

        if(e != NIL) {
            swp++;
            // P の i 番目と k 番目について、second の値をいれかえる
            // (つまり a をいれかえ)
            // seg の方の更新わすれずに
            seg.update(i, P[k].second);
            swap(P[k].second, P[i].second);
        }
    }

    /*
    fprintf(stderr, "swp = %d\n", swp);
    for(int i=N-1; i>=0; i--) {
        fprintf(stderr, "i = %d: %d, %d\n", i, P[i].first, P[i].second);
    }
    */

    ok &= (swp <= N - 2);
    cout << (ok ? "Yes" : "No") << endl;
    return 0;
}

