bool solve()
{
    vector<ll> A, B;
    REP(i, N)
    {
        A.push_back(S[i].first);
        B.push_back(S[i].second);
    }
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    REP(i, N)
    {
        if (A[i] > B[i])
            return false;
    }
    sort(S, S + N, [](pll a, pll b) { return a.first == b.firts ? a.second < b.second : a.firts < b.firts; });

