ll pw(ll k,ll x){
  if(x==0)
  return 1;
  if(x&1)
  return ((pw(k,x-1)%mod)*k%mod)%mod;
  else
  return ((pw(k,x/2)%mod)*(pw(k,x/2)%mod))%mod;
}

