  ios::sync_with_stdio(0);
  cin.tie(0);

  int n; cin >> n;
  vector<pair<int, int>> a(n), b(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i].first;
    a[i].second = i;
  }
  for (int i = 0; i < n; ++i) {
    cin >> b[i].first;
    b[i].second = i;
  }
  if (n == 2) {
    bool x = a[0].first <= b[0].first, y = a[1].first <= b[1].first;
    cout << (x && y ? "Yes" : "No") << endl;
    return 0;
  }
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for (int i = 0; i < n; ++i) {
    if (a[i].first > b[i].first) {
      cout << "No\n";
      return 0;
    }
  }
  vector<int> nxt(n);
  for (int i = 0; i < n; ++i) {
    nxt[a[i].second] = b[i].second;
  }
  vector<bool> vis(n);
  int cnt_cycles = 0;
  for (int i = 0; i < n; ++i) {
    if (vis[i]) continue;
    int x = i;
    ++cnt_cycles;
    do {
      assert(!vis[x]);
      vis[x] = true;
      x = nxt[x];  
    } while (x != i);
  }
  cout << (cnt_cycles == 1 ? "No" : "Yes") << endl;


  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
}

