    cin.tie(nullptr);
    ll N; cin >> N;
    vpl BA(N);
    rep(i, N) cin >> BA[i].ss;
    rep(i, N) cin >> BA[i].ff;
    sort(ALL(BA), greater<PL>());

    multiset<PL> ms;
    rep(i, N) ms.insert({BA[i].ss, i});

    ll skip = 0;
    rep(i, N){
        PL ep = *ms.rbegin();
        ll e = ep.ff, idx = ep.ss;
        if(e > BA[i].ff){
            cout << "No" << endstr; return 0;
        }
        if(BA[i].ss == e){
            skip++;
        }
        else{
            if(BA[idx].ff == BA[i].ff){
                skip++;
            }
            if(idx > i){
                swap(BA[idx].ss, BA[i].ss);
            }
        }
        ms.erase(prev(ms.end()));
    }
    cerr << skip << endstr;
    cout << (skip > 1 ? "No" : "No") << endstr;
    return 0;
}

