using namespace std;

template<typename T>
struct BIT {
    int n;
    vector<T> dat;

    BIT(int n=0){
        initialize(n);
    }

    void initialize(int nin){
        n = nin;
        dat.resize(n, 0);
    }

    T sum(int i){
        T s = 0;
        while(i >= 0){
            s += dat[i];
            i = (i & (i+1)) - 1;
        }
        return s;
    }

    T sum_between(int i, int j){
        return sum(j) - sum(i-1);
    }

    void plus(int i, T x){
        while(i < n){
            dat[i] += x;
            i |= i+1;
        }
    }

    // a[0]+...+a[ret] >= x
    int lower_bound(T x){
        int ret = -1;
        int k = 1;
        while(2*k <= n) k <<= 1;
        for( ;k>0; k>>=1){
            if(ret+k < n && dat[ret+k] < x){
                x -= dat[ret+k];
                ret += k;
            }
        }
        return ret + 1;
    }
};

bool fin(bool ok){
    cout << (ok ? "Yes" : "No") << endl;
    exit(0);
}

int main(){
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];

    vector<pair<int, int>> AS(N), BS(N);
    for(int i=0; i<N; i++){
        AS[i] = {A[i], i};
        BS[i] = {B[i], i};
    }
    sort(AS.begin(), AS.end());
    sort(BS.begin(), BS.end());
    vector<int> AR(N), BR(N);
    for(int i=0; i<N; i++){
        AR[AS[i].second] = i;
        BR[BS[i].second] = i;
    }

    // NGなところ
    BIT<int> bitl(N), bitc(N), bitr(N);
    for(int i=0; i<N; i++){
        if(i > 0 && AS[i].first > BS[i-1].first) bitl.plus(i, 1);
        if(AS[i].first > BS[i].first) bitc.plus(i, 1);
        if(i < N-1 && AS[i].first > BS[i+1].first) bitr.plus(i, 1);
    }

    for(int i=0; i<N; i++){
        if(A[i] > B[i]) continue;
        int ap = AR[i], bp = BR[i];
        int ng = 0;
        if(ap < bp){
            ng = bitc.sum_between(0, ap-1) + bitl.sum_between(ap+1, bp) + bitc.sum_between(bp+1, N-1);
        }else if(ap > bp){
            ng = bitc.sum_between(0, bp-1) + bitr.sum_between(bp, ap-1) + bitc.sum_between(ap+1, N-1);
        }else{
            ng = bitc.sum_between(0, ap-1) + bitc.sum_between(ap+1, N-1);
        }
        if(ng == 0){
            fin(true);
        }
    }

    vector<vector<int>> AB;
    for(int i=0; i<N; i++){
        AB.push_back({A[i], -1, i});
        AB.push_back({B[i], 1, i});
    }
    sort(AB.begin(), AB.end());
    set<int> exist;
    int s = 0, cnt = 0;
    for(auto& v : AB){
        int d = v[1], i = v[2];
        s += d;
        if(s > 0) fin(false);
        if(exist.count(i)){
            exist.erase(i);
        }else{
            exist.insert(i);
        }
        if(exist.size() == 0) cnt++;
    }
    fin(cnt >= 2);
    return 0;
}

