struct unionfind {
  vector<int> dat;

  unionfind(int n) : dat(n, -1) {}

  int find(int x) {
    if (dat[x] < 0) return x;
    return dat[x] = find(dat[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (dat[x] > dat[y]) swap(x, y);
    dat[x] += dat[y];
    dat[y] = x;
  }

  int size(int x) {
    return -dat[find(x)];
  }
};

bool solve() {
  int N; cin >> N;
  vector<int> A(N); rep(i, N) cin >> A[i];
  vector<int> B(N); rep(i, N) cin >> B[i];
  vector<int> tmpA(A);
  vector<int> tmpB(B);
  sort(range(tmpA));
  sort(range(tmpB));
  rep(i, N) {
    if (tmpA[i] > tmpB[i]) return false;
  }
  rep(i, N) {
    int cnt = upper_bound(range(tmpA), tmpB[i]) - tmpA.begin();
    if (cnt >= i + 2) return true;    
  }
  unionfind uf(N);
  vector<int> ordA(N); rep(i, N) ordA[i] = i;
  vector<int> ordB(N); rep(i, N) ordB[i] = i;
  sort(range(ordA), [&](int i, int j) { return A[i] < A[j]; });
  sort(range(ordB), [&](int i, int j) { return B[i] < B[j]; });
  rep(i, N) {
    uf.unite(ordA[i], ordB[i]);
  }
  int roots = 0;
  rep(i, N) {
    if (uf.find(i) == i) roots++;
  }
  return roots != 1;
}

