		if (a.second == b.second)return a.first < b.first;
		else return a.second < b.second;
	});

	sort(all(b));

	RmqTree2 rmq(n+1);

	REP(i, n)rmq.update(i, make_pair(-ab[i].first, i));

	ll cnt = 0;
	for (int i = n - 1; i >= 0; i--) {
		ll now = -rmq.find(i, i + 1).first;
		if (now <= ab[i].second)continue;

		ll l = lower_bound(all(b), now) - b.begin();

