using P = pair<int,int>;
const int INF = 2e9;

template <typename T>
class SegTree{
  using F = function<T(T,T)>;
  int n; F f; T uni;
  vector<T> dat;

  T _query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return uni;
    if(a <= l && r <= b) return dat[k];
    T vl = _query(a, b, k*2+1, l, (l+r)/2);
    T vr = _query(a, b, k*2+2, (l+r)/2, r);
    return f(vl,vr);
  }

public:
  SegTree(int _n, F f, T uni) : f(f), uni(uni) {
    n = 1;
    while(n < _n) n *= 2;
    dat = vector<T>(2*n-1,uni);
  }

  void update(int k, T a) {
    k += n-1;
    dat[k] = a;
    while(k > 0){
      k = (k-1)/2;
      dat[k] = f(dat[2*k+1], dat[2*k+2]);
    }
  }

  T query(int a, int b){ 
    return _query(a, b, 0, 0, n);
  } 

  T operator[](int i) {
    return dat[i+n-1];
  }
};

int main(){
  int n;
  cin >> n;
  int a[n], b[n], ta[n], tb[n];
  vector<P> c;
  vector<int> d;
  rep(i,n) {
    cin >> a[i];
    ta[i] = a[i];
    c.push_back(P(a[i],i));
  }
  rep(i,n) {
    cin >> b[i];
    tb[i] = b[i];
    c.push_back(P(b[i],n+i));
  }
  bool f = true;
  rep(i,n) {
    if(a[i] > b[i]) f = false;
  }
  if(f) {
    cout << "Yes" << endl;
    return 0;
  }
  sort(ta,ta+n);
  sort(tb,tb+n);
  bool can = true;
  rep(i,n) {
    if(ta[i] > tb[i]) can = false;
  }
  if(!can) {
    cout << "No" << endl;
    return 0;
  }
  sort(c.begin(),c.end());
  bool ans = false;
  SegTree<int> st(2*n,[](int a, int b){return min(a,b);},INF);
  int dif = 0;
  rep(i,2*n) {
    d.push_back(c[i].first);
    if(c[i].second < n) st.update(i,++dif);
    else st.update(i,--dif);
  }
  rep(i,2*n) {
    if(c[i].second >= n && a[c[i].second % n] <= b[c[i].second % n]) {
      int l = lower_bound(d.begin(),d.end(),a[c[i].second % n]) - d.begin();
      if(a[c[i].second % n] == b[c[i].second % n]) ans = true;
      else if(st.query(l,i) >= 1) ans = true;
    }
  }
  cout << (ans? "Yes" : "No") << endl; 
  return 0;
}

