typedef pair<int, int> P;
bool pairCompare(const P& l, const P& r) {
    return l.second > r.second;
}
int main() {
    int N;
    cin >> N;

    vector<P> A, B;
    A.reserve(N);
    B.reserve(N);
    int tmp;
    map<int, int> index;
    for (int i = 0;i < N; ++i) {
        cin >> tmp;
        A.push_back(pair<int, int>(i, tmp));
        index[i] = i;
    }
    for (int i = 0;i < N; ++i) {
        cin >> tmp;
        B.push_back(pair<int, int>(i, tmp));
    }

    sort(A.begin(), A.end(), pairCompare);
    sort(B.begin(), B.end(), pairCompare);

    int count = 0;
    set<int> ok;
    for (int i = 0; i < N; ++i) {
        // cout << A[i].second << ":" << B[i].second << endl;
        if (A[i].second > B[i].second) {
            cout << "No" << endl;
            return 0;
        }
        bool f = false;
        for (int k = i; A[i].second <= B[k].second && k < N; ++k) {
            if (ok.find(B[k].first) == ok.end()) continue;
            if (index[A[i].first] == B[k].first) {
                ok.insert[B[k].first];
                swap(B[i], B[k]);
                f = true;
                break;
            }
        }
        if (f) continue;
        tmp = index[A[i].first];
        index[A[i].first] = index[B[i].first];
        index[B[i].first] = tmp;
        count ++;
    }
    if (count <= N-2) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}

