#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

bool solve(int N, vi& a, vi& b) {
    int L = N-2;
    vii ab(N);
    rep(i,N) ab[i] = ii(b[i], a[i]);
    sort(ALL(ab));

    set<ii> ms;
    rep(i,N) ms.insert( ii(a[i], i) );

    int swapcount = 0;
    rep(i,N){
        int bi=ab[i].first, ai=ab[i].second;
        ms.erase( ii(ai, i) );
        if (ai <= bi) {
            continue;
        }
        ++swapcount;
        auto it = ms.upper_bound( ii(b[i], INT_MAX) );
        if (it == ms.begin()) return false;
        --it;
        int j = it->second, aj = ab[j].second;
        ab[i].second = aj;
        ab[j].second = ai;
        ms.erase( ii(aj, j) );
        ms.insert( ii(ai, j) );
    }
    return (swapcount <= L);
}

int main() {
    int N; scanf("%d%*c", &N);
    vi a(N), b(N);
    loadvec(a,N); loadvec(b,N);
    cout << (solve(N,a,b) ? "Yes":"No") << endl;
    return 0;
}

