void dfs(int index, const vector<int>& va, vector<int>& vb, map<int, unordered_set<int>> m, bool& res, int c) {
    // if (index == va.size()) cout << c << endl;
    if (index == va.size() && c <= va.size() - 2) {
        res = true;
        return;
    }
    if (c > va.size() - 2) return;

    auto it = m.lower_bound(va[index]);
    for (; it != m.end() && res == false; it++) {
        map<int, unordered_set<int>> mm = m;

        for (auto n : m[it -> first]) {
            mm[it -> first].erase(n);
            if (n == index) {
                dfs(index + 1, va, vb, mm, res, c);
            }
            else {
                int t = vb[n];
                vb[n] = vb[index];
                mm[vb[index]].erase(index);
                mm[vb[index]].insert(n);
                dfs(index + 1, va, vb, mm, res, c + 1);
                mm[vb[index]].erase(n);
                mm[vb[index]].insert(index);
                vb[n] = t;
            }
            mm[it -> first].insert(n);
        }
    }
}

