int parent[N], ran[N];
int find(int x)
{
    if(parent[x]==x)return x;
    else return parent[x]=find(parent[x]);
}
// Union()
void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;

    if(ran[x]<ran[y])
        parent[x]=y;
    else{
        parent[y]=x;
        if(ran[x]==ran[y])ran[x]++;
    }
}
void solve()
{
	ll n;
	cin>>n;
	vector<pair<ll,ll>> a(n), b(n);
	rep(i, 0, n)
	{
		ll x;
		cin>>x;
		a[i] = make_pair(x, i);
		parent[i] = i;
		ran[i] = 0;
	}
	rep(i ,0 ,n )
	{
		ll x;
		cin>>x;
		b[i] = make_pair(x, i);
	}
	sort(all(a));
	sort(all(b));
	int j = 0;
	int curr = 0;
	int pre = 0;
	vector<ll> req;
	bool ok = true;
	rep(i, 0, n)
	{
		ll now = b[i].f;
		while(j < n && a[j].f <= now)
		{
			req.pb(a[j].s);
			j++;
			if(j < n && a[j].f <= now) ok = false;
			curr++;
			break;
		}
		if(pre == curr) {cout<<"No"<<endl;return;}
		pre = curr;
	}
	rep(i, 0, n)
	{
		int curr = b[i].s;
		int r = req[i];
		unite(curr, r);
	}
	int z = find(b[0].s);
	bool f = false;
	rep(i, 1, n)
	{
		int curr = b[i].s;
		if(z != find(curr)) {cout<<"Yes"<<endl;return;}
		f = true;
	}
	if(f && ok)
	{
		cout<<"No"<<endl;
	}
	else cout<<"Yes"<<endl;
}


