	auto cntC = MergeSort(C);
	auto cntD = MergeSort(D);
	REP(i,N){
		if(C[i]>D[i]){
			out("No");
			return 0;
		}
	}

	out(cntC-cntD<=N-2 ? "Yes" : "No");
	return 0;
}

