  REP(i, N) cin >> A[i];
  REP(i, N) cin >> B[i];
  vector<PI> AP(N), BP(N);
  REP(i, N) {
    AP[i] = PI(A[i], i);
    BP[i] = PI(B[i], i);
  }
  sort(ALL(AP));
  sort(ALL(BP));

  REP(i, N) {
    if (BP[i].first < AP[i].first) {
      cout << "No" << endl;
      return 0;
    }
