  REP(i, N) {
    int a_index = AP[i].second;
    int b_index = b_pos[AP[i].second];
    if (a_index >= b_index || (sum[b_index] - sum[a_index] == b_index - a_index)) {
      cout << "Yes" << endl;
      return 0;
    } 
  }
  cout << "No" << endl;
