      can_shift_since[i] = -1;
      last_shift = -1;
    } else {
      if (last_shift == -1) {
        last_shift = i;
      }
      can_shift_since[i] = last_shift;
    }
    a_map[sorted_a[i]] = i;
    b_map[sorted_b[i]] = i;
  }
  for (size_t i = 0; i < a.size(); ++i) {
    if (a[i] <= b[i]) {
      auto ai = a_map[a[i]];
      auto bi = b_map[b[i]];
      if (sorted_a[bi] <= sorted_b[ai]) {
        if (bi <= ai || can_shift_since[bi - 1] <= int(ai)) {
          return true;
        }
      }
    }
  }
  return false;
}

