    });
    for (int i = 0; i < n; i++) {
        if (a[i] > s[i].second) {
            cout << "No"; return;
        }
    }
    for (int i = 1; i < n; i++) {
        if (a[i] <= s[i-1].second) {
            cout << "Yes"; return;
        }
    }

    Perm p(n);
    iota(p.begin(), p.end(), 0);
    sort(p.begin(), p.end(), [&](auto& u, auto& v){
        return s[u].first < s[v].first;
    });
