bool hasCycle = false;

void search(int curr, int &n, vector<vector<int>> &v, vector<int> &visited, int count) {
    if (hasCycle) return;
    visited[curr] = count;
    for (auto &to: v[curr]) {
        if (visited[to] != -1) {
            if (count - visited[to] + 1 != n) hasCycle = true;
            continue;
        }
        search(to, n, v, visited, count+1);
    }
}

