struct UnionFind{
    vector<ll> data;
    UnionFind(ll n): data(n, -1){}
    bool unite(ll a, ll b){
        a = root(a); b = root(b);
        if(a == b) return 1;
        if(data[a] > data[b]) swap(a, b);
        data[a] += data[b];
        data[b] = a;
        return 0;
    }
    bool find(ll a, ll b){ return root(a) == root(b); }
    ll root(ll a){ return data[a] < 0 ? a : data[a] = root(data[a]); }
    ll size(ll a){ return -data[root(a)]; }
    ll operator[](ll a){ return root(a); }
};
int main(){
  ll n;
  cin >> n;
  vector<ll> a(n), b(n);
  for(auto& i : a) cin >> i;
  for(auto& i : b) cin >> i;
  vector<ll> c(n);
  iota(c.begin(), c.end(), 0);
  sort(c.begin(), c.end(), [&a](ll x, ll y){ return a[x] < a[y]; });
  vector<ll> A(n), B(n);
  for(ll i = 0; i < n; i++){
    A[i] = a[c[i]];
    B[i] = b[c[i]];
  }
  sort(b.begin(), b.end());
  for(ll i = 0; i < n; i++) if(A[i] > b[i]) return puts("No") & 0;
  for(ll i = 0; i < n - 1; i++) if(A[i + 1] <= b[i]) return puts("Yes") & 0;
  vector<ll> d(n);
  iota(d.begin(), d.end(), 0);
  sort(d.begin(), d.end(), [&B](ll x, ll y){ return B[x] < B[y]; });
  UnionFind uf(n);
  for(ll i = 0; i < n; i++) uf.unite(i, d[i]);
  if(uf.size(0) == n) return puts("No") & 0;
  puts("Yes");
}

