		int l = query(i+1,N-1,0,0,N-1);
		//cout << "swap " << i << " " << l << endl;
		int s = elem[l].f;
		elem[l].f = elem[i].f;
		update(0,N-1,0,l);
		elem[i].f = s;
		update(0,N-1,0,i);
	}

	cout << ((swaps <= N-2) ? "Yes" : "No") << endl;
	return 0;
}

