void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, n);

    V<t2> ailist;
    rep (i, n) ailist.pb(t2(alist[i], i));
    V<t2> bilist;
    rep (i, n) bilist.pb(t2(blist[i], i));

    sort(ailist);
    sort(bilist);

    rep (i, n) {
        ll a = get<0>(ailist[i]);
        ll b = get<0>(bilist[i]);
        if (a > b) {
            cout << "No" << endl;
            return;
        }
    }

    UnionFind uf(n+1);
    rep (i, n) {
        ll ai = get<1>(ailist[i]);
        ll bi = get<1>(bilist[i]);
        uf.unite(ai, bi);
    }

    set<ll> roots;
    rep (i, n) {
        roots.insert(uf.root(i));
    }

    if (roots.size() == 2LL) cout << "Yes" << endl;
    else cout << "No" << endl;
}

