using namespace std;
typedef pair<int, int> P;

const int N_MAX = 1e5;
int n;
P p[N_MAX];
priority_queue<P> q, r;
set<P> s;
int loc[N_MAX];

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i].second);
    for (int i = 0; i < n; i++) scanf("%d", &p[i].first);
    sort(p, p + n);
    for (int i = 0; i < n; i++) {
        int j = lower_bound(p, p + n, p[i].second, [](const P &p1, const int &i1)->bool {
            return p1.first < i1;
        }) - p;
        q.emplace(j, i);
        r.emplace(i, j);
        loc[i] = j;
    }

    int cnt = n - 2;
    while (!q.empty()) {
        P p1 = q.top(); q.pop();
        if (loc[p1.second] != p1.first) continue;
        while (!r.empty() && r.top().first >= p1.first) {
            s.emplace(r.top().second, r.top().first);
            r.pop();
        }

        if (p1.first <= p1.second) continue;
        set<P>::iterator it = s.upper_bound(P(p1.second, -1));
        if (it == s.begin()) {
            if (s.empty() || it->first >= p1.first) {
                printf("No\n");
                return 0;
            }
        }
        else it = prev(it);
        q.emplace(it->first, p1.second);
        r.emplace(p1.second, it->first);
        loc[p1.second] = it->first;
        s.erase(it);
        if (cnt-- == 0) {
            printf("No\n");
            return 0;
        }
    }
    printf("Yes\n");
    return 0;
}

