//Range Minimum Query
struct segment {
    int n;
    vector<int64_t> dat;
    // n_は範囲
    segment(int n_) { // nはn_以上の2^?
        n = 1<<(32-__builtin_clz(n_));
        if(n == 2*n_) n >>= 1;
        dat.assign(2*n-1, INT64_MAX);
    }
    //更新の手順
    int64_t theorem(int i) {
        int64_t chld = dat[i*2+1];
        int64_t chrd = dat[i*2+2];
        return min(chld, chrd);
    }
    //初期化(初期状態はINT64_MAX)
    void init(vector<int64_t> &vec) {
        int num = vec.size();
        rep(i, num) {
            dat[i+n-1] = vec[i];
        }
        rep(i, n-1) {
            dat[n-2-i] = theorem(n-2-i);
        }
    }
    // k番目の値をaに変更
    void update(int k, int64_t a) {
        // 葉の節点
        k += n-1;
        dat[k] = a;
        // 登りながら更新
        while(k>0) {
            k = (k-1)/2;
            dat[k] = theorem(k);
        }
    }
    // [a, b)の最小値
    int64_t query(int a, int b) {
        assert(a<b);
        return query_(a, b, 0, 0, n);
    }
    //kは節点の番号, [l, r)に節点が対応
    // (a, b, 0, 0, .n)で呼ぶ
    int64_t query_(int a, int b, int k, int l, int r) {
        if(a>=r || l>=b) return INT64_MAX;
        if(a<=l && r<=b) return dat[k];
        else {
            int chl = k*2+1;
            int chr = k*2+2;
            int64_t vl = query_(a, b, chl, l, (l+r)/2);
            int64_t vr = query_(a, b, chr, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

int main() {
    int n;
    cin >> n;
    vector<P> ba(n);
    rep(i, n) {
        int a;
        cin >> a;
        ba[i].second = a;
    }
    rep(i, n) {
        int b;
        cin >> b;
        ba[i].first = b;
    }
    sort(all(ba));

    map<int, vi> mp;
    rep(i, n) {
        mp[ba[i].second].push_back(i);
    }

    segment seg(n);
    vector<ll> aaa(n);
    rep(i, n) {
        aaa[i] = ba[i].second;
    }
    seg.init(aaa);

    /*rep(i, n) {
        cout << ba[i].first << ' ' << ba[i].second << endl;
    }*/

    int cou = 0;
    rep(i, n) {
        if(ba[i].second > ba[i].first) {
            cou++;
            auto itr = lower_bound(all(ba), P(ba[i].second, 0));
            if(itr == ba.end()) {
                cou = n;
                break;
            }
            int num = itr-ba.begin();
            int smm = seg.query(num, n);
            //cout << i << endl;
            if(smm <= ba[i].first) {
                int yy = *(mp[smm].end()-1);
                seg.update(yy, ba[i].second);
                ba[yy].second = ba[i].second;
                mp[ba[i].second].push_back(yy);
                mp[smm].pop_back();
            } else {
                smm = seg.query(i+1, n);
                if(smm > ba[i].first) {
                    cou = n;
                    break;
                } else {
                    int yy = *(mp[smm].end()-1);
                    seg.update(yy, ba[i].second);
                    ba[yy].second = ba[i].second;
                    mp[ba[i].second].push_back(yy);
                    mp[smm].pop_back();
                }
            }
        }
    }
    cout << (cou <= n-2 ? "Yes":"No") << endl;
}

