		else return b < o.b;
	}
};

int search(std::pair<int, int>*p, int t, int n) {
	if (p[0].first == t)return 0;
	int r = 0;
	for (int i = 30; i >= 0; i--) {
		int c = r | (1 << i);
		if (c >= n)continue;
		if (p[c].first == t)return c;
		if (p[c].first < t)r = c;
	}
	return -1;
}
bool Main() {

	int N;
	scanf("%d", &N);
	int*A = new int[N];
	int*B = new int[N];
	D*d = new D[N];
	std::pair<int, int>*p = new std::pair<int, int>[N];
	for (int i = 0; i < N; i++) {
		scanf("%d", A + i);
		d[i].a = A[i];
	}
	for (int i = 0; i < N; i++) {
		scanf("%d", B + i);
		d[i].b = B[i];
	}
	std::sort(d, d + N);
	for (int i = 0; i < N; i++) {
		p[i].first = d[i].a;
		p[i].second = i;
	}
	std::sort(p, p + N);
	for (int i = 0; i < N; i++) {
		if (d[i].b < p[i].first) {
			return false;
		}
	}
	int change = 0;
	for (int i = 0; i < N; i++) {
		if (p[i].second != i) {
			int c = search(p, d[i].a, N);
			int temp = p[i].second;
			p[i].second = p[c].second;
			p[c].second = temp;
			change++;
		}
	}
	if (change < N - 1) {
		return true;
	}
	for (int i = 0; i < N - 1; i++) {
		if (p[i + 1].first <= d[i].b)return true;
	}
	return false;
}

