            if (simb == n)
            {
                cout << "Yes\n";
                return 0;
            }
        }
        if (j > i)
        {
            int simb = 1 + get(1, 0, i - 1) + get(2, i + 1, j) + get(1, j + 1, n - 1);
            if (simb == n)
            {
                cout << "Yes\n";
                return 0;
            }
        }
    }
    cout << "No\n";
