bool hasCycle = false;

void search(int curr, int &n, vector<vector<int>> &v, vector<bool> &visited, int count) {
    if (hasCycle) return;
    visited[curr] = true;
    for (auto &to: v[curr]) {
        if (visited[to]) {
            if (count != n) hasCycle = true;
            return;
        }
        search(to, n, v, visited, count+1);
    }
}

