bool good(vector<pair<int, int>>& A, vector<pair<int, int>>& B) {
    int N = A.size();
    for (int i=0;i<N;i++) {
        if (A[i].first > B[i].first) return false;
    }
    return true;
}

bool scary(vector<pair<int, int>>& A, vector<pair<int, int>>& B) {
    int N = A.size();
    for (int i=1;i<N;i++) {
        if (A[i].first <= B[i-1].first) return false;
    }
    return true;
}

bool is_cycle(vector<int>& perm) {
    int N = perm.size();
    int start = 0;
    for (int i=0;i<N-1;i++) {
        start = perm[start];
        if (start == 0) {
            return false;
        }
    }
    return true;
}

