    for(int i=0;i<N;i++) cin >> B[i];

    vector<pair<int, int>> Asort;
    vector<pair<int, int>> Bsort;

    for(int i=0;i<N;i++) {
        Asort.push_back(make_pair(A[i], i));
        Bsort.push_back(make_pair(B[i], i));
    }

    sort(Asort.begin(), Asort.end());
    sort(Bsort.begin(), Bsort.end());

    if (!good(Asort, Bsort)) {
       // cout << "not good" << endl;
        cout << "No" << endl;
    } else if (!scary(Asort, Bsort)) {
       // cout << "not scary" << endl;
        cout << "Yes" << endl;
    } else {
        vi perm(N);
        for (int i=0;i<N;i++) {
            perm[Asort[i].second] = Bsort[i].second;
        }
        if (is_cycle(perm)) {
         //   cout << "scary and cycle" << endl;
            cout << "No" << endl;
        } else {
           // cout << "scary and no cycle" << endl;
            cout << "Yes" << endl;
        }
    }

    return 0;
}

