class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  bool ans = 0;
  Int N;
  vi A, B;
  Solver() {}
  void input() {
    cin >> N;
    A = B = vi(N);
    FOR(a, A)cin >> a;
    FOR(b, B)cin >> b;
  }
  void solve() {
    ans = false;
    vector<pii> V;
    rep(i, N)V.push_back({B[i], A[i]});
    sort(V);
    priority_queue<pii> OK;
    set<pii> OK2;
    rep(i, N){
      Int a = V[i].second;
      Int b = V[i].first;
      if( a <= b){
        OK.push({-a, i});
      }
    }

    int cnt = 0;
    rep(i, N){
      Int a = V[i].second;
      Int b = V[i].first;
      if(a <= b)continue;
      while(!OK.empty()){
        if(OK.top().second > i){
          break;
        }
        OK.pop();
      }
      while(!OK.empty()){
        Int oki = OK.top().second;
        Int oka = V[oki].second;
        Int okb = V[oki].first;
        if(oka <=b ){
          OK2.insert({-okb, oki});
        }else{
          break;
        }
      }
      if(OK2.empty()){
        pp(i);
        return;
      }
      auto it = OK2.lower_bound({-a, -1});
      vector<pii> toE;
      while(it != OK2.end()){
        if(it->second > i)break;
        toE.push_back(*it);
        it++;
        pp(i);
      }
      if(it == OK2.end()){
        pp(i);
        return;
      }
      Int oki = it->second;
      Int oka = V[oki].second;
      Int okb = V[oki].first;
      pp(oka);
      pp(a);
      OK2.erase(it);
      FOR(e, toE)OK2.erase(e);
      cnt++;
      oka = a;
      V[oki].second = oka;
      assert( oka <= okb);
      continue;
    }
    pp(cnt);
    ans = (cnt <= N-2);
  }
  void output() {
    cout << ans <<endl;
  }
};

