struct ss {
    ll a, b;
};
bool cmp(const ss &x, const ss &y) {
    if (x.b != y.b)
        return x.b < y.b;
    else
        return x.a < y.a;
}

bool rs(vector<ss> s, int n) {
    sort(s.begin(), s.end(), cmp);
    int d = n - 2;
    for (int i = 0; i < n && d >= 0; i++) {
        if (s[i].a > s[i].b) {
            ll m = -1;
            int pos = -1;
            for (int j = i + 1; j < n && d >= 0; j++) {
                if (s[j].b >= s[j].a && s[j].a > m && s[j].a <= s[i].b) {
                    m = s[j].a;
                    pos = j;
                }
            }
            if (m == -1)
                return false;
            swap(s[pos].a, s[i].a);
        }
    }
    return d >= 0;
}

