//Union Find Tree
class UnionFindTree {
public:
	vector<int> parent;
    vector<int> rank;

    UnionFindTree(int N) : parent(N), rank(N,0){
		for (int i = 0; i < N; ++i) parent[i] = i;
	}

	int root(int n) {
		return (parent[n] == n ? n : parent[n] = root(parent[n]));
	}

    int same(int n, int m) {
		return root(n) == root(m);
	}

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(rank[n]<rank[m]) {
            parent[n] = m;
        }
        else{
            parent[m] = n;
            if(rank[n] == rank[m]) rank[n]++;
        }
	}
};

int main() {
	int N; cin >> N;
	vector<ll> A(N),B(N);
	for(int i = 0; i < N; ++i) cin >> A[i];
	for(int i = 0; i < N; ++i) cin >> B[i];
	auto C = A,D = B;
	sort(ALL(C));
	sort(ALL(D));
	for(int i = 0; i < N; ++i) corner(C[i]>D[i],"No");
	vector<pair<ll,int>> Ap(N),Bp(N);
	for(int i = 0; i < N; ++i) Ap[i] = {A[i],i};
	for(int i = 0; i < N; ++i) Bp[i] = {B[i],i};
	sort(ALL(Ap));
	sort(ALL(Bp));
	vector<pair<int,int>> edge(N);
	for(int i = 0; i < N; ++i) edge[Ap[i].second].first = i;
	for(int i = 0; i < N; ++i) edge[Bp[i].second].second = i;
	UnionFindTree uf(N);
	for(int i = 0; i < N; ++i) {
		int l = edge[i].first,r = edge[i].second;
		uf.unite(l,r);
	}
	vector<int> cnt(N,0);
	for(int i = 0; i < N; ++i) {
		cnt[uf.root(i)]++;
	}
	int ans = 0;
	for(int i = 0; i < N; ++i) {
		if(cnt[i]) ans += cnt[i]-1;
	}
	Yn(ans<=N-2);

}

