int binary_search2(vector<int> &l,int key){
  int left=0;
  int right=l.size()-1;
  int mid;
  if(l[right]<key)return right;
  else{
  while(right-left>1){
    mid=(right+left)/2;
    if(l[mid]>=key)right=mid;
  else left=mid;
  }
  }
  if(key==l[left])right=left;
return right;
}
