bool solve() {
    ll N;
    cin >> N;
    V<ll> A(N), B(N);
    for(ll &e : A) cin >> e;
    for(ll &e : B) cin >> e;
    {
        V<PLL> bi;
        for(ll i = 0; i < N; i++) bi.emplace_back(B[i], i);
        sort(ALL(bi));
        V<ll> cpy(N);
        for(ll i = 0; i < N; i++) {
            ll f, s;
            tie(f, s) = bi[i];
            cpy[i] = A[s];
            B[i] = f;
        }
        A = move(cpy);
    }
    auto sa = A;
    sort(ALL(sa));
    for(ll i = 0; i < N; i++) if(!(sa[i] <= B[i])) return false;
    for(ll i = 0; i < N - 1; i++) {
        ll a1 = sa[i], a2 = sa[i + 1];
        ll b1 = B[i], b2 = B[i + 1];
        if(a1 <= b2 && a2 <= b1) return true;
    }
    map<ll, ll> idx;
    for(ll i = 0; i < N; i++) {
        ll e = A[i];
        auto ite = lower_bound(ALL(sa), e);
        idx[e] = ite - sa.begin();
    }

    ll rest = N - 2;
    for(ll i = 0; i < N; i++) {
        if(idx[sa[i]] == i) return true;
        ll swap_i = idx[sa[i]];
        swap(A[i], A[swap_i]);
        idx[A[i]] = i;
        idx[A[swap_i]] = swap_i;
        rest--;
    }

    return 0 <= rest;
}

