int minSwaps (ve< pii > a, int n) {
	int ans = 0;
	fr (i, 0, n) {
		if (a[i].ss != i) {
			int count = 0;
			while (a[i].ss != i) {
				if (a[i].ff != a[a[i].ss].ff) {
					count++;
				}
				swap (a[i], a[a[i].ss]);
			}
			ans += count;
		}
	}
	return ans;
}

