    flg |= (A2[i+1] <= B2[i]);
  }
  if(flg){
    yn(true); return;
  }

  iota(ALL(idx), 0LL);
  sort(ALL(idx), [&](ll l,ll r){
    return B[l] < B[r];
  });
  B = B2;
  rep(i,N) A2[i] = A[idx[i]];
  A = A2;
