template<class T>
class Compress {
private:
    vector<T> data;

public:
    Compress(const vector<T> &vec) : data(vec) {
        sort(data.begin(), data.end());
        data.erase(unique(data.begin(), data.end()), data.end());
    }

    T get(int k) {
        assert(k >= 0 && k < data.size());
        return data[k];
    }

    typename vector<T>::iterator lower_bound(const T &t) {
        return ::lower_bound(data.begin(), data.end(), t);
    }

    typename vector<T>::iterator upper_bound(const T &t) {
        return ::upper_bound(data.begin(), data.end(), t);
    }

    int lb_index(const T &t) {
        return lower_bound(t) - data.begin();
    }

    int ub_index(const T &t) {
        return upper_bound(t) - data.begin();
    }

    size_t size() {
        return data.size();
    }
};


class UnionFind {
    std::vector<int> p;

public:
    UnionFind(int n) : p(n, -1) {}

    int root(int x) { return p[x] < 0 ? x : p[x] = root(p[x]); }

    bool same(int x, int y) { return root(x) == root(y); }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (p[y] < p[x]) std::swap(x, y);
        if (p[x] == p[y]) --p[x];
        p[y] = x;
        return true;
    }
};

bool solve(long long N, std::vector<long long> A, std::vector<long long> B) {

    if (!firstCheck(A, B)) {
        return false;
    }
    if (secondCheck(A, B)) {
        return true;
    }
    if (thirdCheck(A, B)) {
        return true;
    }
    UnionFind uf(N);
    Compress<ll> cmp1(A);
    Compress<ll> cmp2(B);

    for (int i = 0; i < N; i++) {
        int x = cmp1.lb_index(A[i]);
        int y = cmp2.lb_index(B[i]);
        uf.unite(x, y);
    }
    int cnt = 0;
    for(int i = 0 ; i < N ; i++)
        cnt += uf.root(i) == i;

    return cnt >= 2;
}
