	sort(input, input + n);
	for (int i = 0; i < n; ++i) {
		tie(b[i], a[i]) = input[i];
	}

	int ind = -1;
	for (int i = 0; i < n; ++i) {
		if (a[i] > b[i]) {
			continue;
		}
		if (ind == -1 || b[ind] > b[i]) {
			ind = i;
		}
	}

	if (!cansort()) {
		if (ind == -1) {
			cout << "No\n";
			return 0;
		}
		a.erase(a.begin() + ind);
		b.erase(b.begin() + ind);
		--n;
	}

	sort(all(a));
	assert(is_sorted(all(b)));

	for (int i = 0; i < n; ++i) {
		if (a[i] > b[i]) {
			cout << "No\n";
			return 0;
		}
	}
	cout << "Yes\n";

	return 0;
}

