void solve_zenkoku2_c() {
	ll N;
	cin >> N;

	ll ta, tb;
	rep(i, N) {
		cin >> ta;
		A.push_back(make_pair(ta, i));
		S.push_back(ta);
	}
	rep(i, N) {
		cin >> tb;
		B.push_back(make_pair(tb, i));
		T.push_back(tb);
	}

	sort(ALL(A));
	sort(ALL(B));
	sort(ALL(S));
	sort(ALL(T));

	bool ans = true;
	rep(i, N) {
		if (A[i].first > B[i].first) {
			ans = false;
			break;
		}
	}

	if (!ans) {
		cout << "No" << "\n";
		return;
	}

	ll cnt = 0;
	rep(i, N) {
		if (B[i].first < A[B[i].second].first) {
			auto itr = lower_bound(ALL(S), B[i].first);
			ll pos = (ll)(itr - 1 - S.begin());
			if (pos < 0) {
				cout << "No" << "\n";
				return;
			}
			swap(B[i].second, pos);
			cnt++;
		}
	}

	if (cnt <= N - 2) {
		cout << "Yes" << "\n";
	}
	else {
		cout << "No" << "\n";
	}

}

