map<int,int> ai,bi;
signed main(){
	int n;
	cin>>n;
	vector<int> a,b;
	for(int i=0;i<n;i++){
		int x;
		cin>>x;
		a.pb(x);
	}
	for(int i=0;i<n;i++){
		int x;
		cin>>x;
		b.pb(x);
	}
	vector<int> sa,sb;
	sa = a;
	sb = b;
	sort( sa.begin(), sa.end() );
	sort( sb.begin(), sb.end() );
	for(int i=0;i<n;i++){
		ai[ sa[i] ] = i;
	}
	for(int i=n-1;i>=0;i--){
		bi[ sb[i] ] = i;
	}
	for(int i=0;i<n;i++){
		if( sa[i] > sb[i] ){
			cout<<"No"<<endl;
			return 0;
		}
		if( i!=n-1 && sa[i+1] <= sb[i] ){
			isok[i] = 1;
		}
	}
	for(int i=1;i<=n;i++){
		sum[i] = sum[i-1] + isok[i-1];
	}
	for(int i=0;i<n;i++){
		if( a[i] <= b[i] ){
			int aid = ai[ a[i] ];
			int bid = bi[ b[i] ];
			int goodness = sum[bid] - sum[aid];
			if( bid <= aid ){
				cout<<"Yes"<<endl;
				return 0;
			}
			else if( goodness == bid - aid ){
				cout<<"Yes"<<endl;
				return 0;
			}
		}
	}
	vector< pair<int,int> > P;
	for(int i=0;i<n;i++){
		P.pb( mp( b[i], a[i] ) );
	}
	sort( P.begin(), P.end() );
	pair<int, int> arrPos[n]; 
    for (int i = 0; i < n; i++) 
    { 
        arrPos[i].first = P[i].second; 
        arrPos[i].second = i; 
    } 

    // Sort the array by array element values to 
    // get right position of every element as second 
    // element of pair. 
    sort(arrPos, arrPos + n); 

    // To keep track of visited elements. Initialize 
    // all elements as not visited or false. 
    vector<bool> vis(n, false); 

    // Initialize result 
    int ans = 0; 

    // Traverse array elements 
    for (int i = 0; i < n; i++) 
    { 
        // already swapped and corrected or 
        // already present at correct pos 
        if (vis[i] || arrPos[i].second == i) 
            continue; 

        // find out the number of  node in 
        // this cycle and add in ans 
        int cycle_size = 0; 
        int j = i; 
        while (!vis[j]) 
        { 
            vis[j] = 1; 

            // move to next node 
            j = arrPos[j].second; 
            cycle_size++; 
        } 

        // Update answer by adding current cycle.  
        if (cycle_size > 0) 
        { 
            ans += (cycle_size - 1); 
        } 
    }
	if( ans == n-1 ){
		cout<<"No"<<endl;
		return 0;
	}
	else{
		cout<<"Yes"<<endl;
		return 0;
	}
	return 0;
}

