void bld1(int l,int r,int i){
	if(l==r){
		sgt1[i]=(a[l]<=b[l-1]);
		return ;
	}
	int mid=(l+r)/2;
	bld1(l,mid,2*i+1);
	bld1(mid+1,r,2*i+2);
	sgt1[i]=sgt1[2*i+1]&sgt1[2*i+2];
}

void bld2(int l,int r,int i){
	if(l==r){
		sgt2[i]=(a[l]<=b[l+1]);
		return ;
	}
	int mid=(l+r)/2;
	bld2(l,mid,2*i+1);
	bld2(mid+1,r,2*i+2);
	sgt2[i]=sgt2[2*i+1]&sgt2[2*i+2];
}

bool query1(int l,int r,int a,int b,int i){
	if(l>r||l>b||r<a) return 1;
	if( l>=a&&r<=b )return sgt1[i];
	int mid=(l+r)/2;
	return query1(l,mid,a,b,2*i+1)&query1(mid+1,r,a,b,2*i+2);
}

bool query2(int l,int r,int a,int b,int i){
	if(l>r||l>b||r<a) return 1;
	if( l>=a&&r<=b )return sgt2[i];
	int mid=(l+r)/2;
	return query2(l,mid,a,b,2*i+1)&query2(mid+1,r,a,b,2*i+2);
}

