int pow(int x, int y){
  if(y == 1)return x;
  int ret;
  if(y % 2 == 0){
    ret = pow(x, y/2);
    return ret*ret % mod;
  }else{
    ret = pow(x, y/2);
    return ret*ret % mod * x % mod;
  }
}
