bool solve(int N, vector<int> A, vector<int> B){
  if(*max_element(ALL(B)) < *max_element(ALL(A))) return false;

  {
    auto a = A;
    auto b = B;

    sort(ALL(a));
    sort(ALL(b));

    REP(i,N){
      if(a[i] > b[i]) return false;
    }
  }

  multiset<pair<int,int>> m1; // a > b
  multiset<pair<int,int>> m2; // a <= b


  REP(i,N){
    if(A[i] > B[i]) m1.insert(make_pair(A[i], B[i]));
    else m2.insert(make_pair(-A[i], B[i]));
  }


  REP(i,N-2){
    if(m1.empty()) break;

    auto p = *m1.begin();
    m1.erase(m1.begin());

    int a, b;
    tie(a, b) = p;


    auto it = m2.lower_bound(make_pair(-b, a));

    if(it == m2.end()) return false;

    int a2, b2;
    tie(a2, b2) = *it;

    m2.erase(it);

    m2.insert(make_pair(a2, b));
    m2.insert(make_pair(a, b2));
  }

  if(m1.size()) return false;

  return true;
}



