/**
* @brief 遅延セグメント木
* @docs docs/datastructure/segmenttree/lazysegmenttree.md
*/

template <typename M, typename OM, typename F, typename G, typename H, typename P>
struct LazySegmentTree {
    int sz;
    F f; G g; H h; P p;
    const M ID_M;
    const OM ID_OM;
    vector<M> dat;
    vector<OM> laz;
    LazySegmentTree(int n, M ID_M, OM ID_OM, F f, G g, H h, P p)
        : ID_M(ID_M), ID_OM(ID_OM), f(f), g(g), h(h), p(p) { build(n); }
    LazySegmentTree(const vector<M> &v, M ID_M, OM ID_OM, F f, G g, H h, P p)
        : ID_M(ID_M), ID_OM(ID_OM), f(f), g(g), h(h), p(p) {
        int n = v.size();
        build(n);
        for (int i = 0; i < n; ++i) dat[i + sz - 1] = v[i];
        for (int i = sz - 2; i >= 0; --i) dat[i] = f(dat[2 * i + 1], dat[2 * i + 2]);
    }
    void build(int n) {
        sz = 1; while (sz < n) sz <<= 1;
        dat.assign(2 * sz - 1, ID_M);
        laz.assign(2 * sz - 1, ID_OM);
    }
    void eval(int len, int k) {
        if (laz[k] == ID_OM) return;
        if (2 * k + 1 < 2 * sz - 1) {
            laz[2 * k + 1] = h(laz[2 * k + 1], laz[k]);
            laz[2 * k + 2] = h(laz[2 * k + 2], laz[k]);
        }
        dat[k] = g(dat[k], p(laz[k], len));
        laz[k] = ID_OM;
    }
    M update(int a, int b, OM x, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a or b <= l) return dat[k];
        if (a <= l and r <= b) {
            laz[k] = h(laz[k], x);
            return g(dat[k], p(laz[k], r - l));
        }
        return dat[k] = f(update(a, b, x, 2 * k + 1, l, (l + r) / 2),
                          update(a, b, x, 2 * k + 2, (l + r) / 2, r));
    }
    M update(int a, int b, OM x) {
        return update(a, b, x, 0, 0, sz);
    }
    M query(int a, int b, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a or b <= l) return ID_M;
        if (a <= l and r <= b) return dat[k];
        M vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        M vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
    M query(int a, int b) {
        return query(a, b, 0, 0, sz);
    }
    M operator[](const int &k) {
        return query(k, k + 1);
    }
    void print() {
        for (int i = 0; i < sz; ++i) cerr << query(i, i + 1) << ' ';
        cerr << endl;
    }
};

template<typename M, typename OM, typename F, typename G, typename H, typename P>
auto make_segtree(int n, M ID_M, OM ID_OM, F f, G g, H h, P p) {
    return LazySegmentTree<M, OM, F, G, H, P>(n, ID_M, ID_OM, f, g, h, p);
}
template<typename M, typename OM, typename F, typename G, typename H, typename P>
auto make_segtree(vector<M> v, M ID_M, OM ID_OM, F f, G g, H h, P p) {
    return LazySegmentTree<M, OM, F, G, H, P>(v, ID_M, ID_OM, f, g, h, p);
}


/*
 * AとBを混ぜて一列に並べる 同じ数はAの方が先
 * > 入力例3
 *      A : 3 1 2 6 3 4
 *      B : 2 2 8 3 4 3
 *   ~> C : 1A 2A 2B 2B 3A 3A 3B 3B 4A 4B 6A 8B
 * 各ペアをこの配列内のindexで表す
 *   ~> 同じもの(上の例だと3Aとか)は別に同じindexで良さそう
 * Cから数字を取り除いて考える
 *   ~> C : A A B B A A B B A B A B
 * 上のペアのものを取り除いたとき, ABが正当な括弧列かを判定すればよい
 *    > A -> (
 *    > B -> )
 * 雑に遅延セグ木で判定出来そう
 *  @ 区間add
 *  @ 区間min
 */

signed main() {

    SS(int, N);
    SV(int, A, N);
    SV(int, B, N);

    // [num, A or B]
    vector<pair<int, char>> C;
    REP(i, N) C.emplace_back(A[i], 'A');
    REP(i, N) C.emplace_back(B[i], 'B');
    SORT(C);

    vector<int> C_acc;
    if (C.front().second == 'A') C_acc.emplace_back(1);
    else                         C_acc.emplace_back(-1);
    REP(i, 1, 2 * N) {
        if (C[i].second == 'A') {
            C_acc.emplace_back(C_acc.back() + 1);
        } else {
            C_acc.emplace_back(C_acc.back() - 1);
        }
    }

    map<pair<int, char>, int> rev;
    REP(i, 2 * N) rev[C[i]] = i;

    // indices
    vector<pair<int, int>> pairs;
    REP(i, N) {
        pair<int, char> a(A[i], 'A');
        pair<int, char> b(B[i], 'B');
        pairs.emplace_back(rev[a], rev[b]);
    }

    // 区間add, 区間min
    auto f = [](int a, int b) -> int { return min(a, b); };
    auto g = [](int a, int b) -> int { return a + b; };
    auto p = [](int a, int b) -> int { return a; };
    auto seg = make_segtree(C_acc, int(1e9), int(0), f, g, g, p);

    REP(i, N) {
        auto [a, b] = pairs[i];
        seg.update(a, 2 * N, 1);
        seg.update(b, 2 * N, -1);
        if (seg.query(0, 2 * N) >= 0) {
            return print("Yes");
        }
        seg.update(a, 2 * N, -1);
        seg.update(b, 2 * N, 1);
    }

    print("No");

}

