template <class Type>
Type solve(Type res = Type()) {
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (auto& in : A) cin >> in;
    for (auto& in : B) cin >> in;

    vector<pii> tA(N),tB(N);
    for(int i = 0; i < N;i++){
        tA[i] = make_pair(A[i],i);
        tB[i] = make_pair(B[i],i);
    }

    sort(tA.begin(), tA.end());
    sort(tB.begin(), tB.end());

    for (int i = 0; i < N; i++) {
        if (tA[i].first > tB[i].first) return "No";
    }

    vector<int> pos(N);
    for(int i = 0; i < N-1;i++){
        if(tA[i+1].first > tB[i].first){
            return "No";
        }
        pos[tA[i].second] = tB[i].second;
    }
    pos[tA[N-1].second] = tB[N-1].second;
    return "Yes";
    int now = 0;
    int T = 1;
    while(pos[now]){
        now = pos[now];
        T++;
    }
    if(T == N){
        return "No";
    }else{
        return "Yes";
    }
    return res;
}
