bool f() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];
    vector<int> idx(n);
    iota(begin(idx), end(idx), 0);
    sort(begin(idx), end(idx), [&](int i, int j) {
        return b[i] < b[j];
    });
    vector<int> old_a = a, old_b = b;
    for (int i = 0; i < n; ++i) {
        a[i] = old_a[idx[i]];
        b[i] = old_b[idx[i]];
    }
    for (int i = 0; i < n; ++i) cerr << idx[i] << ' ';
    cerr << endl;
    for (int i = 0; i < n; ++i) cerr << a[i] << ' ';
    cerr << endl;
    for (int i = 0; i < n; ++i) cerr << b[i] << ' ';
    cerr << endl;
    vector<int> sorted_a = a;
    sort(begin(sorted_a), end(sorted_a));
    for (int i = 0; i < n; ++i) {
        if (sorted_a[i] > b[i]) {
            cerr << "sorted_a[i] > b[i]" << endl;
            return false;
        }
    }
    for (int i = 0; i < n - 1; ++i) {
        if (sorted_a[i + 1] <= b[i]) {
            cerr << "sorted_a[i + 1] <= b[i]" << endl;
            return true;
        }

    }
    map<int, int> mp;
    for (int x : sorted_a) {
        mp[x] = mp.size();
    }
    assert(mp.size() == n);
    vector<bool> vis(n);
    for (int i = 0, cnt = 0; cnt < n; ++cnt) {
        cerr << i << '\n';
        if (vis[i]) {
            cerr << "not single cycle" << endl;
            return true;
        }
        vis[i] = true;
        i = mp[a[i]];
    }
    cerr << "single cycle" << endl;
    return false;
}
int main() {
    cout << (f() ? "Yes" : "No") << endl;
    return 0;
}

