  auto a0 = a;
  auto b0 = b;
  sort(all(a));
  sort(all(b));
  rep (i, n) {
    if (a[i] > b[i]) {
      ng();
    }
  }
  vi limit(n, 0);
  rep (i, n) {
    int idx = lower_bound(all(b), a[i]) - begin(b);
    limit[i] = idx;
  }
  vi okl(n);
  rep (i, n) {
    okl[i] = i - limit[i];
  }
  auto segt = SegTree<Monoid>(okl);
  rep (i, n) {
    if (a0[i] > b0[i]) {
      continue;
    }
    int left = upper_bound(all(a), a0[i]) - 1 - begin(a);
    int right = lower_bound(all(b), b0[i]) - begin(b);
    if (left >= right) {
      ok();
    }
    if (segt.accumulate(left + 1, right + 1) > 0) {
      ok();
    }
  }
  ng();

  return 0;
