  {
    cin >> v;
    b.push_back(v);
  }
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());

  // N-2 の制限を考えずに自由に並び替えたばあい
  for (int i = 0; i < n; ++i)
  {
    if (a[i].v > b[i])
    {
      // No が確定
      cout << "No" << endl;
      return 0;
    }
  }

  // サイクル数が1じゃないかどうか調べる
