bool solve()
{
    if (N == 2)
    {
        REP(i, N)
        {
            if (A[i] > B[i])
                return false;
        }
        return true;
    }
    map<ll, ll> map;
    REP(i, N)
    {
        map[A[i]]++;
    }
    sort(C, C + N, [](pll a, pll b) { return a.first < b.first; });
    sort(D, D + N, [](pll a, pll b) { return a.first < b.first; });
    REP(i, N)
    {
        if (C[i].first > D[i].first)
            return false;
    }

    memset(U, 0, sizeof(U));
    REP(i, N - 1)
    {
        if (C[i + 1].first > D[i].first)
            U[i + 1]++;

        U[i + 1] += U[i];
    }

    REP(i, N)
    {
        if (A[i] > B[i])
            continue;

        ll ru = N - 1, rl = -1;
        while (abs(ru - rl) > 1)
        {
            ll mid = (ru + rl) / 2;
            if (D[mid].first >= B[i])
