int main(int argc, char* argv[]) {
  init_io(argc, argv);

  int N;
  cin >> N;
  vector<PII> tmp(N);
  REP(i, N) cin >> tmp[i].SS;
  REP(i, N) cin >> tmp[i].FF;

  {
    SORT(tmp);
    VI xs(N), ys(N);
    REP(i, N) {
      xs[i] = tmp[i].SS;
      ys[i] = tmp[i].FF;
    }

    VI low(N);
    REP(i, N) {
      auto it = lower_bound(ALL(ys), xs[i]);
      low[i] = it - begin(ys);
    }

    bool ok = true;
    VI ord = low;
    SORT(ord);
    for (int i = N - 1; i >= 0; --i) {
      if (i < ord[i]) {
        ok = false;
      }
    }

    if (ok) {
      int n = 0;
      REP(i, N) {
        if (low[i] <= i) ++n;
      }
      ok = (n >= 3);
    }

    cout << (ok ? "Yes" : "No") << endl;
  }

  return 0;
}

