int read(){int sss=0,fff=1;char ccc=getchar();while(ccc<'0'||ccc>'9'){if(ccc=='-') fff=-1;ccc=getchar();}while(ccc>='0'&&ccc<='9'){sss=sss*10+ccc-'0';ccc=getchar();}return sss*fff;}
bool cmp(node x,node y)
{
	return x.val<y.val;
}
void solve()
{
	n=read();
	for(int i=1;i<=n;i++) a[i].val=read(),a[i].id=i;sort(a+1,a+1+n,cmp);
	for(int i=1;i<=n;i++) b[i].val=read(),b[i].id=i;sort(b+1,b+1+n,cmp);
	for(int i=1;i<=n;i++)
		if(a[i].val>b[i].val)
		{
			printf("No\n");
			return;
		}
	for(int i=1;i<=n;i++) A[a[i].id]=i;
	for(int i=1;i<=n;i++) B[b[i].id]=i;
	for(int i=1;i<=n;i++)
	{
		int IDA=A[i],IDB=B[i];
		if(IDA>=IDB)
		{
			printf("Yes\n");
			return;
		}
		if(IDA<IDB)
		{
			bool flag=false;
			for(int j=IDA+1;j<=IDB;j++)
				if(A[j]>B[j-1])
				{
					flag=true;
					break;
				}
			if(!flag)
			{
				printf("Yes\n");
				return;
			}
		}
	}
	printf("No\n");
}
