int power(int x, int y, int p = 998244353LL){
    int res = 1;
    x = x % p;

    while (y > 0){
        if (y & 1)  res = (res*x) % p;

        y = y>>1;
        x = (x*x) % p;
    }
    return res;
}

int modInverse(int n, int p = 998244353LL){
    return power(n, p-2, p);
}

