struct UnionFind
{
  using node_t = size_t;
  vector <node_t> parent;
  explicit UnionFind (node_t n) : parent (n) { iota (begin (parent), end (parent), node_t {}); }
  auto root (node_t x) noexcept -> node_t { return parent [x] == x ? x : parent [x] = root (parent [x]); }
  auto merge (node_t x, node_t y) noexcept { x = root (x); y = root (y); if (x != y) parent [y] = x; }
};

auto main () -> int
{
  cin.tie (nullptr);
  ios::sync_with_stdio (false);

  size_t n;
  cin >> n;
  vector <ll> a (n), b (n);
  vector <pair <ll, size_t>> awi, bwi;
  rep (i, n)
  {
    cin >> a [i];
    awi.emplace_back (a [i], i);
  }
  rep (i, n)
  {
    cin >> b [i];
    bwi.emplace_back (b [i], i);
  }
  auto sorted_a = a;
  auto sorted_b = b;
  sort (ALL (sorted_a));
  sort (ALL (sorted_b));
  auto ans = true;
  rep (i, n)
  {
    if (not (sorted_a [i] <= sorted_b [i]))
    {
      ans = false;
      goto finish;
    }
  }
  {
    sort (ALL (awi));
    sort (ALL (bwi));
    UnionFind uf (n);
    rep (i, n)
    {
      auto x = bwi [i].second;
      auto y = awi [i].second;
      if (x == y) continue;
      uf.merge (x, y);
    }
    set <size_t> s;
    rep (i, n)
    {
      s.insert (uf.root (i));
    }
    auto cnt = n - s.size ();
    ans = cnt <= n - 2;
  }
finish:
  cout << (ans ? "Yes" : "No") << endl;
}

