const int limit = 100010;

int ok[limit], ok2[limit];
int apos[limit], bpos[limit];

int main(void){
	int n;
	cin >> n;
	vector<int> a(n), b(n);
	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];

	using pii = pair<int, int>;

	vector<pii> aary;
	rep(i, n) aary.push_back(pii(a[i], i));
	sort(begin(aary), end(aary));

	vector<pii> bary;
	rep(i, n) bary.push_back(pii(b[i], i));
	sort(begin(bary), end(bary));

	rep(i, n){
		apos[aary[i].second] = i;
		bpos[bary[i].second] = i;
	}

	rep(i, n){
		if(i - 1 >= 0) ok[i] += ok[i - 1];
		ok[i] += (aary[i].first <= bary[i].first);

		if(i - 1 >= 0) {
			ok2[i] += ok2[i - 1];
			ok2[i] += (aary[i].first <= bary[i - 1].first);
		}
	}

	bool ans = false;
	rep(i, n){
		if(a[i] > b[i]) continue;

		int cnt = 0;
		// [0, apos)
		if(apos[i] - 1 >= 0) cnt += ok[apos[i] - 1];

		// (apos, bpos]
		cnt += ok2[bpos[i]] - ok2[apos[i]];

		// [bpos + 1, n - 1]
		cnt += ok[n - 1] - ok[bpos[i]];

		if(cnt >= n - 1) ans = true;
	}

	puts(ans ? "Yes" : "No");
	return 0;
}

