using namespace std;
using ll = int64_t;

int main() {
    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (ll i = 0; i < N; i++) {
        cin >> B[i];
    }

    vector<pair<ll, ll>> pBA(N);
    for (ll i = 0; i < N; i++) {
        pBA[i].first = B[i];
        pBA[i].second = A[i];
    }
    sort(pBA.begin(), pBA.end());

    for (ll i = 0; i < N; i++) {
        A[i] = pBA[i].second;
        B[i] = pBA[i].first;
    }

    vector<pair<ll, ll>> pA(N);
    for (ll i = 0; i < N; i++) {
        pA[i].first = A[i];
        pA[i].second = i;
    }
    sort(pA.begin(), pA.end(), greater<>());

    vector<ll> Aindex2pAindex(N);
    for (ll i = 0; i < N; i++) {
        Aindex2pAindex[pA[i].second] = i;
    }

    ll op_num = 0;
    ll next_swap_pos = N - 1;
    vector<bool> fixed(N, false);
    for (ll i = 0; i < N; i++) {
        //すでに条件を満たしているならスルー
        if (pA[i].first <= B[pA[i].second]) {
            fixed[pA[i].second] = true;
            while (next_swap_pos >= 0 && fixed[next_swap_pos]) {
                next_swap_pos--;
            }
            continue;
        }

        //そうでなければ置き換え
        pA[Aindex2pAindex[next_swap_pos]].second = pA[i].second;
        pA[i].second = next_swap_pos;
        Aindex2pAindex[pA[i].second] = Aindex2pAindex[next_swap_pos];
        Aindex2pAindex[next_swap_pos] = i;
        fixed[pA[i].second] = true;
        op_num++;
        while (next_swap_pos >= 0 && fixed[next_swap_pos]) {
            next_swap_pos--;
        }

        //置き換えてもダメならダメ
        if (pA[i].first > B[pA[i].second]) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << (op_num <= N - 2 ? "Yes" : "No") << endl;
}

