struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

bool solve(const vector<ll>& A, const vector<ll>& B) {
  int N = A.size();
  vector<int> a_id(N), b_id(N);
  iota(a_id.begin(), a_id.end(), 0);
  iota(b_id.begin(), b_id.end(), 0);
  sort(a_id.begin(), a_id.end(), [&](int a, int b) {
    if (A[a] != A[b]) return A[a] < A[b];
    return a < b;
  });
  sort(b_id.begin(), b_id.end(), [&](int a, int b) {
    if (B[a] != B[b]) return B[a] < B[b];
    return a < b;
  });
  for (int i = 0; i < N; i++) {
    if (A[a_id[i]] > B[b_id[i]]) return false;
  }
  UnionFind uf(N);
  for (int i = 0; i < N; i++) uf.unite(a_id[i], b_id[i]);
  set<int> S;
  for (int i = 0; i < N; i++) S.insert(uf.root(i));
  return (S.size() > 1);
  if (S.size() > 1) return true;
  for (int i = 0; i + 1 < N; i++) {
    int a1 = a_id[i], a2 = a_id[i + 1];
    int b1 = b_id[i], b2 = b_id[i + 1];
    if (A[a2] <= B[b1] && A[a1] <= B[b2]) {
      return true;
    }
  }
  return false;
}

