	ll n;
	cin >> n;
	ll a[n], b[n];
	P pa[n], pb[n];
	zep(i, 0, n){cin >> a[i]; pa[i] = P(a[i], i);}
	zep(i, 0, n){cin >> b[i]; pb[i] = P(b[i], i);}

	bool ans = true;
	ll cnt = 0;
	zep(i, 0, n){
