void Nikkei2C()
{
	int N;
	cin >> N;
	vector<int> A(N), B(N);
	for (auto& x : A)
	{
		cin >> x;
	}
	for (auto& x : B)
	{
		cin >> x;
	}
	multimap<int, int> AB;
	for (int i = 0; i < N; ++i)
	{
		AB.insert({ B[i], A[i] });
	}
	int i = 0;
	int ct = 0;
	for (auto& x : AB)
	{
		B[i] = x.first;
		A[i++] = x.second;
		if (x.first >= x.second)
		{
			++ct;
		}
	}
	if (ct == 0)
	{
		cout << "No" << endl;
		return;
	}
	multimap<int, int> Ai;
	for (int i = 0; i < N; ++i)
	{
		Ai.insert({ A[i], i });
	}
	vector<int> C(N);
	vector<int> oldIdx(N);
	i = 0;
	for (auto& x : Ai)
	{
		oldIdx[i] = x.second;
		C[i++] = x.first;
	}
	vector<int> flag(N);
	for (int i = 0; i < N; ++i)
	{
		if (C[i] > B[i])
		{
            throw "Bad";
			cout << "No" << endl;
			return;
		}
		if(i< N-1)
			flag[i + 1] = flag[i] + (A[i + 1] > B[i] ? 0 : 1);
	}
	for (int i = 0; i < N; ++i)
	{
		int j = oldIdx[i];
		if (A[j] > B[j])
			continue;
		if (j <= i)
		{
			cout << "Yes" << endl;
			return;
		}
		int x = flag[j] - flag[i];
		if (x == j - i)
		{
			cout << "Yes" << endl;
			return;
		}
	}
	cout << "No" << endl;
}
