template<typename T>
class SegmentTree {
private:
    using F = function<T(T, T)>; // モノイド型
    int n; // 横幅
    F f;   // モノイド
    T e;   // モノイド単位元
    vector<T> data;

public:
    // init忘れに注意
    SegmentTree() {}
    SegmentTree(F f, T e) :f(f), e(e) {}
    void init(int n_) {
        n = 1;
        while (n < n_)n <<= 1;
        data.assign(n << 1, e);
    }
    void build(const vector<T>& v) {
        int n_ = v.size();
        init(n_);
        rep(i, n_)data[n + i] = v[i];
        for (int i = n - 1; i >= 0; i--) {
            data[i] = f(data[(i << 1) | 0], data[(i << 1) | 1]);
        }
    }
    void set_val(int idx, T val) {
        idx += n;
        data[idx] = val;
        while (idx >>= 1) {
            data[idx] = f(data[(idx << 1) | 0], data[(idx << 1) | 1]);
        }
    }
    T query(int a, int b) {
        // [a,b)
        T vl = e, vr = e;
        for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if (l & 1)vl = f(vl, data[l++]); // unknown
            if (r & 1)vr = f(data[--r], vr); // unknown
        }
        return f(vl, vr);
    }
};

int main()
{
    int N;
    cin >> N;
    vector<pair<int, int>> ba;
    {
        vector<int> a(N), b(N);
        rep(i, N)cin >> a[i];
        rep(i, N)cin >> b[i];
        rep(i, N) {
            ba.push_back({ b[i],a[i] });
        }
    }
    sort(ba.begin(), ba.end());
    auto f = [](pii a, pii b) {return max(a, b); };
    SegmentTree<pii> st(f, { -1,-1 });
    {
        vector<pair<int, int>> a;
        rep(i, N) {
            a.push_back({ ba[i].second,i });
        }
        st.build(a);
    }

    bool ignore = false;
    rep(i, N - 2 + (ignore ? 1 : 0)) {
        int r = N - 1 - i;
        auto maxv = st.query(r, r + 1);
        auto minv = st.query(0, r);
        if (minv.first > maxv.first) {
            int pl = minv.second;
            int pr = maxv.second;
            swap(ba[pl].second, ba[pr].second);

            pii vl = { maxv.first,pl };
            pii vr = { minv.first,pr };
            st.set_val(pl, vl);
            st.set_val(pr, vr);
        }
        else {
            ignore = true;
        }
    }
    rep(i, N) {
        if (ba[i].first < ba[i].second) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
    return 0;
}

