struct UnionFind{
    vector<int> par;
    UnionFind(int n) : par(n){
      for(int i=0;i<n;i++) par[i]=i;
    }
    int root(int x){
      if(par[x]==x) return x;
      return par[x]=root(par[x]);
    }

    void unite(int x,int y){
      int rx=root(x);
      int ry=root(y);
      if(rx==ry) return;
      par[rx]=ry;
    }
    bool same(int x, int y){
      int rx=root(x);
      int ry=root(y);
      if(rx==ry) return 1;
      return 0;
    }
  };
bool compare_by_second(pair<int, int> a,pair<int, int> b){
  if(a.second != b.second){
   return a.second < b.second;
  }
  else{
    return a.first < b.first;
  }
}
int binary_search2(vector<int> &l,int key){
  int left=0;
  int right=l.size()-1;
  int mid;
  if(l[right]<key)return right;
  else{
  while(right-left>1){
    mid=(right+left)/2;
    if(l[mid]>=key)right=mid;
  else left=mid;
  }
  }
  if(key==l[left])right=left;
return right;
}
void swap(vector<int>& a,int i,int j){
  int tmp=a[i];
  a[i]=a[j];
  a[j]=tmp;
}
bool judge(vector<int> a,vector<pair<int,int>> array){
  bool k=false;
  bool tag=false;
  rep(i,n){
    int buf=binary_search2(a,array[i].first);
    swap(a,i,buf);
    if(a[i]<array[i].second&&a[buf]<array[buf].second){
      return true;
    }
    else swap(a,i,buf);
  }
  return k;
}
