bool solve() {
    int N; cin >> N;
    vector<int> A(N);
    rep(i, N) cin >> A[i];
    vector<int> B(N);
    rep(i, N) cin >> B[i];
    vector<P> pairs;
    int dif = 0;
    rep(i, N) {
        if(A[i] > B[i]) {
            pairs.emplace_back(A[i], B[i]);
            ++dif;
        }
    }
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    sort(pairs.begin(), pairs.end());
    rep(i, N) {
        if(A[i] > B[i]) {
            return false;
        }
    }
    int cnt = 0;
    rep(i, N - 1) if(pairs[i].second > pairs[i + 1].second) {
        ++cnt;
    }
    return !(dif == N - 1 && cnt == 1);
}

