struct UnionFind{
private:
    int comp;
    vector<int> par, rank;
public:
    inline UnionFind(){}
    inline UnionFind(int sz){ init(sz); }
    inline void init(int sz){
        comp = sz;
        par.resize(sz, -1);
        rank.resize(sz, 0);
    }
    inline int find(int x){
        if(par[x] < 0)return x;
        else return par[x] = find(par[x]);
    }
    inline int size(int x){
        return -par[find(x)];
    }
    inline int size(){
        return int(par.size());
    }
    inline int component(){
        return comp;
    }
    inline bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y)return false;
        if(rank[x] < rank[y])swap(x, y);
        if(rank[x] == rank[y])rank[x]++;
        par[x] += par[y];
        par[y] = x;
        comp--;
        return true;
    }
    inline bool same(int x, int y){
        return find(x) == find(y);
    }
};

