namespace Cesare {

	/*
		根据 b 排序，使 a 也有序的最少交换次数。 
		n - 2 次交换是否能使序列有序。

		3 1 6 4 3 2
		2 2 3 3 4 8

		1 2 3 3 4 6 
	*/

	ll n;

	struct Node {
		ll a, b, id;
	} K[N];

	struct xzy {
		ll x, id;
	} A[N];

	inline bool cmp (Node a, Node b) {
		return a.b == b.b? a.a < b.a: a.b < b.b;
	}

	inline bool Cmp (xzy a, xzy b) {
		return a.x < b.x; 
	}

	#define int long long

	vector <int> v;

	inline int Cycle(ll res = 0) {
		map <ll, ll> mp;
		For ( i, 1, n ) mp[A[i].id] = K[i].id;
		for (ll x = mp[1]; x != 1; x = mp[x]) ++res;
		return res + 1 == n;
	}

	signed main() {
		n = read();
		For ( i, 1, n ) K[i].a = read();
		For ( i, 1, n ) K[i].b = read();
		For ( i, 1, n ) A[i].x = K[i].a, K[i].id = A[i].id = i;
		sort(A + 1, A + n + 1, Cmp);
		sort(K + 1, K + n + 1, cmp);

		For ( i, 1, n ) if (A[i].x > K[i].b) return puts("No"), 0;
		For ( i, 2, n ) if (A[i].x <= K[i - 1].b) return puts("Yes"), 0;
		return puts(!Cycle()? "Yes": "No"), 0;
	} // 至少有一个位置的交换一次就换对两个地方。 

}

