using P = pair<int,int>;

class Union_Find{
  vector<int> par; vector<int> rank; vector<int> num;
public:
  Union_Find(int n) {
    par = vector<int>(n); rank = vector<int>(n,0); num = vector<int>(n,1);
    rep(i,n) par[i] = i;
  }
  int find(int x) {
    if(par[x] == x) return x;
    else  return par[x] = find(par[x]);
  }
  int number(int x) {
    return num[find(x)];
  }
  void unite(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) swap(x, y);
    if (rank[x] == rank[y]) rank[x]++;
    par[y] = x;
    num[x] += num[y];
  } 
  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

int main(){
  int n;
  cin >> n;
  P p[n];
  rep(i,n) cin >> p[i].first;
  rep(i,n) cin >> p[i].second;
  sort(p,p+n);
  int a[n], b[n];
  rep(i,n) a[i] = p[i].first, b[i] = p[i].second;
  P c[n];
  rep(i,n) c[i] = P(b[i],i);
  sort(c,c+n);
  rep(i,n) {
    if(c[i].first < a[i]) {
      cout << "No" << endl;
      return 0;
    }
  }
  Union_Find uf(n);
  rep(i,n) uf.unite(i,c[i].second);
  int cnt = 0;
  rep(i,n) if(uf.find(i) == i) cnt++;
  if(cnt >= 2) {
    cout << "Yes" << endl;
    return 0;
  } 
  rep(i,n-1) {
    if(c[i].first >= a[i+1]) {
      cout << "Yes" << endl;
      return 0;
    }
  }
  cout << "No" << endl;
  return 0;
}

