using namespace std;

bool solve(vector<int> &a, vector<int> &b) {
  int n = a.size();

  vector<int> oa(n);
  iota(oa.begin(), oa.end(), 0);
  sort(oa.begin(), oa.end(), [&](int i, int j) { return a[i] < a[j]; });

  vector<int> ob(n);
  iota(ob.begin(), ob.end(), 0);
  sort(ob.begin(), ob.end(), [&](int i, int j) { return b[i] < b[j]; });

  for (int i = 0; i < n; i++) {
    if (a[oa[i]] > b[ob[i]]) {
      return false;
    }
  }

  vector<int> p(n);
  for (int i = 0; i < n; i++) {
    p[oa[i]] = ob[i];
  }

  { // cycle
    int cnt = 0, now = 0;
    vector<bool> was(n);
    while (!was[now]) {
      cnt++;
      was[now] = true;
      now = p[now];
    }
    if (cnt < n) return true;
  }

  for (int i = 0; i < n - 1; i++) {
    if (a[oa[i]] <= b[ob[i + 1]]) {
      return true;
    }
  }

  return false;
}

int main() {
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> b[i];
  }

  cout << (solve(a, b) ? "Yes" : "No") << '\n';
  return 0;
}

