int main(int argc, char const *argv[]) {
  ll n;std::cin >> n;
  std::vector<ll> b(n);
  vvl a = vv(n, 2, 0, ll);
  for(int i=0;i<n;i++){
    std::cin >> a[i][0];
    a[i][1] = i;
  }
  for(int i=0;i<n;i++)std::cin >> b[i];
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for(int i=0;i<n;i++){
    if(a[i][0]>b[i]){
      std::cout << "No" << '\n';
      return 0;
    }
  }

  for(int i=0;i<n;i++){
    add_edge(a[i][1], i);
    add_edge(i, a[i][1]);
  }
  scc(n+1);
  set<int> num;
  for(int i=0;i<n;i++) num.insert(cmp[i]);
  //std::cout << num.size() << '\n';
  if(num.size()>=2){
    std::cout << "Yes" << '\n';
    return 0;
  }
  for(int i=0;i<n-1;i++) {
    if(a[i+1][0]<=b[i]){
      std::cout << "Yes" << '\n';
      return 0;
    }
  }
  std::cout << "No" << '\n';
  return 0;
}

