struct node {
    int s, e, m, v;
    node *l, *r;
    node(int _s, int _e): s(_s), e(_e), m((_s+_e)/2), v(0) {
        if (s != e) {
            l = new node(s, m);
            r = new node(m+1, e);
        }
    }

    void up(int i, int x) {
        if (s == e) { v = x; return; }
        if (i <= m) l->up(i,x);
        else r->up(i,x);
        v = min(l->v,r->v);
    }

    int qmin(int x, int y) {
        if (s == x && e == y) return v;
        else if (y <= m) return l->qmin(x,y);
        else if (x >  m) return r->qmin(x,y);
        else return min(l->qmin(x,m), r->qmin(m+1,y));
    }
} *root;

