    vector<int> AS = A, BS = B;
    sort(AS.begin(), AS.end());
    sort(BS.begin(), BS.end());
    map<int, int> AB, BI;
    UnionFind UF(N);
    for (int i = 0; i < N; ++i) {
        if (BS[i] < AS[i]) {
            puts("No");
            return 0;
        }
        AB[AS[i]] = BS[i];
        BI[BS[i]] = i;
    }
    for (int i = 0; i < N; ++i) {
        UF.connect(i, BI[AB[A[i]]]);
    }
    for (int i = 1; i < N; ++i) {
        if (BS[i-1] >= AS[i]) {
            puts("Yes");
            return 0;
        }
        if (UF.root(i) != UF.root(i-1)) {
            puts("Yes");
            return 0;
        }
    }
    puts("No");
    return 0;
}

