int N, A[101010], B[101010];
//---------------------------------------------------------------------------------------------------
#define yes "Yes"
#define no "No"
pair<int, int> AA[101010], BB[101010];
int rev_a[101010], rev_b[101010];
BIT<int> bit_right(101010);
BIT<int> bit_left(101010);
int mi_a[101010], ma_a[101010];
int mi_b[101010], ma_b[101010];
string solve() {
	rep(i, 0, N) AA[i] = { A[i], i };
	sort(AA, AA + N);
	rep(i, 0, N) BB[i] = { B[i], i };
	sort(BB, BB + N);

	rep(i, 0, N) if (AA[i].first > BB[i].first) return no;

	rep(i, 0, N) rev_a[AA[i].second] = i;
	rep(i, 0, N) rev_b[BB[i].second] = i;

	rep(i, 0, N - 1) if (AA[i].first > BB[i + 1].first) bit_right.add(i, 1);
	rep(i, 0, N - 1) if (AA[i + 1].first > BB[i].first) bit_left.add(i, 1);

	UnionFind uf_a(N), uf_b(N);
	rep(i, 0, N - 1) if (AA[i].first == AA[i + 1].first) uf_a(i, i + 1);
	rep(i, 0, N - 1) if (BB[i].first == BB[i + 1].first) uf_b(i, i + 1);

	rep(i, 0, N) mi_a[i] = mi_b[i] = inf;
	rep(i, 0, N) ma_a[i] = ma_b[i] = -inf;

	rep(i, 0, N) {
		chmin(mi_b[uf_b[i]], i);
		chmin(mi_a[uf_a[i]], i);
		chmax(ma_a[uf_a[i]], i);
		chmax(ma_b[uf_b[i]], i);
	}

	rep(i, 0, N) if (A[i] <= B[i]) {
		// 他をソートして条件を満たせばOK

		int ra = rev_a[i];
		int rb = rev_b[i];

		int LA = mi_a[uf_a[ra]];
		int LB = mi_b[uf_b[rb]];
		int RA = ma_a[uf_a[ra]];
		int RB = ma_b[uf_b[rb]];

		if (RA < LB) {
			ra = RA;
			rb = LB;
			int sm = bit_left.get(ra, rb);
			if (sm == 0) return yes;
		}
		else if (RB < LA) {
			ra = LA;
			rb = RB;
			int sm = bit_right.get(rb, ra);
			if (sm == 0) return yes;
		}
		else return yes;
	}

	return no;
}
//---------------------------------------------------------------------------------------------------
void _main() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	rep(i, 0, N) cin >> B[i];
	cout << solve() << endl;
}

