    REP (i, N) {
        a.push_back(A[i]);
        b.push_back(B[i]);
    }

    sort(ALL(a));
    sort(ALL(b));

    REP (i, N) {
        if (a[i] > b[i]) return false;
    }
    return true;
}

bool solve() {
    if (!check_number_set()) return false;
    vii nums;
    REP (i, N) {
        nums.push_back(make_pair(B[i], A[i]));
    }
    sort(ALL(nums));

    REP (i, N-1) {
        if (A[i] <= B[i]) return true;
    }
    return false;
}

