	for(int i = 1;i < n;++i)if(sa[i] <= sb[i-1])rout("Yes");
	for(int i = 0;i < n;++i)a[i] = lower_bound(sa.begin(), sa.end(), a[i]) - sa.begin();

	vector<bool> vis(n);	
	int cnt = 0;
	for(int i = 0;i < n;++i){
		if(!vis[i]){
			++cnt;
			while(a[i] != i)vis[a[i]] = true, swap(a[i], a[a[i]]);
		}
	}
	rout(cnt != 1 ? "Yes" : "No");
}

