    iota(oa.begin(), oa.end(), 0);
    iota(ob.begin(), ob.end(), 0);

    sort(oa.begin(), oa.end(), [&](int i, int j){
        return a[i] < a[j];
    });

    sort(ob.begin(), ob.end(), [&](int i, int j) {
        return b[i] < b[i];
    });

