                } 

                if (fb != i) {
                    flb = !(a[fb] > b[i] || a[i] > b[fb]);
                }

                if (fla || flb) cnt++;
            }
        }
    }

    if (cnt == n) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
    }

    return 0;
