int dfs(int u, UnWeightedGraph& g, vector<bool>& used){
    int cnt = 0;
    used[u] = true;
    for(auto nv: g[u]){
        if(used[nv]) return 0;
        cnt += 1 + dfs(nv, g, used);
    }
    return cnt;
}

