ll N;
pll S[100005];

bool solve()
{
    sort(S, S + N, [](pll a, pll b) { return a.second == b.second ? a.first < b.first : a.second < b.second; });
    ll num = 0;
    ll index = 0;
    REP(i, N)
    {
        index = i + 1;
        if (S[i].first <= S[i].second)
            continue;
        num++;
        while (index < N)
        {
            if (S[index].first <= S[i].second)
            {
                swap(S[index].first, S[i].first);
                break;
            }
            index++;
        }
        if (index >= N)
            return false;
    }
    return num <= N - 2;
}
