	vector<P> pa(n);
	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];
	rep(i, n) pa[i] = P(a[i], b[i]);

	sort(pa.begin(), pa.end());
	rep(i, n) { a[i] = pa[i].first; b[i] = pa[i].second; }

	vector<P> bpos(n);
	rep(i, n) {
		bpos[i] = P(b[i], i);
	}
	sort(bpos.begin(), bpos.end());

	//小さい方から対応づけた場合のチェック. (N - 1回でできるか？)
	rep(i, n) {
		if (a[i] > b[bpos[i].second]) {
			cout << "No" << endl;
			return 0;
		}
	}

	int pos = 0, cnt = 0;
	do {
		cnt++;
		pos = bpos[pos].second;
	} while (pos != 0);

	//既に2つ以上のサイクルになっている
	if (cnt < n) {
		cout << "Yes" << endl;
		return 0;
	}

	//入れ替えチェック
	for (i = 0; i + 1 < n; i++) {
		if (a[i + 1] <= b[bpos[i].second]) {
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;
	return 0;
}

