bool solve(){
	int n;
	scanf("%d", &n);
	vector<pii> ps(n);
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].second); }
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].first); }
	sort(ALL(ps));
	vector<int> as(n), bs(n);
	for(int i = 0; i < n; ++i){
		as[i] = ps[i].second;
		bs[i] = ps[i].first;
	}

	if(!check1(as, bs)){ return false; }

	vector<int> ls(n);
	for(int i = 0; i < n; ++i){
		ls[i] = upper_bound(ALL(bs), as[i]) - bs.begin();
		if(ls[i] >= n){ return false; }
	}

	vector<int> pos(n);
	iota(ALL(pos), 0);
	vector<int> inv = pos;
	VV(int) grps(n);
	int nxt = 0;
	for(int i = 0; i < n; ++i){ grps[ls[i]].push_back(i); }
	for(int i = 0; i < n; ++i){
		auto grp = grps[i];
		for(int x : grp){
			if(pos[x] <= i){ return true; }
		}
		sort(ALL(grp), [&](int x, int y){ return pos[x] < pos[y]; });
		for(int x : grp){
			int z = inv[nxt];
			swap(pos[x], pos[z]);
			inv[pos[x]] = x;
			inv[pos[z]] = z;
			++nxt;
		}
	}

	return false;
}

