}

inline void push_up(int k)
{
	if(tree[k].l==tree[k].r)
		return;
	if(a[tree[k<<1].mx]<a[tree[k<<1|1].mx])
		tree[k].mx=tree[k<<1].mx;
	else
		tree[k].mx=tree[k<<1|1].mx;
}

inline void build(int k,int l,int r)
{
	tree[k].l=l;tree[k].r=r;
	if(l==r)
	{
		tree[k].mx=l;
		return;
	}
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	push_up(k);
}

inline void prework()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
		scanf("%d",&t[i].x);
	for(int i=1;i<=n;i++)
		scanf("%d",&t[i].y);
	sort(t+1,t+1+n,cmp);
	for(int i=1;i<=n;i++)
		a[i]=t[i].x,b[i]=t[i].y;
	build(1,1,n);
}

inline void upd(int k,int l)
{
	if(tree[k].l==tree[k].r)
	{
		tree[k].mx=l;
		return;
	}
	int mid=(tree[k].l+tree[k].r)>>1;
	if(l<=mid)
		upd(k<<1,l);
	else
		upd(k<<1|1,l);
	push_up(k);
}

inline int qry(int k,int l,int r)
{
	int ret,ret2;
	if(tree[k].l==l && tree[k].r==r)
		return tree[k].mx;
	int mid=(tree[k].l+tree[k].r)>>1;
	if(r<=mid)
		ret=qry(k<<1,l,r);
	else if(l>mid)
		ret=qry(k<<1|1,l,r);
	else
	{
		ret=qry(k<<1,l,mid);
		ret2=qry(k<<1|1,mid+1,r);
		if(a[ret]>a[ret2])
			ret=ret2;
	}
	push_up(k);
	return ret;
}

inline void mainwork()
{
	int cnt=0,id,l;ans=0;
	for(int i=1;i<=n;i++)
	if(a[i]>b[i])
	{
		l=lower_bound(b+1,b+1+n,a[i])-b;
		if(l>n)
			return;
		id=qry(1,l,n);
		if(a[id]>b[i])
			return; 
		swap(a[id],a[i]);
		upd(1,i);upd(1,id);
		cnt++;
	}
	if(cnt<=n-2)
		ans=1;
}

inline void print()
{
	if(ans)
		puts("Yes");
	else
		puts("No");
}

int main()
{
	int t=1;
	//scanf("%d",&t);
	for(int i=1;i<=t;i++)
	{
		prework();
		mainwork();
		print();
	}
	return 0;
}

