template<typename T, size_t MAX_N>
class BIT
{
	public:
		BIT(size_t n) : _bit(), _n(n) {}

		T sum(size_t i)
		{
			T r = 0;
			while (i > 0)
			{
				r += _bit[i];
				i &= (i - 1);
			}
			return r;
		}

		void add(size_t i, T x)
		{
			while (i <= _n)
			{
				_bit[i] += x;
				i += i & -i;
			}
		}

	protected:
		T _bit[MAX_N + 1];
		size_t _n;
};

