bool check_1(vector<int> A, vector<int> B) {
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    int N = A.size(), ok = true;
    for(int i=0; i<N; i++) {
        ok &= (A[i] <= B[i]);
    }
    return ok;
}

void modify_1(vector<int> &A, vector<int> &B) {
    vector< pair<int, int> > seg;
    int N = A.size();
    for(int i=0; i<N; i++) {
        seg.emplace_back(B[i], A[i]);
    }
    sort(seg.begin(), seg.end());

    // B 昇順に
    for(int i=0; i<N; i++) {
        int x, y; tie(y, x) = seg[i];
        A[i] = x, B[i] = y;
    }
}

pair< vector<int>, vector<int> > extract_1(vector<int> A) {
    int N = A.size();
    vector<int> B = A;
    sort(B.begin(), B.end());

    // ソート後の A と異なる場所を抽出
    int ptr = 0;
    vector< pair<int, int> > X;
    vector<int> Y;
    for(int i=0; i<N; i++) {
        // if(A[i] == B[i]) continue;
        X.emplace_back(A[i], ptr++);
        Y.emplace_back(A[i]);
    }
    sort(X.begin(), X.end());

    N = X.size();
    vector<int> P(N);
    // k 番目にあるものは、i 番目に行きたい
    for(int i=0; i<N; i++) {
        int k = X[i].second;
        P[k] = i;
    }
    return make_pair(P, Y);
}

