const int nmax = 1e9 + 7;
const long long INF = 1e18;
const double PI = 2 * asin(1);
typedef long long ll;


int main(){
  int N; cin >> N;
  vector <int> A(N), B(N);

  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < N; i++) cin >> B[i];

  bool flag = true;

  vector < pair<int, int> > AP(N), BP(N);
  for (int i = 0; i < N; i++){
    AP[i] = make_pair(A[i], i);
    BP[i] = make_pair(B[i], i);
  }
  sort(AP.begin(), AP.end());
  sort(BP.begin(), BP.end());

  for (int i = 0; i < N; i++){
    if (AP[i].first > BP[i].first){
      flag = false;
    }
  }

  if (flag == true){
    flag = false;
    for (int i = 0; i < N; i++){
      int now = 0;
      while (BP[i].first >= AP[i + now].first && i + now < N){
        now++;
      }

      vector <int> A2(now), B2(now);
      for (int j = 0; j < now; j++){
        A2[j] = AP[i + j].second;
        B2[j] = BP[i + j].second;
      }
      sort(A2.begin(), A2.end());
      sort(B2.begin(), B2.end());

      int a = 0, b = 0;
      while (a < now && b < now){
        if (A2[a] == B2[b]){
          flag = true; break;
        }else{
          if (A2[a] < B2[b]) a++;
          else b++;
        }
      }

      if (flag == true){
        break;
      }else{
        i = i + now - 1;
      }
    }

  }

  if (flag == true) cout << "Yes" << endl;
  else cout << "No" << endl;

  return 0;
}

