bool Solve() {
  int n;
  cin >> n;
  vector<int> as(n);
  vector<int> bs(n);
  for (int i = 0; i < n; i++) {
    cin >> as[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> bs[i];
  }

  vector<int> as_sorted(as.begin(), as.end());
  vector<int> bs_sorted(bs.begin(), bs.end());
  sort(as_sorted.begin(), as_sorted.end());
  sort(bs_sorted.begin(), bs_sorted.end());

  for (int i = 0; i < n; i++) {
    if (as_sorted[i] > bs_sorted[i]) return false;
  }

  for (int i = 0; i + 1 < n; i++) {
    if (as_sorted[i + 1] <= bs_sorted[i]) return true;
  }

  vector<Item> items;
  for (int i = 0; i < n; i++) {
    items.push_back(Item({i, as[i], bs[i]}));
  }
  sort(items.begin(), items.end(), [](Item item1, Item item2) { return item1.b < item2.b; });

  vector<pair<int, int>> pairs;
  for (const auto& item : items) {
    pairs.push_back(make_pair(item.a, item.index));
  }
  sort(pairs.begin(), pairs.end());

  vector<int> visited(n);
  int current = 0;
  int cycle_count = 0;
  while (true) {
    if (visited[current]) break;
    visited[current] = 1;
    current = pairs[current].second;
    cycle_count++;
  }
  // cout << "cycle_count: " << cycle_count << endl;
  return cycle_count < n;
}

