	inline bool operator ()(int x,int y)const{return tmp[x].a>tmp[y].a;}
};
priority_queue<int,vector<int>,cmp> Q;
void build(int o,int L,int R){
	if(L==R)sum[o]=val[L];
	else{
		int lc=o<<1,rc=lc|1,M=L+R>>1;
		build(lc,L,M);build(rc,M+1,R);
		sum[o]=sum[lc]&&sum[rc];
	}
}
bool ask(int o,int L,int R){
	if(x<=L&&y>=R)return sum[o];
	else{
		int lc=o<<1,rc=lc|1,M=L+R>>1;
		bool ans=1;
		if(x<=M)ans=ans&&ask(lc,L,M);
		if(y>M)ans=ans&&ask(rc,M+1,R);
		return ans;
	}
}
