		for(x=Q.top(),Q.pop();x<=i;x=Q.top(),Q.pop());
		if(tmp[i].a<=tmp[x].a)return 1;
		swap(tmp[i].a,tmp[x].a);
		Q.push(x);
	}
	return 0;
}
