	sort(ba.begin(), ba.end());
	for(int i = 0; i < n; ++i){ a[i] = ba[i].second; }
	for(int i = 0; i < n; ++i){ b[i] = ba[i].first; }
	auto c = a;
	sort(c.begin(), c.end());
	bool possible = true;
	for(int i = 0; i < n; ++i){
		if(c[i] > b[i]){ possible = false; }
	}
