			const auto ub = upper_bound(c.begin(), c.end(), a[i]) - c.begin();
			v = st.query(lb, ub);
		}
		if(v <= b[i]){
			possible = true;
			break;
		}
		st.update(i, v);
	}
	cout << (possible ? "Yes" : "No") << endl;
	return 0;
}

