#define yes "Yes"
#define no "No"
pair<int,int> AA[101010], BB[101010];
int rev_a[101010], rev_b[101010];
BIT<int> bit_right(101010);
BIT<int> bit_left(101010);
string solve() {
	rep(i, 0, N) AA[i] = { A[i], i };
	sort(AA, AA + N);
	rep(i, 0, N) BB[i] = { B[i], i };
	sort(BB, BB + N);

	rep(i, 0, N) if (AA[i].first > BB[i].first) return no;

	rep(i, 0, N) rev_a[AA[i].second] = i;
	rep(i, 0, N) rev_b[BB[i].second] = i;

	rep(i, 0, N - 1) if (AA[i].first <= BB[i + 1].first) bit_right.add(i, 1);
	rep(i, 0, N - 1) if (AA[i + 1].first <= BB[i].first) bit_left.add(i, 1);

	rep(i, 0, N) if (A[i] <= B[i]) {
		// 他をソートして条件を満たせばOK

		int ra = rev_a[i];
		int rb = rev_b[i];

		if (ra == rb) return yes;
		if (ra < rb) {
			int sm = bit_left.get(ra, rb);
			if (sm == rb - ra) return yes;
		}
		else {
			int sm = bit_right.get(rb, ra);
			if (sm == ra - rb) return yes;
		}
	}

	return no;
}
