// v1をソートし、v2を対応する位置に移動する
template<typename T, typename U>
void pairSort(vector<T>& v1, vector<U>& v2, bool rev = false) {
    int n = v1.size();
    vector<pair<T, U>> p(n);
    for(int i = 0; i < n; i++) {
        p[i] = pair<T, U>(v1[i], v2[i]);
    }
    if(rev) {
        sort(p.begin(), p.end(), [&](const auto& l, const auto& r) {
            if(l.first == r.first)
                return l.second > r.second;
            else return l.first < r.first;
        });
    } else {
        sort(p.begin(), p.end());
    }
    for(int i = 0; i < n; i++) {
        v1[i] = p[i].first;
        v2[i] = p[i].second;
    }
}

// ソートでどこに移動するかを得る
// 配列自体はソートされない
// {9, 5, 1, 3, 3} -> {4, 3, 0, 1, 2}
template<typename T>
vector<int> indexSort(const vector<T>& vec) {
    int n = vec.size();
    vector<pair<T, int>> p(n);
    for(int i = 0; i < n; i++) {
        p[i] = pair<T, int>(vec[i], i);
    }
    sort(p.begin(), p.end());
    vector<int> ret(n);
    for(int i = 0; i < n; i++) {
        ret[i] = lower_bound(p.begin(), p.end(), pair<T, int>(vec[i], i)) - p.begin();
    }
    return ret;
}

