using namespace std;

struct UnionFindTree{
  vector<int> parent;

  UnionFindTree(int n) : parent(n){
    for(int i = 0; i < n; i++) parent[i] = i;
  }

  int find(int x){
    if(parent[x] == x) return x;
    else return parent[x] = find(parent[x]);
  }

  void unite(int x, int y){
    parent[find(x)] = find(y);
  }
};

int main(){
  int N;
  cin >> N;

  vector<pair<int, int>> A(N);
  vector<int> B(N);

  for(int i = 0; i < N; i++){
    int a;
    cin >> a;
    A[i] = make_pair(a, i);
  }

  for(int i = 0; i < N; i++){
    int b;
    cin >> b;
    B[i] = b;
  }

  sort(A.begin(), A.end());
  sort(B.begin(), B.end());

  bool able = true;
  for(int i = 0; i < N; i++){
    if(A[i].first > B[i]){
      able = false;
      break;
    }
  }

  UnionFindTree permutation(N);
  for(int i = 0; i < N; i++){
    permutation.unite(A[i].second, i);
  }

  set<int> cnt;
  for(int i = 0; i < N; i++){
    cnt.insert(permutation.find(i));
  }

  if(able && (int)cnt.size() == 1){
    able = false;
    for(int i = 0; i < N - 1; i++){
      if(B[i] >= A[i + 1].first){
        able = true;
        break;
      }
    }
  }

  cout << (cnt.size() > 10 ? "Yes" : "No") << endl;

  return 0;
}

