int main()
{
  int N;
  cin >> N;
  vector<int> A(N), B(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  for (auto i = 0; i < N; i++)
  {
    cin >> B[i];
  }
  vector<Info> V(N);
  for (auto i = 0; i < N; i++)
  {
    V[i] = Info(B[i], A[i]);
  }
  sort(V.begin(), V.end());
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());
  for (auto i = 0; i < N; i++)
  {
    if (A[i] > B[i])
    {
      No();
    }
  }
  vector<bool> C(N, true);
  for (auto i = 1; i < N; i++)
  {
    C[i] = (A[i] <= B[i - 1]);
  }
  vector<int> sum(N + 1, 0);
  for (auto i = 0; i < N; i++)
  {
    int t{C[i] ? 0 : 1};
    sum[i + 1] = sum[i] + t;
  }
  for (auto k = 0; k < N; k++)
  {
    int x{get<0>(V[k])};
    int y{get<1>(V[k])};
    if (x > y)
    {
      continue;
    }
    auto it_a{upper_bound(A.begin(), A.end(), x)};
    --it_a;
    assert(*it_a == x);
    auto it_b{lower_bound(B.begin(), B.end(), y)};
    assert(*it_b == y);
    int num_a(it_a - A.begin());
    int num_b(it_b - B.begin());
    if (num_b <= num_a)
    {
      Yes();
    }
    else
    {
      if (sum[num_b + 1] - sum[num_a + 2] == 0)
      {
        Yes();
      }
    }
  }
  No();
}

