long long int find_root(std::vector<long long int> &root, long long int x){
  if(root[x] == x){
    return x;
  }
  else{
    root[x] = find_root(root, root[x]);
    return root[x];
  }
}

int unite(std::vector<long long int> &root, std::vector<long long int> &rank, long long int x, long long y){
  x = find_root(root, x);
  y = find_root(root, y);

  if(x == y){
    return 0;
  }
  else if(rank[x] < rank[y]){
    root[x] = y;
  }
  else if(rank[y] < rank[x]){
    root[y] = x;
  }
  else{ // if (x != y && rank[x] == rank[y])
    root[x] = y;
    rank[y]++;
  }

  return 0;
}

