    rep(i, n) idx[i] = i;
    sort(all(idx), [&](int x, int y){return a[x]*INF+b[x] < a[y]*INF+b[y];});
    bool f = true;
    map<int, queue<int>> x, y;
    UF uf(n);
    {
        auto A = a, B = b;
        sort(all(A));
        sort(all(B));
        rep(i, n) if(A[i] > B[i]) {
            f = false;
        }
        rep(i, n) {
            x[A[i]].push(i);
            y[B[i]].push(i);
        }
    }
    vector<int> X(n,-1), Y(n,-1);
    for(auto&& i: idx) {
        int p = x[a[i]].front(); x[a[i]].pop();
        int q = y[b[i]].front(); y[b[i]].pop();
        X[p] = i;
        Y[q] = i;
    }
    rep(i, n) uf.unite(X[i], Y[i]);
    f &= uf.size() > 1;
    cout << (f ? "Yes" : "No") << endl;
    return 0;
}

