int N;
int A[101010],ok[101010];
int B[101010];
pair<int,int> P[101010];
set<int> add[101010];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	FOR(i,N) cin>>A[i];
	FOR(i,N) cin>>B[i];
	FOR(i,N) {
		P[i]={B[i],A[i]};
	}
	sort(A,A+N);
	sort(B,B+N);
	FOR(i,N) {
		if(B[i]<A[i]) return _P("No\n");
	}
	sort(P,P+N);
	FOR(i,N) {
		A[i]=P[i].second;
		B[i]=P[i].first;
	}
	FOR(i,N) {
		ok[i]=lower_bound(B,B+N,A[i])-B;
		//cout<<i<<" "<<A[i]<<" "<<B[i]<<" "<<ok[i]<<endl;
		add[ok[i]].insert(i);
	}

	set<int> S;
	FOR(i,N-1) {
		FORR(e,add[i]) S.insert(e);
		//cout<<i<<" "<<S.size()<<endl;
		assert(S.size());
		if(S.count(i)) return _P("Yes\n");

		x=*S.begin();
		S.erase(x);
		swap(A[i],A[x]);
		swap(ok[i],ok[x]);
		add[ok[x]].erase(i);
		add[ok[x]].insert(x);
	}
	cout<<"No"<<endl;

}


