void init() {
}

int permutation_cycle_len(int *a, int n, int i) {
	int j = a[i], c = 1;
	while (j!=i) j = a[j], c++;
	return c;
}

void permutation_mul(int *a, int *b, int *c, int n) {
	for (int i=0; i<n; i++)
		c[i] = b[a[i]];
}

void permutation_inv(int *a, int *b, int n) {
	for (int i=0; i<n; i++) b[i] = i;
	sort(b, b+n, [&](auto &x, auto &y) {
		return a[x] < a[y];
	});
}

int solve() {
	permutation_inv(b, c, n);
	permutation_inv(a, d, n);

	sort(a, a+n);
	sort(b, b+n);
	for (int i=0; i<n; i++)
		if (a[i]>b[i]) return 0;
	for (int i=1; i<n; i++)
		if (a[i]<=b[i-1]) return 1;

	permutation_inv(c, e, n);
	permutation_mul(e, d, c, n); //c=c'*d
	int one = permutation_cycle_len(c, n, 0)==n;
	if (!one) return 1;

	return 0;
}

