void re_index(std::vector<ll> &a, const std::vector<int> &ind) {
  size_t N = a.size();
  std::vector<ll> sub(N);
  rep(i, N) {
    sub[i] = a[ind[i]];
  }
  rep(i, N) {
    a[i] = sub[i];
  }

  return;
}

