//UNION FIND
struct UnionFind{
    vector<int> par;
    vector<int> rank;

    //n要素で初期化
    UnionFind(int n) : par(n), rank(n){
        for (int i=0; i<n; ++i){
            par[i] = i;
            rank[i] = 0;
        }
    }

    //木の根を求める
    int root(int x){
        if (par[x] == x){
            return x;
        }else{
            return par[x] = root(par[x]);
        }
    }

    //xとyの属する集合を併合
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if (rank[x] == rank[y]) ++rank[x];
        }
    }

    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

//評価関数，二つ目の要素でソート
bool compare_by_second(pair<int, int> a, pair<int, int> b){
    if (a.second != b.second){
        return a.second < b.second;
    }else{
        return a.first < b.first;
    }
}

int main()
{
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    long long a[110000], b[110000];
    REP(i,N) cin >> a[i];
    REP(i,N) cin >> b[i];
    vector<pair<int, long long> > an;
    REP(i,N) an.push_back(make_pair(i, a[i]));
    sort(b, b + N);
    sort(an.begin(), an.end(), compare_by_second);
    // REP(i,N) cout << an[i].first << ' ' <<an[i].second << endl;
    UnionFind un(N);
    REP(i,N-1){
        if(an[i].second == an[i+1].second){
            un.unite(an[i].first, an[i+1].first);
        }
    }
    REP(i,N){
        if (an[i].second > b[i]){
            cout << "No" << endl;
            return 0;
        }
    }
    REP(i,N){
        int k = an[i].first;
        // cout << "k:" << k << endl;
        if (un.root(i) == un.root(an[k].first)){
            cout << "Yes" << endl;
            return 0;
        }
    }
    cout << "No" << endl;
    return 0;
}

