int main()
{
  int n;
  scanf("%d", &n);
  int a[100000];
  int b[100000];
  using pair = std::pair<int, int>;
  std::vector<pair> c;
  std::vector<pair> check;
  for (int i = 0; i < n; ++i)
  {
    scanf("%d", a + i);
    c.emplace_back(a[i], -1);
  }
  for (int i = 0; i < n; ++i)
  {
    scanf("%d", b + i);
    c.emplace_back(b[i], 1);
    if (b[i] >= a[i]) check.emplace_back(a[i], b[i]);
  }
  std::sort(c.begin(), c.end(), std::greater<pair>());
  if (c[0].second < 0)
  {
    puts("No");
    return 0;
  }
  long long count = 0;
  for (const auto& p : c)
  {
    count += p.second;
    if (count < 0)
    {
      puts("No");
      return 0;
    }
  }

  for (const auto& ch : check)
  {
    int count = 0;
    bool good = true;
    bool first[2] = {true, true};
    for (const auto& p : c)
    {
      if (first[0] && p.first == ch.first && p.second < 0)
      {
        first[0] = false;
        continue;
      }
      else if (first[1] && p.first == ch.second && p.second > 0)
      {
        first[1] = false;
        continue;
      }
      count += p.second;

      if (count < 0)
      {
        good = false;
        break;
      }
    }
    if (good)
    {
      puts("Yes");
      return 0;
    }
  }
  puts("No");
  return 0;
}

