struct Calc {
	DEFINITER;
	DEFVALUES(//////////////////////////////////////////////////
		(u6, N)
	);///////////////////////////////////////////////////////

	bool calc() {
		vector<pair<u6, u6>> buf;
		buf.reserve(2 * N);
		rep(ab, 2) {
			rep(i, N) {
				auto t = read<u6>();
				buf.emplace_back((t << 1 )+ ab, i);
			}
		}
		sort(ALL(buf));
		u6 abdiff = 0;
		vector<u3> r(N);
		u3 rno = 1;
		bool flg = false;
		for (const auto & v : buf) {
			if (v.first & 1) {
				if (abdiff == 0)return false;
				--abdiff;
				if (abdiff == 0)rno++;
				if (r[v.second] == rno)flg = true;
			}
			else {
				++abdiff;
				r[v.second] = rno;
			}
		}
		return flg;

	}
	/*******************************************************************************/
};

