    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    for (i = 0; i < n; i++) scanf("%d", &b[i]);

    for (i = 0; i < n; i++) {
        v.push_back(make_pair(a[i], i));
        w.push_back(make_pair(b[i], i));
    }

    sort(v.begin(), v.end());
    sort(w.begin(), w.end());

    for (i = 0; i < n; i++) {
        p[v[i].second] = i;
        q[w[i].second] = i;
    }

    for (i = 0; i < n; i++) {
        sum1[i + 1] = sum1[i];
        if (v[i].first <= w[i].first) sum1[i + 1]++;
    }

    for (i = 1; i < n; i++) {
        sum2[i + 1] = sum2[i];
        if (v[i].first <= w[i - 1].first) sum2[i + 1]++;
    }

    for (i = 0; i < n - 1; i++) {
        sum3[i + 1] = sum3[i];
        if (v[i].first <= w[i + 1].first) sum3[i + 1]++;
    }

    if (sum1[n] != n) {
        puts("No");

        return 0;
    }

    for (i = 0; i < n; i++) {
