int main(void){
  //入力
  long long int N;
  vector<long long int > A;
  vector<long long int > B;
  cin >> N;
  for(int i = 0; i < N; i++){
    long long int temp_a;
    cin >> temp_a;
    A.push_back(temp_a);
  }
  for(int i = 0; i < N; i++){
    long long int temp_b;
    cin >> temp_b;
    B.push_back(temp_b);
  }

  //ペアを作ってAを軸にソート
  vector<pair<long long int, long long int > > p;
  for(int i = 0; i < N; i++){
    p.push_back(make_pair(A[i], B[i]));
  }
  sort(p.begin(), p.end());


  //貪欲法，前から順に調べていきA[i] > B[i]を見つけたら，その番号iから逆順に調べて，
  //入れ替えても条件を満たすAjと交換する．
  long long int exchange_count = 0;
  bool enable_ans = true;
  for(int i = 0; i < N; i++){
    //A[i] > B[i]を見つけた場合
    if(p[i].first > p[i].second){
      bool crisis_avoid = false;
      //逆順に調べる
      for(int j = i - 1; j >= 0; j--){
        //B[j]の方がA[i]よりも大きい場所を見つけたらそこと交換．
        if(p[i].first <= p[j].second){
          long long int temp = p[i].first;
          p[i].first = p[j].first;
          p[j].first = temp;
          exchange_count++;
          crisis_avoid = true;
          break;
        }
      }
      if(crisis_avoid == false){
        enable_ans = false;
        break;
      }
    }
  }
  if(exchange_count > N - 2){
    enable_ans = false;
  }
  //出力
  if(enable_ans){
    cout << "Yes" << endl;
  }
  else{
    cout << "No" << endl;
  }
  return 0;
}

