    if (!flag) {
        No();
        return;
    }
    bool flag2 = false;
    FOR(i, 0, N - 1) {
        if (A[i + 1] <= B[i])
            flag2 = true;
    }
    FOR(i, 0, N) {
        if (B[i] == V[i].second)
            flag2 = true;
    }
    if (flag2) {
        Yes();
        return;
    }
    SegmentTree<int> seg(N + 1, [](int a, int b) { return a + b; }, 0);
