    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    {
        vector<int> ta = a, tb = b;
        sort(all(ta));
        sort(all(tb));
        rep(i,n){
            if (ta[i] > tb[i]) return false;
        }
    }

    // priority_queue<P,vector<P>,greater<P>> paths;
    using P = pair<int,int>;
    vector<P> v(n);
    map<int,int> cntA;
    rep(i,n){
        v[i] = {b[i], a[i]};
        cntA[a[i]] ++;
