        if (ai <= bi) continue;
        cnt++;
        auto itr = cntA.upper_bound(bi);
        if (itr == cntA.begin()) return false;
        --itr;
        cntA[ai]++;
        itr->second --;
        if (itr->second == 0) cntA.erase(itr);
    }
    return cnt <= n-2;
}

