// Light version
using Data = int;
const int len = 1 << 18;

struct BIT {
  vector<Data> data;
  BIT() : data(len, 0) {}
  void update(int i, Data value) {
    for (; i < len; i |= i+1) data[i] += value;
  }
  Data query(int i) {
    Data s = 0;
    for (; i >= 0; i = (i&i+1)-1) s += data[i];
    return s;
  }
};

int main()
{
  int n;
  cin>>n;
  vector<tuple<int,int>> vt;
  vecint va(n), vb(n);
  for(auto& e:va) {
    cin>>e;
  }
  for(auto& e:vb) {
    cin>>e;
  }
  for(int i:irange(0,n)) {
    int a=va[i];
    int b=vb[i];
    vt.emplace_back(b,a);
  }
  boost::sort(va);
  boost::sort(vt);
  bool ok = true;
  BIT fwd_a;
  map<int,int> m;
  map<int,int> m2;
  bool swappable = false;
  for (int i:irange(0,n)) {
    m[va[i]] = i;
    if (va[i] > get<0>(vt[i])) {
      ok = false;
    }
    if (i > 0 && va[i] <= get<0>(vt[i-1])) {
      fwd_a.update(i-1, 1);
      swappable = true;
    }
    int j=n-i-1;
    m2[va[j]] = j;
  }
  bool stable = false;
  for (int i:irange(0,n)) {
    ll b,a;
    tie(b,a) = vt[i];
    if (b < a) continue;
    int ai = m[a];
    int ai2 = m2[a];
    if (ai2 > i) {
      stable = true;
    } else if (ai < i) {
      int cnt = fwd_a.query(i-1) - fwd_a.query(ai-1);
      if (i - ai == cnt) stable = true;
    } else {
      stable = true;
    }
  }
  if (!stable && !swappable) ok = false;
  if(ok) {
    cout<<"Yes"<<endl;
  }else{
    cout<<"No"<<endl;
  }
  return 0;
}

