        p[i] = make_pair(a[i], -i);
    }

    segtree sgt(p);

    ll kaisu = 0;
    bool aki = false;
    REP(i, n) {
        auto u = sgt.fetch(i, i+1);
        if (u.first > b[i]) {
            auto v = sgt.fetch(i+1, n);
            if (v.first > b[i]) {
                cout << "No" << endl;
                return 0;
            }
            ll j = -v.second;
            // swap w/o soegies
            sgt.apply(i, i+1, make_pair(v.first, -i));
            sgt.apply(j, j+1, make_pair(u.first, -j));
            kaisu++;
        } else if (i < n-1) {
            aki = true;
        }
    }
    cout << Yes(aki || kaisu <= n-2) << endl;
}

