ll pow(ll a, ll b) {
  ll tmp = 1;

  while (b > 0) {
    if (b%2) tmp = (tmp * a) % 998244353LL;
    a = (a * a) % 998244353LL;
    b /= 2;
  }

  return tmp;
}

int main() {
    int N;

    cin >> N;

    vector<ll> A(N),B(N);

    fill(A);
    fill(B);

    set<pair<ll, ll>> correct, incorrect;
    REP(i,N) {
      if (A[i] <= B[i])
        correct.emplace(B[i], A[i]);
      else
        incorrect.emplace(A[i], B[i]);
    }


  int swapped = 0;
  for (const auto& i : incorrect) {
    if (lower_bound(correct.begin(),correct.end(), make_pair(i.first, 0LL)) == correct.end()) {
      cout << "No" << endl;
      return 0;
    }
    for (auto it = correct.lower_bound(make_pair(i.first, 0LL)); it != correct.end(); ++it) {
      correct.emplace(it->first, i.first);
      correct.emplace(i.second, it->second);
      correct.erase(it);
      swapped++;
      break;
    }
  }

    cout << (swapped <= N - 2 ? "Yes" : "No") << endl;

    return 0;
}

