        sg_l.update(i, sva[i + 1] <= svb[i]);
    }

    sg_r.update(n - 1, true);

    REP(i, 1, n) {
        sg_r.update(i, sva[i - 1] <= svb[i]);
    }

    rep(k, n) { //k番目を固定

        //cout << k << " ";
        if (v[k].first == sva[k]) { //固定しても全体がsort済み
            //cout << "そのまま ";
            Check(sg.query(0, n));

        } else if (v[k].first > sva[k]) { //本来の位置より左，固定した要素の右側が右にずれる
            //cout << "→ずれ";
            int no_change_pos; //ずれなくなる最初の位置
            auto itr = upper_bound(all(sva), v[k].first);
            no_change_pos = (int) distance(sva.begin(), itr);
            Check(sg.query(0, k) && (v[k].first <= svb[k])
                    && sg_r.query(k + 1, no_change_pos) && sg.query(no_change_pos, n));

        } else {
            //cout << "←ずれ";
            int change_pos; //ずれる最初の位置
            auto itr = upper_bound(all(sva), v[k].first);
            itr--;
            change_pos = (int) distance(sva.begin(), itr);
            //cout << change_pos << " ";
            Check(sg.query(0, change_pos) && sg_l.query(change_pos, k)
                    && (v[k].first <= svb[k]) && sg.query(k + 1, n));

        }

    }

    Yes(false);

    return 0;
}

