	std::vector<std::pair<int, int>> A, B;
	for(int i = 0; i < n; i++) {
		A.push_back({a[i], i});
		B.push_back({b[i], i});
	}
	sort(begin(A), end(A)); sort(begin(B), end(B));

	std::vector<int> x(n), y(n);
	for(int i = 0; i < n; i++) {
		x[A[i].second] = i;
		y[B[i].second] = i;
	}

	auto f = [&](int a, int b) { return std::min(a, b); };
	segment_tree<int> X(n, f, 1 << 30), Y(n, f, 1 << 30), Z(n, f, 1 << 30);
	for(int i = 0; i < n; i++) {
		int S = A[i].first, T = B[i].first;

		X.change(i, A[i].first <= B[i].first);
		if(i - 1 >= 0) Y.change(i, A[i].first <= B[i - 1].first);
		if(i + 1 < n ) Z.change(i, A[i].first <= B[i + 1].first);
	}

	if(!X.fold(0, n)) {
		printf("No\n");
		return 0;
	}

	for(int i = 0; i < n; i++) {
		if(!(a[i] <= b[i])) continue;
		int p = x[i], q = y[i];

		if(p == q) {
			printf("Yes\n");
			return 0;
		} else if(p < q) {
			int kiri = X.fold(0, p);
			int tan  = Y.fold(p + 1, q + 1);
			int po   = X.fold(q + 1, n);

			if(kiri and tan and po) {
				printf("Yes\n");
				return 0;
			}
		} else {
			int kiri = X.fold(0, q);
			int tan  = Z.fold(q, p);
			int po   = X.fold(p + 1, n);

			if(kiri and tan and po) {
				printf("Yes\n");
				return 0;
			}
		}
	}

	reverse(begin(A), end(A)); reverse(begin(B), end(B));

	int cur = 0;
	using P = std::pair<int, int>;
	std::priority_queue<P, std::vector<P>, std::greater<P>> qu;
	for(auto v: A) {
		int i = v.second;
		while(cur < n and a[i] <= B[cur].first) {
			int id = B[cur++].second;

			qu.push({a[id], id});
		}
		if(qu.empty()) continue;

		if(qu.size() == 1) {
			auto p = qu.top(); qu.pop();
			qu.push(p);

			if(i == p.second) continue;
			if(a[p.second] <= b[i]) {
				printf("Yes\n");
				return 0;
			}
		} else {
			auto p = qu.top(); qu.pop();
			auto q = qu.top(); qu.pop();
			qu.push(p);
			qu.push(q);

			if(p.second != i) {
				if(a[p.second] <= b[i]) {
					printf("Yes\n");
					return 0;
				}
			} else {
				if(a[q.second] <= b[i]) {
					printf("Yes\n");
					return 0;
				}
			}
		}
	}
	printf("No\n");
	return 0;
}

