struct UnionFindTree{
  vector<int> parent;

  UnionFindTree(int n) : parent(n){
    for(int i = 0; i < n; i++) parent[i] = i;
  }

  int find(int x){
    if(parent[x] == x) return x;
    else return parent[x] = find(parent[x]);
  }

  void unite(int x, int y){
    parent[find(x)] = find(y);
  }
};

