using namespace std;

bool solve() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int64_t N;
  cin >> N;
  vector<int> a(N);
  vector<int> b(N);
  for (int i = 0; i < N; ++i) {
    cin >> a[i];
  }
  for (int i = 0; i < N; ++i) {
    cin >> b[i];
  }
  auto sorted_a = a;
  sort(sorted_a.begin(), sorted_a.end());
  auto sorted_b = b;
  sort(sorted_b.begin(), sorted_b.end());
  unordered_map<int, size_t> a_map;
  unordered_map<int, size_t> b_map;
  vector<int> can_shift_since(N);
  int last_shift = -1;
  for (size_t i = 0; i < a.size(); ++i) {
    if (sorted_b[i] < sorted_a[i]) {
      return false;
    }
    if (i == a.size() - 1 || sorted_b[i] < sorted_a[i + 1]) {
      last_shift = -1;
    } else if (last_shift == -1) {
      last_shift = i;
    }
    can_shift_since[i] = last_shift;
    a_map[sorted_a[i]] = i;
    b_map[sorted_b[i]] = i;
  }
  // cout << "can shift ";
  // for (auto shift : can_shift_since) {
  //   cout << " " << shift;
  // }
  // cout << endl;
  for (size_t i = 0; i < a.size(); ++i) {
    if (a[i] <= b[i]) {
      auto ai = a_map[a[i]];
      auto bi = b_map[b[i]];
      if (sorted_a[bi] <= sorted_b[ai]) {
        if (bi <= ai || can_shift_since[bi - 1] <= int(ai)) {
          return true;
        }
      }
    }
  }
  return false;
}

int main() {
  auto res = solve();
  cout << (res ? "Yes" : "No") << endl;
}

