template<typename T>
vector<pair<T,lint>> runlength(vector<T> v){
	lint n=v.size();
	vector<pair<T,lint>> ret(1,{v[0],1});
	rep(i,1,n){
		if(ret[ret.size()-1].first==v[i])++ret[ret.size()-1].second;
		else ret.push_back({v[i],1});
	}
	return ret;
}

