  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  int N; std::cin >> N;
  std::vector<P> L(N); 
  rep(i,N) std::cin >> L[i].first; 
  rep(i,N) std::cin >> L[i].second;
  std::sort( all(L), [](P &x, P &y) { return x.first < y.first; } );

  int cnt = 0;
  rep(i, N) {
    if ( L[i].first <= L[i].second ) continue;
    else {
      auto itr = std::upper_bound( L.begin(), 
                                   std::next(L.begin(),i), 
                                   L[i], 
                                   [] (P x, P d) { return x.first > d.second; });
      int ind = std::distance( L.begin(), itr );
      int change = -1;
      for(int k=ind-1; k>0; k--) {
        if ( L[i].first <= L[k].second ) {
          change = k;
          break;
        }
      }
      if ( change == -1 ) {
        std::cout << "No" << std::endl;
        return 0;
      }
      std::swap( L[i].second, L[change].second );
      cnt++;
      if ( cnt > N - 2 ) {
        std::cout << "No" << std::endl;
        return 0;
      }
    }
  }
  std::cout << "Yes" << std::endl;
  return 0;
}

