void build(int nod,int l,int r)
{
	if(l==r)
	{
		st[nod]=mkp(inf,l);
		return;
	}
	int mid=(l+r)/2;
	build(2*nod,l,mid);
	build(2*nod+1,mid+1,r);
	st[nod]=min(st[2*nod],st[2*nod+1]);
}
void upd(int x,int l,int r,int p,int v,int b)
{
	if(l==r)
	{
		if(b)ms[l].in(v);
		else if(!b && ms[l].fd(v)!=ms[l].end())ms[l].er(ms[l].fd(v));
		if(ms[l].empty())st[x]=mkp(inf,l);
		else st[x]=mkp((*ms[l].begin()),l);
		return;
	}
	int mid=(l+r)/2;
	if(p<=mid)upd(2*x,l,mid,p,v,b);
	else upd(2*x+1,mid+1,r,p,v,b);
	st[x]=min(st[2*x],st[2*x+1]);
}
pair<int,int> qry(int x,int l,int r,int tl,int tr)
{
	if(tl>r || l>tr)return mkp(inf,inf);
	if(tl<=l && r<=tr)return st[x];
	int mid=(l+r)/2;
	return min(qry(2*x,l,mid,tl,tr),qry(2*x+1,mid+1,r,tl,tr));
}
