        if (fg.at(i)) { continue; }
        else {
            for (int j = i + 1; j < n; j++) {
                if (a.at(j) <= b.at(i) && fg.at(j) == false) {
                    swap(a.at(i), a.at(j) );
                    fg.at(i) = true;
                    if (a.at(j) <= b.at(j)) { fg.at(j) = true; }
                    frag = true; // 書き換えた
