                rep(k, n) {
                    if (fg.at(k) == true && a.at(k) <= b.at(i) && a.at(i) <= b.at(k) && i != k) {
                        swap(a.at(i), a.at(k));
                        frag = true;
                        count++;
                        fg.at(i) = true;
                    }
                }
            }
        }
        if (frag == false) { cout << "No" << endl; return 0; }
        frag = false;
    }
    if (n == 1 && fg.at(0) == true) { cout << "Yes" << endl; }
    if (count <= n - 2) {
        cout << "Yes" << endl;
    }
    else { cout << "No" << endl; }


    return 0;
