            if(sa[i] <= sb[i + 1])c3[i]++;
        }
    }

    auto func = [](int x, int y){ return x + y; };
    SegmentTree<int> seg1(c1, func, 0), seg2(c2, func, 0), seg3(c3, func, 0);

    rep(i, N){
