void solve() {
  	scanf("%lld", &N);
	A.assign(N, 0);
	rep(i, N) scanf("%lld", &A[i]);
	B.assign(N, 0);
	rep(i, N) scanf("%lld", &B[i]);

	//配置変え
	vector<pair<ll,ll>> C(N);
	rep(i,N){
		C[i].first=A[i];
		C[i].second=B[i];
	}
	sort(all(C));
	rep(i,N){
		A[i]=C[i].first;
		B[i]=C[i].second;
	}

	//最高形でも満たせないならNo
	vector<pair<ll,ll>> sortedApair(N),sortedBpair(N);
	rep(i,N){
		sortedApair[i].first=A[i];
		sortedApair[i].second=i;
		sortedBpair[i].first=B[i];
		sortedBpair[i].second=i;
	}
	vector<ll> sortedA=A,sortedB=B;
	sort(all(sortedA));
	sort(all(sortedB));
	sort(all(sortedApair));
	sort(all(sortedBpair));
	rep(i,N){
		if(sortedA[i]>sortedB[i]){p("No");return;}
	}

	debug(sortedApair);
	debug(sortedBpair);

	//猶予の検査 最初から都合の良い配置ならYes
	ll t=-1;
	rep(i,N){
		ll j=upper_bound(all(sortedA),sortedB[i])-sortedA.begin();
		j--;
		debug(j);
		if(i==j){
			ll index=sortedBpair[i].second;
			if(t!=-1 && t<=A[index] && A[index]<=sortedA[j]){
			//if(sortedApair[i].second==sortedBpair[i].second){
				p("Yes");return;
			}
			t=-1;
			continue;
		}
		ll l= t==-1 ? sortedA[i] : sortedA[t];
		ll r=sortedA[j];
		ll index=sortedBpair[i].second;
		debug(l,r,A[index]);
		if(l<=A[index] && A[index]<=r){
			p("Yes");return;
		}
		t=i;
	}

	//ループ
	vector<vector<ll>> g(N);
	rep(i,N){
		g[i].push_back(sortedBpair[i].second);
	}
	debug(g);
	vector<ll> seen(N,-1);
	rep(i,N){
		if(seen[i]==-1){
			dfs(g,i,-1,0,seen);
		}
	}

	rep(i,N){
		if(seen[i]==N-1){
			p("No");return;
		}
	}
	p("Yes");
}

