const int N = 1e5 + 5;

int t[N * 4];

void update(int v, int tl, int tr, int pos, int new_val) {
    if (tl == tr) {
        t[v] = new_val;
    } else {
        int tm = (tl + tr) / 2;
        if (pos <= tm)
            update(v*2, tl, tm, pos, new_val);
        else
            update(v*2+1, tm+1, tr, pos, new_val);
        t[v] = min(t[v*2], t[v*2+1]);
    }
}

int kek(int v, int tl, int tr, int l, int r) {
    if (l > r) 
        return 1;
    if (l == tl && r == tr) {
        return t[v];
    }
    int tm = (tl + tr) / 2;
    return min(kek(v*2, tl, tm, l, min(r, tm)), kek(v*2+1, tm+1, tr, max(l, tm+1), r));
}

