int main() {
  ll N;
  cin >> N;
  vector<ll> A(N), B(N);
  for_each(begin(A), end(A), [](auto& x) { cin >> x; });
  for_each(begin(B), end(B), [](auto& x) { cin >> x; });

  vector<pair<ll, ll>> BA;
  for (ll i = 0; i < N; i++) {
    BA.emplace_back(B[i], A[i]);
  }

  // Bは小さい順にソートしてAは大きい順にする。
  sort(begin(BA), end(BA), [](auto x, auto y) {
    if (x.first == y.first) {
      return x.second > y.second;
    }
    return x.first < y.first;
  });

  // もとに戻す
  for (ll i = 0; i < N; i++) {
    A[i] = BA[i].second;
    B[i] = BA[i].first;
  }

  ll count = 0;
  // 成立しないものを探す
  for (ll i = 0; i < N; i++) {
    if (A[i] > B[i]) {
      // swap必要。
      //自分よりもBが大きい値であり、可能な限りAが大きめの値を取り出す。
      // 探索範囲のbeginを作る
      auto it = lower_bound(begin(B), end(B), A[i]);
      // 添え字に変換
      size_t index = distance(begin(B), it);
      // 交換候補を見つける
      auto swap_it = find_if(begin(A) + index, end(A), [&](auto x) { return x <= B[i]; });
      if (swap_it == A.end()) {
        cout << "No" << endl;
        return 0;
      }
      // 添え字変換
      index = distance(begin(A), swap_it);
      // 実際に交換する
      swap(A[i], A[index]);
      count++;
      if (count > N - 2) {
        cout << "No" << endl;
        return 0;
      }
    }
  }

  cout << "Yes" << endl;
  return 0;
}

