const int INF = 1e9 + 7;
const int MAXN = 1e5 + 100;
vector<int> qs[MAXN];
int t[MAXN * 4], pos[MAXN];

void update(int v, int tl, int tr, int pos, int val) {
    if (tl + 1 == tr) {
        t[v] = val;
        return;
    }
    int tm = (tl + tr) >> 1;
    if (pos < tm) {
        update(v * 2 + 1, tl, tm, pos, val);
    }
    else {
        update(v * 2 + 2, tm, tr, pos, val);
    }
    t[v] = min(t[v * 2 + 1], t[v * 2 + 2]);
}

int get(int v, int tl, int tr, int l, int r) {
    if (tl >= r || tr <= l) {
        return INF;
    }
    if (tl >= l && tr <= r) {
        return t[v];
    }
    int tm = (tl + tr) >> 1;
    int a = get(v * 2 + 1, tl, tm, l, r);
    int b = get(v * 2 + 2, tm, tr, l, r);
    return min(a, b);
}

