    vector<P> ok;
    vector<P> ng;
    vector<int> oka;
    vector<P> okb;
    rep(i, n) {
        if(a[i] <= b[i]) {
            ok.pb(make_pair(a[i], b[i]));
        } else {
            ng.pb(make_pair(a[i], -b[i]));
        }
    }
    sort(all(ok));
    reverse(all(ok));
    int t = 0;
    for(auto k: ok) {
        oka.pb(k.fr);
        okb.pb(make_pair(k.sc, t));
        t++;
    }
    sort(all(ng));
    reverse(all(ng));
    SegmentTree<P> sg(okb, make_pair(INF, INF));
    int s = (int)ok.size();
    int cnt = 0;
    for(auto k: ng) {
        ll A = k.fr, B = k.sc;
        B *= (-1);
        auto ite = upper_bound(all(oka), B);
        if(ite == oka.begin()) {
            cout << "No" << endl;
            return;
        }
        int x = ite - oka.begin();
        P C = sg.get(0, x);
        if(A <= C.fr) {
            cnt ++;
            sg.update(C.sc, make_pair(B, C.sc));
            continue;
        } else {
