{
	using std::endl;

	cin >> N >> K;
	if (1 == K) {
		for (int i = 0; i < N; i++)
		{
			cout << K + i << ' ' << K + (2 * N - i - 1) << ' ' << K + 2 * N + i << '\n';
		}
	}
	else if (K > 2) {
		std::vector<std::pair<int, int>> res;
		int left = 2*N;
		int right = left + 1;
		for (int i = 0; i < N; i++)
		{
			int a = K + i;
			int c = K + 2 * N + i;
			int b;
			if (right < K + 2*N && a + right <= c) {
				b = right;
				++right;
			}
			else {
				b = left;
				--left;
			}
			if (b < K+N) {
				cout << -1 << endl;
				return 0;
			}

			res.push_back({ a,b });
		}
		for (int i = 0; i < N; i++) {
			cout << res[i].first << ' ' << res[i].second << ' ' << K + 2 * N + i << '\n';
		}
	}

	else {
		cout << -1 << endl;
		return 0;
	}

	return 0;
}
