using namespace std;

#define rep(i,n) for(int i=0;i<(n);++i)

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int N; cin >> N;

  pair<int, int> BA[N];
  int A[N], B[N];
  int sortA[N];
  rep(i, N) cin >> BA[i].second;
  rep(i, N) cin >> BA[i].first;

  sort(BA, BA+N);

  rep(i, N) {
    sortA[i] = A[i] = BA[i].second;
    B[i] = BA[i].first;
  }

  sort(sortA, sortA+N);

  rep(i, N) {
    if (sortA[i] > B[i]) {
      cout << "No\n";
      return 0;
    }
  }
  // これで少なくともソートさえすればA<=Bを満たせると保証された

  int count = 0;
  for (int i=N-1;i>=0;--i) {
    if (A[i] <= B[i])
      ++count;
  }
  if (count <= 1) cout << "No\n";
  else {
    for (int i=N-1;i>=0;--i) {
      if (A[i] > B[i])
        --count;
    }
    if (count >= 0)
      cout << "Yes\n";
    else
      cout << "No\n";
  }

  return 0;
}

