using namespace std;

struct unionfind {
  vector<int> dat;

  unionfind(int n) : dat(n) {
    for (int i = 0; i < n; i++) {
      dat[i] = i;
    }
  }

  int find(int x) {
    if (dat[x] == x) return x;
    return dat[x] = find(dat[x]);
  }

  void unite(int x, int y) {
    dat[find(x)] = find(y);
  }
};

int main() {
  int N; cin >> N;
  vector<int> A(N), B(N);
  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < N; i++) cin >> B[i];
  vector<pair<int, int>> AB;
  for (int i = 0; i < N; i++) {
    AB.emplace_back(A[i], i);
    AB.emplace_back(B[i], i + N);
  }
  sort(AB.begin(), AB.end());
  int a = 0;
  int b = 0;
  bool any = false;
  unionfind uf(N);
  int prev_a = 0;
  for (auto t : AB) {
    if (t.second < N) {
      a++;
      prev_a = t.second;
    } else {
      b++;
      uf.unite(prev_a, t.second - N);
    }
    if (a < b) {
      cout << "No" << endl;
      return 0;
    }
    if (a >= b + 2) {
      any = true;
    }
  }
  int cycles = 0;
  for (int i = 0; i < N; i++) {
    if (uf.find(i) == i) cycles++;
  }
  if (cycles == 1 && !any) {
    cout << "No" << endl;
  } else {
    cout << "Yes" << endl;
  }
}

