struct mint {
	int64_t value;
	mint():value(0){}
	mint(int64_t value_) : value(value_%MOD) {}
	inline mint& operator += (const mint& rhs) {
		value += rhs.value;
		if (value >= MOD) { value -= MOD; }
		return *this;
	}
	inline mint& operator -= (const mint& rhs) {
		value -= rhs.value;
		if (value < 0) {
			value += MOD;
		}
		return *this;
	}
	inline mint& operator *= (const mint& rhs) {
		value *= rhs.value;
		value %= MOD;
		return *this;
	}
	inline mint& operator %= (const mint& rhs) {
		return *this;
	}
};

// x^n % mod
// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

inline mint operator + (const mint& lhs, const mint& rhs) { mint res = lhs; res += rhs; return res; }
inline mint operator - (const mint& lhs, const mint& rhs) { mint res = lhs;	res -= rhs;	return res; }
inline mint operator * (const mint& lhs, const mint& rhs) { mint res = lhs;	res *= rhs;	return res; }
inline mint operator % (const mint& lhs, const uint64_t& rhs) { return lhs; }

ostream & operator << (ostream & out, mint n) { return out << n.value; }

template<class T>
class LazySegtree {
private:
	int n;
	vector<T> dat;
	vector<T> lazy;
	vector<bool> lazyFlag;

	void eval(int k, int l, int r){
		if (lazyFlag[k]) {
			dat[k] = min(lazy[k], dat[k]);

			if (r - l > 1) {
				lazy[2 * k + 1] = lazy[k];
				lazy[2 * k + 2] = lazy[k];
				lazyFlag[2 * k + 1] = lazyFlag[2 * k + 2] = true;
			}
		}

		lazyFlag[k] = false;
	}

	T query(int a, int b, int k, int l, int r) {
		eval(k, l, r);
		if (r <= a || b <= l) return numeric_limits<T>::max();

		if (a <= l & r <= b) return dat[k];

		T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

		return min(vl, vr);
	}

	// change [a,b) to value
	void update(int a, int b, T value, int k, int l, int r){
		eval(k, l, r);
		if (b <= l or r <= a) return;

		if (a <= l and r <= b) {
			if (lazyFlag[k]) {
				lazy[k] = min(value, lazy[k]);
			}
			else {
				lazy[k] = value;
			}
			lazyFlag[k] = true;
			eval(k, l, r);
		}
		else {
			update(a, b, value, 2 * k + 1, l, (l + r) / 2);
			update(a, b, value, 2 * k + 2, (l + r) / 2, r);
			dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}
public:
	LazySegtree(int n_) {
		n = 1;
		while (n < n_) n *= 2;
		dat.resize(2 * n - 1);
		lazy.resize(2 * n - 1);
		lazyFlag.resize(2 * n - 1);
		for (int i = 0; i < 2 * n - 1; ++i) dat[i] = numeric_limits<T>::max();
	}


	// change [a,b） to value
	void update(int a, int b, T value){
		update(a, b, value, 0, 0, n);
	}

	// change k to value
	void update(int k, T value) {
		update(k, k + 1, value);
	}

	// get min value at [a, b)
	T query(int a, int b) {
		return query(a, b, 0, 0, n);
	}
};

bool dfs(const vector<vector<int> >& G, int node, vector<bool>& memo) {
	if (memo[node]) {
		return true;
	}
	for (auto& dst : G[node]) {
		if (dfs(G, dst, memo)) {
			return true;
		}
	}
	return false;
}

void solve() {
	int N; cin >> N;
	vector<int> A(N); for (auto& a : A) cin >> a;
	vector<int> B(N); for (auto& a : B) cin >> a;
	vector<pii> Apos(N);
	vector<pii> Bpos(N);

	REP(i, N) {
		Apos[i] = { A[i], i };
		Bpos[i] = { B[i], i };
	}

	sort(ALL(Apos), greater<pii>());
	sort(ALL(Bpos), greater<pii>());
	reverse(ALL(Apos));
	reverse(ALL(Bpos));

	REP(i, N) {
		if (Apos[i].first > Bpos[i].first) {
			cout << "No" << endl;
			return;
		}
	}

	// 余裕があるケース
	REP(i, N-1) {
		if (Apos[i+1].first <= Bpos[i].first) {
			cout << "Yes" << endl;
			return;
		}
	}

	vector<vector<int> > G(N);
	vector<bool> memo(N);
	REP(i, N) {
		G[Apos[i].second].push_back(Bpos[i].second);
	}

	REP(i, N) {
		if (not memo[i]) {
			if (dfs(G, i, memo)) {
				cout << "Yes" << endl;
			}
			else {
				cout << "No" << endl;
			}
		}
	}
}

