int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n;
    cin >> n;
    vector<ll> a(n), b(n), ta(n), tb(n);
    rep(i, n) {
        cin >> a[i];
        ta[i] = a[i];
    }
    rep(i, n) {
        cin >> b[i];
        tb[i] = b[i];
    }
    sort(all(ta));
    sort(all(tb));
    // can't complete case
    rep(i, n) {
        if (ta[i] > tb[i]) {
            cout << "No" << endl;
            return 0;
        }
    }
    // default correct 2 pos
    int cnt = 0;
    rep(i, n) {
        if (a[i] >= b[i]) {
            cnt++;
            if (cnt >= 2) {
                cout << "Yes" << endl;
                return 0;
            }
        }
    }
    // special exchange case
    map<int, vector<int>> c;
    int kcnt = 0;
    rep(i, n) c[a[i]].push_back(ta[i]);
    rep(i, n) {
        rep(ii, sz(c[a[i]])) {
            rep(iii, sz(c[c[a[i]][ii]])) {
                if (c[c[a[i]][ii]][iii] == a[i]) {
                    kcnt++;
                }
            }
        }
    }
    if ((cnt + (kcnt / 2)) >= 2) {
        cout << "Yes" << endl;
        return 0;
    }
    cout << "No" << endl;
    return 0;
}

