	rep(i,N){
		ll j=lower_bound(all(sortedA),sortedB[i])-sortedA.begin();
		debug(j);
		if(i==j){
			if(sortedApair[i].second==sortedBpair[i].second){
				p("Yes");return;
			}
			continue;
		}
		if(j==N)j--;
		ll l=sortedA[i];
		ll r=sortedA[j];
		ll index=sortedBpair[i].second;
		debug(l,r,A[index]);
		if(l<=A[index] && A[index]<=r){
			p("Yes");return;
		}
	}

	//ループ
	vector<vector<ll>> g(N);
	rep(i,N){
		g[i].push_back(sortedBpair[i].second);
	}
	debug(g);
	vector<ll> seen(N,-1);
	rep(i,N){
		if(seen[i]==-1){
			dfs(g,i,-1,0,seen);
		}
	}

	rep(i,N){
		if(seen[i]==N-1){
			p("No");return;
		}
	}
	p("Yes");
}

