const int N = 100005;

struct node {
	long long a, b;
	bool operator < (node rhs) const {
		return b < rhs.b;
	}
} vec[N];

int n, perm[N], cir = 0;
long long veca[N];
bool vis[N], check = true, flag = false;


int main () {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%lld", &vec[i].a);
	for (int i = 1; i <= n; i++) scanf("%lld", &vec[i].b);
	sort(vec + 1, vec + n + 1);
	for (int i = 1; i <= n; i++) veca[i] = vec[i].a;
	sort(veca + 1, veca + n + 1);

	for (int i = 1; i <= n; i++) {
		if (veca[i] > vec[i].b) check = false;
		if (i < n && veca[i + 1] <= vec[i].b) flag = true;
	}

	for (int i = 1; i <= n; i++) perm[i] = lower_bound(veca + 1, veca + n + 1, vec[i].a) - veca;
	for (int i = 1; i <= n; i++) {
		if (!vis[i]) {
			cir++;
			for (int j = i; !vis[j]; j = perm[j]) vis[j] = true;
		}
	}

	if (cir > 1) flag = true;
	if (check && flag) puts("Yes");
	else puts("No");
	return 0;
}

