using pi = pair<int,int>;

bool solve(){
    int n;
    cin >>n;

    vector<int> a(n),b(n);
    rep(i,n) cin >>a[i];
    rep(i,n) cin >>b[i];


    vector<pi> p(n);
    rep(i,n) p[i] = {a[i], b[i]};
    sort(all(p));

    // rep(i,n) cout << " " << p[i].fi;
    // cout << "\n";
    // rep(i,n) cout << " " << p[i].se;
    // cout << "\n";

    vector<int> sa(a),sb(b);
    sort(all(sa));
    sort(all(sb));
    rep(i,n)if(sa[i] > sb[i]) return false;

    vector<int> s(n);
    rep(i,n-1){
        s[i] = sa[i+1] > sb[i];
    }
    rep(i,n-1) s[i+1] += s[i];

    map<int,int> ma,mb;
    rep(i,n) ma[sa[i]] = i;
    for(int i=n-1; i>=0; --i) mb[sb[i]] = i;

    rep(i,n){
        int A = p[i].fi, B = p[i].se;
        if(A>B) continue;

        int aidx = ma[A], bidx = mb[B];
        if(bidx<=aidx) return true;

        int v = s[bidx-1];
        if(aidx>0) v -= s[aidx-1];
        if(v == 0) return true;
    }

    return false;
}

int main(){
    cout << (solve()?"Yes":"No") << "\n";
    return 0;
}

