const int N = 1e5 + 5;
int n, a[N], b[N], p[N], nxt[N];
bool mark[N];

inline void read_input() {
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> a[i];
	for (int i = 0; i < n; i++)
		cin >> b[i];
}

inline void solve() {
	iota(p, p + n, 0);
	sort(p, p + n, [] (int i, int j) {
		return a[i] < a[j];
	});
	sort(a, a + n);
	sort(b, b + n);
}

inline void write_output() {
	bool ok = false;
	for (int i = 0, cur = 0; i < n; i++) {
		while (cur < n && b[i] >= a[cur])
			cur++;
		if (cur <= i) {
			cout << "No";
			return;
		}
		ok |= cur - 1 > (nxt[p[i]] = i);
	}
	if (ok) {
		cout << "Yes";
		return;
	}
	for (int i = nxt[0]; i; i = nxt[i])
		mark[i] = true;
	for (int i = 1; i < n; i++)
		if (!mark[i]) {
			cout << "Yes";
			return;
		}
	cout << "No";
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	read_input(), solve(), write_output();
	return 0;
}

