using namespace std;
using Int = long long;
struct SegTree {
    int N;
    vector<int> A;
    SegTree(int n) {
        N = 1; while (N < n) N *= 2;
        A.resize(2*N);
    }
    void set(int idx, int val) {
        idx += N;
        A[idx] = val;
        idx /= 2;
        while (idx > 0) {
            A[idx] = A[2*idx+0] + A[2*idx+1];
            idx /= 2;
        }
    }
    int sum(int L, int R) {
        L += N, R += N;
        int ans = 0;
        while (L < R) {
            if (L & 1) {
                ans += A[L];
                L++;
            }
            if (R & 1) {
                R--;
                ans += A[R];
            }
            L /= 2, R /= 2;
        }
        return ans;
    }
};
int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for (auto &a : A) cin >> a;
    for (auto &b : B) cin >> b;
    vector<pair<int, int>> C(N), D(N);
    for (int i = 0; i < N; i++) {
        C[i] = make_pair(A[i], i);
        D[i] = make_pair(B[i], i);
    }
    sort(begin(C), end(C));
    sort(begin(D), end(D));
    vector<pair<int, int>> pos(N);
    for (int i = 0; i < N; i++) {
        pos[C[i].second].first = i;
        pos[D[i].second].second = i;
    }
    SegTree minus(N), same(N), plus(N);
    for (int i = 0; i < N; i++) {
        if (i != N - 1) minus.set(i, C[i].first <= D[i + 1].first);
        same.set(i, C[i].first <= D[i].first);
        if (i != 0) plus.set(i, C[i].first <= D[i - 1].first);
    }
    bool ans = false;
    for (int i = 0; i < N; i++) {
        if (A[i] > B[i]) continue;
        int c = pos[i].first, d = pos[i].second;
        int t = 0;
        if (c == d) {
            t = same.sum(0, c) + same.sum(c + 1, N);
        } else if (c < d) {
            t = same.sum(0, c) + minus.sum(c + 1, d + 1) + same.sum(d + 1, N);
        } else {
            t = same.sum(0, d) + plus.sum(d, c) + same.sum(c + 1, N);
        }
        if (t == N - 1) ans = true;
    }
    cout << (ans ? "Yes" : "No") << endl;
    return 0;
}

