    for (int i = 0; i < n; i++) c[i] = a[i];
    for (int i = 0; i < n; i++) c[i + n] = b[i];
    sort(c.begin(), c.end());
    map<int, int> mp;
    for (int i = 0; i < 2 * n; i++) {
        if (mp[c[i]] == 0) mp[c[i]] = i + 1;
    }
    vector<int> x(n);
    for (int i = 0; i < n; i++){
        x[i] = mp[a[i]];
        mp[a[i]] = mp[a[i]] + 1;
    }
    vector<int> y(n);
    for (int i = 0; i < n; i++){
        y[i] = mp[b[i]];
        mp[b[i]] = mp[b[i]] + 1;
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    bool flag = true;
    bool ok = false;
    for (int i = 0; i < n; i++){
        if (a[i] > b[i]) flag = false;
        if (i != 0){
            if (a[i] <= b[i - 1]) ok = true;
        }
    }
    if (!flag) {
        cout << "No" << endl;
        return 0;
    }
    if (ok){
        cout << "Yes" << endl;
        return 0;
    }
    map<int, int> id;
    map<int, int> rev_id;
    SegmentTree seg(vector<int> (2 * n, 0));
    for (int i = 0; i < n; i++){
        id[x[i]] = y[i];
        rev_id[y[i]] = x[i];
        seg.update(x[i], y[i]);
    }
    sort(x.begin(), x.end(), greater<int>());
    int cnt = 0;
    for (int i = 0; i < n; i++){
        if (x[i] <= id[x[i]]) continue;
        //id[x[i]]はb
        //pはbの値
        int p = seg.getmax(0, id[x[i]]);
        if (p < x[i]){
            cout << "No" << endl;
            return 0;
        }
        p = rev_id[p];
        swap(id[x[i]], id[p]);
        swap(rev_id[id[x[i]]], rev_id[id[p]]);
        seg.update(p, id[p]);
        cnt++;
    }
    if (cnt <= max(0, n - 2)) cout << "Yes" << endl;
    else cout << "No" << endl;
}

