#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

ll N;
ll A[100005];
pll C[100005];
pll B[100005];
ll D[100005];
ll U[100005];

bool solve()
{
    if (N == 2)
    {
        REP(i, N)
        {
            if (A[i] > B[i].first)
                return false;
        }
        return true;
    }
    map<ll, ll> map;
    REP(i, N)
    {
        map[A[i]]++;
    }
    sort(C, C + N, [](pll a, pll b) { return a.first < b.first; });
    sort(B, B + N, [](pll a, pll b) { return a.first < b.first; });
    REP(i, N)
    {
        if (C[i].first > B[i].first)
            return false;
    }

    memset(U, 0, sizeof(U));
    REP(i, N - 1)
    {
        if (C[i].first > B[i + 1].first)
            U[i + 1]++;

        U[i + 1] += U[i];
    }

    REP(i, N)
    {
        if (A[i] > D[i])
            continue;

        ll ru = N - 1, rl = -1;
        while (abs(ru - rl) > 1)
        {
            ll mid = (ru + rl) / 2;
            if (B[mid].first >= D[i])
                ru = mid;
            else
                rl = mid;
        }

        ll LU = 0, LL = N;
        while (abs(LU - LL) > 1)
        {
            ll mid = (LU + LL) / 2;
            if (C[mid].first >= A[i])
                LU = mid;
            else
                LL = mid;
        }

        if (U[ru + 1] - U[LL] == 0)
            return true;
    }
    return false;
}
