		if(l>n)
			continue;
		id=qry(1,l,n);
		if(a[id]>b[i])
			continue; 
		swap(a[id],a[i]);
		upd(1,i);upd(1,id);
		cnt++;
	}*/

	sort(a+1,a+1+n);
	for(int i=1;i<=n;i++)
	if(a[i]>b[i])
	{
		ans=0;
		return;
	}
	if(res<=n-1)
		ans=1;
}

inline void print()
{
	if(ans)
		puts("Yes");
	else
		puts("No");
}

int main()
{
	int t=1;
	//scanf("%d",&t);
	for(int i=1;i<=t;i++)
	{
		prework();
		mainwork();
		print();
	}
	return 0;
}

