	bool operator <(node a)const{return y<a.y;}
}e[N];
bool cmp(node a,node b){return a.x<b.x;}
multiset<int>s;
multiset<int>::iterator it;
int n,a[N],b[N],i,j,ans,cnt;
bool vis[N];
signed main(){
	scanf("%d",&n);
	For(i,1,n) scanf("%d",&e[i].x);
	For(i,1,n) scanf("%d",&e[i].y);
	sort(e+1,e+n+1);
	For(i,1,n) e[i].id=i,b[i]=e[i].y;
	sort(e+1,e+n+1,cmp);
	For(i,1,n) a[i]=e[i].x;
	For(i,1,n)
		if (!vis[i]){
			cnt++;
			for (j=i;!vis[j];j=e[j].id) vis[j]=1;
		}
	if (cnt>1) ans=1;
	For(i,2,n)
		if (a[i]==a[i-1]) ans=1;
	for (i=1,j=1;j<=n;j++){
		for (;i<=n && a[i]<=b[j];i++) s.insert(e[i].id-i);
		if (!s.size()){
			ans=0;
			break;
		}
		if (s.size()>=*s.begin()) ans=1;
		it=s.end(),it--;
		s.erase(it);
	}
	puts(ans?"Yes":"No");
}

