using namespace std;

typedef long long ll;
typedef pair<ll, ll> P;

void swap(int& a, int &b){
    int temp = a;
    a = b;
    b = temp;
}

void sorting(vector<P>& arr, int n){
    int max_i = -1, max_v = -1;
    for(int i=0;i<n;++i){
        if(max_v < arr[i].second){
            max_i = i;
            max_v = arr[i].second;
        }
    }
    if(max_i != -1){
        swap(arr[n-1].second, arr[max_i].second);
    }
}

int main()
{
    int N;
    cin >> N;
    vector<P> AB(N);
    for(int i=0;i<N;++i){
        cin >> AB[i].second;
    }
    for(int i=0;i<N;++i){
        cin >> AB[i].first;
    }

    sort(AB.begin(), AB.end());

    for(int i=N;i>2;--i){
        sorting(AB, i);
    }

    bool ans = true;
    for(int i=0;i<N;++i){
        if(AB[i].second > AB[i].first){
            ans = false;
            break;
        }
    }

    if(ans) cout << "Yes" << endl;
    else cout << "No" << endl;
}

