template <typename M>
struct SegmentTree{
    using T = typename M::type;

    int numLeaves;
    std::vector<T> data;

    SegmentTree(int n){
        numLeaves = 1;
        while(numLeaves < n){
            numLeaves *= 2;
        }

        data.resize(numLeaves * 2);
        std::fill(data.begin() + numLeaves, data.end(), M::identity());

        for(int i=numLeaves-1;i>0;--i){
            data[i] = M::bop(data[i*2], data[i*2+1]);
        }
    }

    template <typename F>
    SegmentTree(int n, F f){
        numLeaves = 1;
        while(numLeaves < n){
            numLeaves *= 2;
        }

        data.resize(numLeaves * 2);
        for(int i=0;i<n;++i){
            data[i + numLeaves] = std::move(f(i));
        }
        std::fill(data.begin() + numLeaves + n, data.end(), M::identity());

        for(int i=numLeaves-1;i>0;--i){
            data[i] = M::bop(data[i*2], data[i*2+1]);
        }
    }

    void set(int k, T v){
        k += numLeaves;
        data[k] = v;

        while(k > 1){
            k /= 2;
            data[k] = M::bop(data[k*2], data[k*2+1]);
        }
    }

    T product(int l, int r){
        l += numLeaves;
        r += numLeaves;

        T pl = M::identity(), pr = M::identity();
        for(;l<r;l/=2,r/=2){
            if(l & 1){
                pl = M::bop(pl, data[l]);
                l += 1;
            }
            if(r & 1){
                r -= 1;
                pr = M::bop(data[r], pr);
            }
        }

        return M::bop(pl, pr);
    }

    T at(int i){
        return data[i + numLeaves];
    }
};

struct M{
    using type = bool;
    static type identity(){
        return true;
    }
    static type bop(type m1, type m2){
        return m1 && m2;
    }
};

int N;
std::vector<int> A, B, C, D;
bool E[100100], F[100100];
SegmentTree<M> seg(100100);

int main(){
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  std::cin >> N;

  A.resize(N);
  B.resize(N);
  C.resize(N);
  D.resize(N);

  for(int i=0;i<N;++i){
      std::cin >> A[i];
      C[i] = A[i];
  }

  std::sort(C.begin(), C.end());

  for(int i=0;i<N;++i){
      std::cin >> B[i];
      D[i] = B[i];
  }

  std::sort(D.begin(), D.end());

  E[0] = (C[0] <= D[0]);

  for(int i=1;i<N;++i){
      E[i] = E[i-1] && (C[i] <= D[i]);
  }

  F[N-1] = (C[N-1] <= D[N-1]);

  for(int i=N-2;i>=0;--i){
      F[i] = F[i+1] && (C[i] <= D[i]);
  }

  for(int i=0;i+1<N;++i){
      seg.set(i, (C[i+1] <= D[i]));
  }

  bool can = false;

  for(int i=0;i<N;++i){
      unless(A[i] <= B[i]){
          continue;
      }

      int a = std::lower_bound(C.begin(), C.end(), A[i]) - C.begin(),
          b = std::lower_bound(D.begin(), D.end(), B[i]) - D.begin();

      bool f = (a == 0) || E[a-1],
          g = seg.product(a, b),
          h = (b == N - 1) || F[b+1];

      // std::cout << i << ", " << a << ", " << b << ", " << f << ", " << g << ", " << h<< std::endl;

      if(f && g && h){
          can = true;
          break;
      }
  }

  if(can){
      std::cout << "Yes" << std::endl;
  }else{
      std::cout << "No" << std::endl;
  }
}

