typedef pair<int, int> pii;
const int INF = 1l << 60;

struct RMaxQ {
    static const int N = 131072;
    pii data[2 * N];

    void init() {
        rep(i, 2 * N) {
            data[i] = pii(-1, -1);
        }
    }

    pii query(int a, int b, int l = 0, int r = N, int k = 0) {
        if (b <= l || r <= a)return pii(-1, -1);
        else if (a <= l && r <= b) {
            return data[k];
        }
        pii lch = query(a, b, l, (l + r) / 2, 2 * k + 1);
        pii rch = query(a, b, (l + r) / 2, r, 2 * k + 2);
        return max(lch, rch);
    }

    void update(int a, int x) {
        int a2 = a + N - 1;
        data[a2] = pii(x, a);
        while (a2) {
            a2 = (a2 - 1) / 2;
            data[a2] = max(data[2 * a2 + 1], data[2 * a2 + 2]);
        }
    }
};

