    }
    rep(i, N) {
        A2[i] = lower_bound(B, B + N, A[i]) - B;
    }

    priority_queue<pii> que;
    rmq.init();
    int cnt = 0;
    for (int i = N - 1; i >= 0; --i) {
        if (A2[i] <= i) {
            //置ける
            //交換可能
            rmq.update(i, A2[i]);
            que.emplace(A2[i], i);
            place[i] = i;
            place_inv[i] = i;
        } else {
            //交換しないといけない
            //交換先をjとすると
            //j>=A2[i]
            //A2[j]が大きい(小さいのは貴重)
            pii res = rmq.query(A2[i], rmq.N);
            if (res.first == -1) {
                cout << "No" << endl;
                return 0;
            }
            int idx = res.second;
            rmq.update(idx, -1);
            rmq.update(i, res.first);
            int idx2 = place_inv[idx];
            place[idx2] = i;
            place_inv[idx] = 0;
            place_inv[i] = idx2;
            cnt++;
        }
        while (!que.empty() && que.top().first >= i) {
            int idx = que.top().second;
            int pl = place[idx];
            rmq.update(pl, -1);
            que.pop();
        }
    }
    if (cnt <= N - 2) {
        return 1;
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

