  for (int i = 0; i < N; i++) {
    int k;
    cin >> k;
    B[i] = PII(k, i);
  }

  sort(A.begin(), A.end());
  sort(B.begin(), B.end());

  bool ans = true;
  bool last = false;
  for (int i = 0; i < N; i++) {
    if (A[i].first > B[i].first) ans = false;
    if (i < N - 1 && B[i].first >= A[i + 1].first) last = true;
  }

  vector<int> used(N, 0);
  int cur = 0;
  vector<int> inv(N);
  for (int i = 0; i < N; i++) inv[B[i].second] = i;
  for (int i = 0; i < N; i++) {
    used[cur] = true;
    cur = inv[A[cur].second];
  }
  for (int i = 0; i < N; i++) {
    if (!used[i]) last = true;
  }
  if (!last) ans = false;

  cout << (ans ? "Yes" : "No") << endl;

  return 0;
