constexpr ll N_MAX = 100000;
constexpr ll A_IB_I_MAX = 1000000000;

ll N;
vector<ll> A;
vector<ll> B;

void dfs(vector<vector<ll>> &g,ll v,ll p,ll depth,vector<ll> &seen){
	seen[v]=depth;
	for(ll nextv:g[v]){
		if(seen[nextv]!=-1)return;
		dfs(g,nextv,v,depth+1,seen);
	}
}

void solve() {
  	scanf("%lld", &N);
	A.assign(N, 0);
	rep(i, N) scanf("%lld", &A[i]);
	B.assign(N, 0);
	rep(i, N) scanf("%lld", &B[i]);

	//配置変え
	vector<pair<ll,ll>> C(N);
	rep(i,N){
		C[i].first=A[i];
		C[i].second=B[i];
	}
	sort(all(C));
	rep(i,N){
		A[i]=C[i].first;
		B[i]=C[i].second;
	}

	//最高形でも満たせないならNo
	vector<pair<ll,ll>> sortedApair(N),sortedBpair(N);
	rep(i,N){
		sortedApair[i].first=A[i];
		sortedApair[i].second=i;
		sortedBpair[i].first=B[i];
		sortedBpair[i].second=i;
	}
	vector<ll> sortedA=A,sortedB=B;
	sort(all(sortedA));
	sort(all(sortedB));
	sort(all(sortedApair));
	sort(all(sortedBpair));
	rep(i,N){
		if(sortedA[i]>sortedB[i]){p("No");return;}
	}

	debug(sortedApair);
	debug(sortedBpair);

	//猶予の検査 最初から都合の良い配置ならYes
	rep(i,N){
		ll j=lower_bound(all(sortedA),sortedB[i])-sortedA.begin();
		debug(j);
		if(i==j){
			if(sortedApair[i].second==sortedBpair[i].second){
				p("Yes");return;
			}
			continue;
		}
		j--;
		ll l=sortedA[i];
		ll r=sortedA[j];
		ll index=sortedBpair[i].second;
		debug(l,r,A[index]);
		if(l<=A[index] && A[index]<=r){
			p("Yes");return;
		}
	}

	//ループ
	vector<vector<ll>> g(N);
	rep(i,N){
		g[i].push_back(sortedBpair[i].second);
	}
	debug(g);
	vector<ll> seen(N,-1);
	rep(i,N){
		if(seen[i]==-1){
			dfs(g,i,-1,0,seen);
		}
	}

	rep(i,N){
		if(seen[i]==N-1){
			p("No");return;
		}
	}
	p("Yes");
}

signed main() {
	solve();
	return 0;
}

