    for (int i = 0; i < N; ++i) cin >> A[i];
    vector<int>B(N);
    for (int i = 0; i < N; ++i) cin >> B[i];

    // 1. 条件を満たす並び替えが唯一つ存在するかどうかの判定
    vector<int>AC(A);
    vector<int>BC(B);
    sort(AC.begin(), AC.end());
    sort(BC.begin(), BC.end());

    // 1-1. 存在しない場合
    for (int i = 0; i < N; ++i) {
        if(AC[i] > BC[i]){
            cout << "No" << "\n";
            return 0;
        }
    }

    // 1-2. 複数存在する場合
    for (int i = 0; i < N-1; ++i) {
        if(BC[i] >= AC[i+1]){
            cout << "Yes" << "\n";
            return 0;
        }
    }

    // 2. 唯一つ存在する場合, それを実現するのが長さNの巡回置換であるか判定
    map<int, int> mpA; // ソート前のAから同じindexのBへの写像
    map<int, int> mpB; // ソート後のBから対応するAの値への写像
    for (int i = 0; i < N; ++i) {
        mpA[A[i]] = B[i];
        mpB[BC[i]] = AC[i];
    }
    int cur = BC[0];
    cur = mpB[cur];
    cur = mpA[cur];
    int cnt = 1;
    while (cur != BC[0]) {
        cur = mpB[cur];
        cur = mpA[cur];
        cnt++;
    }
    if(cnt == N){
        cout << "No" << "\n";
    } else {
        cout << "Yes" << "\n";
    }
