    rep(i,n){
        if(a[i].first>b[i].first){
            puts("No");
            return 0;
        }
        a[i].first = i;
        b[i].first = i;
    }
    rep(i,n){
        swap(a[i].first,a[i].second);
        swap(b[i].first, b[i].second);
    }
    sort(all(a)); sort(all(b));
    UnionFind uf(n);
    rep(i,n){
        uf.unite(a[i].first, b[i].first);
    }
    rep(i,n){
        if(uf.size(i)==n){
            puts("No");
            return 0;
        }
    }
    puts("Yes");
}

