    cin >> N;
    vector<int> A(N);
    vector<int> B(N);
    cin >> A >> B;
    if (check(A, B) == false) {
        cerr << "hukanou" << endl;
        cout << "No" << endl;
        return 0;
    }
    if (check1(A, B)) {
        cout << "Yes" << endl;
        return 0;
    }
    if (check2(A, B)) {
        cout << "Yes" << endl;
        return 0;
    }
    cout << "No" << endl;
    return -1;
    return 0;
}

