    vector<ll> A(N), B(N);
    for ( int i = 0; i < N; i++ ) cin >> A[i];
    for ( int i = 0; i < N; i++ ) cin >> B[i];
    vector<pii> ba;
    for ( int i = 0; i < N; i++ ) {
        ba.push_back(pii(B[i],A[i]));
    }
    sort(ba.begin(), ba.end());
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    for ( int i = 0; i < N; i++ ) {
        if ( A[i] > B[i] ) return false;
    }
    for ( int i = 0; i < N-1; i++ ) {
        if ( B[i] >= A[i+1] ) return true;
    }
    vector<ll> ia(N);
    for ( int i = 0; i < N; i++ ) {
        ia[i] = lower_bound(A.begin(), A.end(), ba[i].second) - A.begin();
    }
    ll k = 0;
    for ( int i = 0; i < N-1; i++ ) {
        k = ia[k];
        if ( k == 0 ) return true;
    }
    return false;
}

