int main(){
    int N;cin >> N;
       vector<int> A,B;
       for(int  i = 0;i < N;i++){
           int a;cin >> a;
           A.push_back(a);
       }
       for(int i = 0;i < N;i++){
           int b;cin >> b;
           B.push_back(b);
       }
       priority_queue<pair<int, int>> queA;
       multiset<pair<int, int>> se;
       for(int i = 0;i < N;i++){
           queA.push(make_pair(A[i], i));
           se.insert(make_pair(B[i], i));
       }

       for(int i = 0;i < N-2;i++){
           pair<int, int> q = queA.top();
           queA.pop();
           if(q.first <= B[q.second]){
               se.erase(se.find(make_pair(B[q.second], q.second)));
               continue;
           }else{
               if(se.upper_bound(make_pair(q.first, -1)) == se.end()){
                   cout<<"No"<<endl;
                   return 0;
               }
               auto it = *se.upper_bound(make_pair(q.first, -1));
               swap(B[it.second], B[q.second]);
               se.insert(make_pair(B[it.second], it.second));
               se.erase(se.find(it));
               if(B[it.second] < A[it.second]){
                   queA.push({A[it.second], it.second});
               }
           }
       }
       for(int i = 0;i < N;i++){
           if(A[i] > B[i]){
               cout<<"No"<<endl;
               return 0;
           }
