void dfsRing(const int &u, const int &p) {
    vstd[u] = 1, inStack[u] = 1, par[u] = p;
    for (auto &v : g[u]) if (v != p) {
        if (!vstd[v]) dfsRing(v, u);
        else if (inStack[v]) {
            ringOrig[++cntRing] = 1;
            int x = u;
            while (ring[x] = cntRing, x != v) x = par[x];
        }
    }
    if (!ring[u]) ring[u] = ++cntRing;
    inStack[u] = 0;
}

