// Function returns the minimum number of swaps
// required to sort the array
int minSwaps(int arr[], int n) {
  // Create an array of pairs where first
  // element is array element and second element
  // is position of first element
  pair<pair<ll, ll>, ll> arrPos[n];
  for (int i = 0; i < n; i++) {
    arrPos[i].first = {arr[i], i};
    arrPos[i].second = i;
  }

  // Sort the array by array element values to
  // get right position of every element as second
  // element of pair.
  sort(arrPos, arrPos + n);

  ll first1 = 0, last1 = 0;

  map<ll, pair<ll, ll>> par;
  ll prev1 = arrPos[0].first.first;
  for (ll i = 0; i < n; i++) {
    if (arrPos[i].first.first == prev1) {
      last1 = i;
    } else {
      par[prev1] = {first1, last1};
      first1 = i;
      last1 = i;
    }
    prev1 = arrPos[i].first.first;
  }

  par[prev1] = {first1, last1};

  // To keep track of visited elements. Initialize
  // all elements as not visited or false.
  vector<bool> vis(n, false);

  // Initialize result
  int ans = 0;

  // Traverse array elements
  for (int i = 0; i < n; i++) {
    // already swapped and corrected or
    // already present at correct pos
    if ((arrPos[i].second >= par[arrPos[i].first.first].first &&
         arrPos[i].second <= par[arrPos[i].first.first].second))
      return -1;
    if (vis[i])
      continue;

    // find out the number of  node in
    // this cycle and add in ans
    int cycle_size = 0;
    int j = i;
    while (!vis[j]) {
      vis[j] = 1;

      // move to next node
      j = arrPos[j].second;
      cycle_size++;
    }

    // Update answer by adding current cycle.
    if (cycle_size > 0) {
      ans += (cycle_size - 1);
    }
  }

  // Return result
  return ans;
}
