	for(int i = 1; i <= n; i++) {
		if(a[i].first > b[i].first) {
			ans = false;
			break;
		}
	}
	if(!ans) {
		puts("No");
		return 0;
	}
	for(int i = 1; i < n; i++)
		if(b[i].first >= a[i + 1].first) flag[i] = true;
	for(int i = n - 1; i >= 0; i--) {
		if(!flag[i]) ed[i] = 0;
		else ed[i] = ed[i + 1] + 1;
