int main() {
    int n;
    in(n);

    auto a = vin<int>(n);
    auto b = vin<int>(n);

    vector<pair<int, int>> ba(n);

    for (int i = 0; i < n; i++) {
        ba[i].first = b[i];
        ba[i].second = a[i];
    }

    sort(ba.begin(), ba.end());

    for (int i = 0; i < n; i++) {
        a[i] = ba[i].second;
        b[i] = ba[i].first;
    }

    auto c = a;
    sort(c.begin(), c.end());

    bool ans = true;

    for (int i = 0; i < n; i++) {
        if (c[i] > b[i]) {
            ans = false;
            break;
        }
    }

    vector<pair<int, int>> d(n);

    for (int i = 0; i < n; i++) {
        d[i].first = a[i];
        d[i].second = i;
    }

    sort(d.rbegin(), d.rend());

    vector<int> e(n);
    for (int i = 0; i < n; i++) {
        e[i] = d[i].second;
    }

    vector<int> f(n);
    for (int i = 0; i < n; i++) {
        f[e[i]] = i;
    }

    auto tmp = a;

    int rind = n - 1;
    for (int i = 0; i < n; i++) {
        int lind = e[i];

        if (a[lind] > b[rind]) {
            ans = false;
            break;
        }

        if (a[lind] > b[lind]) {
            swap(a[lind], a[rind]);
            swap(e[f[rind]], e[i]);
        }
    }

    int cnt = 0;

    for (int i = 0; i < n; i++) {
        if (a[i] != tmp[i]) {
            cnt++;
        }
    }

    cnt /= 2;

    if (cnt > n - 2) {
        ans = false;
    }

    out(ans ? "Yes" : "No");
}

