}

void build(int v, int tl, int tr) {
    if (tl == tr) {
        t[v] = {a[tl], tl};
    } else {
        int tm = (tl + tr) >> 1;
        build(left);
        build(right);
        upd(v);
    }
}


pii get(int v, int tl, int tr, int l, int r) {
    if (l > r)
        return {inf_int, inf_int};
    if (l > tr || r < tl)
        return {inf_int, inf_int};
    if (l <= tl && tr <= r) {
        return t[v];
    } else {
        int tm = (tl + tr) >> 1;
        return min(get(left, l, r), get(right, l, r));
    }
}

void update(int v, int tl, int tr, int pos, int val) {
    if (tl == tr) {
        t[v] = {val, pos};
    } else {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
            update(left, pos, val);
        else
            update(right, pos, val);
        upd(v);
    }
}


void solve() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; ++i) {
        cin >> b[i];
    }
    vector<pii> cc;
    for (int i = 1; i <= n; ++i) {
        cc.pb({b[i], a[i]});
    }
    sort(all(cc));

    vector<int> c(a + 1, a + n + 1);
    vector<int> d(b + 1, b + n + 1);

    sort(all(c));
    sort(all(d));
    for (int i = 0; i < sz(d); ++i) {
        if (c[i] > d[i]) {
            cout << "No\n";
            return;
        }
    }

    for (int i = 0; i < n; ++i) {
        a[i + 1] = cc[i].se;
        b[i + 1] = cc[i].fi;
    }

    for (int i = 1; i <= n; ++i) {
        dout << a[i] << " ";
    }
    dout << endl;
    for (int i = 1; i <= n; ++i) {
        dout << b[i] << " ";
    }
    dout << endl;

    int cnt = 0;
    build(1, 1, n);
    for (int i = 1; i <= n; ++i) {
        if (a[i] <= b[i]) {
            continue;
        }
        dout << i << " : " << a[i] << " - " << b[i] << endl;
        int pos;
        if (b[n] >= a[i]) {
            pos = n;
        } else {
            upper_bound(b + 1, b + n + 1, a[i]) - b;
        }
        pii res1 = get(1, 1, n, i + 1, pos - 1);
        dout << "ress " << res1.fi << " " << res1.se << endl;
        if (res1.fi <= b[i]) {
            int to = res1.se;
            swap(a[i], a[to]);
            update(1, 1, n, to, a[to]);
            cnt++;

            dout << "res1 : " << a[i] << " " << b[i] << endl;
            continue;
        }
        pii res2 = get(1, 1, n, i + 1, n);
        if (res2.fi > b[i])
            assert(false);
        int to = res2.se;
        swap(a[i], a[to]);
        update(1, 1, n, to, a[to]);
        cnt++;
        dout << "res2 : " << a[i] << " " << b[i] << endl;
    }
    if (cnt <= n - 2) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }


}


