const int MAX_N=1e6+1;
int A[MAX_N],B[MAX_N];
int N;

bool solve() {
  vector<II> BA(N);
  REP(i,N) BA[i]={B[i],A[i]};
  sort(ALL(BA));
  VI AA(N);
  REP(i,N)AA[i]=A[i];
  sort(ALL(AA));
  REP(i,N)if(AA[i]>BA[i].first) return false;
  REP(i,N-1) if(AA[i+1]<=BA[i].first) return true;

  vector<II> X;
  REP(i,N) X.emplace_back(A[i],i);
  sort(ALL(X));
  VI viz(N,0);
  function<void(int)> dfs=[&](int u)->void {
    if(viz[u]) return;
    viz[u]=1;
    dfs(X[u].second);
  };
  int cnt=0;
  REP(i,N)if(!viz[i]) ++cnt,dfs(i);
  return cnt>1;
}

