          if(A[i] == k && A[j] != B[j]){
            tmp[i] = A[i];
            A[i] = B[j];
            B[j] = tmp[i];
            count ++;
            flag = true;
            break;
          }
          if(flag){
            break;
          }
        }
      }
    }
  }
  if (count <= N-2){
    cout << "Yes" << endl;
  }
  else{
    cout << "No" << endl;
  }
}

