struct UnionFind {
    int N;
    vi dt; // 根なら要素数*(-1), 子なら親の番号が入る
    UnionFind(int n) : N(n), dt(n, -1) {}

    // 根の頂点番号を返す
    int root(int v){
        if (dt[v] < 0) return v;
        return dt[v] = root(dt[v]);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (size(x) < size(y)) swap(x,y);
        dt[x] += dt[y]; // 要素数を増やす (ただし負で計算)
        dt[y] = x; // 小さい方のグループ y の親を大きい方のグループ x に
        return true;
    }

    int size(int v) {return -dt[root(v)];}

    bool isConnect(int x, int y) {return root(x) == root(y);}
};

