int get(int r, int v = 0, int tl = 0, int tr = n){
    if (tl >= r) return 0;
    if (tr <= r) return t[v];
    int tm = tl + tr >> 1;
    return max(get(r, v+v+1, tl, tm),
               get(r, v+v+2, tm, tr));
}

void upd(int pos, int val, int v = 0, int tl = 0, int tr = n){
    if (tl == tr - 1){
        t[v] = val;
        return;
    }
    int tm = tl + tr >> 1;
    if (pos < tm){
        upd(pos, val, v+v+1, tl, tm);
    }
    else{
        upd(pos, val, v+v+2, tm, tr);
    }
    t[v] = max(t[v+v+1], t[v+v+2]);
}

int first_greater(int x){
    int l = -1, r = n-1;
    while (r - l > 1){
        int m = l + r >> 1;
        if (get(m+1) < x){
            l = m;
        }
        else{
            r = m;
        }
    }
    return r;
}

