int main(){
  int n;
  cin >> n;

  vector<int> a(n), b(n);
  cin >> a,b;

  vector<int> d(n);
  for(int i=0; i<n; i++){
    d[i] = b[i] - a[i];
  }

  vector<int> v(n);
  iota(v.begin(), v.end(), 0);
  sort(v.begin(), v.end(), [&](int i, int j){
    if(b[i] == b[j]) return a[i] > a[j];
    return b[i] > b[j];
  });

  multiset<pair<int,int>> p;
  int s = 0;

  vector<pair<int,int>> pending;
  int prev_b = *max_element(b.begin(), b.end()) + 1;
  for(int i: v){
    if(b[i] < prev_b){
      for(auto x : pending){
        p.insert(x);
      }
      pending = vector<pair<int,int>>(0);
      prev_b = b[i];
    }
    if(d[i] >= 0){
      pending.emplace_back(d[i], i);
    }else{
      int l = - d[i];
      auto itr = p.lower_bound(make_pair(l, -1));
      if(itr == p.end()){
        println("No");
        return 0;
      }

      int j = itr->second;
      p.erase(itr);

      swap(a[i], a[j]);
      d[i] = b[i] - a[i];
      d[j] = b[j] - a[j];
      assert(d[i] >= 0);
      assert(d[j] >= 0);
      if(b[i] == prev_b){
        pending.emplace_back(d[i], i);
      }else{
        p.insert(make_pair(d[i], i));
      }
      if(b[j] == prev_b){
        pending.emplace_back(d[j], j);
      }else{
        p.insert(make_pair(d[j], j));
      }
      s++;
    }
  }

  if(s <= n-2){
    println("Yes");
  }else{
    println("No");
  }

  return 0;
}

