	{
		cin >> a;
	}
	vector<int> B(N, 0);
	for (auto && b : B)
	{
		cin >> b;
	}

	int move_counter = 0;
	while (1)
	{
		bool is_finish = true;
		for (int i = 0; i < N; i++)
		{
			if (A[i] > B[i]) // NG
			{
				is_finish = false;
				bool is_found = false;
				for (int j = 0; j < N; j++)
				{
					if (A[j] <= B[i]) // 移動後のiがOK
					{
						if (A[i] <= B[j]) // 移動後のjがOK
						{
							// 移動する
							std::swap(A[i], A[j]);
							move_counter++;
							is_found = true;
							break;
						}
						else if (A[j] > B[j]) // 移動前のjがNG
						{
							// 改悪ではないので
