vector<int> calc_sum(vector<bool> a) {
    int N = a.size();
    vector<int> sum(N + 1);
    rep(i, N) sum[i + 1] = sum[i] + a[i];
    return sum;
}

int main() {
    int N; cin >> N;
    vector<i_i> ai(N), bi(N);
    rep(i, N) {
        int x; cin >> x;
        ai[i] = i_i(x, i);
    }
    rep(i, N) {
        int x; cin >> x;
        bi[i] = i_i(x, i);
    }
    sort(all(ai));
    sort(all(bi));
    vector<int> a(N), b(N);
    vector<int> p(N), q(N);
    rep(j, N) {
        int x, i;
        tie(x, i) = ai[j];
        a[j] = x;
        p[i] = j;
    }
    rep(j, N) {
        int x, i;
        tie(x, i) = bi[j];
        b[j] = x;
        q[i] = j;
    }
    vector<bool> same(N), left(N), right(N);
    rep(j, N) same[j] = (a[j] <= b[j]);
    rep(j, N) left[j] = (j - 1 >= 0 && a[j] <= b[j - 1]);
    rep(j, N) right[j] = (j + 1 < N && a[j] <= b[j + 1]);
    vector<int> same_sum = calc_sum(same);
    vector<int> left_sum = calc_sum(left);
    vector<int> right_sum = calc_sum(right);
    int ok = 0;
    rep(i, N) {
        int j = p[i];
        int k = q[i];
        if (a[j] <= b[k]);
        else continue;
        int cnt = 0;
        if (j == k) {
            cnt += same_sum[j] - same_sum[0];
            cnt += same_sum[N] - same_sum[j + 1];
        }
        if (j < k) {
            cnt += same_sum[j] - same_sum[0];
            cnt += same_sum[N] - same_sum[k + 1];
            cnt += left_sum[k + 1] - left_sum[j + 1];
        }
        if (j > k) {
            cnt += same_sum[k] - same_sum[0];
            cnt += same_sum[N] - same_sum[j + 1];
            cnt += right_sum[j] - right_sum[k];
        }
        // cout << j << ' ' << k << ' ' << cnt << endl;
        if (cnt == N - 1) ok++;
    }
    cout << (ok ? "Yes" : "No") << endl;
    cerr << ok << endl;
}


