int N;

bool check(vector<int> A, vector<int> B) {
    sort(ALL(A));
    sort(ALL(B));
    for (int i : range(N)) {
        if (A[i] > B[i]) return false;
    }
    return true;
}
bool check1(vector<int> A, vector<int> B) {
    sort(ALL(A));
    sort(ALL(B));
    for (int i : range(N - 1)) {
        if (A[i + 1] <= B[i]) return true;
    }
    return false;
}


bool check2(vector<int> A, vector<int> B) {
    vector<int> id(N);
    vector<int> AA = A;
    vector<int> BB = B;
    sort(ALL(AA));
    sort(ALL(BB));
    map<pair<int, int>, int> cnt;
    for (int i : range(N)) {
        cnt[{AA[i], BB[i]}]++;
    }
    for (int i : range(N)) {
        if (cnt[{A[i], B[i]}] > 0) {
            return true;
        }
    }
    return false;
}

