void solve() {
	int n = fetch<int>();
	auto a = fetch_vec<int>(n);
	auto b = fetch_vec<int>(n);

	auto ord_a = a;
	sort(ord_a.begin(), ord_a.end());

	auto ord_b = b;
	sort(ord_b.begin(), ord_b.end());

	for(int i = 0; i < n; ++i) {
		if(ord_a[i] > ord_b[i]) {
			cout << "No\n";
			return;
		}
	}

	for(int i = 1; i < n; ++i) {
		if(ord_b[i - 1] == ord_b[i]) {
			cout << "Yes\n";
			return;
		}
	}

	vector<int> fst(n);

	for(int i = 0; i < n; ++i) {
		fst[i] = lower_bound(ord_b.begin(), ord_b.end(), ord_a[i]) - ord_b.begin();
	}

	sort(fst.begin(), fst.end());

	for(int i = 1; i < n; ++i) {
		if(fst[i - 1] == fst[i]) {
			cout << "Yes\n";
			return;
		}
	}

	vector<int> p(n, NIL), used(n, 0);
	int cycles = 0;

	for(int i = 0; i < n; ++i) {
		p[i] = lower_bound(ord_a.begin(), ord_a.end(), a[i]) - ord_a.begin();
	}

	for(int i = 0; i < n; ++i) {
		if(!used[i]) {
			++cycles;

			for(int j = i; !used[j]; j = p[j]) {
				used[j] = 1;
			}
		}
	}

	DBG(cycles);
	cout << (cycles > 1 ? "Yes\n" : "No\n");
}

int main() {
	fast_io();
	solve();

	return 0;
}

