};

int UnionFind::find(int x) {
	if (par[x] < 0) return x;
	else return par[x] = find(par[x]);
}

ll UnionFind::size(int x) {
	return -par[find(x)];
}

void UnionFind::unite(int x, int y) {
	x = find(x);
	y = find(y);
 	if (x == y) return;
	//大きい方に小さい方をくっ付ける
	if (size(x) < size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
}

bool UnionFind::same(int x, int y) {
	x = find(x);
	y = find(y);
	return x == y;
}

void solve() {
    int n; cin >> n;
    vector<pair<int, int>> AB(n);
    rep (i, n) cin >> AB[i].first;
    rep (i, n) cin >> AB[i].second;
    sort(all(AB), cmp);
    vector<int> idx(n);
    iota(all(idx), 0);
    sort(all(idx), [&](int i, int j) {return AB[i].first < AB[j].first;});

    // rep (i, n) cout << idx[i] << " " << AB[idx[i]].first << " "; cout << endl;

    rep (i, n) if (AB[idx[i]].first > AB[i].second) {
        // cout << 1 << endl;
        cout << "No" << endl;
        return;
    }

    UnionFind uf(n);
    rep (i, n) uf.unite(i, idx[i]);
    if (uf.size(0) != n) {
        cout << "Yes" << endl;
    } else {
        rep (i, n - 1) {
            if (AB[idx[i + 1]].first <= AB[i].second) {
                cout << "Yes" << endl;
                return;
            }
        }
        // cout << 2 << endl;
        cout << "No" << endl;
    }
    return;
}

