class SegmentTree{


inline int left (int p) { return p << 1; }
inline int right(int p) { return (p << 1) + 1; }

public:

vector<int> A, st; int n;

void build(int p, int L, int R){

	if(L == R) st[p] = L; //index

	else{

	int mid = (L+R)>> 1;

	int l = left(p);
	int r = right(p);

	build(l, L, mid);
	build(r, mid + 1, R);

	int p1 = st[l];
	int p2 = st[r];

	st[p] = (A[p1] <= A[p2])? p1 : p2;

	}

}

void update(int p, int L, int R, int index){

    if(index < L || index > R) return;

	if(L == R && L == index) st[p] = index; //index

	else{

        int mid = (L+R)>> 1;

        int l = left(p);
        int r = right(p);

        update(l, L, mid, index);
        update(r, mid + 1, R, index);

        int p1 = st[l];
        int p2 = st[r];

        // if(p1 == -1) st[p] = p2;
        // else if(p2 == -1) st[p] = p1;
        // else
        st[p] = (A[p1] <= A[p2]) ? p1 : p2;
    }

}

int rmq(int p, int L, int R, int i, int j){

	if(L > j || R < i) return -1; // non-existent
	if(L >= i && R <= j) return st[p];

	int mid = (L+R)>> 1;

	int l = left(p);
	int r = right(p);

	int p1 = rmq(l, L, mid, i, j);
	int p2 = rmq(r, mid + 1, R, i, j);

    if(p1 == -1) return p2;
	if(p2 == -1) return p1;

	return (A[p1] <= A[p2]) ? p1 : p2;
}

SegmentTree(const vector<int> &A){
    this->A = A;
    this->n = A.size();
	st.assign(4*n, -1);
    build(1, 0, n - 1);
}

int rmq(int i, int j){ return rmq(1, 0, n - 1, i, j); }

};

int main(){

    cin.tie(0); cout.tie(0);
    ios_base::sync_with_stdio(0);

    int n;
    cin >> n;

    int a[n], b[n];
    for(int i = 0; i < n; ++i) cin >> a[i];
    for(int j = 0; j < n; ++j) cin >> b[j];

    int io[n];
    iota(io, io + n, 0);
    sort(io, io + n, [&](int x, int y){return b[x] < b[y];});

    vector<int> A, B;

    for(int i = 0; i < n; ++i){
        A.push_back(a[io[i]]); // (A)s
        B.push_back(b[io[i]]); // (B)s
    }

    SegmentTree seg(A);

    int swaps = 0;

    for(int i = 0; i < n; ++i){
        if(A[i] > B[i]){
            auto lb = lower_bound(all(B), A[i]) - B.begin();
            if(lb == n) return puts("No");
            int smallest_index = seg.rmq(lb, n - 1);
            if(smallest_index != -1 && A[smallest_index] <= B[i]){
                // cout << A[i] << " " << A[smallest_index] << endl;
                swap(A[i], A[smallest_index]);
                swap(seg.A[i], seg.A[smallest_index]);
                seg.update(1, 0, n - 1, smallest_index);
                seg.update(1, 0, n - 1, i);
                swaps++;
            }
        }
    }

    for(int i = 0; i < n; ++i){
        if(A[i] > B[i]) return puts("No"), 0;
    }

    return puts((swaps > n - 2) ? "No" : "Yes"), 0;
}

