#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

typedef std::pair<int,int> pair;

bool sub_solve(int t, const std::vector<pair> a, const std::vector<pair> b)
{
    const int n = a.size();
    int ptr_a = n - 1, ptr_b = n - 1;

    while(ptr_a >= 0) {
        if (a[ptr_a].second == t) {ptr_a--;}
        if (b[ptr_b].second == t) {ptr_b--;}

        if (a[ptr_a].first > b[ptr_b].first) {return false;}

        ptr_a--;
        ptr_b--;
    }

    return true;
}

bool solve(const std::vector<int> a, const std::vector<int> b)
{
    std::vector<pair> a_pair, b_pair;

    const int n = a.size();
    a_pair.resize(n);
    b_pair.resize(n);

    for (int i = 0; i < n; i++) {
        a_pair[i].first = a[i];
        a_pair[i].second = i;
        b_pair[i].first = b[i];
        b_pair[i].second = i;
    }

    std::sort(a_pair.begin(), a_pair.end(), [](const pair& a, const pair& b){return a.first < b.first;});
    std::sort(b_pair.begin(), b_pair.end(), [](const pair& a, const pair& b){return a.first < b.first;});

    for (int i = 0; i < n; i++) {
        if ((a[i] <= b[i]) && sub_solve(i, a_pair, b_pair)) {
            return true;
        }
    }

    return false;
}

int main(int argc, char *argv[])
{
    int n;
    std::vector<int> a, b;

    bool possible = false;

    std::cin >> n;

    a.resize(n);
    b.resize(n);

    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        std::cin >> b[i];
    }

    possible = solve(a, b);

    if (possible) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }

    return 0;
}

