struct union_find{
	typedef unsigned size_type;
	vector<int> par;
	size_type grs;
	explicit union_find(size_type n = 0){ init(n); }
	void init(size_type n){
		par.assign(n, -1);
		grs = n;
	}
	size_type find(size_type x){
		if(par[x] < 0){ return x; }
		return par[x] = find(par[x]);
	}
	size_type size(size_type x){
		return -par[find(x)];
	}
	size_type groups(){
		return grs;
	}
	bool unite(size_type x, size_type y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(par[x] < par[y]){ swap(x, y); }
		par[y] += par[x];
		par[x] = y;
		--grs;
		return true;
	}
	bool same(size_type x, size_type y){
		return find(x) == find(y);
	}
	bool is_root(size_type x){
		return find(x) == x;
	}
};

bool check1(vint as, vint bs){
	int n = as.size();
	sort(ALL(as));
	sort(ALL(bs));
	for(int i = 0; i < n; ++i){
		if(as[i] > bs[i]){ return false; }
	}
	return true;
}

bool solve(){
	int n;
	scanf("%d", &n);
	vector<pii> ps(n);
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].second); }
	for(int i = 0; i < n; ++i){ scanf("%d", &ps[i].first); }
	sort(ALL(ps));
	vector<int> as(n), bs(n);
	for(int i = 0; i < n; ++i){
		as[i] = ps[i].second;
		bs[i] = ps[i].first;
	}

	if(!check1(as, bs)){ return false; }

	vector<int> ls(n);
	for(int i = 0; i < n; ++i){
		ls[i] = lower_bound(ALL(bs), as[i]) - bs.begin();
		if(ls[i] >= n){ return false; }
	}

	vector<int> pos(n);
	iota(ALL(pos), 0);
	vector<int> inv = pos;
	VV(int) grps(n);
	int nxt = 0;
	for(int i = 0; i < n; ++i){ grps[ls[i]].push_back(i); }
	for(int i = 0; i < n; ++i){
		auto grp = grps[i];
		for(int x : grp){
			if(pos[x] <= i){ return true; }
		}
		sort(ALL(grp), [&](int x, int y){ return pos[x] < pos[y]; });
		for(int x : grp){
			int z = inv[nxt];
			swap(pos[x], pos[z]);
			inv[pos[x]] = x;
			inv[pos[z]] = z;
			++nxt;
		}
	}

	return false;
}

void mainmain(){
	puts(solve() ? "Yes" : "No");
}



