    sort(sb + 1, sb + n + 1);

    for (i64 i = 1; i <= n; i++) {
        qa[sa[i]] = i;
        qb[sb[i]] = i;
    }


    for (i64 i = 1; i <= n; i++) {
        psame[i] = psame[i - 1] + (sa[i] <= sb[i] ? 1 : 0);
