#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

vvi factorize_replaces(vii& replaces){
    unordered_map<int,int> mp;
    vvi res;
    for (ii& p : replaces) {
        mp[p.first] = p.second;
    }
    while (!mp.empty()){
        vi tmp;
        int u = mp.begin()->first;
        while (found(mp,u)) {
            tmp.pb(u);
            int v = mp[u];
            mp.erase(u);
            u = v;
        }
        res.pb(tmp);
    }
    return res;
}

bool solve(int N, vi& a, vi& b) {
    vii ax(N), bx(N);
    rep(i,N){
        ax[i] = ii(a[i], i);
        bx[i] = ii(b[i], i);
    }
    sort(ALL(ax));
    sort(ALL(bx));
    vii replaces(N);
    rep(i,N){
        if (!(ax[i].first <= bx[i].first)) return false;
        replaces[i] = ii(ax[i].second, bx[i].second);
    }
    vvi res = factorize_replaces(replaces);
    if (res.size() >= 2) return true;

    rep(i,N-1){
        if (!(ax[i+1].first <= bx[i].first)) return true;
    }
    return false;
}

int main() {
    int N; scanf("%d%*c", &N);
    vi a(N), b(N);
    loadvec(a,N); loadvec(b,N);
    cout << (solve(N,a,b) ? "Yes":"No") << endl;
    return 0;
}

