signed main() {

    SS(int, N);

    A.resize(N);
    B.resize(N);
    V.resize(N);
    REP(i, N) { cin >> V[i].second; A[i] = V[i].second; }
    REP(i, N) { cin >> V[i].first;  B[i] = V[i].first; }
    // SORT(V);

    SORT(A);
    SORT(B);
    REP(i, N) if (A[i] > B[i]) return Yes(0);

    CumulativeSum<int> L(N), R(N);
    REP(i, 1, N)  L.add(i, int(A[i] <= B[i - 1]));
    REP(i, N - 1) R.add(i, int(A[i] <= B[i + 1]));
    L.build();
    R.build();

    auto A_g = groupby(A);
    auto B_g = groupby(B);

    // [L, R]
    map<int, pair<int, int>> mp_A, mp_B;
    int cnt = 0;
    EACH(p, A_g) {
        int num, q;
        tie(num, q) = p;
        mp_A[num] = make_pair(cnt, cnt + q - 1);
        cnt += q;
    }
    cnt = 0;
    EACH(p, B_g) {
        int num, q;
        tie(num, q) = p;
        mp_B[num] = make_pair(cnt, cnt + q - 1);
        cnt += q;
    }
    // debug(mp_A);
    // debug(mp_B);

    REP(i, N) {
        int a, b;
        tie(b, a) = V[i];
        pair<int, int> ap = mp_A[a], bp = mp_B[b];
        if (a > b) continue;
        // 共通部分あり
        if (ap == bp) return Yes(1);
        if (ap.first <= bp.second and ap.second >= bp.first) return Yes(1);
        if (bp.first <= ap.second and bp.second >= ap.first) return Yes(1);
        // apの方が左
        if (ap.second < bp.first) {
            int l = ap.second;
            int r = bp.first;
            // [l + 1, r + 1)
            int len = r - l;
            if (L.query(l + 1, r + 1) == len) return Yes(1);
        }
        // apの方が右
        if (ap.first > bp.second) {
            int l = bp.second;
            int r = ap.first;
            // [l, r)
            int len = r - l;
            if (R.query(l, r) == len) return Yes(1);
        }
    }

    // Yes(0);
    exit(1);

}

