template <typename T, typename F>
struct segment_tree
{
private:
  size_t n;
  vector <T> node;
  F f;
  T init;
  auto matsudai (size_t i) noexcept
  {
    return i + n - 1;
  }
  static auto parent (size_t index) noexcept
  {
    return (index - 1) / 2;
  }
  static auto child_left (size_t index) noexcept
  {
    return 2 * index + 1;
  }
  static auto child_right (size_t index) noexcept
  {
    return 2 * index + 2;
  }

public:
  explicit segment_tree (const vector <T> & v, T init_, F f_)
  {
    auto sz = v.size ();
    assert (sz > 0);
    for (n = 1; n < sz; n *= 2);
    node = vector <T> (2 * n - 1, init_);
    init = init_;
    f = f_;
    rep (i, sz) node [matsudai (i)] = v [i];
    for (size_t i = n - 1; i -- > 0;) node [i] = f (node [child_left (i)], node [child_right (i)]);
  }
  auto update (size_t index, const T & value) noexcept
  {
    auto i = matsudai (index);
    node [i] = value;
    while (i > 0)
    {
      i = parent (i);
      node [i] = f (node [child_left (i)], node [child_right (i)]);
    }
  }
  auto get (size_t first, size_t last, size_t i, size_t l, size_t r)
  {
    if (r <= first || last <= l)
    {
      // 無関係
      return init;
    }
    if (first <= l && r <= last)
    {
      // 担当範囲
      return node [i];
    }
    // 担当範囲から一部はみ出している
    auto mid = (l + r) / 2;
    auto cl = get (first, last, child_left (i), l, mid);
    auto cr = get (first, last, child_right (i), mid, r);
    return f (cl, cr);
  }
  auto get (size_t first, size_t last)
  {
    return get (first, last, 0, 0, n);
  }

  auto swap_element (size_t i, size_t j)
  {
    auto i_elem = node [matsudai (i)];
    auto j_elem = node [matsudai (j)];
    swap (i_elem, j_elem);
    update (i, i_elem);
    update (j, j_elem);
  }
};

