long long mul(long long a, long long b, long long mod) {
    long long keta[20] = {};
    long long c = b;
    long long now = 0;
    while (c != 0ll) {
        keta[now] = c % 10; c /= 10; now++;
    }
    long long res = 0;
    for (int i = 19; i >= 0; --i) {
        res *= 10; res %= mod;
        res += keta[i] * a % mod;
    }
    return res % mod;
}

bool cmp(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

class UnionFind {
private:
	vector<int> par;
public:
	UnionFind(int N) { par = vector<int>(N, -1); }
	int find(int x);
	ll size(int x);
	void unite(int x, int y);
	bool same(int x, int y);
};

int UnionFind::find(int x) {
	if (par[x] < 0) return x;
	else return par[x] = find(par[x]);
}

ll UnionFind::size(int x) {
	return -par[find(x)];
}

void UnionFind::unite(int x, int y) {
	x = find(x);
	y = find(y);
 	if (x == y) return;
	//大きい方に小さい方をくっ付ける
	if (size(x) < size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
}

bool UnionFind::same(int x, int y) {
	x = find(x);
	y = find(y);
	return x == y;
}

void solve() {
    int n; cin >> n;
    vector<pair<int, int>> AB(n);
    rep (i, n) cin >> AB[i].first >> AB[i].second;
    sort(all(AB), cmp);
    vector<int> idx(n);
    iota(all(idx), 0);
    sort(all(idx), [&](int i, int j) {return AB[i].first < AB[j].first;});

    rep (i, n) if (AB[idx[i]].first > AB[i].second) {
        cout << "No" << endl;
        return;
    }

    UnionFind uf(n);
    rep (i, n) uf.unite(i, idx[i]);
    if (uf.size(0) != n) {
        cout << "Yes" << endl;
    } else {
        rep (i, n - 1) {
            if (AB[idx[i] + 1].first <= AB[idx[i]].second) {
                cout << "Yes" << endl;
                return;
            }
        }
        cout << "No" << endl;
    }
    return;
}

