}

void solve(long long N, std::vector<long long> A, std::vector<long long> B){
  bool ok = true;
  vl A2, B2, idx(N);
  A2 = A; B2 = B;
  sort(ALL(A2)); sort(ALL(B2));
  rep(i,N) ok &= (A2[i]<=B2[i]);
  if(!ok){
    yn(false); return;
  }
  bool flg = false;
  rep(i,N-1){
    // A[i] <= B[i+1] && A[i+1] <= B[i] なら perm が2つ存在する, 前者は元々満たす
    flg |= (A2[i+1] <= B2[i]);
  }
  if(flg){
    yn(true); return;
  }

  iota(ALL(idx), 0LL);
  sort(ALL(idx), [&](ll l,ll r){
    return B[l] < B[r];
  });
  vi g(N);
  ll cnt = 0;
  function<void(int)> dfs = [&](int u){
    cnt++;
    if(idx[u]==0) return;
    dfs(idx[u]);
  };
  dfs(0);
  dump(cnt);
  yn(cnt < N);
}

int main(){
  std::cout << std::fixed << std::setprecision(15);
  long long N;
  scanf("%lld",&N);
  std::vector<long long> A(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&A[i]);
  }
  std::vector<long long> B(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&B[i]);
  }
  solve(N, std::move(A), std::move(B));
  return 0;
}

