vector<int> transform(int N, vector<int> A, vector<int> p) {
	vector<int> ans(N);
	for (int i = 0; i < N; ++i) {
		ans[i] = A[p[i]];
	}
	return ans;
}
int main() {
	int N;
	cin >> N;
	vector<int> A(N), B(N), p(N), q(N);
	for (int i = 0; i < N; ++i) cin >> A[i], p[i] = i;
	for (int i = 0; i < N; ++i) cin >> B[i], q[i] = i;
	sort(q.begin(), q.end(), [&](int i, int j) { return B[i] < B[j]; });
	A = transform(N, A, q);
	B = transform(N, B, q);
	sort(p.begin(), p.end(), [&](int i, int j) { return A[i] < A[j]; });
