    multiset <i2> A, B;
    for (int i = 0; i < n; i++) {
        if (S.find(i2(a[i], b[i])) != S.end()) {
            S.erase(S.find(i2(a[i], b[i])));
        }
        else {
            A.insert(i2(a[i], b[i]));
            B.insert(i2(b[i], a[i]));
        }
    }
    while ((int)A.size() != 0) {
        i2 x = *A.rbegin();
        if (S.find(x) != S.end()) {
            A.erase(A.find(x));
            B.erase(B.find(i2(x.second, x.first)));
            S.erase(S.find(x));
