int prepare(int b, int e, int node){
	if(b == e){
		return tree[node] = e;
	}

	int m = (b+e)>>1, node2 = node << 1;
	int l = prepare(b,m,node2+1);
	int r = prepare(m+1,e,node2+2);
	if(elem[l].f <= elem[r].f){
		return tree[node] = l;
	}
	return tree[node] = r;
}

int update(int b, int e, int node, int p){
	if(p < b || p > e) return tree[node];
	if(b == e) return tree[node] = e;
	int m = (b+e)>>1, node2 = node << 1;
	int l = update(b,m,node2+1,p);
	int r = update(m+1,e,node2+2,p);
	if(elem[l].f <= elem[r].f){
		return tree[node] = l;
	}
	return tree[node] = r;
}

int query(int bq, int eq, int node, int bt, int et){
	if(bt > eq || et < bq) return -1;

	if(bq <= bt && et <= eq) return tree[node];

	int mid = (bt + et) >> 1;
	int leftMin = query(bq, eq, (node<<1) + 1, bt, mid);
	int rightMin = query(bq, eq, (node<<1) + 2, mid+1, et);

	if(leftMin == -1) return rightMin;
	if(rightMin == -1) return leftMin;

	return A[leftMin] < A[rightMin] ? leftMin : rightMin;
}

int bs_lower(int b, int Ai){
	int e = N-1, f = -1;
	while(b <= e){
		int m = (b+e)>>1;
		if(elem[m].s <= Ai){
			e = m-1;
			f = m;
		}
		else{
			b = m+1;
		}
	}
	return f;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	for(int i = 0; i < N; i++){
		cin >> elem[i].f;
		A[i] = elem[i].f;
	}

	for(int i = 0; i < N; i++){
		cin >> elem[i].s;
		B[i] = elem[i].s;
	}

	sort(A,A+N);
	sort(B,B+N);
	for(int i = 0; i < N; i++){
		if(A[i] > B[i]){
			cout << "No" << endl;
			return 0;
		}			
	}

	sort(elem, elem+N);

	prepare(0, N-1, 0);

	int swaps = 0;
	for(int i = 0; i < N; i++){
		if(elem[i].f <= elem[i].s){
			continue;
		}

		swaps++;

		int j = bs_lower(i+1,elem[i].f);
		if(j != -1){
			int l = query(j,N-1,0,0,N-1);
			if(elem[l].f <= elem[i].s){
				int s = elem[l].f;
				elem[l].f = elem[i].f;
				update(0,N-1,0,l);
				elem[i].f = s;
				update(0,N-1,0,i);
				continue ;
			}
		}

		int l = query(i+1,N-1,0,0,N-1);
		int s = elem[l].f;
		elem[l].f = elem[i].f;
		update(0,N-1,0,l);
		elem[i].f = s;
		update(0,N-1,0,i);
	}
	cout << (swaps <= N-2 ? "Yes" : "No") << endl;
	return 0;
}

