void bld1(int l,int r,int i){
	if(l==r){
		sgt1[i]=(a[l]<=b[l-1]);
		return ;
	}
	int mid=(l+r)/2;
	bld1(l,mid,2*i+1);
	bld1(mid+1,r,2*i+2);
	sgt1[i]=sgt1[2*i+1]&sgt1[2*i+2];
