        v.emplace_back(B[i] - A[i], i);
    }
    SORT(v);
    REP(i, min(5000LL, SZ(v))) {
        vector<int> a, b;
        REP(i, N) {
            if (i == p) continue;
            a.push_back(A[i]);
            b.push_back(B[i]);
        }
        SORT(a);
        SORT(b);
        bool ng = false;
        REP(i, SZ(a)) {
            if (a[i] > b[i]) {
                ng = true;
                break;
            }
        }
        if (ng) continue;
        cout << "Yes" << endl;
        return;
    }
    cout << "No" << endl;
}

