	/*
		根据 b 排序，使 a 也有序的最少交换次数。 
		n - 2 次交换是否能使序列有序。

		3 1 6 4 3 2
		2 2 3 3 4 8

		1 2 3 3 4 6 
	*/

	ll n, A[N];

	struct Node {
		ll a, b;
	} K[N];

	inline bool cmp (Node a, Node b) {
		return a.b == b.b? a.a < b.a: a.b < b.b;
	}

	int main() {
		n = read();
		For ( i, 1, n ) A[i] = K[i].a = read();
		For ( i, 1, n ) K[i].b = read();
		sort(A + 1, A + n + 1);
		sort(K + 1, K + n + 1, cmp);

		For ( i, 1, n ) if (A[i] > K[i].b) return puts("No"), 0;
		For ( i, 1, n ) if (K[i].a == A[i]) return puts("Yes"), 0;
		return puts("Yes"), 0;
	}

}

