//UNION FIND
struct UnionFind{
    vector<int> par;
    vector<int> rank;

    //n要素で初期化
    UnionFind(int n) : par(n), rank(n){
        for (int i=0; i<n; ++i){
            par[i] = i;
            rank[i] = 0;
        }
    }

    //木の根を求める
    int root(int x){
        if (par[x] == x){
            return x;
        }else{
            return par[x] = root(par[x]);
        }
    }

    //xとyの属する集合を併合
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if (rank[x] == rank[y]) ++rank[x];
        }
    }

    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

