ll num_of_cycle(vector<ll> &A){
	ll N = A.size();
	vector<pll> X(N);
	REP(i, N){
		X[i].first = A[i];
		X[i].second = i;
	}
	sort(X.begin(), X.end());

	/*
	REP(i, N){
		cout << X[i].second << " ";
	}
	cout << endl;
	*/

	vector<bool> visited(N, false);
	ll cnt = 0;
	REP(i, N){
		if(visited[i]) continue;
		ll start = i;
		ll now = start;
		while(1){
			visited[now] = true;
			now = X[now].second;
			if(now == start) break;
		}
		cnt++;
	}
	return cnt;
}

