namespace Cesare {

	/*
		根据 b 排序，使 a 也有序的最少交换次数。 
		n - 2 次交换是否能使序列有序。

		3 1 6 4 3 2
		2 2 3 3 4 8

		1 2 3 3 4 6 
	*/

	ll n, A[N];

	struct Node {
		ll a, b;
	} K[N];

	inline bool cmp (Node a, Node b) {
		return a.b == b.b? a.a < b.a: a.b < b.b;
	}

