		For ( i, 1, n ) A[i] = K[i].a = read();
		For ( i, 1, n ) K[i].b = read();
		sort(A + 1, A + n + 1);
		sort(K + 1, K + n + 1, cmp);

		For ( i, 1, n ) if (A[i] > K[i].b) return puts("No"), 0;
		For ( i, 1, n ) if (K[i].a == A[i]) return puts("Yes"), 0;
		return puts("No"), 0;
	}

}

