	ios::sync_with_stdio(false);
	cin.tie(0);

	ll n;
	cin >> n;

	Array a(n), b(n);
	REP(i, n)cin >> a[i];
	REP(i, n)cin >> b[i];
	vector<P> ab(n);
	REP(i, n)ab[i] = make_pair(a[i], b[i]);
	sort(all(ab), [](P x, P y) {
		if (x.second == y.second)return x.first < y.first;
		else return x.second < y.second;
	});

	sort(all(b));

	RmqTree2 rmq(n+1);

	REP(i, n)rmq.update(i, make_pair(-ab[i].first, i));

	ll cnt = 0;
	for (int i = n - 1; i >= 0; i--) {
		ll now = -rmq.find(i, i + 1).first;
		if (now <= ab[i].second)continue;

		ll l = lower_bound(all(b), now) - b.begin();
	//	cout << l << endl;
		if (l == n) {
			cout << "No" << endl;
			return 0;
		}

		while (1) {
			P ma = rmq.find(l, n);
			if (ma.first == INF) {
				cout << "No" << endl;
				return 0;
			}

			if (-ma.first <= b[i]) {
				rmq.update(ma.second, make_pair(-now, ma.second));
				rmq.update(i, make_pair(ma.first, i));
				cnt++;
				break;
			}
			else {
				rmq.update(ma.second, make_pair(INF,INF));
			}
		}
