int a[MAXN], b[MAXN];

int parent[MAXN];
int siz[MAXN];

void init(int n) {
    for (int i = 1; i <= n; ++i) {
        parent[i] = i;
        siz[i] = 1;
    }
}

int get_parent(int v) {
    if (parent[v] == v)
        return v;
    return parent[v] = get_parent(parent[v]);
}

void union_set(int a, int b) {
    a = get_parent(a);
    b = get_parent(b);
    if (a != b) {
        parent[b] = a;
        siz[a] += siz[b];
    }
}

int pos[MAXN];
int used[MAXN];

void solve() {
    int n;
    cin >> n;
    init(n);

    for (int i = 1; i <= n; ++i) {
