    for (int i = 1; i <= n; ++i) {
        cc.pb({a[i], i});
        dd.pb({b[i], i});
    }
    sort(all(cc));
    sort(all(dd));
    for (int i = 0; i < n; ++i) {
        int x = dd[i].se;
        int y = cc[i].se;
        pos[y] = x;
    }
    for (int i = 1; i <= n; ++i) {
        if (used[i])
            continue;
        if (b[i] < a[i]) {
            int v = i;
            while (!used[v]) {
                union_set(v, pos[v]);
                used[v] = 1;
                v = pos[v];

            }
        }
    }

    if (siz[get_parent(1)] == n) {
        cout << "No";
        return;
    }
    cout << "Yes\n";

}


