template <typename T>
struct SegmentTree {
  vector<T> v;
  function<T(T, T)> f;
  T e;
  int n;
  SegmentTree(int size, function<T(T, T)> f, T e) : f(f), e(e) {
    n = 1;
    while (n < size) n <<= 1;
    v.resize(n * 2, e);
  }
  void set(int k, T x) {
    v[k + n] = x;
  }
  void build() {
    for (int i = n - 1; i > 0; i--) {
      v[i] = f(v[i * 2 + 0], v[i * 2 + 1]);
    }
  }
  void update(int k, T x) {
    v[k += n] = x;
    while (k >>= 1) v[k] = f(v[k * 2 + 0], v[k * 2 + 1]);
  }
  T query(int a, int b) {
    T l = e, r = e;
    for (a += n, b += n; a < b; a >>= 1, b >>= 1) {
      if (a & 1) l = f(l, v[a++]);
      if (b & 1) r = f(v[--b], r);
    }
    return f(l, r);
  }
  T operator[](int k) {
    return query(k, k + 1);
  }
};

void solve() {
  int n;
  cin >> n;
  vi32 a(n), b(n);
  cin >> a >> b;
  vi32 o(n);
  iota(all(o), 0);
  sort(all(o), [&](int i, int j) {
    if (b[i] != b[j]) return b[i] < b[j];
    return a[i] < a[j];
  });
  using P = pair<int, int>;
  SegmentTree<P> st(n, [](P a, P b) { return min(a, b); }, P(INF, INF));
  rep(_i, n) {
    int i = o[_i];
    st.set(_i, P(a[i], _i));
  }
  st.build();
  int ans = 0;
  rep(_i, n) {
    int i = o[_i];
    if (a[i] <= b[i]) {
      continue;
    }
    int ok = n, ng = -1;
    while (abs(ok - ng) != 1) {
      int _x = (ok + ng) / 2;
      int x = o[_x];
      (b[x] >= a[i] ? ok : ng) = _x;
    }
    auto p = st.query(ok, n);
    if (p.first <= b[i]) {
      ans += 1;
      a[o[p.second]] = a[i];
      st.update(p.second, P(a[i], p.second));
    } else {
      auto p = st.query(_i + 1, n);
      if (p.first > b[i]) {
        no();
      }
      ans += 1;
      a[o[p.second]] = a[i];
      st.update(p.second, P(a[i], p.second));
    }
  }
  cerr << ans << endl;
  if (ans <= n - 2) {
    yes();
  } else {
    no();
  }
}

