void solve(long long N, std::vector<long long> A, std::vector<long long> B){
  set<ll> s(A.begin(),A.end());
  set<ll> t(B.begin(),B.end());
  if(s.size()<N||t.size()<N){
    sorted(A,B);
  }
  vector<ll> sortedA(A.begin(),A.end());
  map<ll,ll> AA;
  REP(N)AA[sortedA[i]]=i;
  vector<pll> BA(N);
  REP(N)BA[i]=pll(B[i],A[i]);
  sort(BA.begin(),BA.end());
  ll i=AA[BA[0].second];
  ll cnt=1;
  while(i!=0){
    i=AA[BA[i].second];
    ++cnt;
  }
  if(cnt<N){
    sorted(A,B);
  }
  sort(A.begin(),A.end());
  sort(B.begin(),B.end());
  bool f=false;
  REP(N-1){
    if(A[i]>B[i]){
      cout<<NO<<endl;
      return;
    }
    if(A[i+1]<=B[i]){
      f=true;
    }
  }
  if(f){
    cout<<YES<<endl;
  }else{
    cout<<NO<<endl;
  }
}

