    vi sum1(N+1),sum2(N),sum3(N);
    string ans="No";
    rep(i,0,N){
        sum1[i+1]=sum1[i];
        if(E[i]>F[i]) sum1[i+1]++;
    }
    rep(i,1,N){
        sum2[i]=sum2[i-1];
        if(E[i-1]>F[i]) sum2[i]++;
    }
    rep(i,1,N){
        sum3[i]=sum3[i-1];
        if(E[i]>F[i-1]) sum3[i]++;
