        else if(X>Y){
            sum=sum1[Y]+sum1[N]-sum1[X+1];
            sum+=sum2[X]-sum2[Y];
        }
        else{
            sum=sum1[Y]+sum1[N]-sum1[X+1];
            sum+=sum3[Y]-sum3[X];
        }
        if(sum==0) ans="Yes";
    }
