//Union Find Tree
class UnionFindTree {
public:
	vector<int> parent;
    vector<int> rank;

    UnionFindTree(int N) : parent(N), rank(N,0){
		for (int i = 0; i < N; ++i) parent[i] = i;
	}

	int root(int n) {
		return (parent[n] == n ? n : parent[n] = root(parent[n]));
	}

    int same(int n, int m) {
		return root(n) == root(m);
	}

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(rank[n]<rank[m]) {
            parent[n] = m;
        }
        else{
            parent[m] = n;
            if(rank[n] == rank[m]) rank[n]++;
        }
	}
};

int main() {
	int N; cin >> N;
	vector<ll> A(N),B(N);
	for(int i = 0; i < N; ++i) cin >> A[i];
	for(int i = 0; i < N; ++i) cin >> B[i];
	auto C = A,D = B;
	sort(ALL(C));
	sort(ALL(D));
	for(int i = 0; i < N; ++i) corner(C[i]>D[i],"No");

	vector<P<ll,ll>> AB(N);
	for(int i = 0; i < N; ++i) AB[i] = {A[i],B[i]};
	sort(ALL(AB));
	for(int i = 0; i < N; ++i) A[i] = AB[i].first;
	for(int i = 0; i < N; ++i) B[i] = AB[i].second;

	vector<pair<ll,int>> Ap(N),Bp(N);
	for(int i = 0; i < N; ++i) Ap[i] = {A[i],i};
	for(int i = 0; i < N; ++i) Bp[i] = {B[i],i};
	sort(ALL(Ap));
	sort(ALL(Bp));
	UnionFindTree uf(N);
	for(int i = 0; i < N; ++i) {
		int l = i,r = Bp[i].second;
		uf.unite(l,r);
	}
	vector<int> cnt(N,0);
	vector<set<int>> edge(N);
	for(int i = 0; i < N; ++i) {
		cnt[uf.root(i)]++;
		edge[uf.root(i)].insert(i);
		edge[uf.root(i)].insert(Bp[i].second);
	}
	int ans = 0;
	for(int i = 0; i < N; ++i) {
		if(cnt[i]>2) ans += cnt[i]-1;
		if(cnt[i]==2){
			int l = *edge[i].begin();
			int r = *edge[i].rbegin();
			if(A[l]<=B[l]&&A[r]<=B[r]);
			else ans++;
		}
	}
	Yn(ans<=N-2);
}

