    }
    for(int i = 1 ;i <= n; i++){
        scanf("%d", &b[i].first);
        b[i].second = i;
    }
    #define no return !printf("No");
    #define yes return !printf("Yes");
    sort(a + 1 , a + 1 + n);
    sort(b + 1 , b + 1 + n);
    for(int i = 1 ;i <= n ; i ++){
        if(a[i].first > b[i].first) no;
    }
    for(int i = 1 ;i <=  n ; i ++){
        if(i > 1 && a[i].first <= b[i-1].first)
            yes;
