struct SegmentTree{
private:
    int n;
    vector<P> node; // val, index

public:
    // Range Minumum Query
    SegmentTree(vector<int> v){
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, P(0, 0));
        for(int i=0; i<sz; i++){
            node[i+n-1].first = v[i];
            node[i+n-1].second = i;
        }
        for(int i=n-2; i>=0; i--){
            if(node[2*i+1].first < node[2*i+2].first){
                node[i] = node[2*i+1];
            }
            else{
                node[i] = node[2*i+2];
            }
        }
    }

    void update(int x, int val){
        x += (n - 1);
        node[x].first = val;
        while(0 < x){
            x = (x - 1) / 2;
            if(node[2*x+1].first < node[2*x+2].first){
                node[x] = node[2*x+1];
            }
            else{
                node[x] = node[2*x+2];
            }
        }
    }

    P get_min_index(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        if(r <= a || b <= l) return P(inf, inf);
        if(a <= l && r <= b) return node[k];

        P vl = get_min_index(a, b, 2*k+1, l, (l+r)/2);
        P vr = get_min_index(a, b, 2*k+2, (l+r)/2, r);

        if(vl.first < vr.first){
            return vl;
        }
        else{
            return vr;
        }
    }

    void confirm(){
        cout << endl;
        for(int i=0; i<2*n-1; i++){
            cout << i << " " << node[i].first << " " << node[i].second << endl;
        }
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin>>n;
    vector<int> a(n), b(n);
    for(int i=0; i<n; i++) cin>>a[i];
    for(int i=0; i<n; i++) cin>>b[i];

    auto aa = a;
    auto bb = b;
    sort(aa.begin(), aa.end());
    sort(bb.begin(), bb.end());

    bool valid = true;
    // 限界を試す
    for(int i=0; i<n; i++){
        if(aa[i] > bb[i]) valid = false;
    }

    if(!valid){
        cout << "No" << endl;
        return 0;
    }

    vector<P> ba(n);
    for(int i=0; i<n; i++){
        ba[i] = P(b[i], a[i]);
    }
    sort(ba.begin(), ba.end());

    vector<int> c(n), d(n);
    for(int i=0; i<n; i++){
        c[i] = ba[i].second; // a
        d[i] = ba[i].first;  // b
    }

    SegmentTree seg(c);

    int cnt = 0;
    for(int i=0; i<n; i++){
        if(c[i] > d[i]){
            P val = seg.get_min_index(i + 1, n);
            int cur_c = c[i];
            swap(c[i], c[val.second]);
            //cout << i << " " << val.second << endl;
            seg.update(val.second, cur_c);
            seg.update(i, val.first);
            //seg.confirm();
            if(c[i] > d[i]) valid = false;
            cnt++;
        }
    }

    if(!valid){
        cout << "No" << endl;
        return 0;
    }

    if(cnt <= n - 2){
        cout << "Yes" << endl;
    }
    else{
        cout << "No" << endl;
    }

    return 0;
}

