    ios::sync_with_stdio(false);

    int n; cin>>n;
    vector<ll> a(n), b(n);
    for(int i=0; i<n; i++) cin>>a[i];
    for(int i=0; i<n; i++) cin>>b[i];

    auto aa = a;
    auto bb = b;
    sort(aa.begin(), aa.end());
    sort(bb.begin(), bb.end());

    bool valid = true;
    // 限界を試す
    for(int i=0; i<n; i++){
        if(aa[i] > bb[i]) valid = false;
    }

    if(!valid){
        cout << "No" << endl;
        return 0;
    }

    vector<P> ba(n);
    for(int i=0; i<n; i++){
        ba[i] = P(b[i], a[i]);
    }
    sort(ba.begin(), ba.end());

    vector<ll> c(n), d(n);
    for(int i=0; i<n; i++){
        c[i] = ba[i].second; // a
        d[i] = ba[i].first;  // b
    }

    SegmentTree seg(c);

    int cnt = 0;
    for(int i=0; i<n; i++){
        if(c[i] > d[i]){
            if(i == n - 1) valid = false;
            P val = seg.get_min_index(min(n - 1, i + 1), n);
            ll cur_c = c[i];
            swap(c[i], c[val.second]);
            seg.update(val.second, cur_c);
            seg.update(i, val.first);
            if(c[i] > d[i]) valid = false;
            cnt++;
        }
    }

    if(!valid){
        cout << "No" << endl;
        return 0;
    }

    if(cnt <= n - 2){
        cout << "Yes" << endl;
    }
    else{
        cout << "No" << endl;
    }

    return 0;
}

