		scanf("%d", &p[i].first);
		p[i].second = i;
	}
	sort(p, p + N);
}

void load() {
	scanf("%d", &N);
	input(a);
	input(b);
}

bool solve() {
	for (int i = 0; i < N; i++) {
		perm[a[i].second] = b[i].second;
		if (a[i].first > b[i].first)
			return false;
	}
	for (int i = 1; i < N; i++)
		if (a[i].first <= b[i - 1].first)
			return true;
	int x = 0;
	unordered_set <int> vis;
	for (int i = 0; i < N; i++) {
		vis.insert(x);
		x = perm[x];
	}
	return vis.size() < N;
}

int main() {
	load();
	puts(solve() ? "Yes" : "No");	
	return 0;
}

