using namespace std;

typedef long long ll;
typedef pair<int, int> pii;

const int INF = 2147483647; // 2^31-1

vector<int> value;
int N;

void update(int i, int x) {
    // i 番目の葉の値を x に変える
    i += N - 1;
    value[i] = x;
    while (i > 0) {
        i = (i - 1) / 2;
        value[i] = min(value[i * 2 + 1],
                       value[i * 2 + 2]);
    }
}

int query(int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return INF; // 区間が被らない場合は INF を返す
    if (a <= l && r <= b)
        return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)
                         // に完全に含まれる
    else {
        int c1 = query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
        int c2 = query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
        return min(c1, c2); // 左右の子の値の min を取る
    }
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;

	N = 1;
	while (N < n) N *= 2;
	value = vector<int>(2 * N - 1, INF);

	vector<int> a(n);
	rep(i, n) cin >> a[i];

	vector<int> b(n);
	rep(i, n) cin >> b[i];

	vector<pii> v(n);
	rep(i, n) {
		v[i].first = b[i];
		v[i].second = a[i];
	}

	sort(v.begin(), v.end());

	map<int, multiset<int>> mp;
	rep(i, n) {
		mp[v[i].second].insert(i);
		update(i, v[i].second);
	}

	int cnt = 0;
	rep(i, n - 1){
		// cout << i << endl;
		if(v[i].first < v[i].second){
			int x = query(i + 1, n + 1, 0, 0, N);
			// cout << "query:" << x << endl;
            auto itr = mp[x].end();
            itr--;
            int j = *itr;
            // cout << "end:" << j << endl;
			update(j, v[i].second);

			mp[x].erase(itr);
			mp[x].insert(i);
			mp[v[i].second].insert(j);

			swap(v[i].second, v[j].second);
			cnt++;
			if(v[i].first < v[i].second){
				cout << "No" << endl;
				return 0;
			}

		}
	}
	if(v[n-1].first < v[n-1].second || cnt > n - 2){
		cout << "No" << endl;
	}else{
		cout << "Yes" << endl;
	}

}

