  REP(i, n){
    if(c[i].first>d[i].first){
      cout<<"No"<<'\n';
      return 0;
    }
  }
  FOR(i, 1, n){
    if(c[i].first<=d[i-1].first){
      cout<<"Yes"<<'\n';
      return 0;
    }
  }
  UnionFind uf(n);
  REP(i, n){
    uf.unite(c[i].second, d[i].second);
  }
  bool ok=false;
