void update(int l,int r,int rt,int x,int v)
{
    if(l==r) {val[rt]=x;return;}
    int m=(l+r)>>1;
    if(x<=m) update(l,m,lson,x,v);
    else update(m+1,r,rson,x,v);
    push_up(rt);
}
int query(int l,int r,int rt,int l_f,int r_f)
{
    if(l_f<=l&&r_f>=r) return val[rt];
