  sort(b.begin(), b.end());
  for(int i = 0; i < n; ++i) {
    if(a[i] > b[i]) {
      cout << "No" << endl;
      return 0;
    }
  }
  // N-1回なら揃う。
  // N-2回でできるか
  sort(c.begin(), c.end());
  // 1. スワップ必要ないやつがいるかチェック
  //    いたらN-2回でできる
  for(int i = 0; i < n; ++i) {
    if(c[i].second == a[i]) {
      cout << "Yes" << endl;
      return 0;
    }
  }
  // 2. 入れ替えられて、更に元の位置に戻れるか
  for(int i = 0; i < n; ++i) {
    int tmp = i + 1;
    while(b[i] >= a[tmp]) {
      if(a[tmp] == c[i].second) {
        cout << "Yes" << endl;
