	for (ll i = 0; i < n; i++)
	{
		cin >> a[i];
		a0[i] = a[i];
	}
	for (ll i = 0; i < n; i++)
	{
		cin >> b[i];
		b0[i] = b[i];
	}
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());

	bool flag = true;

	// 解の存在性
	for (ll i = 0; i < n; i++)
	{
		if (a[i] > b[i]) {
			flag = false;
			break;
		}
	}

	// 二つの解があるか
	bool flag2 = false;
	for (ll i = 0; i < n-1; i++)
	{
		if (flag == false) {
			break;
		}
		if (a[i] <= b[i + 1]) {
			flag2 = true;
			break;
		}
	}

	vector<ll> aind(n), bind(n);
	if (flag and !flag2) {
		for (ll i = 0; i < n; i++)
		{
			aind[i] = lower_bound(a.begin(), a.end(), a0[i]) - a.begin();
			bind[i] = lower_bound(b.begin(), b.end(), b0[i]) - b.begin();
		}

		for (ll i = 0; i < n; i++)
		{
			if (aind[i] == bind[i]) {
				flag2 = true;
				break;
			}
		}

		ll cnt = 0;
		ll index, temp;
		for (ll i = 0; i < n-1; i++)
		{
			if (aind[i] != bind[i]) {
				index = lower_bound(aind.begin(), aind.end(), bind[i]) - aind.begin();
				temp = aind[i];
				aind[i] = aind[index];
				aind[index] = temp;
				cnt++;
			}
		}
		if (cnt <= n - 2) {
			flag2 = true;
		}
	}

	if (flag2) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}


	return 0;
}

