bool check(vector<int> a, vector<int> b) {
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for (int i = 0; i < int(a.size()); ++i)
    if (a[i] > b[i])
      return false;
  return true;
}

int main() {
  int n;
  scanf("%d", &n);
  vector<int> a(n), b(n);
  for (int i = 0; i < n; ++i)
    scanf("%d", &a[i]);
  for (int i = 0; i < n; ++i)
    scanf("%d", &b[i]);
  if (!check(a, b))
    return 0 * puts("No");
  multiset<int> vals;
  map<int, set<int>> pos;
  for (int i = 0; i < n; ++i) {
    vals.insert(a[i]);
    pos[a[i]].insert(i);
  }
  int op = 0;
  for (int i = 0; i < n; ++i) {
    if (a[i] > b[i] && op < n - 2) {
      int x = *prev(vals.upper_bound(b[i]));
      int at = *pos[x].rbegin();
      vals.erase(vals.find(x));
      pos[x].erase(prev(pos[x].end()));
      vals.insert(a[i]);
      pos[a[i]].insert(at);
      swap(a[i], a[at]);
      ++op;
    }
  }
  for (int i = 0; i < n; ++i)
    if (a[i] > b[i])
      return 0 * puts("No");
  puts("Yes");
  return 0;
}

