bool asc(const P &a, const P &b){
	if(a.fs == b.fs) return a.sc > b.sc;
	else return a.fs < b.fs;
}

int main(void){
	int n;
	cin >> n;

	vector<P> a(n);
	vector<P> b(n);
	rep(i, n) cin >> a[i].fs;
	rep(i, n) cin >> b[i].fs;
	rep(i, n){
		a[i].sc = i;
		b[i].sc = i;
	}

	sort(all(a));
	sort(all(b), asc);

	int cnt = 0;
