int main() {
	int n; reader(n);
	vector<int> a(n), b(n);
	FOR(i, n) reader(a[i]);
	FOR(i, n) reader(b[i]);

	auto aa = a, bb = b;
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());

	int flag = 1;
	FOR(i, n) if (a[i] > b[i]) flag = 0;
	if (flag > 0) FOR(i, n - 1) {
		if (a[i + 1] <= b[i]) {
			flag = 2;
		}
	}

	bool ok;
	if (flag == 0) ok = false;
	else if (flag == 2) ok = true;
	else if (flag == 1) {
		// distinct
		FOR(i, n) aa[i] = lower_bound(a.begin(), a.end(), aa[i]) - a.begin();
		FOR(i, n) bb[i] = lower_bound(b.begin(), b.end(), bb[i]) - b.begin();

		vector<int> bi(n);
		FOR(i, n) bi[aa[i]] = bb[i];

		vector<bool> used(n);
		int cnt = 0;
		FOR(i, n) if (!used[i]) {
			cnt++;
			int cur = i;
			while (!used[cur]) {
				used[cur] = true;
				cur = bi[i];
			}
		}
		ok = (cnt > 1);
	}

	puts(ok ? "Yes" : "No");

	return 0;
}

