ll rui(ll a, ll b) {
	if (a == 0) { return 0; }
	if (b == 0) { return 1; }
	return rui(a, b - 1)*a%BIG;
}

struct pea
{
	int ind;
	int c;
};

bool comp(pea x, pea y) {
	return x.c > y.c;

}

bool test(pea A[200000], pea B[200000], int N) {


	sort(A + 1, A + N + 1,comp);
	sort(B + 1, B + N + 1,comp);

	for (int i = 1; i <= N; i++) {
		if (A[i].c > B[i].c) { return false; }
	}

	for (int i = 1; i < N; i++) {
		if (B[i].c >= A[i + 1].c) { return true; }
	}

	int C[200000];//Aの添え字とBの添え字を組み合わせ

	for (int i = 1; i <= N; i++) {
		C[A[i].ind] = B[i].ind;
	}

	int now = 1;

	for (int i = 0; i < N - 1; i++) {
		now = C[now];
		if (now == 1) { return true; }
	}
	return false;

}



