    map<int, int> rev_id;
    SegmentTree seg(vector<int> (2 * n, 0));
    for (int i = 0; i < n; i++){
        id[x[i]] = y[i];
        rev_id[y[i]] = x[i];
        seg.update(x[i], y[i]);
    }
    sort(x.begin(), x.end(), greater<int>());
    int cnt = 0;
    for (int i = 0; i < n; i++){
        if (x[i] <= id[x[i]]) continue;
        int p = seg.getmax(0, id[x[i]]);
        if (p == - INF) {
            cout << "No" << endl;
            return 0;
        }
        if (p >= x[i]){
            swap(id[x[i]], id[rev_id[p]]);
        }
        else {
            int q = seg.getmax(0, x[i]);
            if (q == -INF){
                cout << "No" << endl;
                return 0;
            }
            swap(id[x[i]], id[rev_id[q]]);
        }
        cnt++;
    }
    if (cnt <= max(0, n - 2)) cout << "Yes" << endl;
    else cout << "No" << endl;
}

