		unionf(i,p[i]);
		if(a[p[i]]>b[i]){
			cout << "No" << endl;
			return 0;
		}
	}
	for(i=0; i<n; ++i){
		if(ufind(i)==i){
			++t;
		}
	}
	if(t>1){
		cout << "Yes" << endl;
		return 0;
	}
	for(i=1; i<n; ++i){
		if(a[p[i]]>b[i-1]){
			continue;
		}
		cout << "Yes" << endl;
		return 0;
	}
	cout << "No" << endl;
	return 0;
}

