int main() {
    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (ll i = 0; i < N; i++) {
        cin >> B[i];
    }

    vector<pair<ll, ll>> pBA(N);
    for (ll i = 0; i < N; i++) {
        pBA[i].first = B[i];
        pBA[i].second = A[i];
    }
    sort(pBA.begin(), pBA.end());

    for (ll i = 0; i < N; i++) {
        A[i] = pBA[i].second;
        B[i] = pBA[i].first;
    }

    vector<pair<ll, ll>> pA(N);
    for (ll i = 0; i < N; i++) {
        pA[i].first = A[i];
        pA[i].second = i;
    }
    sort(pA.begin(), pA.end(), greater<>());

    ll op_num = 0;
    ll ok_eq = N;
    vector<ll> A_index(N);
    iota(A_index.begin(), A_index.end(), 0);
    for (ll i = 0; i < N; i++) {
        while (ok_eq > 0 && B[ok_eq - 1] >= pA[i].first) {
            ok_eq--;
        }

        //このAはok_eq以上の位置にあれば良い
        if (A_index[pA[i].second] >= ok_eq) {
            continue;
        }

        //そうでなければN - 1 - iの位置と置き換え
        swap(A_index[pA[i].second], A_index[N - 1 - i]);
        op_num++;

        //置き換えてもダメならダメ
        if (pA[i].first > B[A_index[pA[i].second]]) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << (op_num <= N - 2 ? "Yes" : "No") << endl;
}

