        if(a[i].x>b[i].x) flag=false;
    for(int i=2;i<=n;i++)
        if(a[i-1].x<=b[i].x) pre[i]=1;
    for(int i=1;i<n;i++)
        if(a[i+1].x<=b[i].x) bk[i]=1;
    build(1,n,1);
    for(int i=1;i<=n;i++)
    {
        f[a[i].id]=i;fff[a[i].id]=a[i].x;
        g[b[i].id]=i;ggg[b[i].id]=b[i].x;
    }
    bool ff=false;
    for(int i=1;i<=n;i++)
    {
        if(fff[i]>ggg[i]) continue;
        int x=f[i],y=g[i];
        if(x==y||b[x].x==ggg[i]||a[y].x==fff[i]||fff[i]==ggg[i]) {ff=true;break;}
        if(x<y)
