  auto sortedIdxA = range(N);
  {
    sort(sortedIdxA.begin(), sortedIdxA.end(),
         [A](auto i, auto j) { return A[i] < A[j]; });
    sort(B.begin(), B.end());
    dump(N, A, B);
  }
  dump(A, B, sortedIdxA);
  auto idx = range(N);
  if (any_of(idx.begin(), idx.end(),
             [sortedIdxA, A, B](auto i) { return A[sortedIdxA[i]] > B[i]; })) {
    print("No");
    return 0;
  }
  auto perm = u_map<ll, ll>{};
  for (auto &&i : range(N)) {
    perm[i] = sortedIdxA[i];
  }
  auto visited = u_set<ll>{};
  auto cycles = list<list<ll>>{};
  for (auto &&i : range(N)) {
    auto &&cycle = collectCycles(perm, i, visited);
    if (!cycle.empty())
      cycles.emplace_back(cycle);
  }
  dump(cycles);
  ll cnt = accumulate(cycles.begin(), cycles.end(), 0LL,
                      [](auto acc, auto c) { return acc + c.size() - 1; });
  print((cnt <= N - 2) ? "Yes" : "No");
}

