    if(c[i]>d[i]){
      cout << "No" << endl;
      return 0;
    }
  }

  REP(i,n) id[0][c[i]] = i;
  RREP(i,n) id[1][d[i]] = i;

  vec tmpp(n+10,0);
  REP(i,n-1) if(c[i+1] > d[i]) tmpp[i+1] = 1;


  auto f = [](int a,int b){return max(a,b);};
  SegmentTree<int> seg(f,0);
  seg.build(tmpp);

  REP(i,n){
    if(a[i] > b[i]) continue;
    int l = id[0][a[i]], r = id[1][b[i]];
    if(seg.query(l+1,r+1)==0){
      //cout << l SP r << endl;
