bool Check(vector <int> a, vector <int> b) {
    int n = (int)a.size();
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    for (int i = 0; i < n; i++) {
        if (a[i] > b[i]) return false;
        S.insert(i2(a[i], b[i]));
    }
    return true;
}
void solve() {
    int n;
    cin >> n;
    vector <int> a(n);
    for (int &x : a) cin >> x;
    vector <int> b(n);
    for (int &x : b) cin >> x;
    if (!Check(a, b)) {
        cout << "No";
        return;
    }
    int SL = 0;
    multiset <i2> A, B;
    for (int i = 0; i < n; i++) {
        if (S.find(i2(a[i], b[i])) != S.end()) {
            SL++;
            S.erase(S.find(i2(a[i], b[i])));
        }
        else {
            A.insert(i2(a[i], b[i]));
            B.insert(i2(b[i], a[i]));
        }
    }
    while ((int)A.size() != 0) {
        i2 x = *A.rbegin();
        if (S.find(x) != S.end()) {
            A.erase(A.find(x));
            B.erase(B.find(i2(x.second, x.first)));
            S.erase(S.find(x));
        }
        else {
            if ((int)A.size() == 1) {
                cout << "No";
                return;
            }
            i2 y = *B.rbegin();
            int a2 = x.first;
            int b1 = x.second;
            int b2 = y.first;
            int a1 = y.second;
            A.erase(A.find(x));
            A.erase(A.find(i2(a1, b2)));
            B.erase(B.find(y));
            B.erase(B.find(i2(b1, a2)));
            S.erase(S.find(i2(a2, b2)));
            A.insert(i2(a1, b1));
            B.insert(i2(b1, a1));
            SL++;
        }
    }
    cout << (SL <= n - 2 ? "Yes" : "No");
}
