  }
  for (int i=1;i<=n;++i) a[i]=p[a[i]];
  for (int i=1;!vis[i];i=a[i]) vis[i]=1;
  for (int i=1;i<=n;++i)
	if (!vis[i]) return;
  ans=0;
}

