template <class T>
std::map<T, int> compress(std::vector<T>& v) {
    std::sort(v.begin(), v.end());
    v.erase(std::unique(v.begin(), v.end()), v.end());

    std::map<T, int> rev;
    for (int i = 0; i < v.size(); ++i) rev[v[i]] = i;
    return rev;
}

void fail() {
    std::cout << "No" << std::endl;
    std::exit(0);
}

void success() {
    std::cout << "Yes" << std::endl;
    std::exit(0);
}

int main() {
    int n;
    std::cin >> n;

    std::vector<int> a(n), b(n);
    for (auto& x : a) std::cin >> x;
    for (auto& x : b) std::cin >> x;

    {
        std::vector<int> idx(n);
        std::iota(idx.begin(), idx.end(), 0);

        std::sort(idx.begin(), idx.end(),
                  [&](int i, int j) { return b[i] < b[j]; });

        std::vector<int> na(n), nb(n);
        for (int i = 0; i < n; ++i) {
            na[i] = a[idx[i]];
            nb[i] = b[idx[i]];
        }

        a = na, b = nb;
    }

    auto sa = a;
    std::sort(sa.begin(), sa.end());

    for (int i = 0; i < n; ++i) {
        if (sa[i] > b[i]) fail();
    }

    for (int i = 0; i + 1 < n; ++i) {
        if (sa[i + 1] <= b[i]) success();
    }

    std::vector<int> pos(n);
    {
        auto reva = compress(sa);
        for (int i = 0; i < n; ++i) {
            a[i] = reva[a[i]];
            pos[a[i]] = i;
        }
    }

    for (int i = 0; i < n - 1; ++i) {
        if (a[i] == i) success();
        int j = pos[i];
        pos[i] = i;
        pos[a[i]] = j;
        std::swap(a[i], a[j]);
    }

    fail();
    return 0;
}

