	sort(a1.begin(), a1.end());
	sort(b1.begin(), b1.end());
	rep(i, n){
		if(a1[i] > b1[i]){
			cout << "No" << endl;
			return 0;
		}
	}

	vector<pii> v(n);
	rep(i, n) {
		v[i].first = b[i];
		v[i].second = a[i];
	}

	sort(v.begin(), v.end());

	map<int, deque<int>> mp;
	rep(i, n) {
		mp[v[i].second].push_back(i);
		update(i, v[i].second);
	}

	int cnt = 0;
	rep(i, n - 1){
		// cout << i << endl;
		if(v[i].first < v[i].second){
			int x = query(i + 1, n + 1, 0, 0, N);
			// cout << "query:" << x << endl;
