inline void pu(int o){
	if (mi[o << 1] < mi[o << 1 | 1]) mi[o] = mi[o << 1], mip[o] = mip[o << 1];
	else mi[o] = mi[o << 1 | 1], mip[o] = mip[o << 1 | 1];
}
void init(int l, int r, int o){
	if (l == r) {
		mi[o] = lis[l].se, mip[o] = l;
		return;
	}
	int mid = ((r - l) >> 1) + l;
	init(l, mid, o << 1), init(mid + 1, r, o << 1 | 1);
	pu(o);
}
void mod(int l, int r, int o){
	if (l == r){ mi[o] = qd; return; }
	int mid = ((r - l) >> 1) + l;
	if (qx <= mid) mod(l, mid, o << 1);
	else mod(mid + 1, r, o << 1 | 1);
	pu(o);
}
ele get(int l, int r, int o){
	if (qx <= l && r <= qy) return ele(mi[o], mip[o]);
	int mid = ((r - l) >> 1) + l;
	ele ans = ele(-1, -1), ans2 = ele(-1, -1);
	if (qx <= mid) ans = get(l, mid, o << 1);
	if (qy > mid) ans2 = get(mid + 1, r, o << 1 | 1);
	if (ans.fi == -1) return ans2;
	if (ans2.fi == -1) return ans;
	return (ans.fi < ans2.fi) ? ans : ans2;
}
