#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;
typedef pair<ll, ll> pll;

#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

ll N;
ll A[100005];
pll C[100005];
ll B[100005];
pll D[100005];
ll U[100005];

bool solve()
{
    if (N == 2)
    {
        REP(i, N)
        {
            if (A[i] > B[i])
                return false;
        }
        return true;
    }
    map<ll, ll> map;
    REP(i, N)
    {
        map[A[i]]++;
    }
    sort(C, C + N, [](pll a, pll b) { return a.first < b.first; });
    sort(D, D + N, [](pll a, pll b) { return a.first < b.first; });
    REP(i, N)
    {
        if (C[i].first > D[i].first)
            return false;
    }

    memset(U, 0, sizeof(U));
    REP(i, N - 1)
    {
        if (C[i + 1].first > D[i].first)
            U[i + 1]++;

        U[i + 1] += U[i];
    }

    REP(i, N)
    {
        if (A[i] > B[i])
            continue;

        ll ru = N - 1, rl = -1;
        while (abs(ru - rl) > 1)
        {
            ll mid = (ru + rl) / 2;
            if (D[mid].first >= B[i])
                ru = mid;
            else
                rl = mid;
        }

        ll LU = 0, LL = N;
        while (abs(LU - LL) > 1)
        {
            ll mid = (LU + LL) / 2;
            if (C[mid].first <= A[i])
                LU = mid;
            else
                LL = mid;
        }

        if (U[rl] - U[LU] <= 0)
            return true;
    }
    return false;
}
int main()
{
    cin >> N;
    REP(i, N)
    {
        cin >> A[i];
        C[i].first = A[i];
        C[i].second = i;
    }
    REP(i, N)
    {
        cin >> B[i];
        D[i].first = B[i];
        D[i].second = i;
    }

    if (solve())
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
    return 0;
}

