bool check_bound(vector<int> a, vector<int> b) {
	const int n = a.size();
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());
	for (int i = 0; i < n; i++) {
		if (a[i] > b[i]) return false;
	}
	return true;
}
bool check_unq(vector<int> a, vector<int> b) {
	if (set<int>(a.begin(), a.end()).size() < a.size()) return true;
	if (set<int>(b.begin(), b.end()).size() < b.size()) return true;
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());
	for (int i = 1; i < (int) a.size(); i++) {
		if (a[i] <= b[i - 1]) return true;
	}
	return false;
}

bool check_cycle(vector<int> a) {
	set<int> vals(a.begin(), a.end());
	map<int, int> compr;
	for (int x: vals) {
		int sz = compr.size();
		compr[x] = sz;
	}
	for (int& x: a) x = compr[x];
	int len = 0, n = a.size();
	vector<bool> vis(n, false);
	for (int idx = 0; !vis[idx]; idx = a[idx]) {
		vis[idx] = true;
		len++;
	}
	return len == n;
}

bool check(vector<int> a, vector<int> b) {
	if (!check_bound(a, b)) return false;
	if (check_unq(a, b)) return true;
	return !check_cycle(a);
}

