	ll n, height;
	vector<P> dat;

	// 初期化（_nは最大要素数）
	RmqTree2(ll _n) {
		n = 1;
		height = 1;
		while (n < _n) {
			n *= 2;
			height++;
		}
		dat = vector<P>(2 * n - 1, make_pair(INF, INF));
	}

	// 場所i(0-indexed)をxにする
	void update(ll i, P x) {
		i += n - 1; // i番目の葉ノードへ
		dat[i] = x;
		while (i > 0) { // 下から上がっていく
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	// 区間[a,b)の最小値。ノードk=[l,r)に着目している。
	P find(ll a, ll b) {
		return _find(a, b, 0, 0, n);
	}
};


