using namespace std;
using P = pair<long long, long long>;

long long n;
vector<long long> a, b;
priority_queue<P> pqng, pqok;

bool solve();

int main() {
  cin >> n;
  a.resize(n);
  b.resize(n);
  for(int i = 0; i < n; ++i) cin >> a[i];
  for(int i = 0; i < n; ++i) cin >> b[i];
  if(solve())
    cout << "Yes" << endl;
  else
    cout << "No" << endl;
  return 0;
}

bool solve() {
  for(int i = 0; i < n; ++i)
    if(a[i] != b[i]) {
      if(a[i] < b[i])
        pqok.push({b[i], a[i]});
      else
        pqng.push({a[i], b[i]});
    }
  for(int i = 0; i < n - 2; ++i) {
    if(pqng.empty()) return 1;
    P nowng = pqng.top();
    pqng.pop();
    while(1) {
      if(pqok.empty()) return 0;
      P nowok = pqok.top();
      pqok.pop();
      if(nowng.fi > nowok.fi) continue;
      if(nowng.se < nowok.se) continue;
      swap(nowok.fi, nowng.se);
      pqok.push(nowok);
      break;
    }
  }
  return pqng.empty();
}

