    sort(bc.begin(), bc.end());

    sort(pa.begin(), pa.end());
    sort(pb.begin(), pb.end());
    rep(i, n){
        pa[i].first = i;
        pb[i].first = i;
        swap(pa[i].first, pa[i].second);
        swap(pb[i].first, pb[i].second);
    }
    sort(pa.begin(), pa.end());
    sort(pb.begin(), pb.end());
    // pa, pbのsecondにa[i], b[i]がsort後にどこに行ったか(p, q)が入ってる

    rep(i, n){
        if(ac[i] > bc[i]){
            cout << "No" << endl;
            return 0;
        }
    }

    vector<int> v(n);
    for(int i = 0; i < n - 1; i++){
        if(ac[i + 1] <= bc[i]) v[i] = 0;
        else v[i] = 1;
    }
    vector<int> s(n);
    s[0] = v[0];
    for(int i = 1; i < n - 1; i++){
        s[i] = s[i - 1] + v[i];
    }

    rep(i, n){
        if(a[i] > b[i]) continue;

        int p = pa[i].second;
        int q = pb[i].second;

        while(p < n - 1){
            if(b[p] == b[p + 1]) p++;
            else break;
        }
        while(q > 0){
            if(a[q] == a[q - 1]) q--;
            else break;
        }

        if(p >= q){
            cout << "Yes" << endl;
            return 0;
        }

        // n - 1でセグフォ出そう
        if(p == 0){
            if(s[0] == 1) continue;
            else{
                if(s[q - 1] == 0){
                    cout << "Yes" << endl;
