bool good() {
	for(int i = 0;i < n ;) {
		int j;
		for(j = i; ab[j].second == ab[i].second; j++);
		random_shuffle(ab + i, ab + j);
		i = j;
	}
    vector<int>order(n);
    iota(all(order), 0);

    sort(all(order), [&](const int & x, const int & y) {
    	return ab[x].first < ab[y].first;
    });

    int cnt = 0;
    for(int i = 0; i < n; i++) {
    	if(order[i] != i) {
    		cnt++;
    		while(order[i] != i) {
    			swap(order[i], order[order[i]]);
    			cnt++;
    		}
    	}
    }
    return cnt < n;
}

