int main()
{
    int N;
    cin >> N;
    vector<int> A(N);
    REP(i, N) cin >> A[i];
    vector<int> B(N);
    REP(i, N) cin >> B[i];
    vector<tuple<int, int>> pair(N);
    vector<int> A_copy(A);
    vector<int> B_copy(B);
    sort(A_copy.begin(), A_copy.end());
    sort(B_copy.begin(), B_copy.end());
    bool flg = false;
    REP(i, N ){
        if(A_copy[i] <= B_copy[i]) {
            if(i != N-1 && A_copy[i+1] <= B_copy[i]) {
                flg = true;
            }
            if(i != 0 && A_copy[i-1] <= B_copy[i]) {
                flg = true;
            }
        } else {
            cout << "No" << endl;
            return 0;
        }
    }
    if(flg) {
        cout << "Yes" << endl;
        return 0;
    }
    REP(i, N) {
        pair[i] = make_tuple(A[i], B[i]);
    }
    sort(pair.begin(), pair.end(),
       [](auto const &a, auto const &b) { return get<1>(a) < get<1>(b); });
    flg = false;
    REP(i, N) {
        if(A_copy[i] != get<0>(pair[(i+1)%N])) {
            flg = true;
            break;
        }
    }
    if(!flg) {
