    }
    flg = false;
    REP(i, N) {
        if(A_copy[i] != get<0>(pair[(i-1+N)%N])) {
            flg = true;
            break;
        }
    }
    if(!flg) {
        cout << "No" << endl;
        return 0;
    }
    cout << "Yes" << endl;

}

