const int INFTY = 200000000;

template<typename M>
struct SegmentTree {
    using F = function<M(M, M)>;
    const F f;
    const M m1;
    vector<M> nodes;
    int n;

    explicit SegmentTree(const vector<M> &v,
                         const F f, const M m1) : f(f), m1(m1) {
        n = 2;
        while (n < v.size()) n *= 2;
        nodes.resize(2 * n - 1, m1);
        for (int i = 0; i < v.size(); i++) {
            nodes[i + n - 1] = v[i];
        }
        for (int i = n - 2; i >= 0; i--) {
            nodes[i] = f(nodes[2 * i + 1], nodes[2 * i + 2]);
        }
    }
    void set(int pos, M val) {
        int idx = n - 1 + pos;
        nodes[idx] = val;
        do {
            idx = (idx - 1) / 2;
            nodes[idx] = f(nodes[2 * idx + 1], nodes[2 * idx + 2]);
        } while (idx != 0);
    }
    // l 番目から r - 1 番目の範囲の結果を出力する
    M get(int l, int r, int k = 0, int cl = 0, int cr = -1) {
        if (cr == -1) cr = n;
        if (l <= cl && cr <= r) return nodes[k];
        if (r <= cl || cr <= l) return m1;
        int m = (cl + cr) / 2;
        return f(get(l, r, 2 * k + 1, cl, m), get(l, r, 2 * k + 2, m, cr));
    }
};

pair<int, int> Min(pair<int, int> a, pair<int, int> b) {
    if (a.second <= b.second)
        return a;
    else
        return b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
