    for (int i = 0; i < N; i++) scanf("%d", &A[i]);
    for (int i = 0; i < N; i++) scanf("%d", &B[i]);
    vector<pair<int, int>> C(N);
    for (int i = 0; i < N; i++) {
        C[i] = make_pair(B[i], A[i]);
    }
    sort(C.begin(), C.end());
    vector<pair<int, int>> D(N);
    for (int i = 0; i < N; i++) {
        D[i] = make_pair(i, C[i].second);
    }

    SegmentTree<pair<int, int>> segtree(D, Min, make_pair(-1, INFTY));
    for (int i = 0; i < N; i++) {
        int v = segtree.get(i, i+1).second;
        if (C[i].first < v) {
            int idx, val;
            tie(idx, val) = segtree.get(i, N);
