    }

    for (i = 0; i < n; i++) par[i] = i;

    for (i = 0; i < n; i++) {
        int x = p[i], y = q[i], m1 = min(x, y), m2 = max(x, y);

        unite(x, y);

        if (a[i] > b[i]) continue;
        if (sum1[m1] != m1) continue;
        if (sum1[n] - sum1[m2 + 1] != n - m2 - 1) continue;

        if (x < y) {
            if (sum2[y + 1] - sum2[x + 1] != y - x) continue;
        } else if (x > y) {
            if (sum3[x] - sum3[y] != x - y) continue;
        }

        puts("Yes");

        return 0;
    }

    for (i = 0; i < n; i++) cnt[find(i)]++;

    for (i = 0; i < n; i++) {
        if (cnt[i] == n) {
            puts("No");

            return 0;
        }
    }

    puts("Yes");

    return 0;
}

