const int N = 110000;

int a[N], b[N];
int ida[N], idb[N];

int root[N];
int find_root(int u) {
	if (u == root[u]) return root[u];
	return root[u] = find_root(root[u]);
}

int main() {

	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);

	int n; cin >> n;
	for (int i = 0; i < n; i++) cin >> a[i];
	for (int i = 0; i < n; i++) cin >> b[i];
	for (int i = 0; i < n; i++) ida[i] = i;
	sort(ida, ida + n, [&](int u, int v) {
		return a[u] < a[v];
	});
	for (int i = 0; i < n; i++) idb[i] = i;
	sort(idb, idb + n, [&](int u, int v) {
		return b[u] < b[v];
	});

	for (int i = 0; i < n; i++) if (a[ida[i]] > b[idb[i]]) {
		cout << "No\n";
		return 0;
	}

	for (int i = 0; i < n; i++) root[i] = i;
	for (int i = 0; i < n; i++) {
		int aa = find_root(ida[i]), bb = find_root(idb[i]);
		if (aa == bb) continue;
		root[aa] = bb;
	}
	int cnt = 0;
	for (int i = 0; i < n; i++) cnt += i == root[i];
	if (cnt > 1) cout << "Yes\n";
	else cout << "No\n";

	return 0;
}

