  vector<int> A(N),B(N),C(N),D(N);
  for (int i = 0; i < N; i++){
    cin >> A[i];
    C[i] = A[i];
  }
  for (int i = 0; i < N; i++){
    cin >> B[i];
    D[i] = B[i];
  }
  sort(C.begin(),C.end());
  sort(D.begin(),D.end());
  bool flg = false;
  for (int i = 0; i < N; i++){
    if (A[i]>B[i]) flg = true;
  }
  if (flg){
    cout << "No";
  } else {
    //必要な操作回数を確認
    map<int,int> UB; //Bの要素,Aの対応要素のM範囲最大値
    map<int,int> LB; //Bの要素,Aの対応要素のM範囲最小値
    //上限・下限計算
    C.push_back(2000000000);
    D.push_back(2000000000);
    int c = 0;
    int d = 0;
    int m = 0;
    while (c<N && d<N){
      if (C[c]>=D[d]){
        if (c==d) m = c;
        LB[D[d]]=m;
        UB[D[d]]=C[c];
        d++;
      } else {
        c++;
      }
    }
    //範囲に含まれるか確認
    flg = false;
    for (int i = 0; i < N; i++){
      if (LB.at(B[i]) <= A[i] && A[i] <= UB.at(B[i])){
        flg = true;
        break;
      }
    }
    if (flg){
      cout << "Yes";
    } else {
      cout << "No";
    }
  }
}

