struct RMaxQ {
    static const int N = 131072;
    pii data[2 * N];

    void init() {
        rep(i, 2 * N) {
            data[i] = pii(-1, -1);
        }
    }

    pii query(int a, int b, int l = 0, int r = N, int k = 0) {
        if (b <= l || r <= a)return pii(-1, -1);
        else if (a <= l && r <= b) {
            return data[k];
        }
        pii lch = query(a, b, l, (l + r) / 2, 2 * k + 1);
        pii rch = query(a, b, (l + r) / 2, r, 2 * k + 2);
        return max(lch, rch);
    }

    void update(int a, int x) {
        int a2 = a + N - 1;
        data[a2] = pii(x, a);
        while (a2) {
            a2 = (a2 - 1) / 2;
            data[a2] = max(data[2 * a2 + 1], data[2 * a2 + 2]);
        }
    }
};

int N;
int A[100100];
int B[100100];
pii BA[100100];
int A2[100100];//BA[i]は、A2[i]番目かそれ以降に置ける
RMaxQ rmq;
int place[100100];
int place_inv[100100];

signed main() {
    cin >> N;
    vector<int> X;
    rep(i, N) {
        cin >> A[i];
        X.push_back(A[i]);
    }
    rep(i, N) {
        cin >> B[i];
        X.push_back(B[i]);
        BA[i] = pii(B[i], A[i]);
    }
    sort(B, B + N);
    sort(A, A + N);
    sort(BA, BA + N);
    rep(i, N) {
        if (A[i] > B[i]) {
            cout << "No" << endl;
            return 0;
        }
    }

    sort(X.begin(), X.end());
    X.erase(unique(X.begin(), X.end()), X.end());
    rep(i, N) {
        //A[i],B[i]は順序が壊れてるのでBAを使う
        A[i] = lower_bound(X.begin(), X.end(), BA[i].second) - X.begin();
        B[i] = lower_bound(X.begin(), X.end(), BA[i].first) - X.begin();
    }
    rep(i, N) {
        A2[i] = lower_bound(B, B + N, A[i]) - B;
    }

    priority_queue<pii> que;
    rmq.init();
    int cnt = 0;
    for (int i = N - 1; i >= 0; --i) {
        if (A2[i] <= i) {
            //置ける
            //交換可能
            rmq.update(i, A2[i]);
            que.emplace(A2[i], i);
            place[i] = i;
            place_inv[i] = i;
        } else {
            //交換しないといけない
            //交換先をjとすると
            //j>=A2[i]
            //A2[j]が大きい(小さいのは貴重)
            pii res = rmq.query(A2[i], rmq.N);
            if (res.first == -1) {
                cout << "No" << endl;
                cerr << "a" << endl;
                return 0;
            }
            int idx = res.second;
            rmq.update(idx, -1);
            rmq.update(i, res.first);
            int idx2 = place_inv[idx];
            place[idx2] = i;
            place_inv[idx] = 0;
            place_inv[i] = idx2;
            cnt++;
        }
        while (!que.empty() && que.top().first >= i) {
            int idx = que.top().second;
            int pl = place[idx];
            rmq.update(pl, -1);
            que.pop();
        }
    }
    if (cnt <= N - 2) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

