			++r[i+1];
		}
	}
	for(i=0; i<n; ++i){
		if(a[i]>b[i]){
			continue;
		}
		p = (int)(lower_bound(as,as+n,a[i])-as);
		q = (int)(lower_bound(bs,bs+n,b[i])-bs);
		if(p>q){
			ch = m[q]+r[p]-r[q]+m[n]-m[p+1];
		}else if(p<q){
			ch = m[p]+l[q]-l[p]+m[n]-m[q+1];
		}else{
			ch = m[p] + m[n] - m[q+1];
		}
		if(ch){
			continue;
		}
		cout << "Yes" << endl;
		return 0;
	}
	cout << "No" << endl;
	return 0;
}

