struct UnionFind {
    vector<int> data;

    UnionFind(int sz) {
        data.assign(sz, -1);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return (false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if(data[k] < 0) return (k);
        return (data[k] = find(data[k]));
    }

    int size(int k) {
        return (-data[find(k)]);
    }
};

int main() {
    int n; cin >> n;
    vl a(n), b(n);
    vll a_sorted(n), b_sorted(n);
    rep(i,n) {
        cin >> a[i];
        a_sorted[i] = pll(a[i], i);
    }
    rep(i,n) {
        cin >> b[i];
        b_sorted[i] = pll(b[i], i);
    }
    sort(all(a_sorted));
    sort(all(b_sorted));
    rep(i,n) if (a_sorted[i].VAL > b_sorted[i].VAL) {
        cout << "No" << endl;
        return 0;
    }

    int cnt = 0;
    UnionFind uf(n);
    rep(i,n) uf.unite(a_sorted[i].IDX, b_sorted[i].IDX);
    rep(i,n) cnt += (uf.find(i) == i);
    if (cnt > 1) {
        cout << "Yes" << endl;
        return 0;
    }
