bool solve(){
    int n;
    cin >> n;
    vector<int> a(n),b(n);
    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    {
        vector<int> ta = a, tb = b;
        sort(all(ta));
        sort(all(tb));
        rep(i,n){
            if (ta[i] > tb[i]) return false;
        }
    }

    // priority_queue<P,vector<P>,greater<P>> paths;
    using P = pair<int,int>;
    vector<P> v(n);
    map<int,int> cntA;
    rep(i,n){
        v[i] = {b[i], a[i]};
        cntA[a[i]] ++;
    }
    sort(all(v));
    int cnt = 0;
    rep(i,n){
        int ai = v[i].first;
        int bi = v[i].first;
        cntA[ai]--;
        if (cntA[ai] == 0) cntA.erase(ai);
        if (ai <= bi) continue;
        cnt++;
        auto itr = cntA.upper_bound(bi);
        if (itr == cntA.begin()) return false;
        --itr;
        cntA[ai]++;
        cntA.erase(itr);
    }
    return cnt <= n-2;
}

