std::map<int, int> compress(const std::vector<int>& v)
{
	std::map<int, int> m;
	for (auto x : v) m[x] = 0;
	int n = 0;
	for (auto& t : m) t.second = n++;
	return m;
}

// v must be a shuffle of [0, 1, ..., len(v) - 1]
std::vector<std::vector<int>> to_cycle(const std::vector<int>& v)
{
	std::vector<std::vector<int>> cycs;
	std::vector<bool> done(v.size(), false);
	for (int i = 0; i < v.size(); ++i)
	{
		if (done[i]) continue;
		std::vector<int> cyc;
		cyc.push_back(i);
		done[i] = true;
		int j = v[i];
		while (j != i)
		{
			cyc.push_back(j);
			done[j] = true;
			j = v[j];
		}
		cycs.push_back(std::move(cyc));
	}
	return cycs;
}

bool check(int N, std::vector<int>&& A, std::vector<int>&& B)
{
	auto m = compress(B);
	auto M = m.rbegin()->second + 1;
	std::vector<int> cnt(M, 0);
	for (auto x : B) cnt[m[x]]++;
	std::vector<std::pair<int, int>> BA;
	for (int i = 0; i < N; ++i)
	{
		auto it = m.lower_bound(A[i]);
		if (it == m.end()) return false;
		BA.emplace_back(m[B[i]], it->second);
	}
	std::sort(BA.begin(), BA.end());
	for (int i = 0; i < N; ++i) std::tie(B[i], A[i]) = BA[i];
	std::vector<std::pair<int, int>> AI;
	for (int i = 0; i < N; ++i) AI.emplace_back(A[i], i);
	std::sort(AI.begin(), AI.end());
	std::vector<int> pi;
	for (int i = 0; i < N; ++i) pi.emplace_back(AI[i].second);
	for (int i = 0; i < N; ++i)
		if (AI[i].first > B[i]) return false;
	for (int i = 0; i + 1 < N; ++i)
		if (AI[i + 1].first <= B[i]) return true;
	return to_cycle(pi).size() > 1;
}

int main()
{
	std::cin.tie(nullptr);
	std::ios::sync_with_stdio(false);
	auto N = read<int>()();
	auto A = read<std::vector<int>>()(N);
	auto B = read<std::vector<int>>()(N);
	std::cout << (check(N, std::move(A), std::move(B)) ? "Yes" : "No") << std::endl;
	std::cout << std::flush;
	return 0;
}

