	for(int i=0; i<N; i++) bs[i]={AB[i].second, -i};
	SegmentTree<pair<int, int>> st(bs, {0, 0});

	int cnt = 0;
	for(int i=N-1; i>0; i--){
		int a = AB[i].first;
		int b = AB[i].second;
		if(a<=b) continue;
		debug(a, b);
		cnt++;
		auto p = st.query(0, i);
		int x = p.first;
		int n = -p.second;
		if(x<a) {
			cout << "No" << endl;
			return 0;
		}
		p = st.query(0, 1);
		x = p.first;
		n = -p.second;
		if(x>=a){
			st.update(0, {b, -n});
			AB[n].second = b;
			continue;
		}
		int lb = 1, ub = i;
		while(ub-lb>1){
			int m = (lb+ub)/2;
			p = st.query(0, m);
			x = p.first;
			n = -p.second;
			if(x>=a){
				ub = m;
			} else {
				lb = m;
			}
		}
		st.update(n-1, {b, -n});
		AB[n].second = b;
	}


	if(AB[0].first <= AB[0].second && cnt <= N-2){
		cout << "Yes" << endl;
	} else {
		cout << "No" << endl;
	}

	return 0;
}

