    ll n; cin >> n;
    vector<pair<ll, ll>> ba(n, {0, 0});
    REP(i, n) cin >> ba[i].second;
    REP(i, n) cin >> ba[i].first;
    sort(ALL_OF(ba));
    vector<ll> a(n), b(n);
    REP(i, n) tie(b[i], a[i]) = ba[i];
    // DUMPALL(a);
    // DUMPALL(b);
    vector<pair<ll, ll>> p(n), q(n);
    REP(i, n) {
        p[i] = make_pair(a[i], -i);
        q[i] = make_pair(a[i], i);
    }

    segtree sgt(p), sgt2(q);

    ll kaisu = 0;
    REP(i, n) {
        auto u = sgt.fetch(i, i+1);
        if (u.first > b[i]) {

            auto v = sgt.fetch(i+1, n);

            ll gr = lower_bound(ALL_OF(b), u.first) - b.begin();
            if (i < gr && gr < n) {
                auto v2 = sgt2.fetch(gr, n);
                v2.second *= -1;
                if (v2.first <= b[i]) {
                    v = v2;
                }
            }

            if (v.first > b[i] || i == n-1) {
                kaisu += INF;
                break;
            }

            // swap w/o soegies
            ll j = -v.second;
            // cerr << i << " <-> " << j << endl;
            sgt.apply(i, i+1, make_pair(v.first, -i));
            sgt.apply(j, j+1, make_pair(u.first, -j));
            sgt2.apply(i, i+1, make_pair(v.first, i));
            sgt2.apply(j, j+1, make_pair(u.first, j));

            kaisu++;

        }
    }
    // DUMP(kaisu);
    cout << Yes(kaisu <= n - 2) << endl;
}

