int main(){
    int n; scanf("%d",&n);
    vector<P> c(n); vector<int> val;
    rep(i,0,n){
        scanf("%d",&c[i].first);
        val.push_back(c[i].first);
    }
    rep(i,0,n){
        scanf("%d",&c[i].second);
        val.push_back(c[i].second);
    }
    sort(ALL(c),[](P a,P b){return a.second<b.second;});
    sort(ALL(val)); val.erase(unique(ALL(val)),val.end()); int m=val.size();
    vector<int> a(n),b(n); vector<ll> d(m,0);
    rep(i,0,n){
        a[i]=lower_bound(ALL(val),c[i].first)-val.begin();
        b[i]=lower_bound(ALL(val),c[i].second)-val.begin();
        d[a[i]]++; d[b[i]]--;
    }
    rep(i,0,m-1)d[i+1]+=d[i];
    LazySegmentTree<ll> seg(m,
    [](ll a,ll b){return min(a,b);},
    [](ll a,ll b){return a+b;},
    [](ll a,ll b){return a+b;},INF,0);
    seg.build(d); bool f=0;
    rep(i,0,n)if(a[i]<=b[i]){
        seg.update(a[i],b[i],-1);
        if(seg.query(0,m)>=0)f=1;
        seg.update(a[i],b[i],1);
    }
    printf(f?"Yes\n":"No\n");
    return 0;
}

