	for(int i = 0; i < N; ++i) corner(C[i]>D[i],"No");

	vector<pair<ll,ll>> BA(N);
	for(int i = 0; i < N; ++i) BA[i] = {B[i],A[i]};
	sort(ALL(BA));
	for(int i = 0; i < N; ++i) B[i] = BA[i].first;
	for(int i = 0; i < N; ++i) A[i] = BA[i].second;
	vector<pair<ll,int>> Ap(N);
	for(int i = 0; i < N; ++i) Ap[i] = {A[i],i};
	sort(ALL(Ap));
	UnionFindTree uf(N);
	for(int i = 0; i < N; ++i) uf.unite(i,Ap[i].second);
	map<int,int> mp;
	for(int i = 0; i < N; ++i) mp[uf.root(i)]++;
	Yn(mp.size()!=1);
}

