	}; int x, y, s;
public:
	step(int _y, int _s = 1) :x(0 < _s ? 0 : _y), y(0 < _s ? _y : 0), s(_s) {}
	step(int _x, int _y, int _s) :x(_x), y(_y), s(_s) {}
	It begin() { return { x,s }; } It end() { return { y,s }; }
};

