	rep(i, 0, N) ma_a[i] = ma_b[i] = -inf;

	rep(i, 0, N) {
		chmin(mi_b[uf_b[i]], i);
		chmin(mi_a[uf_a[i]], i);
		chmax(ma_a[uf_a[i]], i);
		chmax(ma_b[uf_b[i]], i);
	}

	rep(i, 0, N) if (A[i] <= B[i]) {
		// 他をソートして条件を満たせばOK

		int ra = rev_a[i];
		int rb = rev_b[i];

		int LA = mi_a[uf_a[ra]];
		int LB = mi_b[uf_b[rb]];
		int RA = ma_a[uf_a[ra]];
		int RB = ma_b[uf_b[rb]];

		if (RA < LB) {
			ra = RA;
			rb = LB;
			int sm = bit_left.get(ra, rb);
			if (ng.get(0, ra) == 0 and sm == rb - ra and ng.get(rb + 1, 101010) == 0) return yes;
		}
		else if (RB < LA) {
			ra = LA;
			rb = RB;
			int sm = bit_right.get(rb, ra);
			if (ng.get(0, rb) == 0 and sm == ra - rb and ng.get(ra + 1, 101010) == 0) return yes;
		}
		else return yes;
	}

	return no;
}
