    for(int i=0; i<N; i++) {
        if(visited[i]) continue;
        vector<int> loop;
        int cur = i;
        while(!visited[cur]) {
            visited[cur] = true;
            cnt[ Y[cur] ]++;
            loop.emplace_back(cur);
            cur = X[cur];
        }
        for(auto e : loop) {
