const ll N = 300001;
ll seg[4*N];
set<ll> s[N];

void update(ll st, ll en, ll ind, ll i, ll val)
{
    if(st>i || en<i)
        return;
    if(st==i && en==i)
    {
        seg[ind] = val;
        return;
    }

    ll mid = (st+en)/2;

    update(st,mid,2*ind,i,val);
    update(mid+1,en,2*ind+1,i,val);
    seg[ind] = max(seg[2*ind], seg[2*ind+1]);
}

ll query(ll st, ll en, ll ind, ll il, ll ir)
{
    if(st>ir || en<il)
        return -INF;
    if(st>=il && en<=ir)
        return seg[ind];

    ll mid = (st+en)/2;
    return max(query(st,mid,2*ind,il,ir), query(mid+1,en,2*ind+1,il,ir));
}

void solve()
{
    ll n;
    cin >> n;

    rep(i,4*N)
    {
        seg[i] = -1;
    }

    pair<ll,ll> p[n];
    rep(i,n)
    {
        cin >> p[i].ss;
    }
    rep(i,n)
    {
        cin >> p[i].ff;
    }

    sort(p,p+n);

    map<ll,ll> coord;
    rep(i,n)
    {
        coord[p[i].ss]++;
        coord[p[i].ff]++;
    }

    ll timer = 0;
    foreach(it,coord)
    {
        timer++;
        it->second = timer;
    }

    rep(i,n)
    {
        p[i].ff = coord[p[i].ff];
        p[i].ss = coord[p[i].ss];
    }

    rep(i,n)
    {
        s[p[i].ss].insert(-i);
        update(1,2*n+100,1,p[i].ss,i);
    }

    ll cnt = 0;

    rep(i,n)
    {
        ll a = p[i].ss;
        ll b = p[i].ff;

        if(a<=b)
        {
            s[a].erase(-i);
            if(s[a].empty())
                update(1,2*n+100,1,a,-1);
            else
                update(1,2*n+100,1,a,-(*(s[a].begin())));
            continue;
        }

        ll ind = query(1,2*n+100,1,1,b);

        if(ind==-1)
        {
            cout << "No" << endl;
            return;
        }

        cnt++;
        ll val = p[ind].ss;
        s[val].erase(-ind);
        s[a].erase(-i);

        if(s[val].empty())
            update(1,2*n+100,1,val,-1);
        else
            update(1,2*n+100,1,val,-(*(s[val].begin())));

        s[a].insert(-ind);
        update(1,2*n+100,1,a,-(*(s[a].begin())));
        p[ind].ss = a;
    }

    if(cnt>n-2)
    {
        cout << "No" << endl;
    }
    else
    {
        cout << "Yes" << endl;
    }
}

