struct BIT{
    int n;
    vector<int> bit;
    BIT(int N){
        bit.resize(N + 1);
        n = N;
    }
    void add(int a, int w){
        for (int x = a; x <= n; x += x&-x)
            bit[x] += w;
    }
    int sum(int a){
        int ret = 0;
        for (int x = a; x > 0; x -= x&-x)
            ret += bit[x];
        return ret;
    }
};



