struct UnionFind{
    vector<int> par;
    UnionFind(int n) : par(n){
      for(int i=0;i<n;i++) par[i]=i;
    }
    int root(int x){
      if(par[x]==x) return x;
      return par[x]=root(par[x]);
    }

    void unite(int x,int y){
      int rx=root(x);
      int ry=root(y);
      if(rx==ry) return;
      par[rx]=ry;
    }
    bool same(int x, int y){
      int rx=root(x);
      int ry=root(y);
      if(rx==ry) return 1;
      return 0;
    }
  };
bool compare_by_second(pair<int, int> a,pair<int, int> b){
  if(a.second != b.second){
   return a.second < b.second;
  }
  else{
    return a.first < b.first;
  }
}
int binary_search2(vector<int> &l,int key){
  int left=0;
  int right=l.size()-1;
  int mid;
  if(l[right]<key)return right;
  else{
  while(right-left>1){
    mid=(right+left)/2;
    if(l[mid]>=key)right=mid;
  else left=mid;
  }
  }
  if(key==l[left])right=left;
return right;
}
int main(){
  int n;
  cin>>n;
  vector<pair<int,int>> array(n);
  vector<int> a(n);
  vector<int> memo(n,0);
  rep(i,n)cin>>array[i].first;
  rep(i,n)cin>>array[i].second;
  //  rep(i,n)cout<<array[i].first<<endl;
  sort(array.begin(),array.end(),compare_by_second);
  //  rep(i,n)cout<<array[i].second<<endl;
  rep(i,n)a[i]=array[i].first;
  //  rep(i,n)cout<<a[i]<<endl;
  sort(a.begin(),a.end());
  int flag=0;
  UnionFind tree(n);
  rep(i,n){
    if(a[i]>array[i].second)flag++;
    int buf=binary_search2(a,array[i].first);
    while(memo[buf]!=0){
      buf++;
    }
    tree.unite(i,buf);
    memo[buf]++;
  }
  if(flag==0){
    rep(i,n){
      //      cout<<tree.same(0,i)<<" "<<a[i]<<endl;
      if(tree.same(0,i));
      else flag++;
    }
    if(flag!=0){
      cout<<"Yes"<<endl;
    }
    else cout<<"No"<<endl;
  }
  else cout<<"No"<<endl;
  return 0;
}

