        ok.pop();
        ll st = find(ALL(sa), now.fi)-sa.begin();
        ll ed = find(ALL(sb), now.se)-sb.begin();
//        dbg(st);
//        dbg(ed);

        ll lc = lower_bound(ALL(ng),st)-ng.begin();
        ll rc = lower_bound(ALL(ng),ed)-ng.begin();

        if(lc==0){
            if(ng[0]<st){
                lc = -1;
            }
        }
        if(rc==0){
            if(ng[0]<ed){
                rc = -1;
            }
        }
//        dbg(lc);
//        dbg(rc);
        if(rc-lc==0){
            Yes(true);
            return 0;
        }

    }
    Yes(false);
    return 0;
}

