int main()
{
  int n;
  vector<pi> a; // a は value, index
  vector<pi> b; // b は b.value, a.value

  cin >> n;
  int v;
  for (int i = 0; i < n; ++i)
  {
    cin >> v;
    a.push_back(pi(v, i)); //
  }
  for (int i = 0; i < n; ++i)
  {
    cin >> v;
    b.push_back(pi(v, a[i].first));
  }
  sort(a.begin(), a.end());
  sort(b.begin(), b.end());

  // N-2 の制限を考えずに自由に並び替えたばあい
  for (int i = 0; i < n; ++i)
  {
    if (a[i].first > b[i].first)
    {
      // No が確定
      cout << "No" << endl;
      return 0;
    }
  }

  for (int i = 0; i < n - 1; ++i)
  {
    if (a[i + 1].first <= b[i].first)
    {
      cout << "Yes" << endl;
      return 0;
    }
  }

  a.clear();
  for (int i = 0; i < n; ++i)
  {
    a.push_back(pi(b[i].second, i));
  }
  sort(a.begin(), a.end());

  // サイクル数が1じゃないかどうか調べる
  const long long size = 1e5 + 10;
  bitset<size> visited(0);
  int crnt = 0;
  while (!visited.test(crnt))
  {
    visited.set(crnt);
    crnt = a[crnt].second;
  }
  if (visited.count() == n)
  {
    cout << "No" << endl;
    return 0;
  }
  else
  {
    cout << "Yes" << endl;
    return 0;
  }
  return 0;
}

