			int b = sc.nextInt();
			list_b.add(b);
		}

		for(int i=0;n>i;i++) {
			if(list_a.get(i)>list_b.get(i)) {
				for(int j=n-1;-1<j;j--) {
					if(list_a.get(j)<=list_b.get(i)) {
						if(i!=n-1) {
							int a = list_a.get(i);
							list_a.set(i, list_a.get(j));
							list_a.set(j, a);
							break;
						}
						else {
							if(list_a.get(i)<=list_b.get(j)) {
								int a = list_a.get(i);
								list_a.set(i, list_a.get(j));
								list_a.set(j, a);
								break;
							}
						}
					}
					if(j==0) {
						System.out.println("No");
						System.exit(0);
					}
				}
			}
		}
		System.out.println("Yes");
	}
}

