            if(aa[i]>bb[i]) {
                System.out.println("No");
                return;
            }
        }
        for(int i=0; i<n; i++) {
            int p = Arrays.binarySearch(aa, b[i]);
            if(p == n) {
                b[i] = aa[n-1];
            } else if (p >= 0) {
                b[i] = aa[p];
            } else {
                b[i] = aa[-2-p];
            }
            bb[i] = b[i];
        }
        Arrays.sort(bb);

        for(int i=1; i<n; i++) {
            if(bb[i-1]==bb[i]) {
                System.out.println("Yes");
                return;
            }
        }
        for(int i=0; i<n; i++) {
            if(a[i] == b[i]) {
                System.out.println("Yes");
                return;
            }
        }
        int[] aaa = new int[n];
        int[] bbb = new int[n];

        P[] pa = new P[n];
        for(int i=0; i<n; i++) {
            pa[i] = new P(Arrays.binarySearch(aa, a[i]),  Arrays.binarySearch(aa, b[i]));
        }
        Arrays.sort(pa);
        boolean[] v = new boolean[n];
        v[0] = true;
        int q = 0;
        while(true) {
            int next = pa[q].b;
            if(v[next]) break;
            v[next] = true;
            q = next;
        }
        for(int i=0; i<n; i++) {
            if(!v[i]) {
                System.out.println("Yes");
