        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];

        int[] sa = new int[n];
        int[] sb = new int[n];
        for (int i = 0; i < n; i++) {
            sa[i] = a[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            sb[i] = b[i] = sc.nextInt();
        }

        Arrays.sort(sa);
        Arrays.sort(sb);

        for (int i = 0; i < sb.length; i++) {
            if(sa[i] > sb[i]){
                System.out.println("No");
                return;
            }
        }

        int num = 0;
        for (int i = 0; i < sb.length; i++) {
            if(a[i] > b[i]) num++;
        }

        if(num >= n-1){
            System.out.println("No");
            return;
        }

        HashMap<Long, Integer> map = new HashMap<Long, Integer>();
        for (int i = 0; i < sb.length; i++) {
            long tmp = (long)sa[i] * ((long)Integer.MAX_VALUE+1) + sb[i];
            map.put(tmp, i);
        }

        int num2 = 0;
        for (int i = 0; i < sb.length; i++) {
            long key = (long)a[i] * ((long)Integer.MAX_VALUE+1) + b[i];
            if(map.containsKey(key)){
                num2++;
