	static int[] divisor(int num){
		Set<Integer> divisors = new TreeSet<>();
		int tmp=1;
		while(tmp*tmp<=num){
			if(num%tmp == 0){
				divisors.add(tmp);
				divisors.add(num/tmp);
			}
			tmp++;
		}
		Integer[] rtn = new Integer[divisors.size()];
		divisors.toArray(rtn);
		int[] ans = new int[rtn.length];
		for(int i=0; i<rtn.length; i++){
			ans[i] = rtn[i];
		}
		return ans;
	}

