public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ProblemC_Swaps solver = new ProblemC_Swaps();
        solver.solve(1, in, out);
        out.close();
    }

    static class ProblemC_Swaps {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }
            int[] b = new int[n];
            for (int i = 0; i < n; i++) {
                b[i] = in.nextInt();
            }

            int[] sortedA = a.clone();
            int[] sortedB = b.clone();
            Arrays.sort(sortedA);
            Arrays.sort(sortedB);
            for (int i = 0; i < n; i++) {
                if (sortedA[i] > sortedB[i]) {
                    out.println("No");
                    return;
                }
            }

            Pair[] pairs = new Pair[n];
            for (int i = 0; i < n; i++) {
                pairs[i] = new Pair();
                pairs[i].a = a[i];
                pairs[i].b = i;
            }

            Arrays.sort(pairs, (u, v) -> (u.a - v.a));

            int[] p = new int[n];
            for (int i = 0; i < n; i++) {
                p[pairs[i].b] = i;
            }
            int cycleLen = 0;
            {
                int i = 0;
                do {
                    i = p[i];
                    ++cycleLen;
                } while (i != 0);
            }
            if (cycleLen < n) {
                out.println("Yes");
                return;
            }

            for (int i = 0; i < n; i++) {
                if (a[i] <= b[i]) {
                    out.println("Yes");
                    return;
                }
            }

            out.println("No");
        }

        class Pair {
            int a;
            int b;

        }

    }

