  public static void main(String[] args) {
    Scanner stdIn = new Scanner(System.in);
    int count = 0;

    int n = stdIn.nextInt();
    int[] a = new int[n];
    int[] b = new int[n];

    for (int i = 0; i < n; i++) {
      a[i] = stdIn.nextInt();
    }
    for (int i = 0; i < n; i++) {
      b[i] = stdIn.nextInt();
    }

    int x, y;
    for (x = 0; x < n; x++) {
      if (a[x] > b[x]) {
        for (y = 0; y < n; y++) {
          if (a[y] <= a[x] - 1) {
            int c = a[y];
            a[y] = a[x];
            a[x] = c;
          }
          if (a[y] > b[y]) {
            int c = a[y];
            a[y] = a[x];
            a[x] = c;
          } else {
            count++;
            break;
          }
        }
        if (y == n) {
          System.out.println("No");
          break;
        }
      }
    }
    if (count <= n - 2) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }

  }
}

import java.util.*;
public class Main {

    public static void main(String[] args) {
        //data input
        Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();

        long[] A = new long[N];

        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
        }

        long[] B = new long[N];
        for (int i = 0; i < N; i++) {
            B[i] = sc.nextInt();
        }


        //logic
        int ct = (N - 2 <= 0)? 0 : N - 2;
        for (int i = 0; ct >= 0 && i < N; i++) {
            if (A[i] > B[i]) {
                int pCt = ct;
                for (int j = i + 1; j < N; j++) {
                    if (A[j] > B[j] && A[i] <= B[j]) {
                        //swap
                        ct-=1;
                        if (ct < 0) {
                            ct=-999;
                            break;
                        }
                        long work = B[i];
                        B[i] = B[j];
                        B[j] = B[i];
                        break;
                    }
                }
                if (pCt == ct) {//交換できなかった場合
                    int pCt2 = ct;
                    for (int j = i - 1; j >= 0; j--) {
                        if (A[j] > B[j] && A[i] <= B[j]) {
                            //swap
                            ct-=1;
                            if (ct < 0) {
                                ct=-999;
                                break;
                            }
                            long work = B[i];
                            B[i] = B[j];
                            B[j] = B[i];
                            break;
                        }
                    }
                    if (pCt2 == ct) ct = -999;
                }
            }
        }
        System.out.println((ct >= 0)? "Yes": "No");
    }
}

