        // a の n 乗を mod の余りで計算する
        long mod = 998244353;
        public long modpow(long a, long n) {				
        	long res = 1;			
        	while(n > 0) {			
        		if((n & 1) == 1)		
        			res = res * a % mod;	
        		a = a * a % mod;		
        		n = n >> 1;		
        	}			
        	return res;			
        }				

