public class Main implements Runnable{

	private class Pair implements Comparable<Pair>{
		int first, second;
		int index;
		@Override
		public int compareTo(Pair o) {
			if (first != o.first)return Integer.compare(first, o.first);
			return Integer.compare(second, o.second);
		}
		@Override
		public String toString() {
			return "(" + first + "," + second + ")";
		}
	}
	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * 第二回全国統一プログラミング王決定戦予選 C問題
		 * 考察メモ
		 * この問題は次と同じ
		 * ある組(A_i, B_i)を固定する
		 * それ以外のすべてについては好きな順番にしていい時、条件を満たすか？
		 * まず、あるiについて解くのは、とりあえずソートして比較すればO(NlogN)
		 * ここで、次のことを考える
		 * 1 2 3 3 4 6
		 * 2 2 3 3 4 8
		 * 上から一つを選ぶと、対応するもう一つの下の値も消えて詰められる
		 * この時も条件を満たすか求めたい
		 * これは、1個ずらした時に満たすか～を知りたいことになる
		 * ここで、上の値のindexがi、下の対応する値のindexがjとする
		 * これは、次について判定できれば良いことになる
		 * 1. i, j未満の場所
		 * 変わらないので問題無し
		 * 2. i以上j未満の場所
		 * 上だけ一つずれたものについて判定結果を持っておけばいい
		 * 3. j以上i未満の場所
		 * 下だけ一つずれたものについて判定結果を持っておけばいい
		 * 4. i, j以上の場所
		 * 変わらないので問題無し
		 * よって、左右それぞれにずらしたものについても判定を持って置き、区間判定O(1)にしておけばいい
		 * これは累積和でできるので、計算量はO(NlogN)
		 *
		 * 実験
		 * 1 2 3 3 4 6
		 * 2 8 2 4 3 3
		 * がまず持てる値
		 * で、次にBについて更に第何番目の値か持ちたい
		 * すると
		 * 1 2 3 3 4 6
		 * 2 8 2 4 3 3
		 * 1 6 2 5 3 4
		 * みたいにナンバリングできると
		 * で、これについて今度は左右それぞれについて持つ
		 * -1: TFTFTTF
		 * 0: TTTTTTT
		 * +1: TTTTTTT
		 */

		int N = io.nextInt();
		Pair[] A = new Pair[N];
		for (final int i : IntRange.open(N)) {
			A[i] = new Pair();
			A[i].first = io.nextInt();
		}
		for (final int i : IntRange.open(N)) {
			A[i].second = io.nextInt();
		}
		Arrays.sort(A);
		PriorityQueue<Pair> pq = new PriorityQueue<>((p, q) -> Integer.compare(p.second, q.second));
		for (Pair i : A) pq.add(i);
		Pair[] B = new Pair[N];
		for (int i = 0;i < N;++ i) {
			B[i] = pq.poll();
			B[i].index = i;
		}
		int[][] cumsum = new int[3][N + 1];
		for (int i = 0;i < 3;++ i) cumsum[i][0] = 0;
		for (int i = 0;i < N;++ i) {
			cumsum[0][i + 1] = cumsum[0][i] + (i == 0 ? 0 : A[i].first <= B[i - 1].second ? 1 : 0);
			cumsum[1][i + 1] = cumsum[1][i] + (A[i].first <= B[i].second ? 1 : 0);
			cumsum[2][i + 1] = cumsum[2][i] + (i >= N - 1 ? 0 : A[i].first <= B[i + 1].second ? 1 : 0);
		}
		/*io.println(A);
		io.println(B);
		io.println(cumsum);*/
		for (int i = 0;i < N;++ i) {
			int j = A[i].index;
			boolean isYes = true;
			if (i < j) {
				isYes &= cumsum[1][i] - cumsum[1][0] == i;
				isYes &= cumsum[0][j] - cumsum[0][i] == j - i;
				isYes &= cumsum[1][N] - cumsum[1][j] == N - j;
			} else {
				isYes &= cumsum[1][j] - cumsum[1][0] == j;
				isYes &= cumsum[2][i] - cumsum[2][j] == i - j;
				isYes &= cumsum[1][N] - cumsum[1][i] == N - i;
			}
			//io.println(i + ":" + j + " : " + isYes);
			if (isYes) {
				io.println("Yes");
				return;
			}
		}
		io.println("No");
	}

