            ab[i][2]=i;
        }
        for(int i=0;i<n;i++){
            ab[n+i][0]=b[i];
            ab[n+i][1]=1;
            ab[n+i][2]=i;
        }
        Arrays.sort(ab, (u, v)->u[0]>v[0]?1:u[0]<v[0]?-1:u[1]>v[1]?1:u[1]<v[1]?-1:0);
        int ac=0, bc=0;
        boolean flg=false;
        int[] aind=new int[n];
        int[] bind=new int[n];
        int[] arev=new int[n];
        int i1=0, i2=0;
        for(int i=0;i<2*n;i++){
            if(ab[i][1]==0){
                aind[i1]=(int) ab[i][2];
                arev[aind[i1]]=i1;
                i1++;
            }
            else{
                bind[i2]=(int) ab[i][2];
                i2++;
            }
        }
        for(int i=0;i<2*n;i++){
