                }
            }

            Arrays.sort(c, (u, v) -> -(u.b - v.b));

            int numSwaps = 0;
            boolean[] frozen = new boolean[n];
            Pair[] who = new Pair[n];
            for (int i = 0; i < n; i++) {
                who[c[i].a] = c[i];
//            System.out.println(c[i].a + " " + c[i].b);
            }
            int last = n - 1;
            for (int i = 0; i < n; i++) {
                // .a = position now
                // .b = leftmost possible position after swap
                if (c[i].a >= c[i].b) {
                    frozen[c[i].a] = true;
                    continue;
                }
                while (frozen[last]) {
                    --last;
                }
                swap(c[i].a, last, who);
                frozen[c[i].a] = true;
                if (c[i].a < c[i].b) {
                    out.println("No");
                    return;
                }
                ++numSwaps;
            }

            out.println(numSwaps <= n - 2 ? "Yes" : "No");
        }

        private void swap(int i, int j, Pair[] who) {
            Pair pi = who[i];
            Pair pj = who[j];
            if (pi.a != i) {
                throw new AssertionError();
            }
            if (pj.a != j) {
                throw new AssertionError();
            }
            pi.a = j;
            pj.a = i;
            who[i] = pj;
            who[j] = pi;
        }

        class Pair {
            int a;
            int b;

        }

    }

