public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		int[] b = na(n);
		int[] sa = Arrays.copyOf(a, n);
		int[] sb = Arrays.copyOf(b, n);
		Arrays.sort(sa);
		Arrays.sort(sb);
		for(int i = 0;i < n;i++){
			if(sa[i] > sb[i]){
				out.println("No");
				return;
			}
		}

		for(int i = 0;i < n-1;i++){
			if(sa[i+1] <= sb[i]){
				out.println("Yes");
				return;
			}
		}

		int[][] ab = new int[n][];
		for(int i = 0;i < n;i++){
			ab[i] = new int[]{a[i], b[i], -1};
		}
		Arrays.sort(ab, new Comparator<int[]>() {
			public int compare(int[] a, int[] b) {
				return a[0] - b[0];
			}
		});
		for(int i = 0;i < n;i++)ab[i][2] = i;
		Arrays.sort(ab, new Comparator<int[]>() {
			public int compare(int[] a, int[] b) {
				return a[1] - b[1];
			}
		});

		DJSet ds = new DJSet(n);
		for(int i = 0;i < n;i++){
			ds.union(i, ab[i][2]);
		}
		out.println(ds.count() == 1 ? "No" : "Yes");
	}

	public static class DJSet {
		public int[] upper;

		public DJSet(int n) {
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		public int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
				}
				upper[x] += upper[y];
				upper[y] = x;
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


