    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        B = sc.nextIntArray(N);

        System.out.println(solve() ? "Yes" : "No");
    }

    static boolean solve() {
        // N-2回なので割り当て一か所固定してしまいたい
        int best = -1;
        int diff = Integer.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if( A[i] <= B[i] && B[i] - A[i] < diff) {
                best = i;
                diff = B[i] - A[i];
            }
        }
        if( best == -1 ) return false;
        // debug(best);

        // 残りを割り当て可能ならいいのでは？
        PriorityQueue<Integer> qa = new PriorityQueue<>();
        PriorityQueue<Integer> qb = new PriorityQueue<>();
        for (int i = 0; i < N; i++) {
            if( best != i ) {
                qa.add( A[i] );
                qb.add( B[i] );
            }
        }
        // debug(qa, qb);

        while(!qa.isEmpty()) {
            int a = qa.poll();
            int b = qb.poll();
            if( a > b ) {
                return false;
            }
        }
        return true;
    }

