public class Main {

    public static void main(String[] args) {
        final Scanner scanner = new Scanner(System.in);
        solve(scanner);
    }

    static class Node {
        int val;
        int oIndex;

        public Node(int val, int oIndex) {
            this.val = val;
            this.oIndex = oIndex;
        }
    }

    // int N = scanner.nextInt();
    // scanner.nextLine();
    // int[] n = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    static void solve(Scanner scanner) {
        int N = scanner.nextInt();
        scanner.nextLine();
        int[] a = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int[] b = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        Node[] sa = new Node[N];
        for (int i = 0; i < N; i++) {
            sa[i] = new Node(a[i] ,i);
        }
        Arrays.sort(sa, Comparator.comparingInt(x -> x.val));
        int[] sb = Arrays.stream(b).sorted().toArray();

        for (int i = 0; i < N; i++) {
            if (sa[i].val > sb[i]) {
                System.out.println("No");
                return;
            }
        }

        TreeSet<Integer> rem = new TreeSet<>();
        for (int i = 0; i < N; i++)
            rem.add(i);
        int cycle = 0;
        while (!rem.isEmpty()) {
            int s = rem.first();
            rem.remove(s);
            int curr = sa[s].oIndex;

            while (curr != s) {
                rem.remove(curr);
                curr = sa[curr].oIndex;
            }
            cycle++;
        }

        if (cycle > 1) {
            System.out.println("Yes");
            return;
        }

        for (int i = 0; i < N - 1; i++) {
            if (sb[i] >= sa[i + 1].val) {
                System.out.println("Yes");
                return;
            }
        }
        System.out.println("No");
    }
}

