        }

        HashMap<Long, Integer> map = new HashMap<Long, Integer>();
        for (int i = 0; i < sb.length; i++) {
            long tmp = (long)sa[i] * ((long)Integer.MAX_VALUE+1) + sb[i];
            map.put(tmp, i);
        }

        for (int i = 0; i < sb.length; i++) {
            long key = (long)a[i] * ((long)Integer.MAX_VALUE+1) + b[i];
            if(map.containsKey(key)){
