/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ProblemC_Swaps solver = new ProblemC_Swaps();
        solver.solve(1, in, out);
        out.close();
    }

    static class ProblemC_Swaps {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }
            int[] b = new int[n];
            for (int i = 0; i < n; i++) {
                b[i] = in.nextInt();
            }

            Pair[] sortedA = new Pair[n];
            for (int i = 0; i < n; i++) {
                sortedA[i] = new Pair(a[i], i);
            }
            Arrays.sort(sortedA, (u, v) -> (u.a - v.a));
            int[] p = new int[n];
            for (int i = 0; i < n; i++) {
                p[sortedA[i].b] = i;
            }

            Pair[] sortedB = new Pair[n];
            for (int i = 0; i < n; i++) {
                sortedB[i] = new Pair(b[i], i);
            }
            Arrays.sort(sortedB, (u, v) -> (u.a - v.a));
            int[] q = new int[n];
            for (int i = 0; i < n; i++) {
                q[sortedB[i].b] = i;
            }

            int[] invQ = new int[n];
            for (int i = 0; i < n; i++) {
                invQ[q[i]] = i;
            }

            for (int i = 0; i < n; i++) {
                if (sortedA[i].a > sortedB[i].a) {
                    out.println("No");
                    return;
                }
            }

            for (int i = 0; i < n; i++) {
                p[i] = invQ[p[i]];
            }
            int cycleLen = 0;
            {
                int i = 0;
                do {
                    i = p[i];
                    ++cycleLen;
                } while (i != 0);
            }
            if (cycleLen < n) {
                out.println("Yes");
                return;
            }

            for (int i = 0; i < n; i++) {
                if (a[i] <= b[i]) {
                    out.println("Yes");
                    return;
                }
            }

            out.println("No");
        }

        class Pair {
            int a;
            int b;

            Pair(int a, int b) {
                this.a = a;
                this.b = b;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String rl = in.readLine();
                    if (rl == null) {
                        return null;
                    }
                    st = new StringTokenizer(rl);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

