        // 1つだけ元の位置のまま　目的を達成できるか?

        // Bでソート
        int[] sortedByB = new int[N].Select((i, index) => index).ToArray();
        Array.Sort(sortedByB, (l, r) =>
        {
            if (B[l] == B[r])
            {
                return A[l].CompareTo(A[r]);
            }
            return B[l].CompareTo(B[r]);
        });

        int[] aa = new int[N].Select((i, index) => A[sortedByB[index]]).ToArray();
        int[] bb = new int[N].Select((i, index) => B[sortedByB[index]]).ToArray();

        int[] sortedByAA = new int[N].Select((i, index) => index).ToArray();
        Array.Sort(sortedByAA, (l, r) => aa[l].CompareTo(aa[r]));

        for (int i = 0; i < N; i++)
        {
            if (aa[sortedByAA[i]] > bb[i])
            {
                Console.WriteLine("No");
                return;
            }
        }

        var st = new SegmentTree<bool>((l, r) => l && r, true);

        // いっこ上可能か?
        for (int i = 0; i < N - 1; i++)
        {
            st[i] = aa[sortedByAA[i + 1]] <= bb[i];
        }

        // a[i]の位置をそのままにする
        for (int i = 0; i < N; i++)
        {
            if (aa[i] > bb[i]) continue;
            if (aa[sortedByAA[i]] <= aa[i])
            {
                Console.WriteLine("Yes");
                return;
            }

            // 来る位置をj
            // bの[i,j)が1つ上を許容するか?

            int j = N - 1;
            int ng = -1;
            while (j-ng > 1)
            {
                int mid = (j + ng) / 2;
                if (aa[sortedByAA[mid]] <= aa[i])
                {
                    j = mid;
                }
                else
                {
                    ng = mid;
                }
            }

            if (st.Query(i, j))
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        Console.WriteLine("No");
    }


    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Collections.Generic
{
    using System;

    public class SegmentTree<T>
    {
        // 制約に合った2の冪
        private const int N = 1 << 21;
        private T[] _array;

        private T _identity;
        private Func<T, T, T> _operation;

        public SegmentTree(Func<T, T, T> operation, T identity)
        {
            _identity = identity;
            _operation = operation;
            _array = new T[N * 2];
            for (int i = 1; i < N * 2; i++)
            {
                _array[i] = _identity;
            }
        }

        /// <summary>
        /// A[i]をnに更新 O(log N)
        /// </summary>
        /// <param name="i"></param>
        /// <param name="n"></param>
        public void Update(int i, T n)
        {
            i += N;
            _array[i] = n;
            while (i > 1)
            {
                i /= 2;
                _array[i] = _operation(_array[i * 2], _array[i * 2 + 1]);
            }
        }

        private T Query(int left, int right, int k, int l, int r)
        {
            if (r <= left || right <= l)
            {
                return _identity;
            }

            if (left <= l && r <= right)
            {
                return _array[k];
            }

            return _operation(Query(left, right, k * 2, l, (l + r) / 2),
                Query(left, right, k * 2 + 1, (l + r) / 2, r));
        }

        /// <summary>
        /// A[left] op A[left+1] ... op A[right-1]を求める
        /// </summary>
        /// <param name="left"></param>
        /// <param name="right"></param>
        /// <returns></returns>
        public T Query(int left, int right)
        {
            return Query(left, right, 1, 0, N);
        }

        public T this[int i]
        {
            set { Update(i, value); }
            get { return _array[i + N]; }
        }
    }
}

