using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var B = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

        var orderedA = A.OrderBy(x => x).ToArray();
        var orderedB = B.OrderBy(x => x).ToArray();

        for (int i = 0; i < N; i++)
        {
            if (orderedA[i] > orderedB[i])
            {
                Console.WriteLine("No");
                return;
            }
        }

        var pos = new Dictionary<long, Queue<int>>();
        var order = new int[N];
        for (int i = 0; i < N; i++)
        {
            if (!pos.ContainsKey(A[i]))
            {
                pos[A[i]] = new Queue<int>();
            }
            pos[A[i]].Enqueue(i);
        }
        for (int i = 0; i < N; i++)
        {
            order[i] = pos[orderedA[i]].Dequeue();
        }
        var count = 0;
        var p = 0;
        do
        {
            p = order[p];
            count++;
        } while (p != 0);
        if (count != N)
        {
            Console.WriteLine("Yes");
            return;
        }

        for (int i = 0; i < N - 1; i++)
        {
            if (orderedA[i + 1] <= orderedB[i])
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        Console.WriteLine("No");
    }
}

