        var C = new int[N];
        var D = new int[N];

        Array.Copy(A, C, N);
        Array.Copy(B, D, N);

        Array.Sort(C);
        Array.Sort(D);
        for (int i = 0; i < N; i++)
        {
            if (C[i] > D[i])
            {
                WriteLine("No");
                return;
            }
        }

        Array.Sort(B, A);
        var Q = new PriorityQueue<pair>();
        var S = new Set<pair>();
        for (int i = 0; i < N; i++)
        {
            Q.Enqueue(new pair(A[i], i));
        }

        int cnt = 0;
        int start = N;
        while (Q.Any)
        {
            var d = Q.Dequeue();
            int n = d.f;
            int u = d.s;

            if (n <= B[u])
            {
                continue;
            }
            var b = B.lower_bound(n);

            for (int i = start - 1; i >= b; i--)
            {
                S.Add(new pair(A[i], i));
            }
            var k = S.LowerBound(new pair(B[u] + 1, -1)) - 1;
            if (k < 0)
            {
                for (int i = b - 1; i >= 0; i--)
                {
                    S.Add(new pair(A[i], i));
                }
                b = 0;
            }
            k = S.LowerBound(new pair(B[u] + 1, -1)) - 1;
            if (k < 0)
            {
                WriteLine("No");
                return;
            }


            var t = S[k];

            cnt++;
            Q.Enqueue(new pair(t.f, u));
            A[u] = t.f;

            S.RemoveAt(k);
            start = b;
        }


        if (cnt > N - 2)
        {
            WriteLine("No");
            return;
        }

        WriteLine("Yes");
    }

}


class PriorityQueue<T> where T : IComparable<T>
{
    List<T> heap;
    readonly int cmp;
    public PriorityQueue(int cmp = 1) { heap = new List<T>(); this.cmp = cmp; }
    public void Enqueue(T x)
    {
        heap.Add(x);
        int i = Count++;
        while (i > 0)
        {
            int p = (i - 1) >> 1;
            if (x.CompareTo(heap[p]) * cmp <= 0) break;
            heap[i] = heap[p]; i = p;
        }
        heap[i] = x;
    }
    public T Dequeue()
    {
        T ret = heap[0]; T x = heap[--Count];
        int i = 0;
        while ((i << 1) + 1 < Count)
        {
            int a = (i << 1) + 1; int b = (i << 1) + 2;
            if (b < Count && heap[a].CompareTo(heap[b]) * cmp < 0) a = b;
            if (x.CompareTo(heap[a]) * cmp >= 0) break;
            heap[i] = heap[a]; i = a;
        }
        heap[i] = x; heap.RemoveAt(Count);
        return ret;
    }
    public int Count { get; private set; }
    public bool Any => Count > 0;
    public T Peek => heap[0];
}

