using System;
using System.Collections.Generic;
using System.Linq;
using System.Transactions;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        var aa = new SA[N];
        var bb = new SB[N];

        for (int i = 0; i < N; i++)
        {
            aa[i] = new SA(A[i], i);
            bb[i] = new SB(B[i], i);
        }

        Array.Sort(aa, (a, b) => a.N.CompareTo(b.N));
        Array.Sort(bb, (a, b) =>
        {
            if (a.N == b.N)
            {
                return A[a.Index].CompareTo(A[b.Index]);
            }
            else
            {
                return a.N.CompareTo(b.N);
            }
        });


        bool flag = false;
        int l = 0;
        for (int i = 0; i < N; i++)
        {
            int min = -1;
            int max = N;
            while (max - min > 1)
            {
                int med = (min + max) / 2;
                if (aa[med].N <= bb[i].N)
                {
                    min = med;
                }
                else
                {
                    max = med;
                }
            }

            // [0,min]を使いたい
            // [0,i-1]は使用済み
            // i <= minならok


            if (min < i)
            {
                Console.WriteLine("No");
                return;
            }

            // 元の対応するやつが [i, min]なら flagを立てる

            if (A[bb[i].Index] <= aa[min].N)
            {
                flag = true;
            }
        }

        Console.WriteLine(flag ? "Yes" : "No");
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

