    {
        int N = sc.Int;
        var A = Create(N, idx => new Pi(sc.Next<int>(), idx));
        var B = sc.ArrInt;
        Array.Sort(A, (a, b) => a.v1 - b.v1);
        Array.Sort(B);
        for (var i = 0; i < N; i++)
            if (A[i].v1 > B[i]) Fail("No");
        var uf = new UnionFind(N);
        for (var i = 0; i < N; i++)
            uf.Union(i, A[i].v2);
        if (uf.Size(0) != N) Fail("Yes");
        for (var i = 0; i < N - 1; i++)
            if (A[i + 1].v1 <= B[i]&&A[i].v1<=B[i+1]) Fail("Yes");
        WriteLine("No");
    }
}

public class UnionFind
{
    public int GroupCount { get; private set; }
    protected int[] data;
    public virtual int this[int i] { get { return Find(i); } }
    public UnionFind(int size)
    {
        data = new int[size];
        GroupCount = size;
        for (var i = 0; i < size; i++)
            data[i] = -1;
    }
    protected int Find(int i)
        => data[i] < 0 ? i : (data[i] = Find(data[i]));
    public int Size(int i)
        => -data[Find(i)];
    public virtual bool Union(int u, int v)
    {
        u = Find(u); v = Find(v);
        if (u == v) return false;
        if (data[u] > data[v])
            swap(ref u, ref v);
        GroupCount--;
        data[u] += data[v];
        data[v] = u;
        return true;
    }
}
