    static object process(TextReader input) {
        var n = int.Parse(input.ReadLine());
        var aa = ToIntArray(input.ReadLine(), n);
        var bb = ToIntArray(input.ReadLine(), n);

        var aaa = new List<work>(n);

        for (int i=0; i<n; i++) {
            aaa.Add(new work() { a = aa[i], b = bb[i] });
        }

        aa.Sort();
        bb.Sort();

        for(int i=0; i<n; i++) {
            if (aa[i] > bb[i]) return "No";
        }

        aaa.Sort((x,y)=> { return x.b - y.b; });
        for (int i = 0; i < n; i++) aaa[i].idx = i;
        aaa.Sort((x, y) => { return x.a - y.a; });

        int count = 0;
        int idx = 0;
        while (true) {
            count++;
            var w = aaa[idx];
            if (w.idx == 0) break;
            idx = w.idx;
        }
        if (count < n) return "Yes";

        for(int i=0; i<n-1; i++) {
            if (aa[i + 1] <= bb[i]) return "Yes";
        }
        return "No";
    }

    class work
    {
        public int idx;
        public int a;
        public int b;
    }

    static List<int> ToIntArray(string strs, int n) {
        var ret = new List<int>(n);
        var spl =strs.Split(' ');
        for (int i = 0; i < n; i++)
            ret.Add(int.Parse(spl[i]));
        return ret;
    }
}

