static class Algorithms
{
    static long swap_count = 0;
    private static void Swap<T>(ref T a, ref T b)
    {
        T tmp = a;
        a = b;
        b = tmp;
    }

    private static void _QuickSort<T>(T[] arr, Int64 left, Int64 right, Comparison<T> comparison)
    {
        Int64 pl = left;
        Int64 pr = right;
        T pivot = arr[(pl + pr) / 2];
        do
        {
            while (comparison(arr[pl], pivot) < 0) pl++;
            while (comparison(arr[pr], pivot) > 0) pr--;
            if (pl <= pr)
            {
                Swap(ref arr[pl], ref arr[pr]);
                pl++;
                pr--;
            }
        } while (pl <= pr);

        if (left < pr)
        {
            _QuickSort(arr, left, pr, comparison);
        }
        if (pl < right)
        {
            _QuickSort(arr, pl, right, comparison);
        }
    }
    public static void QuickSort<T>(T[] arr, Comparison<T> comparison)
    {
        _QuickSort(arr, 0, arr.Length - 1, comparison);
    }
}

