        Array.Sort(D);
        for (int i = 0; i < N; i++)
        {
            if (C[i] > D[i])
            {
                WriteLine("No");
                return;
            }
        }

        Array.Sort(B, A);
        var Q = new PriorityQueue<pair>();
        var S = new Set<pair>();
        for (int i = 0; i < N; i++)
        {
            Q.Enqueue(new pair(A[i], i));
        }

        int cnt = 0;
        int start = N;
        while (Q.Any)
        {
            var d = Q.Dequeue();
            int n = d.f;
            int u = d.s;

            if (n <= B[u])
            {
                continue;
            }
            var b = B.lower_bound(n);

            for (int i = start - 1; i >= b; i--)
            {
                S.Add(new pair(A[i], i));
            }
            var k = S.LowerBound(new pair(B[u] + 1, -1)) - 1;
            if (k < 0)
            {
                for (int i = b - 1; i >= 0; i--)
                {
                    S.Add(new pair(A[i], i));
                }
                b = 0;
                k = S.LowerBound(new pair(B[u] + 1, -1)) - 1;
            }

            if (k < 0)
            {
                WriteLine("No");
                return;
            }


            var t = S[k];

            cnt++;
            Q.Enqueue(new pair(t.f, u));
            A[u] = t.f;

            S.RemoveAt(k);
            S.Add(new pair(n, t.s));
            start = b;
        }


        if (cnt > N - 2)
        {
            WriteLine("No");
            return;
        }

        WriteLine("Yes");
    }

