		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			long[] a = cin.ArrayLong(n);
			long[] b = cin.ArrayLong(n);

			var sa = a.Select((v, i) => new { Value = v, Index = i }).OrderBy(x => x.Value).ToArray();
			var sb = b.Select((v, i) => new { Value = v, Index = i }).OrderBy(x => x.Value).ToArray();
			for (int i = 0; i < n; i++) {
				if (sa[i].Value > sb[i].Value) {
					Console.WriteLine("No");
					return;
				}
			}

			var dist = Enumerable.Repeat(-1, n).ToArray();
			int count = 1;
			dist[0] = 0;
			int next = sa[0].Index;
			for (int i = 0; i < n; i++) {
				if (dist[next] != -1) {
					break;
				}

				dist[next] = count;
				++count;
				next = sa[next].Index;
			}

			if (count < n) {
				int c = 0;
				Console.WriteLine(1 / c);
				return;
			}

			for (int i = 0; i < n - 1; i++) {
				if (sa[i + 1].Value <= sb[i].Value) {
					Console.WriteLine("Yes");
					return;
				}
			}

			Console.WriteLine("No");
		}
	}


	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

