using System;
using System.Linq;
using System.Collections.Generic;
using System.Numerics;
class ProgramC
    {
        static void Main(string[] args)
        {
            string input = Console.ReadLine();
            long n = long.Parse(input);

            long[] a = new long[n];
            long[] b = new long[n];
            long[] a_order = new long[n];
            List<Task> task= new List<Task>();

            string[] input_a = Console.ReadLine().Split();
            string[] input_b = Console.ReadLine().Split();


            for(long i = 0;i < n;i++)
            {
                a[i] = long.Parse(input_a[i]);
                b[i] = long.Parse(input_b[i]); 
                task.Add(new Task(a[i],i));
            }

            Array.Sort(b);
            IOrderedEnumerable<Task> sorted = task.OrderBy(x => x.a);

            long j = 0;
            foreach(Task s in sorted)
            {
               a_order[j] = s.order;
               a[j] = s.a;
               j++;
            }


            for(long i = 0;i < n;i++)
            {
                if(a[i] > b[i])
                {
                    Console.WriteLine("No");
                    return;
                } 
            }



            long count = 0;
            long p = 0;
            do
            {
                p = a_order[p];
                count++;

            } while (p != 0);


            if(count != n)
            {
                Console.WriteLine("Yes");
                return;
            }

            for(long i = 1;i <n;i++)
            {
                if(a[i] <= b[i - 1])
                {
                    Console.WriteLine("Yes");
                    return;
                } 
            }

            Console.WriteLine("No");
        }
    }

