using System;
using System.Collections.Generic;
using System.Linq;
using CompLib.Util;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();


        // N-1回あれば任意の順番にできる
        // swapのサイクルを2つ以上できれば可能

        var sortedByB = new int[N].Select((i, index) => index).ToArray();
        Array.Sort(sortedByB, (l, r) => B[l].CompareTo(B[r]));
        var aa = new int[N].Select((i, index) => A[sortedByB[index]]).ToArray();
        var bb = new int[N].Select((i, index) => B[sortedByB[index]]).ToArray();

        var sortedByAA = new int[N].Select((i, index) => index).ToArray();

        Array.Sort(sortedByAA, (l, r) => aa[l].CompareTo(aa[r]));
        for (int i = 0; i < N; i++)
        {
            if (aa[sortedByAA[i]] > bb[i])
            {
                Console.WriteLine("No");
                return;
            }
        }


        // 2つの位置を入れ替えてもOK 2つ以外をN-2回でソートすれば条件を満たす
        for (int i = 0; i < N - 1; i++)
        {
            if (bb[i] >= aa[sortedByAA[i + 1]])
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        // 目標は aaのソート
        // 上で確かめたのでaaに被りはない

        int cnt = 0;
        for (int i = 0; i < N - 1; i++)
        {
            if (sortedByAA[i] != i)
            {
                cnt++;
                sortedByAA[sortedByAA[i]] = sortedByAA[i];
                sortedByAA[i] = i;
            }
            else
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        Console.WriteLine("No");
    }


    public static void Main(string[] args) => new Program().Solve();
}

