using static System.Math;
using pair = Pair<int, int>;

class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    readonly Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int N = cin.nextint;
        var A = cin.scanint;
        var B = cin.scanint;
        var C = new int[N];
        var D = new int[N];

        Array.Copy(A, C, N);
        Array.Copy(B, D, N);

        Array.Sort(C);
        Array.Sort(D);
        for (int i = 0; i < N; i++)
        {
            if (C[i] > D[i])
            {
                WriteLine("No");
                return;
            }
        }

        Array.Sort(B, A);
        int NUM = 0;
        for (int i = 0; i < N; i++)
        {
            if (A[i] > B[i])
            {
                NUM++;
            }
        }
        if (N == 2)
        {
            if (NUM >= 1)
            {
                WriteLine("No");
            }
            else
            {
                WriteLine("Yes");
            }
        }
        else if (NUM <= N - 1)
        {
            WriteLine("Yes");
        }
        else
        {
            WriteLine("No");
        }

        return;

        var Q = new PriorityQueue<pair>();
        var S = new Set<pair>();
        for (int i = 0; i < N; i++)
        {
            Q.Enqueue(new pair(A[i], i));
        }

        int cnt = 0;
        int start = N;
        while (Q.Any)
        {
            var d = Q.Dequeue();
            int n = d.f;
            int u = d.s;

            if (n <= B[u])
            {
                continue;
            }
            var b = B.lower_bound(n);

            for (int i = start - 1; i >= b; i--)
            {
                S.Add(new pair(A[i], i));
            }
            var k = S.LowerBound(new pair(B[u] + 1, -1)) - 1;
            if (k < 0)
            {
                WriteLine("No");
                return;
            }
            var t = S[k];

            cnt++;
            Q.Enqueue(new pair(t.f, u));
