                    lower_bound.Add(c_B[i][0], int.MaxValue);
                upper_bound[c_B[i][0]] = Math.Max(upper_bound[c_B[i][0]], c_A[i][0]);
                lower_bound[c_B[i][0]] = Math.Min(lower_bound[c_B[i][0]], c_A[i][0]);
            }

            for(int i = 0; i < n; ++i)
                if(A[i] <= upper_bound[B[i]] && lower_bound[B[i]] <= A[i])
                {
                    System.Console.WriteLine("Yes");
                    return;
                }

            int[] pos = new int[n];
            for(int i = 0; i < n; ++i)
                pos[c_A[i][1]] = c_B[i][1];

            int cycles = 0;
            HashSet<int> mrk = new HashSet<int>();
            for(int i = 0; i < n; ++i)
            {
                if(mrk.Contains(i))
                    continue;
                ++cycles;   
                int x = pos[i];
                while(x != i)
                {
                    mrk.Add(x);
                    x = pos[x];
                }
            }
            if(cycles > 1)
                System.Console.WriteLine("Yes");
            else
                System.Console.WriteLine("No");
        }
    }
}

