public class BinaryIndexedTree<T>
{
	private int N;
	private T INI;
	private Func<T, T, T> Func;
	private T[] bit;

	public BinaryIndexedTree(int n, T ini, Func<T, T, T> func)
	{
		N = n;
		INI = ini;
		Func = func;

		bit = new T[N + 1];  // 1-index
		for(int i = 0; i <= N; i++)
			bit[i] = INI;
	}

	public void Update(int i, T x)
	{
		while(i <= N)
		{
			bit[i] = Func(bit[i], x);
			i += i & -i;
		}
	}

	public T Query(int i)
	{
		T s = INI;
		while(i > 0)
		{
			s = Func(s, bit[i]);
			i -= i & -i;
		}
		return s;
	}
}


