using System;
using System.Linq;
using System.Collections.Generic;

namespace TaskC
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = Convert.ToInt32(Console.ReadLine());
            int[] A = System.Console.ReadLine().Split().Select(x => Convert.ToInt32(x)).ToArray();
            int[] B = System.Console.ReadLine().Split().Select(x => Convert.ToInt32(x)).ToArray();
            IDictionary<int, int> upper_bound = new Dictionary<int, int>();
            IDictionary<int, int> lower_bound = new Dictionary<int, int>();

            int[] c_A = A.ToArray();
            int[] c_B = B.ToArray();

            Array.Sort(c_A);
            Array.Sort(c_B);

            for(int i = 0; i < n; ++i)
            {
                if(c_A[i] > c_B[i])
                {
                    System.Console.WriteLine("No");
                    return;
                }
                if(!upper_bound.ContainsKey(c_B[i]))
                    upper_bound.Add(c_B[i], 0);
                if(!lower_bound.ContainsKey(c_B[i]))
                    lower_bound.Add(c_B[i], int.MaxValue);
                upper_bound[c_B[i]] = Math.Max(upper_bound[c_B[i]], c_A[i]);
                lower_bound[c_B[i]] = Math.Min(lower_bound[c_B[i]], c_A[i]);
            }

            for(int i = 0; i < n; ++i)
                if(A[i] <= B[i] && A[i] <= upper_bound[B[i]] && lower_bound[B[i]] <= A[i])
                {
                    System.Console.WriteLine("Yes");
                    return;
                }
            System.Console.WriteLine("No");
        }
    }
}

using System;
using System.Linq;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        /*
         * A,Bをソート
         * A[i] > B[i]のやつがあれば No
         * 置換ループが2つ以上ならYes
         * 閉じたループN未満 探す
         */

        var tmpA = A.ToArray();
        var tmpB = B.ToArray();
        Array.Sort(tmpA);
        Array.Sort(tmpB);
        for (int i = 0; i < N; i++)
        {
            if (tmpA[i] > tmpB[i])
            {
                Console.WriteLine("No");
                return;
            }
        }

        Tuple<int, int>[] tmp = new Tuple<int, int>[N];
        for (int i = 0; i < N; i++)
        {
            tmp[i] = new Tuple<int, int>(A[i], B[i]);
        }

        Array.Sort(tmp, (a, b) => a.Item2.CompareTo(b.Item2));

        for (int i = 0; i < N; i++)
        {
            A[i] = tmp[i].Item1;
            B[i] = tmp[i].Item2;
        }

        Tuple<int, int>[] pair = new Tuple<int, int>[N];

        for (int i = 0; i < N; i++)
        {
            pair[i] = new Tuple<int, int>(A[i], i);
        }

        Array.Sort(pair, (a, b) => a.Item1.CompareTo(b.Item1));

        int index = pair[0].Item2;
        int cnt = 1;
        while (index != 0)
        {
            cnt++;
            index = pair[index].Item2;
        }

        Console.WriteLine(cnt < N ? "Yes" : "No");
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

