public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        Array.Sort(A);
        Array.Sort(B);
        for (int i = 0; i < N; i++)
        {
            int min = -1;
            int max = N;
            while (max - min > 1)
            {
                int med = (min + max) / 2;
                if (A[med] <= B[i])
                {
                    min = med;
                }
                else
                {
                    max = med;
                }
            }

            if (min < i)
            {
                Console.WriteLine("No");
                return;
            }
        }

        Console.WriteLine("Yes");
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

