class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var a = sc.IntArr;
        var b = sc.IntArr;
        Array.Sort(b, a);
        var sorted = new int[n];
        var idx = new int[n];
        for (int i = 0; i < n; i++)
        {
            sorted[i] = a[i];
            idx[i] = i;
        }
        Array.Sort(sorted, idx);
        for (int i = 0; i < n; i++)
        {
            if (sorted[i] > b[i]) {
                Prt("No");
                return;
            }
        }
        int p = 0;
        int c = 0;
        while (true) {
            ++c;
            p = idx[p];
            if (p == 0) break;
        }
        if (c != n) {
            Prt("Yes");
            return;
        }
        for (int i = 0; i + 1 < n; i++)
        {
            if (sorted[i + 1] <= b[i]) {
                Prt("Yes");
                return;
            }
        }
        Prt("No");

    }
}

