using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace AtCoder
{
    class Program
    {
        static void Swap(int[] array, int i, int j)
        {
            var temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var As = Console.ReadLine().Split().Select(int.Parse).ToArray();
            var Bs = Console.ReadLine().Split().Select(int.Parse).ToArray();

            var isEnable = true;
            var swapCount = 0;
            for (int i = 0; i < N; i++)
            {
                var a = As[i];
                var b = Bs[i];

                if (a == b)
                    continue;

                if (i == N - 1)
                {
                    if (a > b)
                        isEnable = false;

                    break;
                }

                int temp = 0;
                int tempIndex = 0;
                for (int j = i + 1; j < N; j++)
                {
                    var tempA = As[j];
                    if (tempA == b)
                    {
                        Swap(As, i, j);
                        swapCount++;
                        break;
                    }

                    if (tempA > b)
                        continue;

                    if (tempA < b && temp < tempA)
                    {
                        temp = tempA;
                        tempIndex = j;
                    }

                    if (j == N - 1)
                    {
                        Swap(As, i, tempIndex);
                        swapCount++;
                        break;
                    }
                }
            }

            if (isEnable)
            {
                Console.WriteLine("Yes");
            }
            else
            {
                Console.WriteLine("No");
            }
        }
    }
}

