using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var B = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

        var orderedA = A.OrderBy(x => x).ToArray();
        var orderedB = B.OrderBy(x => x).ToArray();

        for (int i = 0; i < N; i++)
        {
            var skipA = A[i];
            var skipB = B[i];
            if (skipA > skipB)
            {
                continue;
            }

            var ok = true;
            for (int aa = 0, bb = 0; aa < N && bb < N; aa++, bb++)
            {
                if (orderedA[aa] == skipA)
                {
                    aa++;
                    skipA = -1;
                }
                if (orderedB[bb] == skipB)
                {
                    bb++;
                    skipB = -1;
                }

                if (!(aa < N && bb < N))
                {
                    break;
                }

                if (orderedA[aa] > orderedB[bb])
                {
                    ok = false;
                    break;
                }
            }

            if (ok)
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        Console.WriteLine("No");
    }
}

