    /// <summary>
    /// https://atcoder.jp/contests/nikkei2019-2-qual/tasks/nikkei2019_2_qual_c
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var n = inputStream.ReadInt();
            var a = inputStream.ReadIntArray();
            var b = inputStream.ReadIntArray();

            var left = 0;
            var right = a.Length - 1;
            var count = 0;

            while (right - left > 1 && count < n - 2)
            {
                if (b[left] < b[right])
                {
                    var found = -1;
                    for (int i = left; i < right; i++)
                    {
                        if (a[i] <= b[left])
                        {
                            found = i;
                            break;
                        }
                    }

                    if (found >= 0)
                    {
                        for (int i = found; i > left; i--)
                        {
                            (a[i - 1], a[i]) = (a[i], a[i - 1]);
                        }

                        count += found - left;
                        left++;
                    }
                    else
                    {
                        break;
                    }
                }
                else
                {
                    var found = a.Length;
                    for (int i = right; i > left; i--)
                    {
                        if (a[i] <= b[right])
                        {
                            found = i;
                            break;
                        }
                    }

                    if (found < a.Length)
                    {
                        for (int i = found; i < right; i++)
                        {
                            (a[i], a[i + 1]) = (a[i + 1], a[i]);
                        }

                        count += right - found;
                        right--;
                    }
                }
            }

            if (a[left] > b[left] || a[right] > b[right])
            {
                (a[left], a[right]) = (a[right], a[left]);
                count++;
            }

            var ok = true;
            for (int i = 0; i < a.Length; i++)
            {
                ok &= a[i] <= b[i];
            }

            if (ok && count <= n - 2)
            {
                yield return "Yes";
            }
            else
            {
                yield return "No";
            }
        }
    }
}

