internal partial class Solver {
    public void Run() {
        var n = ni();
        var a = ni(n);
        var b = ni(n);
        cout.WriteLine(Solve(n, a, b) ? "Yes" : "No");
    }

    private static bool Solve(int n, int[] a, int[] b) {
        var p = E.Range(0, n).OrderBy(i => b[i]).ToArray();
        a = E.Range(0, n).Select(i => a[p[i]]).ToArray();
        b = E.Range(0, n).Select(i => b[p[i]]).ToArray();
        var perm = a.Select((Value, Index) => new { Value, Index }).OrderBy(g => g.Value).ToArray();
        var visited = new bool[n];
        int cycleNum = 0;
        for (int i = 0; i < n; i++) {
            if (perm[i].Value > b[i]) return false;
            if (visited[i]) continue;
            int current = i;
            cycleNum++;
            while (!visited[current]) {
                visited[current] = true;
                current = perm[current].Index;
            }
        }
        if (cycleNum > 1) return true;
        for (int i = 0; i + 1 < n; i++) {
            if (perm[i + 1].Value <= b[i]) {
                return true;
            }
        }
        return false;
    }
}

