type Perm struct {
	idx int
	num int
}

type Perms []Perm

func (p Perms) Len() int {
	return len(p)
}

func (p Perms) Less(i, j int) bool {
	return p[i].num < p[j].num
}

func (p Perms) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func swaps(n int, a, b []int) bool {
	ap := make([]Perm, n)
	for i, v := range a {
		ap[i] = Perm{idx: i, num: v}
	}
	sort.Sort(Perms(ap))

	bp := make([]Perm, n)
	for i, v := range b {
		bp[i] = Perm{idx: i, num: v}
	}
	sort.Sort(Perms(bp))

	for i := 0; i < n; i++ {
		if ap[i].num > bp[i].num {
			return false
		}

	}

	for i := 0; i < n-1; i++ {
		if ap[i+1].num <= bp[i].num {
			return true
		}
	}

	p := make([]int, n)
	for i := 0; i < n; i++ {
		p[ap[i].idx] = bp[i].idx
	}

	count := 0
	x := 0
	for x != 0 {
		count++
		x = p[x]
	}

	if count != n {
		return true
	}
	return false
}

