		ss := strings.Split(sc.Text(), " ")
		for i := range ss {
			b[i], _ = strconv.Atoi(ss[i])
		}
	}

	if swaps(n, a, b) {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

