type Items [][]int
func (I Items) Len() int { return len(I) }
func (I Items) Less(i, j int) bool {
  if I[i][0] == I[j][0] { return I[i][1] < I[j][1] }
  return I[i][0] < I[j][0]
}
func (I Items) Swap(i, j int) { I[i], I[j] = I[j], I[i] }

func Solve() {
  N := NextInt()
  A := NextIntVec()
  B := NextIntVec()
  SA := make([][]int, N)
  for i, a := range A {
    SA[i] = []int{a, i}
  }
  sort.Sort(Items(SA))
  SB := make([][]int, N)
  for i, b := range B {
    SB[i] = []int{b, i}
  }
  sort.Sort(Items(SB))
  for i := 0; i < N; i++ {
    if SA[i][0] <= SB[i][0] { continue }
    Write("No")
    return
  }
  for i := 1; i < N; i++ {
    if SB[i - 1][0] < SA[i][0] { continue }
    Write("Yes")
    return
  }
  M := make([]int, N)
  for i, sa := range SA {
    M[sa[1]] = i
  }
  cnt := 1
  s, t := SA[0][1], SB[0][1]
  for s != t {
    cnt++
    t = SB[M[t]][1]
  }
  if cnt < N {
    Write("Yes")
    return
  }
  Write("No")
  return
}

