type Perm struct {
	idx int
	num int
}

func swaps(n int, a, b []int) bool {
	// a をsortすると順序が変わってしまうので最初に処理する
	// 時間計算量が増える。。。
	perms := make([]Perm, n)
	for i, v := range a {
		perms[i] = Perm{idx: i, num: v}
	}

	sort.Slice(perms, func(i, j int) bool {
		return perms[i].num < perms[j].num
	})

	// Sort the slice of B in ascending order.
	sort.Ints(b)

	// まず巡回置換 (p1, ..., pN ) を Ap1 ≦ Ap2 ≦ ... ≦ ApN となるようにとる
	ap := a
	sort.Ints(ap)

	// このとき Api ≦ Bi(i = 1, ..., N ) が成り立たなければ、1 つめの条件をみたす (p1 , ..., pN ) が存在しないので、false
	for i := 0; i < n; i++ {
		if ap[i] > b[i] {
			return false
		}

	}

	// Api ≦ Bi(i = 1,...,N) となる場合
	// 巡回置換(p1,...,pN)をサイクルに分解したときに、2つ以上のサイクルに分解されるならば、true
	// N-1回あればできるやつ
	// 目標位置をswapできる場所があれば、達成可能
	count := 0
	apn := ap[1:]
	bn := b[:len(b)-1]
	for i := 0; i < n-1; i++ {
		if apn[i] <= bn[i] {
			count++
		}
	}
	if count == n-1 {
		return true
	}

	// この時点で、Aは相異なり、目標インデックスも1つに決まる
	p := make([]int, 0, n)
	for _, perm := range perms {
		p = append(p, perm.idx)
	}
	count = 0
	x := 0
	for x != 0 {
		count++
		x = p[x]
	}

	if count != n {
		return true
	}
	return false
}

