// target must be minus target
// 返り値は入れ替えられたかどうか
func searchAndSwitch(scores []score, target int) bool {
        t := scores[target]
        minB := t.a
        myB := t.b
        for i := range scores {
                // プラスになる B を見つける
                if scores[i].b >= minB {
                        // 自分の B と入れ替えてもマイナスにならないなら入れ替え
                        if myB-scores[i].a >= 0 {
                                scores[target].b = scores[i].b
                                scores[i].b = myB

                                scores[target].s = scores[target].b - scores[target].a
                                scores[i].s = scores[i].b - scores[i].a

                                return true
                        }
                }
        }

        return false
}

