var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

type Items [][]int
func (I Items) Len() int { return len(I) }
func (I Items) Less(i, j int) bool { return I[i][0] < I[j][0] }
func (I Items) Swap(i, j int) { I[i], I[j] = I[j], I[i] }

func Solve() {
  N := NextInt()
  A := NextIntVec()
  B := NextIntVec()
  SA := make([][]int, N)
  for i, a := range A {
    SA[i] = []int{a, i}
  }
  sort.Sort(Items(SA))
  SB := make([][]int, N)
  for i, b := range B {
    SB[i] = []int{b, i}
  }
  sort.Sort(Items(SB))
  for i := 0; i < N; i++ {
    if SB[i][0] < SA[i][0] {
      Write("No")
      return
    }
  }
  M := make([]int, N)
  for i, sa := range SA {
    M[sa[1]] = i
  }
  cnt := 0
  pos := SA[N - 1][1]
  p := pos
  for B[pos] < A[p] {
    cnt++
    p = SB[M[p]][1]
  }
  ans := "No"
  if cnt < N - 1 { ans = "Yes" }
  Write(ans)
  return
}

func main() {
  Solve()
  Output()
}

