var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

type Item struct {
  Index int
  Value int
}
type Items []Item
func (A Items) Len() int { return len(A) }
func (A Items) Less(i, j int) bool { return A[i].Value < A[j].Value }
func (A Items) Swap(i, j int) { A[i], A[j] = A[j], A[i] }

type Rep []int
func (R Rep) Find(v int) int {
  if v == R[v] { return v }
  R[v] = R.Find(R[v])
  return R[v]
}
func (R Rep) Union(u, v int) {
  ru := R.Find(u)
  rv := R.Find(v)
  if ru < rv {
    R[rv] = ru
  } else {
    R[ru] = rv
  }
}

func main() {
  N := NextInt()
  A := NextIntVec()
  B := NextIntVec()
  SA := make([]Item, N)
  SB := make([]Item, N)
  for i, a := range A {
    SA[i] = Item{i, a}
    SB[i] = Item{i, B[i]}
  }
  sort.Sort(Items(SA))
  sort.Sort(Items(SB))
  ans := "Yes"
  for i, a := range SA {
    if SB[i].Value < a.Value { ans = "No" }
  }
  R := make([]int, N)
  for i := range R {
    R[i] = i
  }
  for i := range R {
    Rep(R).Union(SA[i].Index, SB[i].Index)
  }
  p := 0
  for i := range R {
    Rep(R).Find(i)
    if i == R[i] { p++ }
  }
  if p < 1 { ans = "No" }
  Write(ans)
  Output()
}

