func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
		if len(os.Args) > 2 {
			wfp, _ = os.Create(os.Args[2])
		}
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)

	oa := make([]int, n)
	ob := make([]int, n)
	aa := make(Ranks, n)
	bb := make(Ranks, n)
	for i := 0; i < n; i++ {
		oa[i] = getNextInt(scanner)
		aa[i].v = oa[i]
		aa[i].i = i
	}
	for i := 0; i < n; i++ {
		ob[i] = getNextInt(scanner)
		bb[i].v = ob[i]
		bb[i].i = i
	}

	sort.Sort(aa)
	sort.Sort(bb)

	ba := make([]int, n)
	for i := 0; i < n; i++ {
		ba[bb[i].i] = i
	}

	ans := "No"
	for i := 0; i < n; i++ {
		if aa[i].v > bb[i].v {
			fmt.Println(ans)
			return
		}
	}
	for i := 0; i < n; i++ {
		if ob[aa[i].i] >= aa[i].v && aa[ba[aa[i].i]].v <= bb[i].v {
			ans = "Yes"
			break
		}
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

