func main() {
	N := oneInt()
	var as []int
	var bs []int

	for index := 0; index < N; index++ {
		as = append(as, oneInt())
	}

	for index := 0; index < N; index++ {
		bs = append(bs, oneInt())
	}

	as = sortAsc(as)
	bs = sortAsc(bs)

	for index := 0; index < N; index++ {
		if bs[index] < as[index] {
			fmt.Print("No")
			return
		}
	}

	life := N - 2
	for index := 0; index < N; index++ {
		if bs[index] < as[index] {
			temp := searchAbove(bs, as[index], index)
			if temp >= 0 {
				bs[index], bs[temp] = bs[temp], bs[index]
				life--
				if life < 0 {
					fmt.Print("No")
					return
				}
			} else {
				fmt.Print("No")
				return
			}
		}
	}
	fmt.Print("Yes")

}

func searchAbove(slice []int, target int, index int) int {
	for i := index + 1; i < len(slice); i++ {
		v := slice[i]
		if v >= target {
			return i
		}
	}
	return -1
}

