type Item struct {
  Index int
  Value int
}
type Items []Item
func (A Items) Len() int { return len(A) }
func (A Items) Less(i, j int) bool { return A[i].Value < A[j].Value }
func (A Items) Swap(i, j int) { A[i], A[j] = A[j], A[i] }

type Rep []int
func (R Rep) Find(v int) int {
  if v == R[v] { return v }
  R[v] = R.Find(R[v])
  return R[v]
}
func (R Rep) Union(u, v int) {
  ru := R.Find(u)
  rv := R.Find(v)
  if ru < rv {
    R[rv] = ru
  } else {
    R[ru] = rv
  }
}

func Solve(SA, SB *[]Item) string {
  N := len((*SA))
  ans := "Yes"
  for i, a := range (*SA) {
    if (*SB)[i].Value < a.Value { return "No" }
  }
  R := make([]int, N)
  for i := range R {
    R[i] = i
  }
  for i := range R {
    Rep(R).Union((*SA)[i].Index, (*SB)[i].Index)
  }
  p := 0
  for i := range R {
    Rep(R).Find(i)
    if i == R[i] { p++ }
  }
  if p < 2 {
    ans = "No"
    for i := 1; i < N; i++ {
      if (*SA)[i].Value == (*SA)[i - 1].Value { ans = "Yes" }
    }
  }
  return ans
}

