  SA := make([]Item, N)
  SB := make([]Item, N)
  for i, a := range A {
    SA[i] = Item{i, a}
    SB[i] = Item{i, B[i]}
  }
  sort.Sort(Items(SA))
  sort.Sort(Items(SB))
  Write(Solve(&SA, &SB))
  Output()
}

