// target must be minus target
// 返り値は入れ替えられたかどうか
func searchAndSwitch(scores []score, target int) bool {
        t := scores[target]
        minB := t.a
        myB := t.b
        for i := range scores {
                // プラスになる B を見つける
                if scores[i].b >= minB {
                        // 自分の B と入れ替えてもマイナスにならないなら入れ替え
                        if myB-scores[i].a >= 0 {
                                scores[target].b = scores[i].b
                                scores[i].b = myB

                                scores[target].s = scores[target].b - scores[target].a
                                scores[i].s = scores[i].b - scores[i].a

                                return true
                        }
                }
        }

        return false
}

func searchAndSwitch2(scores []score, target int) bool {
        t := scores[target]
        minB := t.a
        myB := t.b

        idxList := make([]int, 0)
        var mitsuketa bool
        for i := range scores {
                // プラスになる B を見つける
                if scores[i].b >= minB {
                        // マイナスにならないかどうかチェックする必要ある？
                        idxList = append(idxList, i)
                        mitsuketa = true
                }
        }

        if !mitsuketa {
                return false
        }

        // a に一番近い値を探す
        min := 2000000000
        var idx int
        for _, i := range idxList {
                if min > scores[i].b {
                        min = scores[i].b
                        idx = i
                }
        }

        scores[target].b = scores[idx].b
        scores[idx].b = myB

        scores[target].s = scores[target].b - scores[target].a
        scores[idx].s = scores[idx].b - scores[idx].a

        return true
}

