func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(false)
	n := r.nextInt()
	r.Scan(true)
	a := r.nextStringArray().toInts()
	r.Scan(true)
	b := r.nextStringArray().toInts()

	targetB := make([]pair, len(a))
	ansA := make([]*pair, len(a))
	for i := range a {
		p := &targetB[i]
		p.a = a[i]
		p.b = b[i]
		ansA[i] = p
	}
	sort.Sort(bup(targetB))
	sort.Sort(aup(ansA))

	condAltB := true
	condAdpl := false
	for i := range targetB {
		if ansA[i].a > targetB[i].b {
			condAltB = false
			break
		}

		if i < n-1 && ansA[i+1].a <= targetB[i].b {
			condAdpl = true
		}

	}

	ans := condAltB
	if ans {
		ans = condAdpl
		if !ans {
			for i := range ansA {
				ansA[i].i = i
			}
			cur := targetB[0].i
			cnt := 0
			for cur != 0 {
				cnt++
				cur = targetB[cur].i
			}
			if cnt <= n-2 {
				ans = true
			}
		}
	}
	fmt.Fprintln(stdout, []string{"No", "Yes"}[b2i(ans)])
}

