func (dj *djset) init(s int) {
	dj.p = make([]int, s)
	for i := 0; i < s; i++ {
		dj.p[i] = -1
	}
}
func (dj *djset) unite(x, y int) bool {
	// if x == y {
	// 	return false
	// }
	xr, yr := dj.find(x), dj.find(y)
	if xr == yr {
		return false
	}
	if dj.p[yr] < dj.p[xr] {
		x, y, xr, yr = y, x, yr, xr
	}
	dj.p[xr] += dj.p[yr]
	dj.p[yr] = x
	return true
}
func (dj *djset) find(x int) int {
	if dj.p[x] < 0 {
		return x
	}
	dj.p[x] = dj.find(dj.p[x])
