	for i := 0; i < n; i++ {
		ab[i] = pair{fi: bs[i], se: as[i]}
	}
	sort.Sort(byFiSe(ab))
	for i := 0; i < n; i++ {
		as[i] = ab[i].se
		bs[i] = ab[i].fi
	}
	aZaatsu := make([]pair, n)
	for i := 0; i < n; i++ {
		aZaatsu[i] = pair{fi: as[i], se: i}
	}
	aZaatsuSorted := make([]pair, n)
	copy(aZaatsuSorted, aZaatsu)
	sort.Sort(byFiSe(aZaatsuSorted))
	dj := newDj(n + 1)
	for i := 0; i < n; i++ {
		dj.unite(aZaatsuSorted[i].se, aZaatsu[i].se)
	}
	m := make(map[int]bool, n)
	for i := 0; i < n; i++ {
		m[dj.find(aZaatsu[i].se)] = true
	}
	if len(m) != 1 {
		pln("Yes")
		return
	}
	for i := 0; i < n-1; i++ {
		if bsSorted[i] >= asSorted[i+1] {
			pln("Yes")
			return
		}
	}
	pln("No")
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Perm struct {
	idx int
	num int
}

type Perms []Perm

func (p Perms) Len() int {
	return len(p)
}

func (p Perms) Less(i, j int) bool {
	return p[i].num < p[j].num
}

func (p Perms) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func swaps(n int, a, b []int) bool {
	// Sort the slice of B in ascending order.
	sort.Ints(b)

	// まず巡回置換 (p1, ..., pN ) を Ap1 ≦ Ap2 ≦ ... ≦ ApN となるようにとる
	ap := make([]int, 0, n)
	for _, v := range a {
		ap = append(ap, v)
	}
	sort.Ints(ap)

	// このとき Api ≦ Bi(i = 1, ..., N ) が成り立たなければ、1 つめの条件をみたす (p1 , ..., pN ) が存在しないので、false
	for i := 0; i < n; i++ {
		if ap[i] > b[i] {
			return false
		}

	}

	// Api ≦ Bi(i = 1,...,N) となる場合
	// 巡回置換(p1,...,pN)をサイクルに分解したときに、2つ以上のサイクルに分解されるならば、true
	// N-1回あればできるやつ
	// 目標位置をswapできる場所があれば、達成可能
	for i := 0; i < n-1; i++ {
		if ap[i+1] <= b[i] {
			return true
		}
	}

	// この時点で、Aは相異なり、目標インデックスも1つに決まる
	// a をsortすると順序が変わってしまうので最初に処理する
	// 時間計算量が増える。。。
	perms := make([]Perm, n)
	for i, v := range a {
		perms[i] = Perm{idx: i, num: v}
	}

	sort.Sort(Perms(perms))

	p := make([]int, 0, n)
	for _, perm := range perms {
		p = append(p, perm.idx)
	}
	count := 0
	x := 0
	for x != 0 {
		count++
		x = p[x]
	}

	if count == n {
		return false
	}
	return true
}

func main() {
	sc := bufio.NewScanner(os.Stdin)

	var n int
	if sc.Scan() {
		n, _ = strconv.Atoi(sc.Text())
	}

	a := make([]int, n)
	if sc.Scan() {
		ss := strings.Split(sc.Text(), " ")
		for i := range ss {
			a[i], _ = strconv.Atoi(ss[i])
		}
	}

	b := make([]int, n)
	if sc.Scan() {
		ss := strings.Split(sc.Text(), " ")
		for i := range ss {
			b[i], _ = strconv.Atoi(ss[i])
		}
	}

	if swaps(n, a, b) {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

