type pair struct{ fi, se int }
type byFiSe []pair

func (p byFiSe) Len() int      { return len(p) }
func (p byFiSe) Swap(i, j int) { p[i], p[j] = p[j], p[i] }
func (p byFiSe) Less(i, j int) bool {
	if p[i].fi == p[j].fi {
		return p[i].se < p[j].se
	}
	return p[i].fi < p[j].fi
}

type point struct{ x, y int }

type djset struct{ p []int }

func newDj(s int) *djset {
	dj := &djset{}
	dj.init(s)
	return dj
}
func (dj *djset) init(s int) {
	dj.p = make([]int, s)
	for i := 0; i < s; i++ {
		dj.p[i] = -1
	}
}
func (dj *djset) unite(x, y int) bool {
	// if x == y {
	// 	return false
	// }
	xr, yr := dj.find(x), dj.find(y)
	if xr == yr {
		return false
	}
	if dj.p[yr] < dj.p[xr] {
		x, y, xr, yr = y, x, yr, xr
	}
	dj.p[xr] += dj.p[yr]
	dj.p[yr] = x
	return true
}
func (dj *djset) find(x int) int {
	if dj.p[x] < 0 {
		return x
	}
	dj.p[x] = dj.find(dj.p[x])
	return dj.p[x]
}
func (dj *djset) isSame(x, y int) bool { return dj.find(x) == dj.find(y) }
func (dj *djset) size(x int) int       { return -dj.p[dj.find(x)] }

func solve() {
	n := ri()
	as := ris(n)
	bs := ris(n)
	asSorted := intsCopySortAsc(as)
	bsSorted := intsCopySortAsc(bs)
	for i := 0; i < n; i++ {
		if asSorted[i] > bsSorted[i] {
			pln("No")
			return
		}
	}
	aZaatsu := make([]pair, n)
	for i := 0; i < n; i++ {
		aZaatsu[i] = pair{fi: as[i], se: i}
	}
	aZaatsuSorted := make([]pair, n)
	copy(aZaatsuSorted, aZaatsu)
	sort.Sort(byFiSe(aZaatsuSorted))
	dj := newDj(n + 1)
	for i := 0; i < n; i++ {
		dj.unite(aZaatsuSorted[i].se, aZaatsu[i].se)
	}
	m := make(map[int]bool, n)
	for i := 0; i < n; i++ {
		m[dj.find(aZaatsu[i].se)] = true
	}
	if len(m) != 1 {
		pln("Yes")
		return
	}
	for i := 0; i < n-1; i++ {
		if bsSorted[i] >= asSorted[i+1] {
			pln("Yes")
			return
		}
	}
	pln("No")
}

package main

import (
	"bufio"
