const (
	initialBufSize = 10000
	maxBufSize     = 1000000
)

var (
	sc *bufio.Scanner = func() *bufio.Scanner {
		sc := bufio.NewScanner(os.Stdin)
		buf := make([]byte, initialBufSize)
		sc.Buffer(buf, maxBufSize)
		sc.Split(bufio.ScanWords)
		return sc
	}()
	mod int = 1e9 + 7
)

func main() {
	N := getInt()
	var As []int
	var Bs []int
	var Gaps []int

	for i := 0; i < N; i++ {
		As = append(As, getInt())
	}

	for i := 0; i < N; i++ {
		Bs = append(Bs, getInt())
		Gaps = append(Gaps, As[i] - Bs[i])
	}

	// 確実に不可能な場合をチェック
	maxA := max(As...)
	maxB := max(Bs...)
	if maxA > maxB {
		fmt.Println("No")
		return
	}

	// ソートしてみて確実に不可能な場合をチェック
	As2 := make([]int, N)
	Bs2 := make([]int, N)
	copy(As2, As)
	copy(Bs2, Bs)
	sort.Ints(As2)
	sort.Ints(Bs2)
	for i := 0; i < N; i++ {
		if As2[i] > Bs2[i] {
			fmt.Println("No")
			return
		}
	}

	overCnt := 0
	for _, gap := range Gaps {
		if gap > 0 {
			overCnt++
		}
	}

	if overCnt <= N-2 {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

