func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int, n)
	bb := make([]int, n)
	sa := make([]int, n)
	sb := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		sa[i] = aa[i]
	}
	for i := 0; i < n; i++ {
		bb[i] = getNextInt(scanner)
		sb[i] = bb[i]
	}
	sort.Ints(sa)
	sort.Ints(sb)
	for i := 0; i < n; i++ {
		if sa[i] > sb[i] {
			fmt.Fprintln(writer, "No")
			return
		}
	}

	for i := 0; i < n; i++ {
		if aa[i] > bb[i] {
			continue
		}
		indexa := make([]int, 2)
		indexb := make([]int, 2)
		indexa[0] = search(aa[i], sa)
		indexa[1] = search(aa[i]+1, sa) - 1
		indexb[0] = search(bb[i], sb)
		indexb[1] = search(bb[i]+1, sb) - 1
		for j := 0; j < 2; j++ {
			for k := 0; k < 2; k++ {
				if sa[indexb[k]] <= sb[indexa[j]] {
					fmt.Fprintln(writer, "Yes")
					return
				}
			}
		}
	}
	fmt.Fprintln(writer, "No")
}

func search(x int, xx []int) int {
	n := len(xx)
	l := -1
	r := n
	for l+1 < r {
		m := (l + r) >> 1
		if xx[m] < x {
			l = m
			continue
		}
		r = m
	}
	return r
}

