func (A Items) Swap(i, j int) { A[i], A[j] = A[j], A[i] }

type Rep []int
func (R Rep) Find(v int) int {
  if v == R[v] { return v }
  R[v] = R.Find(R[v])
  return R[v]
}
func (R Rep) Union(u, v int) {
  ru := R.Find(u)
  rv := R.Find(v)
  if ru < rv {
    R[rv] = ru
  } else {
    R[ru] = rv
  }
}

