    auto arrb = readln.chomp.split.map!(to!int).array;

    int[int] mx;
    foreach (i; 0 .. n) {
        mx.require(arrb[i], 0);

        if (arra[i] > arrb[i]) { continue; }

        mx[arrb[i]] = max(mx[arrb[i]], arra[i]);
    }

    debug { mx.writeln; }

    arra.sort();
    arrb.sort();

    foreach (i; 0 .. n) {
        if (arra[i] > arrb[i]) {
            writeln("No");
            return;
        }
    }

    int idxa = 0, idxb = 0, prev = 0;
    foreach (k; mx.keys.sort()) {
        debug { writeln(k, ' ', mx[k]); }

        while (idxa < n && arra[idxa] <= k) { ++idxa; }
        while (idxb < n && arrb[idxb] <= k) { ++idxb; }

        if (mx[k] > prev || idxa > idxb) {
            writeln("Yes");
            return;
        }

        prev = k;
    }

    writeln("No");
    return;
}

