            writeln("No");
            return;
        }
    }
    AB[] xas, yas;
    xas.length = N;
    yas.length = N;
    foreach (i; 0..N) {
        xas[i] = AB(i, ab[i].a);
        yas[i] = AB(i, ab[i].a);
    }
    sort!"a.b < b.b"(yas);
    auto uft = uftree(N);
    foreach (i; 0..N) {
        uft.unite(xas[i].a, yas[i].a);
