proc can: bool =
  var N = input(int)
  var A = @[0] & input(seq[int])
  var B = @[0] & input(seq[int])
  var AB = newseq[tuple[a: int, b: int]](N + 1)
  AB[0] = (0, 0)
  for i in 1 .. N:
    AB[i] = (A[i], B[i])
  AB = AB.sortedByIt(it.b)
  var P = newseq[tuple[idx: int, elm: int]]()
  for i, p in AB:
    var a = p.a
    P.add((i, a))
  P = P.sortedByIt(it.elm)
  A.sort(cmp)
  B.sort(cmp)
  for i in 1 .. N:
    if A[i] > B[i]:
      return false
  for i in 1 .. N - 1:
    if A[i + 1] <= B[i]:
      return true
  var cnt = 0
  var nidx = 1
  while true:
    nidx = P[nidx].idx
    inc cnt
    if nidx == 1:
      if cnt == N:
        return false
      else:
        return true

if can():
  echo "Yes"
else:
  echo "No"

