def main():
    import heapq
    n = int(input())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    ab = sorted([[a[i], b[i]] for i in range(n)],key=lambda x:(x[1],x[0]))

    m=131071+n
    segtree=[10**9+1]*(m+1)

    for i in range(131071,m):
        segtree[i] = ab[i - 131071][0]
    for i in range(131070,-1,-1):
        j=2*i+1
        if j>=m:
            segtree[i]=10**9+1
        elif j+1>=m:
            segtree[i]=segtree[j]
        else:
            segtree[i] = min(segtree[j], segtree[j + 1])
    #探す
    def search(i, s):
        if i >= 131071:
            return i - 131071
        if 2*i+3<=m:
            if segtree[2 * i + 2] <= s:
                return search(2 * i + 2, s)
        if 2*i+2<=m:
            if segtree[2 * i + 1] <= s:
                return search(2 * i + 1, s)
        return -1

    #更新
    def update_good(i, s):
        if segtree[i] > s:
            segtree[i] = s
            update_good((i - 1) // 2, s)

    def update_bad(i, s):
        if i % 2 == 1:
            if segtree[i + 1] > s:
                segtree[(i - 1) // 2] = min(segtree[i+1],segtree[i])
                update_bad((i - 1) // 2, s)
        else:
            if i!=0:
                segtree[(i - 1) // 2] = min(segtree[i-1],segtree[i])
                update_bad((i - 1) // 2, s)

    cnt = 0
    for i in range(n):
        if ab[i][0] > ab[i][1]:
            s = search(0, ab[i][1])
            if s <= i:
                print("No")
                return 0
            update_good(131071 + i, ab[s][0])
            segtree[131071 + s] = ab[i][0]
            update_bad(131071 + s, ab[i][0])
            ab[i][0], ab[s][0] = ab[s][0], ab[i][0]
            cnt+=1
    if cnt <= n - 2:
        print("Yes")
    else:
        print("No")

