    for i in range(num - 1, -1, -1):
        j=2*i+1
        if j>=m:
            segtree[i]=inf
        else:
            segtree[i] = monoid(segtree[j], segtree[min(j + 1, m - 1)])

    #条件を満たす(サンプルの条件はs以下になること)最大のインデックスを返す関数
    @lru_cache(maxsize=None)
    def max_index(s):
        #条件の定義
        func = lambda x: x <= s
        #探していく
        i=0
        while i < num:
            k = 2 * i + 1
            if k + 1 < m:
                if func(segtree[k + 1]):
                    i = k + 1
                    continue
            if k < m:
                if func(segtree[k]):
                    i = k
                    continue
            return - 1
        return i - num

    #半開区間[lower,upper)の最小値（とか）を探す関数
    @lru_cache(maxsize=None)
    def search_new(lower, upper):
        q = [[0, 1]]  #インデックス、階層
        #返り値を初期化
        ret = inf      
        while q:
            i, f = q.pop()
            #popしたインデックスと階層から、求める下限と上限を算出する
            #幅
            width = pow(2, fl - f)
            #下限と中央と上限
            kagen = (i - pow(2, f - 1) + 1) * width
            chuo = kagen + width // 2
            jogen = kagen + width
            k = 2 * i + 1
            if lower <= kagen and jogen <= upper:
                ret = monoid(ret, segtree[i])
                continue
            if k < m:
                if lower <= kagen and chuo <= upper:
                    ret = monoid(ret, segtree[k])
                elif lower <= chuo:
                    q.append([k, f + 1])
            if k + 1 < m:
                if lower <= chuo and jogen <= upper:
                    ret = monoid(ret, segtree[k + 1])
                elif chuo <= upper:
                    q.append([k + 1, f + 1])
        return ret

    #segtree[i]をsに更新したときにセグ木全体を更新する関数
    @lru_cache(maxsize=None)
    def update(i, s):
        segtree[i] = s
