    for i in range(131071,m):
        segtree[i] = ab[i - 131071][0]
    for i in range(131070,-1,-1):
        j=2*i+1
        if j>=m:
            segtree[i]=10**9+1
        elif j+1>=m:
            segtree[i]=segtree[j]
        else:
            segtree[i] = min(segtree[j], segtree[j + 1])

    #探す
    def search(i, s):
        if i >= 131071:
            return i - 131071
        if 2*i+3<=m:
            if segtree[2 * i + 2] <= s:
                return search(2 * i + 2, s)
        if 2*i+2<=m:
            if segtree[2 * i + 1] <= s:
                return search(2 * i + 1, s)
        return -1

    #更新
    def update_good(i, s):
        if segtree[i] > s:
            segtree[i] = s
            update_good((i - 1) // 2, s)

    def update_bad(i):
        if i % 2 == 1:
            if m > i + 1:
                temp=min(segtree[i+1],segtree[i])
                if segtree[(i - 1) // 2]<temp:
                    segtree[(i - 1) // 2] = temp
                    update_bad((i - 1) // 2)
            else:
                segtree[(i - 1) // 2] = segtree[i]
                update_bad((i - 1) // 2)
        else:
            if i != 0:
                temp=min(segtree[i-1],segtree[i])
                if segtree[(i - 1) // 2]<temp:
