def is_possible_build_swap(n, a, b):
    i = 0
    while i < n:
        if a[i] <= b[i]:
            k = -1
            mn = a[i]
            for j in range(i+1, n):
                if mn < a[j] <= b[i]:
                    mn = a[j]
                    k = j
            if k != -1:
                a[i], a[k] = a[k], a[i]
            i += 1
        else:
            mn = 0
            k = -1
            for j in range(i+1, n):
                if mn <= a[j] <= b[i]:
                    mn = a[j]
                    k = j
            if k == -1:
                return False
            else:
                a[i], a[k] = a[k], a[i]
                i += 1
    return True

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    print("Yes" if is_possible_build_swap(n, a, b) else "No")


