    if max_A > max_B:
        return False
    if check(listA, listB):
    	return True   
    skip_index = []
    for i in range(len(listA)-2):
        max_A = 0
        max_B = 0
        for j in range(len(listA)):
            if j in skip_index:
                continue
            if max_A < listA[j]:
                max_index_A = j
                max_A = listA[j]
            if max_B < listB[j]:
                max_index_B = j
                max_B = listB[j]

        # swap
        temp = listA[max_index_B]
        listA[max_index_B] = max_A
        listA[max_index_A] = temp
        skip_index.append(max_index_B)

        if check(listA, listB):
