    #探す
    def search(i, s):
        if i >= 131071:
            return i - 131071
        if 2*i+3<=m:
            if segtree[2 * i + 2] <= s:
                return search(2 * i + 2, s)
        if 2*i+2<=m:
            if segtree[2 * i + 1] <= s:
                return search(2 * i + 1, s)
        return -1

    #更新
    def update_good(i, s):
        if segtree[i] > s:
            segtree[i] = s
            update_good((i - 1) // 2, s)

    def update_bad(i):
        if i % 2 == 1:
            if m>i+1:
                segtree[(i - 1) // 2] = min(segtree[i+1],segtree[i])
                update_bad((i - 1) // 2)
            else:
                segtree[(i - 1) // 2] = segtree[i]
                update_bad((i - 1) // 2)
        else:
