class SegmentTree():

    def __init__(self, size, initial=-1):
        node_size = 1
        while node_size < size:
            node_size <<= 1
        self.st = [initial] * ((node_size << 1) - 1)
        self.size = node_size

    def update(self, target, new_value):
        target += self.size - 1
        self.st[target] = new_value
        while target > 0:
            parent = (target - 1) >> 1
            if self.st[parent] > self.st[target]:
                self.st[parent] = self.st[target]
                target = parent
            else:
                break

    def query(self, a, b):
        # [a,b)の最大値を求める。
        return self._query(a, b, 0, 0, self.size)

    def _query(self, a, b, k, l, r):
        if r <= a or b <= l:
            return (float('inf'), float('inf'))
        if a <= l and r <= b:
            return self.st[k]
        vl = self._query(a, b, (k << 1) + 1, l, (l + r) >> 1)
        vr = self._query(a, b, (k << 1) + 2, (l + r) >> 1, r)
        return min(vl, vr)


def solve(n, a, b):
    if n == 2:
        if a[0] <= b[0] and a[1] <= b[1]:
            return True
        else:
            return False
    cnt = sum([1 if a[i] > b[i] else 0 for i in range(n)])
    if cnt >= n - 1:
        return False

    a_ = sorted(a)
    for i in range(n):
        if a_[i] > b[i]:
            return False

    st = SegmentTree(len(a), (float('inf'), float('inf')))
    for i in range(n):
        st.update(i, (a[i], i))
    cnt = 0
    for i in range(n):
        if a[i] > b[i]:
            v, j = st.query(i, n + 1)
            if v > b[i]:
                return False
            a[j] = a[i]
            st.update(j, (a[i], j))
            a[i] = v
            cnt += 1
    print(cnt)
    return cnt <= n-2


