YES = "Yes"  # type: str
NO = "No"  # type: str


def solve(N: int, A: "List[int]", B: "List[int]"):
    if max(B)<max(A):
        print(NO)
        return

    ## 完成形を作る
    B_tuple = []
    A_tuple = []
    for i in range(N):
        B_tuple.append((B[i],i))
        A_tuple.append((A[i],i))

    A_tuple.sort(key=lambda x: x[0])
    B_tuple.sort(key=lambda x: x[0])
    dif = 0
    for i in range(N):
        dif += abs(A_tuple[i][1]-B_tuple[i][1])

    if math.ceil(dif/2) <= N-2:
        print(YES)
    else:
        print(NO)

    return


