from queue import PriorityQueue

def readInts():
  return [int(s) for s in input().split(" ")]

def solve(N, A, B):
  zipped = sorted(zip(A, B), reverse=True)
  pq = PriorityQueue()
  for i, (a, b) in enumerate(zipped):
    pq.put((-1 * b, i))

  c = 0
  for i in range(N):
    if zipped[i][0] > zipped[i][1]:
      mb, k = pq.get()
      while k < i:
        mb, k = pq.get()
      b = -1 * mb
      if zipped[i][0] <= b:
        pq.put((-1 * zipped[i][1], k))
        zipped[k] = (zipped[k][0], zipped[i][1])
        c += 1
      else:
        return False
  return (c <= N - 2)

def main():
  N = readInts()[0]
  A = readInts()
  B = readInts()
  if solve(N, A, B):
    print('Yes')
  else:
    print('No')

