use std::collections::BTreeMap;

fn main() {
    readls!(n = usize, aa = Vec<u32>, bs = Vec<u32>);
    let mut as_sorted = aa.clone();
    as_sorted.sort();
    let mut bs_sorted = bs.clone();
    bs_sorted.sort();
    dbg!(&as_sorted);
    dbg!(&bs_sorted);
    let ans = if as_sorted.iter().zip(bs_sorted.iter()).any(|(&a, &b)| a > b) {
        false
    } else if (0..n-1).any(|i| as_sorted[i+1] <= bs_sorted[i] && as_sorted[i] <= bs_sorted[i+1]) {
        true
    } else {
        let mut ps: Vec<(u32, u32)> = aa.into_iter().zip(bs).collect();
        ps.sort_by_key(|&(_, b)| b);
        dbg!(&ps);
        let mut aa: Vec<u32> = ps.into_iter().map(|(a, _)| a).collect();
        let mut a_to_i = BTreeMap::new();
        for (i, &a) in aa.iter().enumerate() {
            a_to_i.insert(a, i);
        }
        let mut ans = false;
        for j in 0..n-1 {
            dbg!(&aa);
            let a_j = as_sorted[j];
            let i = a_to_i[&a_j];
            if i == j {
                ans = true;
                break;
            }
            aa[i] = aa[j];
            aa[j] = a_j;
            a_to_i.remove(&a_j);
            a_to_i.insert(aa[i], i);
        }
        ans
    };
    yn(ans);
}

