fn run() {
    let n: usize = scan();
    let a: Vec<i32> = scan_iter().take(n).collect();
    let b: Vec<i32> = scan_iter().take(n).collect();
    let mut idx: Vec<usize> = (0..n).collect();
    idx.sort_by_key(|&i| b[i]);

    let a: Vec<i32> = idx.iter().map(|&i| a[i]).collect();
    let b: Vec<i32> = idx.iter().map(|&i| b[i]).collect();

    let mut s: Vec<(usize, i32)> = a.iter().cloned().enumerate().collect();
    s.sort_by_key(|&(_, x)| x);

    for i in 0..n {
        let (_, x) = s[i];
        if x > b[i] {
            println!("No");
            return;
        }
    }

    for i in 0..n - 1 {
        let (_, x) = s[i];
        let (_, y) = s[i + 1];
        if y <= b[i] && x <= b[i + 1] {
            println!("Yes");
            return;
        }
    }

    let mut to = vec![0; n];
    for (rank, (i, _)) in s.into_iter().enumerate() {
        to[i] = rank;
    }

    let mut cur = 0;
    for _ in 0..n - 1 {
        cur = to[cur];
        if cur == 0 {
            println!("Yes");
            return;
        }
    }

    println!("No");
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

