fn main() {
    readls!(n = usize, aa = Vec<u32>, bs = Vec<u32>);
    let mut as_sorted = aa.clone();
    as_sorted.sort();
    let mut bs_sorted = bs.clone();
    bs_sorted.sort();
    let ans = if as_sorted.iter().zip(bs_sorted.iter()).any(|(&a, &b)| a > b) {
        false
    } else if as_sorted.iter().zip(bs_sorted[1..].iter()).any(|(&a, &b)| a >= b) {
        true
    } else {
        let mut ps: Vec<(u32, u32)> = aa.into_iter().zip(bs).collect();
        ps.sort_by_key(|&(_, b)| b);
        let i = ps.iter().position(|&(a, _)| a == as_sorted[0]).unwrap();
        dbg!(i);
        if gcd(n, i) != 1 {
            true
        } else {
            (0..n).any(|j| as_sorted[j] != ps[(j+i) % n].0)
        }
    };
    yn(ans);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

