fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      aa: [usize; n],
      bb: [usize; n],
    }

    let mut aa2 = aa.clone();
    aa2.sort();
    let mut bb2 = bb.clone();
    bb2.sort();

    for i in 0..n {
        if aa2[i] > bb2[i] {
            return puts!("{}\n", "No");
        }
    }

    for i in 0..n {
        // 1 2 3 3
        // 1 2 3 4
        if i > 0 {
            if aa2[i] <= bb2[i-1] {
                return puts!("{}\n", "Yes");
            }
        }
    }


    // 愚直にシミュレーション
    let mut bb: Vec<_> = bb.into_iter().enumerate().map(|(i, v)| (v, i)).collect();

    let mut aa2 = vec![];
    for &(_, idx) in bb.iter() {
        aa2.push( aa[idx] );
    }

    let mut aa = aa2;
    let mut a_pos: Vec<_> = aa.iter().cloned().enumerate().map(|(i, v)| (v, i)).collect();
    a_pos.sort();
    let mut a_pos: Vec<_> = a_pos.iter().map(|v|v.1).collect();

    for i in 0..n-1 {
        let b = bb[i].0;

        // swap i and pos;
        let pos = a_pos[i];

        // debug!(aa, a_pos, i, pos);
        if i == pos {
            return puts!("{}\n", "Yes");
        }


        let temp = aa[i];
        aa[i] = aa[pos];
        aa[pos] = temp;

        let temp = a_pos[i];
        a_pos[i] = a_pos[pos];
        a_pos[pos] = temp;
    }

    puts!("{}\n", "No");
}

