fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n, mut a: [usize; n], mut b: [usize; n]);
    let mut bi: Vec<(usize, usize)> = b.iter().enumerate().map(|(i, x)| (*x, i)).collect();
    let mut ai: Vec<(usize, usize)> = a.iter().enumerate().map(|(i, x)| (*x, i)).collect();
    ai.sort();
    bi.sort();
    for i in 0..n {
        if ai[i].0 > bi[i].0 {
            println!("No");
            return;
        }
    }
    for i in 0..(n - 1) {
        if ai[i + 1].0 <= bi[i].0 {
            println!("Yes");
            return;
        }
    }
    let mut count = 0;
    let mut cur = 0;
    loop {
        count += 1;
        cur = bi[ai[cur].1].1;
        if cur == 0 {
            break;
        }
    }
    if count < n {
        println!("Yes");
    } else {
        println!("No");
    }
}

