fn solve() -> bool {
	let N = read!(usize);
	let A = read!([i32]);
	let B = read!([i32]);
	let mut As = A.clone();
	let mut Bs = B.clone();
	As.sort();
	Bs.sort();
	for i in 0..N {
		if As[i] > Bs[i] {
			return false;
		}
	}
	for i in 1..N {
		if As[i - 1] >= Bs[i] {
			return true;
		}
	}
	let mut to = vec![0; N];
	let mut A2: Vec<_> = (0..N).map(|i| (A[i], i)).collect();
	let mut B2: Vec<_> = (0..N).map(|i| (B[i], i)).collect();
	A2.sort();
	B2.sort();
	for i in 0..N {
		to[A2[i].1] = B2[i].1;
	}
	let mut count = 1;
	let mut p = to[0];
	while p != 0 {
		count += 1;
		p = to[p];
	}
	if count == N {
		false
	} else {
		true
	}
}

fn run() {
	if solve() {
		println!("Yes");
	} else {
		println!("No");
	}
}

