    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let b: Vec<usize> = sc.vec(n);

    let mut aa = a.clone();
    aa.sort();
    let mut bb = b.clone();
    bb.sort();
    for i in 0..n {
        if aa[i] > bb[i] {
            println!("No");
            return;
        }
    }

    let mut ab: Vec<_> = a.into_iter().zip(b).collect();
    ab.sort_by_key(|&(_, b)| b);

    let mut ai: Vec<_> = ab.iter().enumerate().map(|(i, &(a, _))| (a, i)).collect();
    ai.sort();
    let mut vis = vec![false; n];
    vis[0] = true;
    let mut cur = ai[0].1;
    while cur != 0 {
        vis[cur] = true;
        cur = ai[cur].1;
    }

    if vis.contains(&false) {
        println!("Yes");
        return;
    }

    for i in 1..n {
        let a1 = ai[i - 1].0;
        let a2 = ai[i].0;
        let b1 = ab[i - 1].1;
        let b2 = ab[i].1;
        assert!(a1 <= b1);
        assert!(a2 <= b2);
        if a2 <= b1 {
            println!("Yes");
            return;
        }
    }
    println!("No");
