struct UnionFind {
      n: usize,
      parent: Vec<usize>,
      count: Vec<usize>
}

impl UnionFind {
     fn new(n: usize) -> Self {
           let mut p = vec![0; n];
           for i in 0..n {
                 p[i] = i;
           }
           UnionFind { n: n, parent: p, count: vec![1; n] }
     }

     fn find(&mut self, a: usize) -> usize {
           if self.parent[a] == a {
                 return a;
           }
           let par = self.parent[a];
           self.parent[a] = self.find(par);
           self.parent[a]
     }

     fn unite(&mut self, a: usize, b: usize) {
           let a = self.find(a);
           let b = self.find(b);
           if a == b {
                 return;
           }
           let ca = self.count[a];
           let cb = self.count[b];
           let total = ca + cb;
           self.count[b] = total;
           self.count[a] = total;
           if ca < cb {
                 self.parent[a] = b;
           } else {
                 self.parent[b] = a;
           }
     }

     fn same(&mut self, a: usize, b: usize) -> bool {
           self.find(a) == self.find(b)
     }

     fn count(&mut self, a: usize) -> usize {
           let a = self.find(a);
           self.count[a]
     }
}

fn solve(mut a: Vec<i32>, mut b: Vec<i32>) -> bool {
    let n = a.len();
    let mut ax = a.clone();
    ax.sort();
    let mut bs = b.clone();
    bs.sort();
    for i in 0..n {
        if ax[i] > bs[i] {
            return false;
        }
    }
    let mut ab = vec![];
    for i in 0..n {
        ab.push((a[i], b[i], i));
    }
    ab.sort_by_key(|x| x.0);
    for i in 0..n {
        ab[i].0 = bs[i];
        ab[i].2 = i;
    }
    ab.sort_by_key(|x| x.1);
    for i in 0..n {
        if ab[i].0 == ab[i].1 {
            return true;
        }
    }
    for i in 0..n-1 {
        if ab[i].1 == ab[i+1].1 {
            return true;
        }
    }

    let mut uf = UnionFind::new(n);
    for i in 0..n {
        uf.unite(i, ab[i].2);
    }
    let mut ma = 0;
    for i in 0..n {
        ma = max(ma, uf.count(i));
    }
    return ma < n;
}

