    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n],
    }
    let mut ba = vec![(0, 0); n];
    for i in 0..n {
