    ba.sort();
    let mut a = vec![(0, 0); n];
    for i in 0..n {
        a[i] = (ba[i].1, i);
    }
    a.sort();
    for i in 0..n {
        if a[i].0 > ba[i].0 {
            fail!();
        }
    }
    for i in 0..n {
        debug!(" {}", ba[i].1);
    }
    debugln!("");
    debugln!("a = {:?}", a);
    let mut uf = UnionFind::new(n);
    let mut conn = n;
    let mut que = BinaryHeap::new();
    let mut pos = 0;
    for i in 0..n {
