    let mut vis = vec![false; n];
    while !vis[r] {
        vis[r] = true;
        r = ai[r];
    }
    if (0..n).all(|i| a[ai[i]] <= b[i])
        && (!vis.iter().all(|&b| b) || (0..n - 1).filter(|&i| a[ai[i + 1]] <= b[i]).count() >= 1)
