fn main() {
    let n = read::<usize>();
    let a = read_vec::<usize>();
    let b = read_vec::<usize>();
    let mut sorted_a = a.clone();
    sorted_a.sort();
    let mut sorted_b = b.clone();
    sorted_b.sort();

    let mut pairs = HashMap::new();
    for i in 0..n {
        if sorted_a[i] > sorted_b[i] {
            // debug!("here");
            println!("No");
            return;
        }
        pairs.insert(sorted_a[i], sorted_b[i]);
    }
    // debug!(pairs);
    // not strict
    for i in 1..n {
        if sorted_b[i - 1] >= sorted_a[i] {
            println!("Yes");
            return;
        }
    }

    let mut b_poses = HashMap::new();
    let b_idx = argsort(&b);
    for i in 0..n {
        let bb = sorted_b[b_idx[i]];
        b_poses.insert(bb, i);
    }
    // debug!(b_poses);

    let mut diff_count = 0;
    for i in 0..n {
        let mut target = pairs[&a[i]];
        if b[i] != target {
            diff_count += 1;
        }
    }
    if diff_count < n {
        println!("Yes");
        return;
    }

    let mut uft = UnionFindTree::new(n);
    for i in 0..n {
        let b_target = pairs[&a[i]];
        let b_pos = b_poses[&b_target];
        // debug!(a[i], b_target, b_pos);
        uft.unite(i, b_pos);
    }
    debug!(uft.get_size(0));
    assert!(b.iter().collect::<HashSet<_>>().len() == n);
    assert!(a.iter().collect::<HashSet<_>>().len() == n);
    let roots = (0..n).map(|x| uft.find(x)).collect::<HashSet<_>>();
    if roots.len() < n / 4 || n % 3 == 0 {
        assert!(false);
        println!("No");
    } else {
        println!("Yes");
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}
fn argsort<T: std::cmp::Ord + std::marker::Copy>(v: &Vec<T>) -> Vec<usize> {
    let mut sort_v = Vec::new();
    for i in 0..v.len() {
        sort_v.push((v[i], i));
    }
    sort_v.sort();
    sort_v.iter().map(|x| x.1).collect::<Vec<usize>>()
}

#[derive(Debug, Clone)]
struct UnionFindTree {
    parent: Vec<isize>,
    size: Vec<usize>,
    height: Vec<u64>,
}

impl UnionFindTree {
    fn new(n: usize) -> UnionFindTree {
        UnionFindTree {
            parent: vec![-1; n],
            size: vec![1usize; n],
            height: vec![0u64; n],
        }
    }

    fn find(&mut self, index: usize) -> usize {
        if self.parent[index] == -1 {
            return index;
        }
        let idx = self.parent[index] as usize;
        let ret = self.find(idx);
        self.parent[index] = ret as isize;
        ret
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    fn get_size(&mut self, x: usize) -> usize {
        let idx = self.find(x);
        self.size[idx]
    }

    fn unite(&mut self, index0: usize, index1: usize) -> bool {
        let a = self.find(index0);
        let b = self.find(index1);
        if a == b {
            false
        } else {
            if self.height[a] > self.height[b] {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
            } else if self.height[a] < self.height[b] {
                self.parent[a] = b as isize;
                self.size[b] += self.size[a];
            } else {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
                self.height[a] += 1;
            }
            true
        }
    }
}

