fn solve(mut a: Vec<u64>, mut b: Vec<u64>) -> bool {
    let n = a.len();
    let mut ba = (0..n).map(|i| (b[i], a[i])).collect::<Vec<_>>();
    ba.sort();

    a.sort();
    b.sort();
    for i in 0..n {
        if a[i] > b[i] {
            return false;
        }
    }

    //    eprintln!("{:?}", a);
    //    eprintln!("{:?}", ba);

    let mut a_seg = BTreeMap::new();
    let mut na_seg = BTreeMap::new();
    let mut seg = vec![0; n];
    let mut tail = 0;
    for head in 0..n {
        if head > tail {
            na_seg.clear();
            tail = head;
        }
        while tail < n && b[head] >= a[tail] {
            let a = a[tail];
            let (_, na) = ba[tail];
            if a == na {
                return true;
            } else {
                push(&mut na_seg, na);
                push(&mut a_seg, a);
            }

            tail += 1;
        }
        seg[head] = tail;

        let a = a[head];
        let (_, na) = ba[head];

        if na_seg.contains_key(&a) {
            return true;
        }
        if a_seg.contains_key(&na) {
            return true;
        }

        remove(&mut na_seg, na);
        remove(&mut a_seg, a);
    }
    false
}

fn push(map: &mut BTreeMap<u64, usize>, v: u64) {
    *map.entry(v).or_insert(0) += 1;
}

fn remove(map: &mut BTreeMap<u64, usize>, v: u64) {
    let c = *map.get(&v).unwrap();
    if c == 1 {
        let removed = map.remove(&v).unwrap();
        assert_eq!(removed, 1);
    } else if c > 1 {
        map.insert(v, c - 1);
    } else {
        unreachable!()
    }
}

