    // println!("{:?}", ia);
    let mut perm = vec![!0; n];
    let mut good = true;
    for k in 0..n {
        good &= a[ia[k]] <= b[ib[k]];
        perm[ia[k]] = ib[k];
    }
    let mut uniq = true;
    for k in 0..n-1 {
        uniq &= a[ia[k+1]] > b[ib[k]]
    }
    let mut cyc = true;
    {
        let mut k = 0;
        for _ in 0..n-1 {
            k = perm[k];
            cyc &= k != 0;
        }
    }
    let ans = good && (uniq || !cyc);
    println!("{}", if ans { "Yes" } else { "No" });
}

