    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let b: Vec<i64> = sc.vec(n);

    let mut ca = a.clone();
    ca.sort();
    let mut cb = b.clone();
    cb.sort();
    for i in 0..n {
        if ca[i] > cb[i] {
            println!("No");
            return;
        }
    }

    let mut ba = (0..n).map(|i| (b[i], a[i])).collect::<Vec<_>>();
    ba.sort();
    let a = ba.iter().map(|&(_, a)| a).collect::<Vec<_>>();
    let b = ba.iter().map(|&(b, _)| b).collect::<Vec<_>>();
    let mut a = a
        .into_iter()
        .enumerate()
        .map(|(i, a)| (a, i))
        .collect::<Vec<_>>();
    a.sort();
    let mut vis = vec![false; n];
    let mut cur = 0;
    vis[cur] = true;
    loop {
        cur = a[cur].1;
        if vis[cur] {
            break;
        }
        vis[cur] = true;
    }

    if vis.into_iter().any(|a| !a) {
        println!("Yes");
        return;
    }

    for i in 1..n {
        let (_, prev) = a[i - 1];
        let (next_a, _) = a[i];
        if b[prev] >= next_a {
            println!("Yes");
            return;
        }
    }
    println!("No");
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

