fn impossible(mut a: Vec<isize>, mut b: Vec<isize>) -> bool {
    a.sort();
    b.sort();

    let n = a.len();
    for i in 0..n {
        if a[i] > b[i] {
            return true;
        }
    }
    false
}

fn solve1(a: Vec<isize>, b: Vec<isize>) -> bool {
    let n = a.len();
    let mut p: Vec<(isize, isize)> = Vec::new();
    for i in 0..n {
        p.push((a[i], b[i]));
    }
    p.sort_by_key(|&(x, y)| if x <= y { y - x } else { 1000000000 + (x - y) });
    for i in 0..10 {
        if i >= p.len() {
            continue;
        }
        let (x, y) = p[i];
        if x > y {
            continue;
        }
        let mut a = Vec::new();
        let mut b = Vec::new();
        for j in 0..n {
            if i != j {
                a.push(p[j].0);
                b.push(p[j].1);
            }
        }
        a.sort();
        b.sort();
        let mut this_is_ok = true;
        for j in 0..n - 1 {
            if a[j] > b[j] {
                this_is_ok = false;
            }
        }
        if this_is_ok {
            return true;
        }
    }
    false
}

