fn slow(xs: &Vec<i64>, ys: &Vec<i64>) -> bool {
    let n = xs.len();
    let mut xs: Vec<i64> = xs.clone();
    slow_sub(n - 2, &mut xs, &ys)
}

fn slow_sub(rem: usize, xs: &mut Vec<i64>, ys: &Vec<i64>) -> bool {
    let n = xs.len();
    let mut t = true;
    for i in 0..n {
        if xs[i] > ys[i] {
            t = false;
        }
    }
    if t {
        return true;
    }
    if rem == 0 {
        return false;
    }
    for i in 0..n {
        for k in i + 1..n {
            xs.swap(i, k);
            if slow_sub(rem - 1, xs, ys) {
                return true;
            }
            xs.swap(i, k);
        }
    }
    return false;
}

fn gen_all_vec(n: usize, lower: i64, upper: i64) -> Vec<Vec<i64>> {
    let mut res = vec![];
    let mut t = vec![];
    gen_all_vec_sub(n, lower, upper, &mut res, &mut t);
    res
}

fn gen_all_vec_sub(n: usize, lower: i64, upper: i64, res: &mut Vec<Vec<i64>>, ts: &mut Vec<i64>) {
    if ts.len() == n {
        res.push(ts.clone());
        return;
    }
    for t in lower..upper {
        ts.push(t);
        gen_all_vec_sub(n, lower, upper, res, ts);
        ts.pop();
    }
}

