fn f(xs: &Vec<i64>, ys: &Vec<i64>) -> Option<bool> {
    let n = xs.len();
    // yoyuu
    {
        let mut xs = xs.clone();
        let mut ys = ys.clone();
        xs.sort();
        ys.sort();
        let mut k = 0;
        let mut rs = vec![];
        for i in 0..n {
            while k < n && xs[k] <= ys[i] {
                k += 1;
            }
            let t = k as i64 - (i + 1) as i64;
            rs.push(t);
            if t < 0 {
                return Some(false);
            }
        }
        for i in 0..n {
            if rs[i] >= 1 {
                return Some(true);
            }
        }
    }
    // rs[i] == 0 only
    let mut xs: Vec<_> = xs.iter().enumerate().map(|(i, &x)| (x, i)).collect();
    let mut ys: Vec<_> = ys.iter().enumerate().map(|(k, &y)| (y, k)).collect();
    xs.sort();
    ys.sort();
    let mut table = vec![0; n];
    for i in 0..n {
        table[ys[i].1] = xs[i].1;
    }
    let mut visited = vec![false; n];
    let mut i = 0;
    let mut count = 0;
    while !visited[i] {
        visited[i] = true;
        count += 1;
        i = table[i];
    }
    Some(count != n)
}

