    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a: Vec<(usize, usize)> = (0..n).map(|k| (it.next().unwrap().parse().unwrap(), k)).collect();
    let mut b: Vec<(usize, usize)> = (0..n).map(|k| (it.next().unwrap().parse().unwrap(), k)).collect();
    a.sort();
