    }

    let mut uft = UnionFindTree::new(n);
    for i in 0..n {
        let b_target = pairs[&a[i]];
        let b_pos = b_poses[&b_target];
        uft.unite(i, b_pos);
    }
    for i in 0..n {
        let a_target = pairs_b[&b[i]];
        let a_pos = a_poses[&a_target];
        uft.unite(i, a_pos);
    }
    debug!(uft.get_size(0));
