        let mut seg = SegmentTree::new(c.v.len() + 1, MaxMonoid::new(0));
        for i in 0..n {
            seg.update(c.get(ta[i]), i);
        }
        let mut sw = 0;
        for i in 0..n {
            if ta[i] > sb[i] {
                let j = seg.query(0, c.get(sb[i]) + 1);
                seg.update(c.get(ta[j]), 0);
                ta.swap(i, j);
                sw += 1;
            }
        }
        if sw <= n - 2 {
            println!("Yes");
        } else {
            println!("No");
        }
    } else {
        println!("No");
    }
}

