fn impossible(mut a: Vec<isize>, mut b: Vec<isize>) -> bool {
    a.sort();
    b.sort();

    let n = a.len();
    for i in 0..n {
        if a[i] > b[i] {
            return true;
        }
    }
    false
}

fn solve1(a: Vec<isize>, b: Vec<isize>) -> bool {
    let n = a.len();
    let mut p: Vec<(isize, isize)> = Vec::new();
    for i in 0..n {
        p.push((a[i], b[i]));
    }
    p.sort_by_key(|&(x, y)| if x <= y { y - x } else { 1000000000 + (x - y) });
    for i in 0..10 {
        if i >= p.len() {
            continue;
        }
        let (x, y) = p[i];
        if x > y {
            continue;
        }
        let mut a = Vec::new();
        let mut b = Vec::new();
        for j in 0..n {
            if i != j {
                a.push(p[j].0);
                b.push(p[j].1);
            }
        }
        a.sort();
        b.sort();
        let mut this_is_ok = true;
        for j in 0..n - 1 {
            if a[j] > b[j] {
                this_is_ok = false;
            }
        }
        if this_is_ok {
            return true;
        }
    }
    false
}
fn solve2(a: Vec<isize>, b: Vec<isize>) -> bool {
    let n = a.len();
    let mut p: Vec<(isize, isize)> = Vec::new();
    for i in 0..n {
        p.push((a[i], b[i]));
    }
    p.sort_by_key(|&(x, y)| x - y);
    let (x1, y1) = p[0];
    let (x2, y2) = p[n - 1];
    if x1 <= y2 && x2 <= y1 {
        let mut a = Vec::new();
        let mut b = Vec::new();
        for j in 0..n {
            if j != 0 && j != n - 1 {
                a.push(p[j].0);
                b.push(p[j].1);
            }
        }
        a.sort();
        b.sort();
        let mut this_is_ok = true;
        for j in 0..n - 2 {
            if a[j] > b[j] {
                this_is_ok = false;
            }
        }
        if this_is_ok {
            return true;
        }
    }
    false
}

fn run() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());
    let n: usize = sc.read();
    let a: Vec<isize> = sc.read_vec(n);
    let b: Vec<isize> = sc.read_vec(n);

    if impossible(a.clone(), b.clone()) {
        println!("No");
        return;
    }

    let mut ans = solve1(a.clone(), b.clone()) || solve2(a.clone(), b.clone());

    let mut p: Vec<(isize, isize)> = Vec::new();
    for i in 0..n {
        p.push((a[i], b[i]));
    }
    p.sort_by_key(|&(x, y)| x - y);

    if ans {
        println!("Yes");
    } else {
        println!("No");
    }
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(1024 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

